from __future__ import annotations

import sys as _sys
import types as _types

_ROOT = __name__                              # имя пакета: kompas_lib
_ALL: dict[str, list[str]] = {}               # __all__ модулей: "dims" → [...], "" — корень
_NAMES: dict[str, frozenset[str]] = {}        # имена модулей — заполняется в конце файла


class _SubModule(_types.ModuleType):
    """Модуль пакета внутри этого файла: его имена — общие имена файла (они уникальны во всём пакете)."""

    def __getattr__(self, name):
        relative = self.__name__[len(_ROOT) + 1:]
        if name == "__all__" and relative in _ALL:
            return _ALL[relative]
        names = _NAMES.get(relative)
        if names is None or name in names or name in _ALL.get(relative, ()):
            try:
                return globals()[name]
            except KeyError:
                pass
        sub = _sys.modules.get(f"{self.__name__}.{name}")
        if isinstance(sub, _SubModule):
            return sub
        raise AttributeError(f"module {self.__name__!r} has no attribute {name!r}")

    def __dir__(self):
        relative = self.__name__[len(_ROOT) + 1:]
        return sorted(_NAMES.get(relative, frozenset()) | set(_ALL.get(relative, ())))


def _submodule(relative: str) -> _SubModule:
    """Модуль kompas_lib.<relative> (создаётся при первом обращении и регистрируется в sys.modules)."""
    name = f"{_ROOT}.{relative}"
    module = _sys.modules.get(name)
    if not isinstance(module, _SubModule):
        module = _SubModule(name)
        module.__file__ = __file__
        module.__package__ = name.rpartition(".")[0]
        _sys.modules[name] = module
    return module


_TAIL_GUARD = False       # блоки `if _TAIL_GUARD:` в конце файла уже выполнены выше — через _run_tail_section


def _run_tail_section(name: str) -> None:
    """Выполнить раздел, код которого стоит в конце файла (блок `if _TAIL_GUARD:  # раздел <name>`).

    Большие сгенерированные разделы (перечисления SDK) вынесены в конец, чтобы поиск по файлу сначала находил
    API, а выполняются на своём месте в порядке зависимостей. Номера строк в трассировках — настоящие."""
    with open(__file__, encoding="utf-8") as stream:
        lines = stream.read().split("\n")
    start = next(i for i, line in enumerate(lines) if line.startswith(f"if _TAIL_GUARD:  # раздел {name} "))
    end = lines.index(f"# === конец раздела {name}", start)
    code = "\n" * (start + 1) + "\n".join(line[4:] for line in lines[start + 1:end])
    exec(compile(code, __file__, "exec"), globals())

