def verify_installed() -> list[tuple[str, int, int]]:
    """Сверяет сгенерированные значения с constants.py установленного КОМПАСа.

    Возвращает список расхождений (имя, значение_из_SDK, значение_в_constants.py),
    кроме известных (KNOWN_MISMATCHES).
    """
    # из kompas_lib._loader: flat_constants

    flat = flat_constants()
    result = []
    for name, enum_cls in MEMBER_INDEX.items():
        if name in KNOWN_MISMATCHES or name not in flat:
            continue
        value = int(enum_cls[name])
        if flat[name] != value:
            result.append((name, value, flat[name]))
    return result


__all__ = [
    "raw", "by_name", "verify_installed", "KNOWN_MISMATCHES", "PROJECTION_NAMES",
    "DocumentType", "SheetFormat", "Projection", "ViewType", "StampCell", "LineStyle",
    "DimOrientation", "HideMessage", "RasterFormat",
]
_ALL['enums'] = __all__


