"""Исключения библиотеки."""


class KompasError(Exception):
    """Базовое исключение kompas_lib."""


class KsapiNotFoundError(KompasError):
    """Не найден ksapi.py / установленный КОМПАС-3D."""


class NotConnectedError(KompasError):
    """Нет связи с запущенным КОМПАС-3D."""


class KompasBusyError(KompasError):
    """В документе выполняется интерактивный процесс пользователя; изменение небезопасно."""


class OperationFailedError(KompasError):
    """Вызов KsAPI вернул неуспех."""

    def __init__(self, operation: str, details: str = "") -> None:
        self.operation = operation
        self.details = details
        super().__init__(f"{operation} не выполнено" + (f": {details}" if details else ""))


class WrongDocumentTypeError(KompasError):
    """Документ не того типа (например, ожидался чертёж)."""


class LayoutError(KompasError):
    """Компоновка невозможна (не помещается на формат и т.п.)."""


class ComponentNotFoundError(KompasError, LookupError):
    """Компонент сборки не найден или запрос неоднозначен; текст перечисляет варианты."""


class MateError(KompasError):
    """Сопряжение не выполнено (ошибка КОМПАСа или не сходится геометрия); сопряжение удалено, положение возвращено.

    `mate` — объект `assembly.Mate` с подробностями.
    """

    def __init__(self, message: str, mate=None) -> None:
        self.mate = mate
        super().__init__(message)


def check(result, operation: str, details: str = ""):
    """Возвращает result, если он «истинный», иначе бросает OperationFailedError.

    Для кортежей KsAPI вида (ok, ...) проверяется первый элемент.
    """
    ok = result[0] if isinstance(result, tuple) and result else result
    if not ok:
        raise OperationFailedError(operation, details)
    return result


