# === 05/55 kompas_lib._loader — kompas_lib/_loader.py
# ==================================================================================================================
"""Поиск установленного КОМПАС-3D и загрузка `ksapi.py` из его каталога Bin.

`ksapi.py` импортирует модуль верхнего уровня `constants`. Чтобы не засорять `sys.path`
и не конфликтовать с пользовательскими модулями `constants`, оба модуля загружаются через
importlib, а `sys.modules['constants']` подменяется только на время импорта ksapi.
"""

import glob
import importlib.util
import os
import sys
from pathlib import Path
from types import ModuleType

# из kompas_lib.errors: KsapiNotFoundError

_VISUAL_CLSID = r"CLSID\{8C3719B5-0DF2-4C12-9CA8-3AF4827A3BBB}\LocalServer32"

_state: dict[str, object] = {}


def _from_registry() -> Path | None:
    if os.name != "nt":
        return None
    try:
        import winreg

        with winreg.OpenKey(winreg.HKEY_CLASSES_ROOT, _VISUAL_CLSID) as key:
            value, _ = winreg.QueryValueEx(key, "")
        return Path(str(value).strip().strip('"')).parent
    except OSError:
        return None


def running_kompas_dirs() -> list[Path]:
    """Каталоги запущенных процессов KOMPAS.exe (Windows, через Toolhelp32 + QueryFullProcessImageNameW)."""
    if os.name != "nt":
        return []
    import ctypes
    from ctypes import wintypes

    TH32CS_SNAPPROCESS = 0x2
    PROCESS_QUERY_LIMITED_INFORMATION = 0x1000

    class PROCESSENTRY32W(ctypes.Structure):
        _fields_ = [("dwSize", wintypes.DWORD), ("cntUsage", wintypes.DWORD),
                    ("th32ProcessID", wintypes.DWORD), ("th32DefaultHeapID", ctypes.c_void_p),
                    ("th32ModuleID", wintypes.DWORD), ("cntThreads", wintypes.DWORD),
                    ("th32ParentProcessID", wintypes.DWORD), ("pcPriClassBase", ctypes.c_long),
                    ("dwFlags", wintypes.DWORD), ("szExeFile", ctypes.c_wchar * 260)]

    k32 = ctypes.WinDLL("kernel32", use_last_error=True)
    k32.CreateToolhelp32Snapshot.restype = wintypes.HANDLE
    k32.OpenProcess.restype = wintypes.HANDLE
    snap = k32.CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0)
    if not snap or snap == wintypes.HANDLE(-1).value:
        return []
    result: list[Path] = []
    try:
        entry = PROCESSENTRY32W()
        entry.dwSize = ctypes.sizeof(PROCESSENTRY32W)
        ok = k32.Process32FirstW(snap, ctypes.byref(entry))
        while ok:
            if entry.szExeFile.lower() == "kompas.exe":
                h = k32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, entry.th32ProcessID)
                if h:
                    try:
                        buf = ctypes.create_unicode_buffer(1024)
                        size = wintypes.DWORD(len(buf))
                        if k32.QueryFullProcessImageNameW(h, 0, buf, ctypes.byref(size)):
                            result.append(Path(buf.value).parent)
                    finally:
                        k32.CloseHandle(h)
            ok = k32.Process32NextW(snap, ctypes.byref(entry))
    finally:
        k32.CloseHandle(snap)
    return result


def candidate_dirs() -> list[Path]:
    """Каталоги, в которых ищется ksapi.py, в порядке приоритета:
    KOMPAS_BIN → запущенный KOMPAS.exe → реестр → установленные версии (новые первыми)."""
    result: list[Path] = []
    env = os.environ.get("KOMPAS_BIN")
    if env:
        result.append(Path(env))
    result += running_kompas_dirs()
    reg = _from_registry()
    if reg:
        result.append(reg)
    for pattern in (r"C:\Program Files\ASCON\*\*\Bin(x64)", r"C:\Program Files\ASCON\*\Bin",
                    r"C:\Program Files\ASCON\*"):
        result += sorted((Path(p) for p in glob.glob(pattern)), reverse=True)
    return list(dict.fromkeys(result))


def find_kompas_bin() -> Path:
    tried = candidate_dirs()
    for d in tried:
        if (d / "ksapi.py").is_file():
            return d
    raise KsapiNotFoundError(
        "Не найден ksapi.py. Укажите каталог Bin КОМПАС-3D через переменную окружения KOMPAS_BIN. "
        f"Проверены: {[str(t) for t in tried]}"
    )


def _load_module(name: str, path: Path) -> ModuleType:
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise KsapiNotFoundError(f"Не удалось загрузить {path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def load(bin_dir: str | os.PathLike | None = None) -> ModuleType:
    """Загружает ksapi (один раз на процесс) и возвращает модуль."""
    if "ksapi" in _state:
        return _state["ksapi"]  # type: ignore[return-value]
    bin_path = Path(bin_dir) if bin_dir else find_kompas_bin()

    consts = _load_module("_kompas_constants", bin_path / "constants.py")
    consts3d = _load_module("_kompas_constants3d", bin_path / "constants3d.py")

    saved = sys.modules.get("constants")
    sys.modules["constants"] = consts
    try:
        ksapi = _load_module("ksapi", bin_path / "ksapi.py")
        sys.modules.setdefault("ksapi", ksapi)
    finally:
        if saved is None:
            sys.modules.pop("constants", None)
        else:
            sys.modules["constants"] = saved

    _state.update(ksapi=ksapi, constants=consts.constants, constants3d=consts3d.constants, bin=bin_path)
    return ksapi


def ks() -> ModuleType:
    """Модуль ksapi (загружается при первом обращении)."""
    return load()


def bin_dir() -> Path:
    load()
    return _state["bin"]  # type: ignore[return-value]


def flat_constants() -> dict[str, int]:
    """Плоские константы установленного КОМПАСа (constants.py + constants3d.py)."""
    load()
    result: dict[str, int] = {}
    for key in ("constants", "constants3d"):
        for k, v in vars(_state[key]).items():
            if not k.startswith("_") and isinstance(v, int):
                result.setdefault(k, v)
    return result


