# === 06/55 kompas_lib.watchdog — kompas_lib/watchdog.py
# ==================================================================================================================
"""Наблюдение за модальными окнами КОМПАСа без закрытия пользовательских диалогов."""

import ctypes
from dataclasses import dataclass
import threading
import warnings


@dataclass(frozen=True)
class ModalDialog:
    handle: int
    title: str


def modal_dialogs(main_window: int) -> list[ModalDialog]:
    """Видимые диалоги того же процесса с заблокированным окном-владельцем."""
    from ctypes import wintypes
    user32=ctypes.WinDLL('user32',use_last_error=True)
    user32.GetWindow.argtypes=[wintypes.HWND,wintypes.UINT]
    user32.GetWindow.restype=wintypes.HWND
    user32.IsWindowEnabled.argtypes=[wintypes.HWND]
    user32.IsWindowVisible.argtypes=[wintypes.HWND]
    user32.GetWindowThreadProcessId.argtypes=[wintypes.HWND,ctypes.POINTER(wintypes.DWORD)]
    user32.GetWindowTextW.argtypes=[wintypes.HWND,wintypes.LPWSTR,ctypes.c_int]
    pid=wintypes.DWORD()
    user32.GetWindowThreadProcessId(main_window,ctypes.byref(pid))
    result=[]
    callback_type=ctypes.WINFUNCTYPE(wintypes.BOOL,wintypes.HWND,wintypes.LPARAM)
    @callback_type
    def callback(window,_):
        if not user32.IsWindowVisible(window):
            return True
        candidate=wintypes.DWORD()
        user32.GetWindowThreadProcessId(window,ctypes.byref(candidate))
        owner=user32.GetWindow(window,4)  # GW_OWNER
        if candidate.value==pid.value and owner and not user32.IsWindowEnabled(owner):
            title=ctypes.create_unicode_buffer(512)
            user32.GetWindowTextW(window,title,len(title))
            result.append(ModalDialog(int(window),title.value))
        return True
    user32.EnumWindows.argtypes=[callback_type,wintypes.LPARAM]
    user32.EnumWindows(callback,0)
    return result


class ModalWatchdog:
    """Поток сообщает о новых окнах, пока основной поток ожидает вызов KsAPI.

    on_dialog вызывается из сторожевого потока. Обработчик не должен вызывать
    KsAPI; автоматическое закрытие окон библиотека не выполняет.
    """
    def __init__(self,main_window,on_dialog=None,interval=0.5,poll=None):
        if interval<=0:
            raise ValueError('interval должен быть положительным')
        self.main_window=main_window
        self.on_dialog=on_dialog or self._warn
        self.interval=interval
        self.poll=poll or modal_dialogs
        self.dialogs=[]
        self.error=None
        self._stop=threading.Event()
        self._thread=None

    @staticmethod
    def _warn(dialog):
        warnings.warn(f'КОМПАС ожидает ответа в окне {dialog.title!r} (HWND={dialog.handle})',RuntimeWarning)

    def _run(self):
        seen=set()
        try:
            while not self._stop.is_set():
                current=self.poll(self.main_window)
                for dialog in current:
                    if dialog.handle not in seen:
                        self.dialogs.append(dialog)
                        self.on_dialog(dialog)
                seen={d.handle for d in current}
                self._stop.wait(self.interval)
        except Exception as error:
            self.error=error
            self._warn(ModalDialog(0,f'Сторож остановлен: {error}'))

    def __enter__(self):
        self._stop.clear()
        self._thread=threading.Thread(target=self._run,name='kompas-modal-watchdog',daemon=True)
        self._thread.start()
        return self

    def __exit__(self,*_):
        self._stop.set()
        self._thread.join(timeout=max(1.,2*self.interval))


