# === 07/55 kompas_lib.geom — kompas_lib/geom.py
# ==================================================================================================================
"""Простая 2D-геометрия для компоновки и проверки пересечений (без зависимостей от КОМПАСа).

Система координат — как в КОМПАСе: X вправо, Y вверх, единицы — мм листа (если не оговорено).
"""

import math
from dataclasses import dataclass
from typing import Iterable

EPS = 1e-9


@dataclass(frozen=True)
class Point:
    x: float
    y: float

    def __add__(self, o: "Point") -> "Point":
        return Point(self.x + o.x, self.y + o.y)

    def __sub__(self, o: "Point") -> "Point":
        return Point(self.x - o.x, self.y - o.y)

    def dist(self, o: "Point") -> float:
        return math.hypot(self.x - o.x, self.y - o.y)


@dataclass(frozen=True)
class Rect:
    """Ось-ориентированный прямоугольник: (x1, y1) — левый нижний, (x2, y2) — правый верхний угол."""
    x1: float
    y1: float
    x2: float
    y2: float

    @staticmethod
    def of(x1: float, y1: float, x2: float, y2: float) -> "Rect":
        """Нормализует порядок координат."""
        return Rect(min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2))

    @property
    def width(self) -> float:
        return self.x2 - self.x1

    @property
    def height(self) -> float:
        return self.y2 - self.y1

    @property
    def center(self) -> Point:
        return Point((self.x1 + self.x2) / 2, (self.y1 + self.y2) / 2)

    @property
    def area(self) -> float:
        return max(0.0, self.width) * max(0.0, self.height)

    def expand(self, left: float = 0, bottom: float = 0, right: float = 0, top: float = 0) -> "Rect":
        return Rect(self.x1 - left, self.y1 - bottom, self.x2 + right, self.y2 + top)

    def inflate(self, d: float) -> "Rect":
        return self.expand(d, d, d, d)

    def shift(self, dx: float, dy: float) -> "Rect":
        return Rect(self.x1 + dx, self.y1 + dy, self.x2 + dx, self.y2 + dy)

    def intersects(self, o: "Rect", tol: float = 0.0) -> bool:
        """Пересечение с перекрытием больше tol (касание не считается)."""
        return (min(self.x2, o.x2) - max(self.x1, o.x1) > tol and
                min(self.y2, o.y2) - max(self.y1, o.y1) > tol)

    def intersection(self, o: "Rect") -> "Rect | None":
        r = Rect(max(self.x1, o.x1), max(self.y1, o.y1), min(self.x2, o.x2), min(self.y2, o.y2))
        return r if r.width > EPS and r.height > EPS else None

    def contains(self, o: "Rect", tol: float = 1e-6) -> bool:
        return (o.x1 >= self.x1 - tol and o.y1 >= self.y1 - tol and
                o.x2 <= self.x2 + tol and o.y2 <= self.y2 + tol)

    def contains_point(self, p: Point, tol: float = 1e-6) -> bool:
        return self.x1 - tol <= p.x <= self.x2 + tol and self.y1 - tol <= p.y <= self.y2 + tol

    def union(self, o: "Rect") -> "Rect":
        return Rect(min(self.x1, o.x1), min(self.y1, o.y1), max(self.x2, o.x2), max(self.y2, o.y2))

    def as_tuple(self) -> tuple[float, float, float, float]:
        return (self.x1, self.y1, self.x2, self.y2)


def union_all(rects: Iterable[Rect]) -> Rect | None:
    result: Rect | None = None
    for r in rects:
        result = r if result is None else result.union(r)
    return result


@dataclass(frozen=True)
class Segment:
    a: Point
    b: Point

    @property
    def length(self) -> float:
        return self.a.dist(self.b)

    @property
    def bbox(self) -> Rect:
        return Rect.of(self.a.x, self.a.y, self.b.x, self.b.y)


class SegmentIndex:
    """Равномерная сетка для быстрого отбора отрезков вблизи прямоугольника.

    Отрезок заносится во все клетки, через которые проходит (точно, по полосам строк), поэтому `query(rect)`
    возвращает надмножество отрезков, пересекающих `rect` (точную проверку делает вызывающий код).
    Ведёт себя как последовательность отрезков (`len`, итерация), так что передаётся туда же, где и список.
    """

    def __init__(self, segments: Iterable[Segment], cell: float = 10.0) -> None:
        self.segments: list[Segment] = list(segments)
        self.cell = float(cell)
        self._grid: dict[tuple[int, int], list[int]] = {}
        for idx, s in enumerate(self.segments):
            for key in self._cells(s):
                self._grid.setdefault(key, []).append(idx)

    def __len__(self) -> int:
        return len(self.segments)

    def __iter__(self):
        return iter(self.segments)

    def _cells(self, s: Segment):
        c = self.cell
        x1, y1, x2, y2 = s.a.x, s.a.y, s.b.x, s.b.y
        j0, j1 = math.floor(min(y1, y2) / c), math.floor(max(y1, y2) / c)
        if j0 == j1 or abs(y2 - y1) < EPS:
            for i in range(math.floor(min(x1, x2) / c), math.floor(max(x1, x2) / c) + 1):
                for j in range(j0, j1 + 1):
                    yield (i, j)
            return
        lo, hi = min(y1, y2), max(y1, y2)
        for j in range(j0, j1 + 1):
            ya, yb = max(lo, j * c), min(hi, (j + 1) * c)
            xa = x1 + (x2 - x1) * (ya - y1) / (y2 - y1)
            xb = x1 + (x2 - x1) * (yb - y1) / (y2 - y1)
            for i in range(math.floor(min(xa, xb) / c), math.floor(max(xa, xb) / c) + 1):
                yield (i, j)

    def query(self, r: Rect) -> list[Segment]:
        c = self.cell
        i0, i1 = math.floor(r.x1 / c), math.floor(r.x2 / c)
        j0, j1 = math.floor(r.y1 / c), math.floor(r.y2 / c)
        if (i1 - i0 + 1) * (j1 - j0 + 1) > 4 * max(1, len(self._grid)):
            return self.segments                    # запрос шире самой сетки — дешевле отдать всё
        seen: set[int] = set()
        for i in range(i0, i1 + 1):
            for j in range(j0, j1 + 1):
                seen.update(self._grid.get((i, j), ()))
        return [self.segments[k] for k in sorted(seen)]


def near(obstacles, r: Rect, tol: float = 0.0):
    """Отрезки-кандидаты вблизи r: из SegmentIndex — по сетке, из обычной последовательности — все."""
    if isinstance(obstacles, SegmentIndex):
        return obstacles.query(r.inflate(tol) if tol else r)
    return obstacles


def as_index(obstacles, cell: float = 10.0) -> SegmentIndex:
    return obstacles if isinstance(obstacles, SegmentIndex) else SegmentIndex(obstacles, cell)

def _orient(p: Point, q: Point, r: Point) -> float:
    return (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x)


def segments_cross(s1: Segment, s2: Segment, tol: float = 1e-6) -> bool:
    """Собственное пересечение отрезков (общие концы и касание концом не считаются)."""
    d1 = _orient(s2.a, s2.b, s1.a)
    d2 = _orient(s2.a, s2.b, s1.b)
    d3 = _orient(s1.a, s1.b, s2.a)
    d4 = _orient(s1.a, s1.b, s2.b)
    scale1 = max(s2.length, EPS)
    scale2 = max(s1.length, EPS)
    return ((d1 / scale1 > tol and d2 / scale1 < -tol) or (d1 / scale1 < -tol and d2 / scale1 > tol)) and \
           ((d3 / scale2 > tol and d4 / scale2 < -tol) or (d3 / scale2 < -tol and d4 / scale2 > tol))


def segment_rect_overlap(s: Segment, r: Rect) -> float:
    """Длина части отрезка внутри прямоугольника (отсечение Лианга — Барски)."""
    dx, dy = s.b.x - s.a.x, s.b.y - s.a.y
    t0, t1 = 0.0, 1.0
    for p, q in ((-dx, s.a.x - r.x1), (dx, r.x2 - s.a.x), (-dy, s.a.y - r.y1), (dy, r.y2 - s.a.y)):
        if abs(p) < EPS:
            if q < 0:
                return 0.0
            continue
        t = q / p
        if p < 0:
            t0 = max(t0, t)
        else:
            t1 = min(t1, t)
        if t0 > t1:
            return 0.0
    return (t1 - t0) * s.length


def segment_hits_rect(s: Segment, r: Rect, tol: float = 1e-6) -> bool:
    """Отрезок проходит через внутренность прямоугольника (а не только касается границы)."""
    inner = Rect(r.x1 + tol, r.y1 + tol, r.x2 - tol, r.y2 - tol)
    if inner.width <= 0 or inner.height <= 0:
        return False
    return segment_rect_overlap(s, inner) > tol


def collinear_overlap(s1: Segment, s2: Segment, tol: float = 1e-6) -> float:
    """Длина общей части двух отрезков, лежащих на одной прямой (0 — если не на одной прямой)."""
    if s1.length < EPS or s2.length < EPS:
        return 0.0
    if abs(_orient(s1.a, s1.b, s2.a)) / s1.length > tol or abs(_orient(s1.a, s1.b, s2.b)) / s1.length > tol:
        return 0.0
    ux, uy = (s1.b.x - s1.a.x) / s1.length, (s1.b.y - s1.a.y) / s1.length

    def t(p: Point) -> float:
        return (p.x - s1.a.x) * ux + (p.y - s1.a.y) * uy

    lo2, hi2 = sorted((t(s2.a), t(s2.b)))
    return max(0.0, min(s1.length, hi2) - max(0.0, lo2))


def arc_polyline(center: Point, radius: float, a1: float = 0.0, a2: float = 360.0, ccw: bool = True,
                 per_circle: int = 48) -> list[Segment]:
    """Ломаная, аппроксимирующая дугу (углы в градусах; a1 == a2 — полная окружность)."""
    sweep = (a2 - a1) % 360.0 if ccw else -((a1 - a2) % 360.0)
    if abs(sweep) < 1e-9:
        sweep = 360.0
    n = max(2, int(math.ceil(abs(sweep) / 360.0 * per_circle)))
    pts = [Point(center.x + radius * math.cos(math.radians(a1 + sweep * i / n)),
                 center.y + radius * math.sin(math.radians(a1 + sweep * i / n))) for i in range(n + 1)]
    return [Segment(pts[i], pts[i + 1]) for i in range(n)]


def arc_extremes(center: Point, radius: float, a1: float = 0.0, a2: float = 360.0, ccw: bool = True) -> list[Point]:
    """Точки дуги, задающие её габарит: концы + квадрантные точки (0°, 90°, 180°, 270°) внутри дуги.

    Соглашение об углах — как в arc_polyline (a1 == a2 — полная окружность).
    """
    sweep = (a2 - a1) % 360.0 if ccw else -((a1 - a2) % 360.0)
    full = abs(sweep) < 1e-9

    def at(a: float) -> Point:
        return Point(center.x + radius * math.cos(math.radians(a)), center.y + radius * math.sin(math.radians(a)))

    pts = [] if full else [at(a1), at(a1 + sweep)]
    for q in (0.0, 90.0, 180.0, 270.0):
        off = (q - a1) % 360.0 if sweep >= 0 else (a1 - q) % 360.0
        if full or off <= abs(sweep) + 1e-9:
            pts.append(at(q))
    return pts


@dataclass(frozen=True)
class OBox:
    """Повёрнутый прямоугольник: точки o + a·d + b·n, a ∈ [a1, a2], b ∈ [n1, n2], где n = d, повёрнутый на 90°.

    Для наклонных надписей (диаметральные размеры). d — единичный вектор.
    """
    o: Point
    d: tuple[float, float]
    a1: float
    a2: float
    n1: float
    n2: float

    @staticmethod
    def of(r: "Rect | OBox") -> "OBox":
        if isinstance(r, OBox):
            return r
        return OBox(Point(0.0, 0.0), (1.0, 0.0), r.x1, r.x2, r.y1, r.y2)

    @property
    def n(self) -> tuple[float, float]:
        return (-self.d[1], self.d[0])

    def point(self, a: float, b: float) -> Point:
        n = self.n
        return Point(self.o.x + a * self.d[0] + b * n[0], self.o.y + a * self.d[1] + b * n[1])

    def local(self, p: Point) -> Point:
        dx, dy = p.x - self.o.x, p.y - self.o.y
        n = self.n
        return Point(dx * self.d[0] + dy * self.d[1], dx * n[0] + dy * n[1])

    def corners(self) -> list[Point]:
        return [self.point(self.a1, self.n1), self.point(self.a2, self.n1),
                self.point(self.a2, self.n2), self.point(self.a1, self.n2)]

    @property
    def bbox(self) -> Rect:
        cs = self.corners()
        return Rect(min(p.x for p in cs), min(p.y for p in cs), max(p.x for p in cs), max(p.y for p in cs))

    def hits_segment(self, s: Segment, tol: float = 1e-6) -> bool:
        """Отрезок проходит через внутренность (касание границы не считается)."""
        return segment_hits_rect(Segment(self.local(s.a), self.local(s.b)), Rect(self.a1, self.n1, self.a2, self.n2),
                                 tol)

    def intersects(self, other: "OBox | Rect", tol: float = 0.0) -> bool:
        """Перекрытие внутренностей больше tol (теорема о разделяющей оси)."""
        other = OBox.of(other)
        a, b = self.corners(), other.corners()
        for ax in (self.d, self.n, other.d, other.n):
            pa = [p.x * ax[0] + p.y * ax[1] for p in a]
            pb = [p.x * ax[0] + p.y * ax[1] for p in b]
            if min(max(pa), max(pb)) - max(min(pa), min(pb)) <= tol:
                return False
        return True


