# === 08/55 kompas_lib.vec3 — kompas_lib/vec3.py
# ==================================================================================================================
"""Трёхмерные векторы кортежами `(x, y, z)`: арифметика и округление координат, прочитанных из KsAPI."""

import math

Vec3 = tuple[float, float, float]


def vadd(a: Vec3, b: Vec3) -> Vec3:
    return (a[0] + b[0], a[1] + b[1], a[2] + b[2])


def vsub(a: Vec3, b: Vec3) -> Vec3:
    return (a[0] - b[0], a[1] - b[1], a[2] - b[2])


def vmul(a: Vec3, k: float) -> Vec3:
    return (a[0] * k, a[1] * k, a[2] * k)


def dot(a: Vec3, b: Vec3) -> float:
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]


def cross(a: Vec3, b: Vec3) -> Vec3:
    return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])


def norm(a: Vec3) -> float:
    return math.sqrt(dot(a, a))


def unit(a: Vec3) -> Vec3:
    n = norm(a)
    if n < 1e-12:
        raise ValueError("нулевой вектор")
    return (a[0] / n, a[1] / n, a[2] / n)


def rounded(v: float, nd: int = 6) -> float:
    """Округлить координату и убрать «-0.0»: значения из KsAPI сравниваются и печатаются без шума."""
    v = round(float(v), nd)
    return 0.0 if v == 0 else v


