"""Нормативные константы ЕСКД, которых нет в KsAPI.

* ГОСТ 2.301-68 — форматы;
* ГОСТ 2.302-68 — масштабы;
* ГОСТ 2.104-2006 — поля рамки;
* ГОСТ 2.307-2011 — расстояния для размеров.
"""

from dataclasses import dataclass
from fractions import Fraction

# из kompas_lib.enums: SheetFormat

# --- ГОСТ 2.301: размеры форматов (короткая × длинная сторона), мм
FORMAT_SIZES: dict[SheetFormat, tuple[float, float]] = {
    SheetFormat.A0: (841.0, 1189.0),
    SheetFormat.A1: (594.0, 841.0),
    SheetFormat.A2: (420.0, 594.0),
    SheetFormat.A3: (297.0, 420.0),
    SheetFormat.A4: (210.0, 297.0),
    SheetFormat.A5: (148.0, 210.0),
}

# Порядок от меньшего к большему — для подбора формата.
FORMAT_ORDER = (SheetFormat.A4, SheetFormat.A3, SheetFormat.A2, SheetFormat.A1, SheetFormat.A0)


def format_size(fmt: SheetFormat, landscape: bool) -> tuple[float, float]:
    """(ширина, высота) листа в мм."""
    short, long_ = FORMAT_SIZES[SheetFormat(fmt)]
    return (long_, short) if landscape else (short, long_)


# --- ГОСТ 2.104: поля внутренней рамки, мм (слева — подшивка)
FRAME_LEFT = 20.0
FRAME_OTHER = 5.0


# --- ГОСТ 2.302: масштабы
@dataclass(frozen=True, order=True)
class Scale:
    """Масштаб изображения, value = длина на чертеже / натуральная длина."""
    value: Fraction

    @property
    def factor(self) -> float:
        return float(self.value)

    @property
    def label(self) -> str:
        """'1:2', '2,5:1', '1:1' — как в основной надписи."""
        def fmt(x: Fraction) -> str:
            s = f"{float(x):g}"
            return s.replace(".", ",")
        if self.value >= 1:
            return f"{fmt(self.value)}:1"
        return f"1:{fmt(1 / self.value)}"

    def __str__(self) -> str:
        return self.label


def _s(num: str, den: str = "1") -> Scale:
    return Scale(Fraction(num) / Fraction(den))


SCALE_NATURAL = _s("1")
SCALES_REDUCTION = tuple(_s("1", d) for d in
                         ("2", "2.5", "4", "5", "10", "15", "20", "25", "40", "50", "75", "100",
                          "200", "400", "500", "800", "1000"))
SCALES_ENLARGEMENT = tuple(_s(n) for n in ("2", "2.5", "4", "5", "10", "20", "40", "50", "100"))

# Все допустимые масштабы, по возрастанию.
STANDARD_SCALES: tuple[Scale, ...] = tuple(sorted(SCALES_REDUCTION + (SCALE_NATURAL,) + SCALES_ENLARGEMENT))


def is_standard_scale(factor: float, tol: float = 1e-6) -> bool:
    return any(abs(s.factor - factor) <= tol for s in STANDARD_SCALES)


def nearest_scale_not_above(factor: float) -> Scale:
    """Наибольший стандартный масштаб, не превышающий factor (для подгонки на лист)."""
    candidates = [s for s in STANDARD_SCALES if s.factor <= factor + 1e-9]
    return candidates[-1] if candidates else STANDARD_SCALES[0]


def scale_from_factor(factor: float) -> Scale:
    for s in STANDARD_SCALES:
        if abs(s.factor - factor) < 1e-6:
            return s
    return Scale(Fraction(factor).limit_denominator(1000))


# --- ГОСТ 2.307: размеры, мм на листе
DIM_FIRST_OFFSET = 10.0   # от контура до первой размерной линии (не менее)
DIM_STEP = 7.0            # между параллельными размерными линиями (не менее)
DIM_EXT_OVERSHOOT = 2.0   # выход выносной линии за размерную (1…5)
DIM_TEXT_HEIGHT = 3.5     # высота размерных чисел по умолчанию


