# === 10/55 kompas_lib.core — kompas_lib/core.py
# ==================================================================================================================
"""Сессия КОМПАС-3D и базовый документ.

Работаем с **видимым** КОМПАСом пользователя: подключаемся к запущенному экземпляру
(или запускаем новый с окном). Все изменения документа выполняются внутри `Document.edit()`:
* подавляются модальные сообщения (иначе вызов может заблокироваться навсегда);
* изменения объединяются в один шаг отмены (Ctrl+Z пользователя откатывает всю операцию);
* по завершении документ перерисовывается.
"""

import os
import warnings
from contextlib import contextmanager
from pathlib import Path
from typing import TYPE_CHECKING, Iterator

_loader = _submodule('_loader')
# из kompas_lib.enums: DocumentType, HideMessage, raw
# из kompas_lib.errors: KompasBusyError, KompasError, NotConnectedError, OperationFailedError, WrongDocumentTypeError, check

# из kompas_lib.drawing: Drawing  (только для аннотаций)
# из kompas_lib.assembly: AssemblyDocument  (только для аннотаций)
# из kompas_lib.model: PartDocument  (только для аннотаций)

_DOC_TAG = "kompas_lib:"      # префикс метки документа в его комментарии (Document.tag)


class Kompas:
    """Подключение к запущенному КОМПАС-3D."""

    def __init__(self, app) -> None:
        self.raw = app
        self.ks = _loader.ks()
        self._quiet_depth = 0
        self._saved_hide: int | None = None

    # --- подключение -------------------------------------------------------------------------
    @classmethod
    def connect(cls, start: bool = False, bin_dir: str | os.PathLike | None = None) -> "Kompas":
        """Подключиться к запущенному КОМПАСу; при start=True — запустить новый, если не запущен."""
        ks = _loader.load(bin_dir)
        app = ks.GetKompas()
        if app is None and start:
            app = ks.OpenKompas()
        if app is None:
            raise NotConnectedError("КОМПАС-3D не запущен (или недоступен для KsAPI).")
        running = [os.path.normcase(str(p)) for p in _loader.running_kompas_dirs()]
        loaded = os.path.normcase(str(_loader.bin_dir()))
        if running and loaded not in running:
            warnings.warn(f"ksapi загружен из {loaded}, а запущен КОМПАС из {running}. "
                          "Версии API могут не совпадать; задайте KOMPAS_BIN.", RuntimeWarning, stacklevel=2)
        app.SetVisible(True)
        return cls(app)

    @property
    def version(self) -> str:
        return self.raw.GetApplicationName(True)

    @property
    def build(self) -> int:
        return self.raw.GetBuildNumber()

    # --- сообщения ---------------------------------------------------------------------------
    @contextmanager
    def quiet(self, mode: HideMessage = HideMessage.HIDE_NO) -> Iterator[None]:
        """Подавить модальные сообщения КОМПАСа на время блока (с восстановлением прежнего режима)."""
        if self._quiet_depth == 0:
            self._saved_hide = self.raw.GetHideMessage()
            self.raw.SetHideMessage(int(mode))
        self._quiet_depth += 1
        try:
            yield
        finally:
            self._quiet_depth -= 1
            if self._quiet_depth == 0 and self._saved_hide is not None:
                self.raw.SetHideMessage(self._saved_hide)

    # --- документы ---------------------------------------------------------------------------
    def wrap(self, raw_doc) -> "Document":
        """Обернуть ksapi-документ в класс библиотеки по его типу."""
        if raw_doc is None or not raw_doc:
            raise OperationFailedError("Получение документа", "пустой интерфейс")
        doc_type = DocumentType(raw_doc.GetDocumentType())
        if doc_type == DocumentType.DRAWING:
            # из kompas_lib.drawing: Drawing
            return Drawing(self, raw_doc)
        if doc_type == DocumentType.ASSEMBLY:
            # из kompas_lib.assembly: AssemblyDocument
            return AssemblyDocument(self, raw_doc)
        if doc_type == DocumentType.PART:
            # из kompas_lib.model: PartDocument
            return PartDocument(self, raw_doc)
        return Document(self, raw_doc)

    @property
    def documents(self) -> list["Document"]:
        docs = self.raw.GetDocuments()
        return [self.wrap(docs.GetItem(i)) for i in range(docs.GetCount())]

    @property
    def active_document(self) -> "Document | None":
        d = self.raw.GetActiveDocument()
        return self.wrap(d) if d else None

    def find_open(self, path: str | os.PathLike) -> "Document | None":
        """Документ, уже открытый в КОМПАСе, по пути к файлу."""
        d = self.raw.GetDocuments().GetItemByFilePath(str(Path(path).resolve()))
        return self.wrap(d) if d else None

    def open(self, path: str | os.PathLike, read_only: bool = False, visible: bool = True) -> "Document":
        """Открыть документ (или вернуть уже открытый)."""
        p = Path(path).resolve()
        if not p.is_file():
            raise FileNotFoundError(p)
        existing = self.find_open(p)
        if existing is not None:
            return existing
        with self.quiet():
            d = self.raw.GetDocuments().Open(str(p), visible, read_only)
        if not d:
            raise OperationFailedError("Открытие документа", str(p))
        return self.wrap(d)

    def new_drawing(self, fmt=None, landscape: bool | None = None, visible: bool = True,
                    tag: str | None = None) -> "Drawing":
        """Создать чертёж с настройками по умолчанию; при необходимости задать формат. `tag` — см. `find`."""
        with self.quiet():
            d = self.raw.GetDocuments().AddWithDefaultSettings(int(DocumentType.DRAWING), visible)
        drawing: "Drawing" = self.wrap(d)  # type: ignore[assignment]
        if tag:
            drawing.tag = tag
        if fmt is not None:
            drawing.sheet.set_format(fmt, landscape=True if landscape is None else landscape)
        return drawing  # type: ignore[return-value]

    def new_part(self, visible: bool = True, tag: str | None = None) -> "PartDocument":
        """Новая деталь. `tag` — метка, по которой её найдёт следующий скрипт (`find`) и закроет `close_tagged`."""
        with self.quiet():
            d = self.raw.GetDocuments().AddWithDefaultSettings(int(DocumentType.PART), visible)
        doc = self.wrap(d)
        if tag:
            doc.tag = tag
        return doc  # type: ignore[return-value]

    def new_assembly(self, visible: bool = True, tag: str | None = None) -> "AssemblyDocument":
        """Новая пустая сборка (см. `kompas_lib.assembly`). `tag` — см. `find`."""
        with self.quiet():
            d = self.raw.GetDocuments().AddWithDefaultSettings(int(DocumentType.ASSEMBLY), visible)
        doc = self.wrap(d)
        if tag:
            doc.tag = tag
        return doc  # type: ignore[return-value]

    # --- свои документы среди документов пользователя ---------------------------------------
    def find(self, tag: str) -> "Document | None":
        """Открытый документ с меткой `tag` (из `new_part(tag=…)` и т.п.); при нескольких — последний.

        Так следующий скрипт находит деталь предыдущего, а не берёт `k.documents[-1]` — в КОМПАСе пользователя
        это может быть чужой документ. Метка — комментарий документа (`IKompasDocument.SetComment`, spikes/s110).
        """
        found = [d for d in self.documents if d.tag == tag]
        return found[-1] if found else None

    def tagged(self, prefix: str = "") -> list["Document"]:
        """Документы с меткой kompas_lib (метка начинается с `prefix`); документы без метки сюда не попадают."""
        return [d for d in self.documents if d.tag is not None and d.tag.startswith(prefix)]

    def close_tagged(self, prefix: str = "", save: bool = False) -> int:
        """Закрыть свои документы (с меткой, начинающейся с `prefix`), не трогая документы пользователя.
        Вместо `for d in k.documents[1:]: d.close()` — та закрывает без сохранения и чужие. Возвращает число."""
        docs = self.tagged(prefix)
        for d in docs:
            d.close(save=save)
        return len(docs)

    @contextmanager
    def scratch_part(self, tag: str = "scratch", visible: bool = True) -> Iterator["PartDocument"]:
        """Временная деталь для эксперимента: создаётся с меткой и закрывается без сохранения на выходе из блока
        (и при исключении). Остатки упавших скриптов — `k.close_tagged("scratch")`.

            with k.scratch_part() as doc, doc.edit():
                b = PartBuilder(doc); ...
        """
        doc = self.new_part(visible, tag=tag)
        try:
            yield doc
        finally:
            try:
                doc.close(save=False)
            except KompasError:
                pass

    # --- растр -------------------------------------------------------------------------------
    def raster_params(self):
        """Новый объект IRasterConvertParameters."""
        conv = self.raw.GetConverter(int(raw.ksKOMPASConverterEnum.ksConverterToRaster))
        par = self.ks.IRasterConvertParameters(conv.GetConverterParameters(0))
        if not par:
            raise OperationFailedError("Получение параметров растра")
        return par

    def watchdog(self,on_dialog=None,interval=0.5):
        """Наблюдать за блокирующими диалогами в течение блока with."""
        # из kompas_lib.watchdog: ModalWatchdog
        return ModalWatchdog(int(self.raw.GetMainWindowHandle()),on_dialog,interval)


class Document:
    """Базовый документ КОМПАС."""

    def __init__(self, kompas: Kompas, raw_doc) -> None:
        self.kompas = kompas
        self.ks = kompas.ks
        self.raw = raw_doc

    def __repr__(self) -> str:
        return f"<{type(self).__name__} {self.name!r}>"

    # --- свойства ----------------------------------------------------------------------------
    @property
    def type(self) -> DocumentType:
        return DocumentType(self.raw.GetDocumentType())

    @property
    def name(self) -> str:
        return self.raw.GetName()

    @property
    def path(self) -> str:
        """Полный путь к файлу ('' для несохранённого документа)."""
        return self.raw.GetFullPath() or ""

    @property
    def is_changed(self) -> bool:
        return bool(self.raw.IsChanged())

    @property
    def tag(self) -> str | None:
        """Метка kompas_lib (`new_part(tag=…)`, `Kompas.find`); None — документ не помечен (например, пользователя).

        Хранится в комментарии документа с префиксом `kompas_lib:`; при сохранении попадает в файл.
        """
        comment = self.raw.GetComment() or ""
        return comment[len(_DOC_TAG):] if comment.startswith(_DOC_TAG) else None

    @tag.setter
    def tag(self, value: str | None) -> None:
        self.raw.SetComment(_DOC_TAG + value if value else "")

    # --- жизненный цикл ----------------------------------------------------------------------
    def activate(self) -> None:
        self.raw.SetActive()

    def save(self) -> None:
        with self.kompas.quiet():
            check(self.raw.Save(), "Сохранение документа", self.name)

    def save_as(self, path: str | os.PathLike) -> Path:
        p = Path(path).resolve()
        same_file = bool(self.path) and os.path.normcase(self.path) == os.path.normcase(str(p))
        if not same_file and self.kompas.find_open(p) is not None:
            raise KompasError(f"Файл {p} уже открыт в КОМПАСе другим документом; закройте его или выберите другое имя")
        p.parent.mkdir(parents=True, exist_ok=True)
        with self.kompas.quiet():
            check(self.raw.SaveAs(str(p)), "Сохранение документа", str(p))
        return p

    def close(self, save: bool = False) -> None:
        opt = raw.DocumentCloseOptions.kdSaveChanges if save else raw.DocumentCloseOptions.kdDoNotSaveChanges
        with self.kompas.quiet():
            check(self.raw.Close(int(opt)), "Закрытие документа", self.name)

    # --- редактирование ----------------------------------------------------------------------
    def _undo_iface(self):
        """Интерфейс с SetUndoContainer (2D или 3D документ) или None."""
        return None

    @property
    def busy(self) -> bool:
        """Пользователь выполняет в документе интерактивную команду."""
        return bool(self.raw.IsActiveProcessRunning())

    @contextmanager
    def edit(self, allow_busy: bool = False) -> Iterator["Document"]:
        """Блок изменений: без модальных сообщений, одним шагом отмены, с перерисовкой в конце."""
        if not allow_busy and self.busy:
            raise KompasBusyError(f"В документе {self.name!r} выполняется команда пользователя.")
        if hasattr(self, "_model_cache"):
            self.invalidate_geometry()
        undo = self._undo_iface()
        with self.kompas.quiet():
            nested = bool(undo and undo.IsUndoContainer())
            if undo and not nested:
                undo.SetUndoContainer(True)
            try:
                yield self
            finally:
                if hasattr(self, "_model_cache"):
                    self.invalidate_geometry()
                if undo and not nested:
                    undo.SetUndoContainer(False)
                if not nested:
                    self.redraw()

    def redraw(self) -> None:
        self.raw.RedrawDocument(int(raw.ksRedrawDocumentModeEnum.ksRedrawFull))

    # --- снимки ------------------------------------------------------------------------------
    def capture(self, dpi: int = 100, fmt=None, page: int = 0) -> bytes:
        """Растровое изображение документа (по умолчанию PNG), возвращает байты."""
        # из kompas_lib.capture: render_document
        return render_document(self, dpi=dpi, fmt=fmt, page=page)

    def require(self, *types: DocumentType) -> None:
        if self.type not in types:
            raise WrongDocumentTypeError(f"Ожидался документ типа {[t.name for t in types]}, а получен {self.type.name}")


