# ==================================================================================================================
"""3D-документ (деталь/сборка): свойства и геометрические факты для агента.

Грани и рёбра возвращаются как dataclass с распознанной геометрией (плоскость, цилиндр, конус,
отрезок, окружность…). Исходный объект KsAPI хранится в `.raw` — его можно передать в
`View.project_edge()` для получения проекции на чертеже.
"""

from dataclasses import dataclass, field
from contextlib import contextmanager
from typing import TYPE_CHECKING, Iterable

# из kompas_lib.core: Document
# из kompas_lib.enums: raw
# из kompas_lib.errors: OperationFailedError, check
# из kompas_lib.vec3: Vec3, rounded

if TYPE_CHECKING:
    pass

_O3D = raw.ksObj3dTypeEnum


@dataclass(frozen=True)
class Box3:
    x1: float
    y1: float
    z1: float
    x2: float
    y2: float
    z2: float

    @property
    def size(self) -> Vec3:
        return (self.x2 - self.x1, self.y2 - self.y1, self.z2 - self.z1)

    @property
    def center(self) -> Vec3:
        return ((self.x1 + self.x2) / 2, (self.y1 + self.y2) / 2, (self.z1 + self.z2) / 2)


@dataclass
class Face:
    """Грань тела."""
    index: int
    kind: str                       # plane | cylinder | cone | sphere | torus | other
    area: float
    box: Box3
    radius: float | None = None     # цилиндр, сфера; для конуса — радиус основания
    axis_origin: Vec3 | None = None  # ось вращения (цилиндр, конус, тор)
    axis_dir: Vec3 | None = None
    normal: Vec3 | None = None      # плоскость: нормаль в начале параметризации
    raw: object = field(default=None, repr=False, compare=False)
    cone_angle: float | None = None  # угол полураствора конуса, градусы
    minor_radius: float | None = None  # радиус образующей тора
    internal: bool | None = None    # ориентированная нормаль цилиндра направлена к оси
    major_radius: float | None = None  # радиус осевой окружности тора
    point: Vec3 | None = None       # плоскость: точка на ней (середина параметров поверхности)
    outward: Vec3 | None = None     # плоскость: нормаль наружу из тела (с учётом ориентации грани)
    sweep: float | None = None      # цилиндр, конус, тор: охват вокруг оси, градусы (360 — полный, 90 — скругление)
    ends: tuple | None = None       # цилиндр, конус: ((t0, r0), (t1, r1)) — концы вдоль axis_dir от axis_origin
                                    # и радиусы на них; заполняет `build.drawing_check.measure_model`
    arc: tuple | None = None        # цилиндр < 360°: точки при Umin, Uср, Umax посередине V (там же)
    key: int | None = None          # ключ грани — тот же, что в `Edge.faces` (s112)


@dataclass
class Edge:
    """Ребро тела.

    Топология (s112): `key` — ключ ребра, `faces` — ключи двух смежных граней (`Face.key`), `vertices` — ключи
    начальной и конечной вершин (у замкнутой окружности совпадают). Ключи стабильны между запросами и после
    следующих операций, пока объект жив; по ним отбирают «ребро между гранями А и Б» без координат.
    """
    index: int
    kind: str                       # line | circle | arc | ellipse | other
    length: float
    box: Box3
    start: Vec3 | None = None
    end: Vec3 | None = None
    center: Vec3 | None = None      # окружность / дуга
    radius: float | None = None
    normal: Vec3 | None = None      # нормаль плоскости окружности (= ось)
    raw: object = field(default=None, repr=False, compare=False)
    key: int | None = None
    faces: tuple = ()               # (ключ грани +, ключ грани −) — IEdge.GetAdjacentFace(True/False)
    vertices: tuple = ()            # (ключ начальной вершины, ключ конечной)
    convexity: str | None = None    # convex | concave | smooth (грани стыкуются по касательной) | None
    tangents: tuple = ()            # единичные касательные в начале и в конце (по направлению ребра)
    mid: Vec3 | None = None         # точка в середине параметра (у дуги — какая из двух дуг окружности)


def _vec(t) -> Vec3:
    return (rounded(t[1]), rounded(t[2]), rounded(t[3]))


def read_faces(ks, part, objects=None, *, kinds: str | Iterable[str] | None = None) -> list[Face]:
    """Грани тел `part` (деталь или компонент сборки) в собственной СК её файла.

    Для компонента сборки координаты не зависят от его положения (spikes/s81, s83): в СК сборки их переводит
    `IPart.GetSummMatrix` головной детали. `objects` — готовый список граней KsAPI (например, грани операции).
    """
    if objects is None:
        feat = ks.IFeature(part)
        if not feat:
            raise OperationFailedError("Доступ к элементам детали")
        objects = feat.GetModelObjects([int(_O3D.o3d_face)])
    wanted = {kinds} if isinstance(kinds, str) else set(kinds) if kinds is not None else None
    result = []
    for i, f in enumerate(objects or []):
        ms = ks.IMathSurface3D(f.GetMathObject())
        if not ms:
            continue
        surface_kind = next((name for name, test in (("plane", ms.IsPlanar), ("cylinder", ms.IsCylinder),
                            ("cone", ms.IsCone), ("torus", ms.IsTorus), ("sphere", ms.IsSphere)) if test()), "other")
        if wanted is not None and surface_kind not in wanted:
            continue
        box = Box3(*ms.GetGabarit(0, 0, 0, 0, 0, 0)[1:7])
        # IMathSurface3D.GetArea возвращает 0 для поверхностей граней.
        # IFace считает площадь обрезанной грани, с отверстиями и границами.
        iface = ks.IFace(f)
        area = float(iface.GetArea(int(raw.ksLengthUnitsEnum.ksLUnMM)))
        face = Face(i, surface_kind, area, box, raw=f, key=int(ks.GetReference(iface)))
        if surface_kind == "plane":
            u = (ms.GetParamUMin() + ms.GetParamUMax()) / 2
            v = (ms.GetParamVMin() + ms.GetParamVMax()) / 2
            face.normal = _vec(ms.GetNormal(u, v, 0, 0, 0))
            face.point = _vec(ms.GetPoint(u, v, 0, 0, 0))
            sign = 1 if iface.GetNormalOrientation() else -1
            face.outward = tuple(rounded(sign * c) for c in face.normal)  # type: ignore[assignment]
        elif surface_kind in ("cylinder", "cone", "torus", "sphere"):
            face.radius = rounded(ms.GetRadius())
            if face.kind == "cone":
                from math import degrees
                param = ms.GetConeParam(0, 0, 0)
                if param[0]:
                    face.cone_angle = rounded(abs(degrees(param[2])))
            elif face.kind == "torus":
                param = ms.GetTorusParam(0, 0)
                if param[0]:
                    # KsAPI v26 возвращает (ok, радиус образующей, радиус осевой окружности),
                    # несмотря на обратные имена аргументов в SDK. Проверено по дугам разреза.
                    face.minor_radius = rounded(param[1])
                    face.major_radius = rounded(param[2])
            pl = ms.GetPlacement()
            if pl:
                face.axis_origin = _vec(pl.GetOrigin(0, 0, 0))
                face.axis_dir = _vec(pl.GetVector(int(_O3D.o3d_axisOZ), 0, 0, 0))
            if face.kind in ("cylinder", "cone", "torus"):
                # U — угол вокруг оси: 2π у целого отверстия, π/2 у скругления ребра (spikes/s105)
                u0, u1 = ms.GetParamUMin(), ms.GetParamUMax()
                sweep = (u1 - u0) * 57.29577951308232
                face.sweep = rounded(sweep) if 0.0 < sweep <= 360.5 else None
            if face.kind == "cylinder" and face.axis_origin and face.axis_dir:
                u = (u0 + u1) / 2
                v = (ms.GetParamVMin() + ms.GetParamVMax()) / 2
                p, n = ms.GetPoint(u, v, 0, 0, 0), ms.GetNormal(u, v, 0, 0, 0)
                if p[0] and n[0]:
                    direction = 1 if iface.GetNormalOrientation() else -1
                    vector = [p[j+1]-face.axis_origin[j] for j in range(3)]
                    face.internal = direction*sum(vector[j]*n[j+1] for j in range(3)) < 0
        result.append(face)
    return result


class PartDocument(Document):
    """Документ детали (или сборки) и его верхний компонент."""

    def __init__(self, kompas, raw_doc) -> None:
        super().__init__(kompas, raw_doc)
        self.d3 = self.ks.IKompasDocument3D(raw_doc)
        self._model_cache_depth = 0
        self._model_cache: dict = {}
        self._model_cache_identity = None

    @contextmanager
    def geometry_cache(self):
        """Повторные чтения геометрии/МЦХ без повторного обхода KsAPI внутри блока.

        Операции PartBuilder, переменные и смена исполнения сбрасывают кэш. Вход/выход из edit()
        тоже сбрасывает его. После сырых Set*/Update/Rebuild внутри блока обязательно вызвать
        invalidate_geometry(). Изменения другим интерфейсом/в UI внутри блока не отслеживаются;
        вне блока никакие снимки не сохраняются. Верхняя деталь никогда не кэшируется.
        """
        self._model_cache_depth += 1
        try:
            yield self
        finally:
            self._model_cache_depth -= 1
            if not self._model_cache_depth:
                self.invalidate_geometry()

    def invalidate_geometry(self) -> None:
        """Сбросить снимки геометрии и МЦХ после низкоуровневых изменений."""
        self._model_cache.clear()
        self._model_cache_identity = None

    def _cached_model_read(self, key, read):
        if not self._model_cache_depth:
            return read()
        part = self.part
        # IPart в каждом исполнении свой. Нормализуем интерфейс: указатели разных обёрток не равны.
        identity = int(self.ks.GetReference(self.ks.IPart(part)))
        if identity != self._model_cache_identity:
            self.invalidate_geometry()
            self._model_cache_identity = identity
        if key not in self._model_cache:
            self._model_cache[key] = read()
        return self._model_cache[key]

    @property
    def part(self):
        """Верхний компонент **текущего исполнения**.

        Не кэшируется: после `SetCurrentEmbodiment` у документа другая верхняя деталь, и операции, добавленные
        через старый объект, уходят в прежнее исполнение (spikes/s90).
        """
        return self.d3.GetTopPart()

    def _undo_iface(self):
        return self.d3

    # --- свойства ----------------------------------------------------------------------------
    @property
    def designation(self) -> str:
        """Обозначение (децимальный номер)."""
        return self.part.GetMarking()

    @designation.setter
    def designation(self, value: str) -> None:
        self.invalidate_geometry()
        self.part.SetMarking(value)
        self.part.Update()

    @property
    def title(self) -> str:
        """Наименование."""
        return self.part.GetName()

    @title.setter
    def title(self, value: str) -> None:
        self.invalidate_geometry()
        self.part.SetName(value)
        self.part.Update()

    @property
    def material(self) -> str:
        return self.part.GetMaterial()

    def set_material(self, name: str, density: float) -> None:
        """Материал и плотность (г/см³)."""
        self.invalidate_geometry()
        self.part.SetMaterial(name, density)
        self.part.Update()

    @property
    def mass(self) -> float:
        """Масса, г (как возвращает KsAPI)."""
        return float(self.part.GetMass())

    @property
    def density(self) -> float:
        return float(self.part.GetDensity())

    def info(self) -> dict:
        """Сводка для агента."""
        return {
            "name": self.title, "designation": self.designation, "material": self.material,
            "mass_g": round(self.mass, 3), "box": self.box().__dict__,
            "faces": len(self._objects(_O3D.o3d_face)), "path": self.path,
        }

    # --- геометрия ---------------------------------------------------------------------------
    def box(self) -> Box3:
        """Габарит тел детали (без системных плоскостей)."""
        res = check(self.part.GetGabarit(False, False, 0, 0, 0, 0, 0, 0), "Габарит детали")
        return Box3(*res[1:7])

    def _objects(self, obj_type: int) -> list:
        feat = self.ks.IFeature(self.part)
        if not feat:
            raise OperationFailedError("Доступ к элементам детали")
        return feat.GetModelObjects([int(obj_type)])

    def faces(self, *, kinds: str | Iterable[str] | None = None) -> list[Face]:
        """Грани тел документа с распознанным типом поверхности.

        Для сборки — только тела самой сборки: грани компонентов не обходятся (у сборки 5М — 0 граней при
        1264 деталях, spikes/s19). Для образмеривания детали открывайте её файл.
        """
        wanted = (kinds,) if isinstance(kinds, str) else tuple(sorted(set(kinds))) if kinds is not None else None

        def read():
            full = self._model_cache.get(("faces", None)) if self._model_cache_depth else None
            if wanted is not None and full is not None:
                return [face for face in full if face.kind in wanted]
            return read_faces(self.ks, self.part, kinds=wanted)
        return list(self._cached_model_read(("faces", wanted), read))

    def features(self, tol: float = 1e-3, faces=None):
        """Распознанные элементы и данные модельных резьб для 2D/3D-оформления."""
        # из kompas_lib.dims.features: recognize_features, Thread
        faces = self.faces() if faces is None else faces
        features = recognize_features(faces, tol=tol)
        collection = self.ks.ISymbols3DContainer(self.part).GetThreads()
        by_reference = {face.key: face.index for face in faces}
        for obj in collection.GetObjects():
            thread = self.ks.IThread(obj)
            params = self.ks.IThreadsParameters(obj)
            features.threads.append(Thread(
                designation=params.GetDesignation() if params else "",
                diameter=float(params.GetDiameter()) if params else None,
                pitch=float(params.GetPitch()) if params else None,
                length=float(thread.GetLength()), left=bool(thread.IsLeftThread()),
                raw=obj,
                faces=tuple(by_reference[face_key(self.ks, face)] for face in thread.GetThreadFaces()
                            if face_key(self.ks, face) in by_reference),
            ))
        return features

    def auto_dimension(self, **kwargs):
        """Автоматически поставить ассоциативные 3D-размеры, вернуть отчёт."""
        # из kompas_lib.dims.model: auto_dimension_model
        return auto_dimension_model(self, **kwargs)

    def edges(self) -> list[Edge]:
        return list(self._cached_model_read("edges", lambda: read_edges(self.ks, self._objects(_O3D.o3d_edge))))


def face_key(ks, obj) -> int:
    """Ключ грани: указатель интерфейса `IFace` стабилен для одной грани — из детали, из операции, из
    `IEdge.GetAdjacentFace`, `IFace.GetConnectedFaces` (s112c). Сам `GetReference(obj)` у разных обёрток разный."""
    return int(ks.GetReference(ks.IFace(obj)))


def edge_key(ks, obj) -> int:
    """Ключ ребра (как `face_key`, через `IEdge`)."""
    return int(ks.GetReference(ks.IEdge(obj)))


def _api_key(ks, obj) -> int | None:
    return int(ks.GetReference(obj)) if obj is not None else None


def _unit_tangent(t) -> Vec3 | None:
    if not t or not t[0]:
        return None
    x, y, z = float(t[1]), float(t[2]), float(t[3])
    n = (x * x + y * y + z * z) ** 0.5
    return (x / n, y / n, z / n) if n > 1e-12 else None


_CONVEXITY = {1: "convex", -1: "concave", 0: "smooth"}
# Порог «гладкого» стыка граней для IEdge.GetAngleType, рад (≈0,06°): касательные грани — smooth (s112).
SMOOTH_ANGLE = 1e-3


def read_edges(ks, objects) -> list[Edge]:
    """Рёбра тел из объектов KsAPI (все рёбра детали, рёбра операции `IFeature(op).GetModelObjects`…).

    `IFeature(part).GetModelObjects([o3d_edge])` отдаёт и рёбра эскизов, и оси начала координат (у бруска
    19 вместо 12, фаска по такому — ошибка 36, spikes/s109): у них нет смежных граней — пропускаются.
    Топология ребра (`key`, `faces`, `vertices`, `convexity`, `tangents`) — для отбора без координат (s112).
    """
    result = []
    for i, e in enumerate(objects or []):
        ie = ks.IEdge(e)
        if not ie:
            continue
        fp, fm = ie.GetAdjacentFace(True), ie.GetAdjacentFace(False)
        if fp is None and fm is None:
            continue
        mc = ks.IMathCurve3D(e.GetMathObject())
        if not mc:
            continue
        box = Box3(*mc.GetGabarit(0, 0, 0, 0, 0, 0)[1:7])
        t0, t1 = mc.GetParamMin(), mc.GetParamMax()
        edge = Edge(i, "other", float(mc.GetLength(int(raw.ksLengthUnitsEnum.ksLUnMM))), box, raw=e)
        edge.start = _vec(mc.GetPoint(t0, 0, 0, 0))
        edge.end = _vec(mc.GetPoint(t1, 0, 0, 0))
        edge.mid = _vec(mc.GetPoint((t0 + t1) / 2, 0, 0, 0))
        edge.key = _api_key(ks, ie)
        edge.faces = (_api_key(ks, fp), _api_key(ks, fm))
        edge.vertices = (_api_key(ks, ie.GetVertex(True)), _api_key(ks, ie.GetVertex(False)))
        edge.tangents = (_unit_tangent(mc.GetTangentVector(t0, 0, 0, 0)), _unit_tangent(mc.GetTangentVector(t1, 0, 0, 0)))
        if fp is not None and fm is not None:
            edge.convexity = _CONVEXITY.get(int(ie.GetAngleType(SMOOTH_ANGLE)))
        if mc.IsLineSeg() or mc.IsStraight():
            edge.kind = "line"
        elif (is_circle := mc.IsCircle()) or mc.IsArc():
            edge.kind = "circle" if is_circle else "arc"
            edge.center = _vec(mc.GetCentre(0, 0, 0))
            edge.radius = rounded(mc.GetRadius())
            pl = mc.GetPlacement()
            if pl:
                edge.normal = _vec(pl.GetVector(int(_O3D.o3d_axisOZ), 0, 0, 0))
        elif mc.IsEllipse() or mc.IsEllipseArc():
            edge.kind = "ellipse"
        result.append(edge)
    return result


# ==================================================================================================================
# === 12/55 kompas_lib.capture — kompas_lib/capture.py
# ==================================================================================================================
"""Снимки документов КОМПАС: лист чертежа целиком, область листа, 3D-модель с заданного ракурса.

Растр формирует сам КОМПАС (`SaveAsToRasterFormat`), результат возвращается байтами без временных файлов.
Обрезка области листа требует Pillow (`pip install kompas-lib[imaging]`).
"""

import io
from contextlib import contextmanager
from typing import TYPE_CHECKING, Iterator

# из kompas_lib.enums: PROJECTION_NAMES, Projection, RasterFormat
# из kompas_lib.errors: KompasError, OperationFailedError, check
# из kompas_lib.geom: Rect

# из kompas_lib.core: Document  (только для аннотаций)
# из kompas_lib.model: PartDocument  (только для аннотаций)

MM_PER_INCH = 25.4


def render_document(doc: "Document", dpi: int = 100, fmt: RasterFormat | None = None, page: int = 0) -> bytes:
    """Растр документа (для чертежа — лист `page`, для модели — текущий вид окна)."""
    par = doc.kompas.raster_params()
    par.SetRasterFormat(int(fmt or RasterFormat.PNG))
    par.SetResolution(int(dpi))
    par.SetReturnResultAsArrayBytes(True)
    with doc.kompas.quiet():
        check(doc.raw.SaveAsToRasterFormat("", par), "Растровый экспорт", doc.name)
    pages = par.GetResultArrayBytes() or []
    if page >= len(pages):
        raise OperationFailedError("Растровый экспорт", f"нет страницы {page} (всего {len(pages)})")
    return bytes(pages[page])


def crop_sheet(png: bytes, sheet_size: tuple[float, float], region: Rect, pad: float = 2.0) -> bytes:
    """Вырезать из растра листа область `region` (мм листа, Y вверх) с полем `pad` мм."""
    try:
        from PIL import Image
    except ImportError as e:  # pragma: no cover
        raise KompasError("Для вырезки области нужен Pillow: pip install kompas-lib[imaging]") from e
    img = Image.open(io.BytesIO(png))
    w_mm, h_mm = sheet_size
    kx, ky = img.width / w_mm, img.height / h_mm
    r = region.inflate(pad)
    box = (
        max(0, int(r.x1 * kx)), max(0, int((h_mm - r.y2) * ky)),
        min(img.width, int(round(r.x2 * kx))), min(img.height, int(round((h_mm - r.y1) * ky))),
    )
    if box[2] <= box[0] or box[3] <= box[1]:
        raise KompasError(f"Область {region.as_tuple()} вне листа {w_mm:g}×{h_mm:g} мм — снимать нечего")
    out = io.BytesIO()
    img.crop(box).save(out, format="PNG")
    return out.getvalue()


_AUX_FLAGS = ("Planes", "Axis", "Sketches", "Places", "Surfaces", "Curves", "ControlPoints", "AuxiliaryGeom")


@contextmanager
def hidden_auxiliary(part_doc: "PartDocument", hide_dimensions: bool = False) -> Iterator[None]:
    """Временно скрыть в 3D вспомогательные объекты (плоскости, оси, эскизы…)."""
    d3 = part_doc.d3
    # AuxiliaryGeom включает и аннотации. Отдельные группы скрывают вспомогательную
    # геометрию, сохраняя размеры и обозначения при hide_dimensions=False.
    flags = [f for f in _AUX_FLAGS if f != "AuxiliaryGeom" or hide_dimensions]
    flags += ["Dimensions", "Designations"] if hide_dimensions else []
    saved = {f: getattr(d3, f"IsHideAll{f}")() for f in flags}
    try:
        for f in flags:
            getattr(d3, f"SetHideAll{f}")(True)
        yield
    finally:
        for f, v in saved.items():
            getattr(d3, f"SetHideAll{f}")(v)
        part_doc.redraw()


def model_dpi(part_doc: "PartDocument", max_px: int, dpi: int) -> int:
    """Разрешение, при котором снимок модели не превысит `max_px` по длинной стороне.

    КОМПАС растрирует модель в натуральную величину: пиксели = размер в мм / 25.4 · dpi (сборка 3.8 м при 96 dpi —
    262 Мпикс, spikes/s19). Оценка сверху — диагональ габарита (проекция при любом ракурсе не больше её).
    """
    try:
        b = part_doc.box()
        diag = ((b.x2 - b.x1) ** 2 + (b.y2 - b.y1) ** 2 + (b.z2 - b.z1) ** 2) ** 0.5
    except Exception:  # noqa: BLE001 — нет тел/габарита: оставляем dpi как есть
        return int(dpi)
    if diag <= 0:
        return int(dpi)
    return max(MIN_MODEL_DPI, min(int(dpi), int(max_px * MM_PER_INCH / diag)))


MIN_MODEL_DPI = 5


def render_model(part_doc: "PartDocument", projection: Projection | str | None = Projection.ISO,
                 dpi: int = 100, hide_auxiliary: bool = True, restore_view: bool = True,
                 max_px: int | None = 2000) -> bytes:
    """Снимок 3D-модели с заданного ракурса.

    `projection` — стандартная проекция (Projection) или имя проекции модели ('#Изометрия',
    пользовательская 'Вид 1'…). None — текущий вид окна. Если restore_view=True, после снимка
    восстанавливается исходная ориентация камеры пользователя.
    `max_px` — предел длинной стороны снимка в пикселях (dpi уменьшается по габариту модели); None — без предела.
    """
    if max_px is not None:
        dpi = model_dpi(part_doc, max_px, dpi)
    vpm = part_doc.d3.GetViewProjectionManager()
    saved_matrix = vpm.GetMatrix3D() if restore_view else None
    saved_scale = vpm.GetScale() if restore_view else None
    try:
        if projection is not None:
            name = PROJECTION_NAMES[projection] if isinstance(projection, Projection) else projection
            vp = vpm.GetViewProjectionByName(name)
            if not vp:
                raise OperationFailedError("Выбор проекции", f"нет проекции {name!r}")
            vp.SetCurrent(True)
        if hide_auxiliary:
            with hidden_auxiliary(part_doc):
                return render_document(part_doc, dpi=dpi)
        return render_document(part_doc, dpi=dpi)
    finally:
        if saved_matrix is not None:
            vpm.SetMatrix3D(saved_matrix, saved_scale)


# ==================================================================================================================
# === 13/55 kompas_lib.pdf_drawing — kompas_lib/pdf_drawing.py
# ==================================================================================================================
"""Чертёж из PDF любого происхождения: что можно прочитать машинно и что — только глазами.

PDF бывает разный: вектор с настоящим текстом (КОМПАС, SolidWorks, NX…), вектор с битой
кодировкой шрифта, текст «в кривых» (AutoCAD SHX), скан. Модуль не угадывает чертёж целиком:

* `PdfPage.kind` — можно ли доверять текстовому слою (`text`) или читать только по растру
  (`garbled` / `curves` / `raster` / `empty`);
* при `kind == "text"` — надписи с координатами и разбором: Ø, R, M, углы, линейные, `*` справочные,
  «N мест», обозначения видов `А`, `Д-Д`, `Б(2:1)`, масштаб;
* `views()` — виды листа (группы основных линий): габарит, обозначение, масштаб; `view.geometry()` — его
  линии в мм модели без ручного выбора области и начала координат;
* `geometry(region, scale=, origin=)` — линии вида в мм модели: отрезки, дуги, окружности с погрешностью
  радиуса (`kompas_lib.pdf_geometry`) — координаты и радиусы, которых нет в надписях;
* `export_images()` / `render()` — PNG листа, фрагментов и штампа, которые агент смотрит сам
  (вместо OCR). Работает для любого PDF; размер картинок ограничен `MAX_PX`, чтобы при просмотре
  их не уменьшали и мелкий текст оставался читаемым.

Координаты — мм листа, начало в левом нижнем углу, Y вверх (как `Rect` и листы КОМПАСа).
Текстовый слой может нести правдоподобные, но неверные символы — спорное сверяйте по картинке.

    pdf = read_pdf_drawing("Задание.pdf")
    print(pdf.summary())                       # тип листа + разобранные надписи (если есть текст)
    files = pdf.export_images("out/sheet")     # обзор, фрагменты r1c1…, штамп — открыть и прочитать
    pdf.render(0, Rect(100, 50, 250, 150), out="out/zoom.png")   # приблизить спорное место

Требует PyMuPDF (`pip install kompas-lib[pdf]`).
"""

import math
import os
import re
from collections import Counter
from dataclasses import dataclass, field
from pathlib import Path
from typing import TYPE_CHECKING

# из kompas_lib.geom: Rect

# из kompas_lib.pdf_geometry: PdfView, ViewGeometry  (только для аннотаций)

PT_MM = 25.4 / 72.0
MAX_PX = 1568   # длинная сторона картинки, которую модель видит без уменьшения

# ГОСТ 2.104: основная надпись 185×55 в правом нижнем углу рамки, поле рамки слева 20, прочие 5.
_FRAME_LEFT, _FRAME_OTHER = 20.0, 5.0
_STAMP_W, _STAMP_H = 185.0, 55.0
_FORMATS = {"A0": (841, 1189), "A1": (594, 841), "A2": (420, 594), "A3": (297, 420), "A4": (210, 297)}

_NUM = r"\d+(?:[.,]\d+)?"
_DIAMETER = "⌀Ø∅øΦ"
_PATTERNS = {
    "count_prefix": re.compile(rf"^(\d+)\s*отв\.?\s*(.+)$", re.I),
    "diameter": re.compile(rf"^[{_DIAMETER}]\s*({_NUM})(.*)$"),
    "radius": re.compile(rf"^R\s*({_NUM})(.*)$"),
    "thread": re.compile(rf"^[MМ]\s*({_NUM})(.*)$"),
    "angle": re.compile(rf"^({_NUM})\s*°(.*)$"),
    "scale": re.compile(rf"^(?:М\s*)?({_NUM}):({_NUM})$"),
    "view": re.compile(rf"^([А-ЯЁA-Z])(?:\s*[-–]\s*\1)?\s*(?:\(\s*({_NUM}:{_NUM})\s*\))?$"),
    "count": re.compile(r"^(\d+)\s*([а-яё]{2,10}\.?)$", re.I),
    "linear": re.compile(rf"^({_NUM})(.*)$"),
}
_DIMENSIONS = ("diameter", "radius", "thread", "angle", "linear")
# Символы, ожидаемые на чертеже ЕСКД/ISO; прочее — признак битой кодировки шрифта.
_GOOD_SYMBOLS = set("⌀Ø∅°±×«»—–…№′″≈≤≥∠⊥∥□⌒")


@dataclass
class Annotation:
    """Надпись чертежа из текстового слоя."""
    id: str
    page: int
    text: str
    kind: str                   # diameter radius thread angle linear scale view count text
    bbox: Rect                  # мм листа, Y вверх
    angle: float = 0.0          # направление строки, градусы против часовой
    height: float = 0.0         # высота шрифта, мм
    value: float | None = None  # номинал (Ø, R, M, угол, линейный) или масштаб вида
    count: int | None = None    # «6 мест», «4 отв.»
    reference: bool = False     # справочный размер «*»
    suffix: str = ""            # остаток надписи: допуск, посадка, шаг резьбы…
    label: str = ""             # обозначение вида: «Д», «Б»
    scale: str = ""             # «2:1» у вида или масштаб листа
    zone: str = "field"         # field | stamp | margin
    source: str = "text"

    def short(self) -> str:
        x, y = self.bbox.center.x, self.bbox.center.y
        extra = []
        if self.count:
            extra.append(f"×{self.count}")
        if self.reference:
            extra.append("справ.")
        if self.scale and self.kind == "view":
            extra.append(f"масштаб {self.scale}")
        tail = f" [{', '.join(extra)}]" if extra else ""
        rot = f" {self.angle:g}°" if self.angle else ""
        return f"{self.id} {self.kind:<8} {self.text!r}{tail} @({x:.0f},{y:.0f}){rot}"


@dataclass
class PdfPage:
    index: int
    width: float                 # мм
    height: float
    format: str | None           # A0…A4 по размеру листа (±3 мм), иначе None
    kind: str                    # text | garbled | curves | raster | empty
    text_quality: float          # доля ожидаемых символов в текстовом слое, 0…1
    chars: int                   # непробельных символов в текстовом слое
    paths: int                   # векторных путей
    image_coverage: float        # доля площади листа под растровыми картинками
    annotations: list[Annotation] = field(default_factory=list)

    @property
    def frame(self) -> Rect:
        """Внутренняя рамка по ГОСТ 2.104 (для листа другого стандарта — приблизительно)."""
        return Rect(_FRAME_LEFT, _FRAME_OTHER, self.width - _FRAME_OTHER, self.height - _FRAME_OTHER)

    @property
    def stamp(self) -> Rect:
        """Место основной надписи по ГОСТ 2.104: правый нижний угол рамки, 185×55."""
        f = self.frame
        return Rect(max(f.x1, f.x2 - _STAMP_W), f.y1, f.x2, min(f.y2, f.y1 + _STAMP_H))

    @property
    def text_usable(self) -> bool:
        return self.kind == "text"

    def tiles(self, rows: int = 2, cols: int = 2, overlap: float = 15.0) -> list[Rect]:
        """Области рамки сеткой rows×cols с перекрытием (мм) — для чтения листа по частям."""
        f = self.frame
        w, h = f.width / cols, f.height / rows
        result = []
        for r in range(rows):           # сверху вниз, слева направо
            for c in range(cols):
                x1, y2 = f.x1 + c * w, f.y2 - r * h
                result.append(Rect(max(f.x1, x1 - overlap), max(f.y1, y2 - h - overlap),
                                   min(f.x2, x1 + w + overlap), min(f.y2, y2 + overlap)))
        return result

    def find(self, kind: str | None = None, zone: str | None = None) -> list[Annotation]:
        return [a for a in self.annotations
                if (kind is None or a.kind == kind) and (zone is None or a.zone == zone)]

    def summary(self) -> str:
        fmt = self.format or "нестандартный"
        lines = [f"Лист {self.index + 1}: {self.width:.0f}×{self.height:.0f} мм ({fmt}), kind={self.kind}, "
                 f"текст {self.chars} симв. (качество {self.text_quality:.2f}), путей {self.paths}, "
                 f"растр {self.image_coverage:.0%}"]
        if self.kind != "text":
            lines.append("  Текстовому слою доверять нельзя — читайте лист глазами: export_images() → PNG.")
            return "\n".join(lines)
        if self.image_coverage > 0.5:
            lines.append("  Под текстом скан: текстовый слой может быть чужим OCR — сверяйте по растру.")
        for zone, title in (("field", "Поле чертежа"), ("stamp", "Основная надпись"), ("margin", "Поля рамки")):
            items = self.find(zone=zone)
            if items:
                lines.append(f"  {title}:")
                lines += [f"    {a.short()}" for a in items]
        return "\n".join(lines)


@dataclass
class PdfDrawing:
    path: Path
    pages: list[PdfPage]

    def annotations(self) -> list[Annotation]:
        return [a for p in self.pages for a in p.annotations]

    def summary(self) -> str:
        return "\n".join([f"{self.path.name}: {len(self.pages)} лист(ов)"] + [p.summary() for p in self.pages])

    def render(self, page: int = 0, region: Rect | None = None, dpi: float | None = None,
               max_px: int = MAX_PX, out: str | os.PathLike | None = None) -> bytes:
        """PNG листа или области (мм листа, Y вверх). При `out` ещё и пишет файл.

        Без `dpi` разрешение подбирается так, чтобы длинная сторона была `max_px`: больше агенту
        не нужно — картинку всё равно ужмут при просмотре, и мелкий текст пропадёт.
        """
        fitz = _fitz()
        with fitz.open(self.path) as doc:
            pg = doc[page]
            h = pg.rect.height
            if region is None:
                region = Rect(0, 0, pg.rect.width * PT_MM, h * PT_MM)
            clip = fitz.Rect(region.x1 / PT_MM, h - region.y2 / PT_MM,
                             region.x2 / PT_MM, h - region.y1 / PT_MM) & pg.rect
            zoom = (dpi / 72.0) if dpi else min(600 / 72.0, max_px / max(clip.width, clip.height, 1e-6))
            png = pg.get_pixmap(matrix=fitz.Matrix(zoom, zoom), clip=clip).tobytes("png")
        if out is not None:
            Path(out).write_bytes(png)
        return png

    def export_images(self, out_dir: str | os.PathLike, page: int = 0, px_per_mm: float = 6.0,
                      max_px: int = MAX_PX) -> list[Path]:
        """Растр для чтения глазами: обзор листа, фрагменты рамки и штамп — PNG-файлы в `out_dir`.

        Сетка подбирается так, чтобы во фрагменте было не меньше `px_per_mm` пикселей на мм листа
        (6 px/мм — шрифт 3,5 мм ≈ 20 px, цифры читаются). Порядок фрагментов: сверху вниз, слева направо.
        """
        out = Path(out_dir)
        out.mkdir(parents=True, exist_ok=True)
        p = self.pages[page]
        f = p.frame
        cols = max(1, math.ceil(f.width * px_per_mm / max_px))
        rows = max(1, math.ceil(f.height * px_per_mm / max_px))
        stem = f"{self.path.stem}_p{page + 1}"
        files = [out / f"{stem}_overview.png", out / f"{stem}_stamp.png"]
        self.render(page, None, max_px=max_px, out=files[0])
        self.render(page, p.stamp, max_px=max_px, out=files[1])
        if rows * cols > 1:
            for i, box in enumerate(p.tiles(rows, cols)):
                r, c = divmod(i, cols)
                name = out / f"{stem}_r{r + 1}c{c + 1}.png"
                self.render(page, box, max_px=max_px, out=name)
                files.append(name)
        return files

    def geometry(self, region: Rect, page: int = 0, **kw) -> "ViewGeometry":
        """Отрезки, дуги и окружности вида в области `region` (мм листа) — в мм модели:
        `scale="1:2"`, `origin=(x, y)` мм листа, `min_width`, `tol` — см. `pdf_geometry.view_geometry`."""
        # из kompas_lib.pdf_geometry: view_geometry
        return view_geometry(self.path, region, page=page, **kw)

    def views(self, page: int = 0) -> list["PdfView"]:
        """Виды листа: габарит, обозначение («А», «Д-Д», «Б(2:1)»), масштаб; `view.geometry()` — линии вида
        в мм модели от левого нижнего угла габарита. См. `pdf_geometry.find_views`."""
        # из kompas_lib.pdf_geometry: find_views
        return find_views(self.path, self.pages[page])


# --- разбор надписи -------------------------------------------------------------------------------
def _parse_num(s: str) -> float:
    return float(s.replace(",", "."))


def parse_annotation(text: str) -> dict:
    """Разобрать одну надпись. Возвращает поля `Annotation`: kind, value, count, reference, suffix…"""
    t = " ".join(text.split())
    out: dict = {"kind": "text"}
    if not t:
        return out
    m = _PATTERNS["count_prefix"].match(t)
    if m:                                    # «4 отв. Ø11» — количество перед размером
        inner = parse_annotation(m[2])
        if inner["kind"] in _DIMENSIONS:
            inner["count"] = int(m[1])
            return inner
    if t.endswith("*"):
        out["reference"] = True
        t = t[:-1].rstrip()
    for kind in ("diameter", "radius", "thread", "angle"):
        m = _PATTERNS[kind].match(t)
        if m:
            out.update(kind=kind, value=_parse_num(m[1]), suffix=m[2].strip())
            return out
    m = _PATTERNS["scale"].match(t)
    if m:
        out.update(kind="scale", scale=f"{m[1]}:{m[2]}")
        return out
    m = _PATTERNS["view"].match(t)
    if m and not out.get("reference"):
        out.update(kind="view", label=m[1], scale=m[2] or "")
        return out
    m = _PATTERNS["count"].match(t)
    if m:
        out.update(kind="count", count=int(m[1]), suffix=m[2])
        return out
    m = _PATTERNS["linear"].match(t)
    if m and (not m[2] or not m[2].strip()[:1].isalpha() or len(m[2].strip()) <= 4):
        out.update(kind="linear", value=_parse_num(m[1]), suffix=m[2].strip())
        return out
    out.pop("reference", None)
    return out


def text_quality(text: str) -> float:
    """Доля символов, ожидаемых на чертеже (ASCII, кириллица, знаки ЕСКД). 1.0 для пустой строки."""
    chars = [c for c in text if not c.isspace()]
    if not chars:
        return 1.0
    good = sum(1 for c in chars if ("!" <= c <= "~") or ("\u0400" <= c <= "\u04ff") or c in _GOOD_SYMBOLS)
    return good / len(chars)


def classify(chars: int, quality: float, paths: int, image_coverage: float) -> str:
    """Можно ли пользоваться текстовым слоем страницы."""
    if chars >= 10 and quality < 0.85:
        return "garbled"
    if chars >= 10:
        return "text"
    if image_coverage > 0.5:
        return "raster"
    if paths > 50:
        return "curves"          # линии есть, текста нет — надписи нарисованы штрихами
    return "empty"


def sheet_format(width: float, height: float, tol: float = 3.0) -> str | None:
    short, long_ = sorted((width, height))
    for name, (s, l) in _FORMATS.items():
        if abs(short - s) <= tol and abs(long_ - l) <= tol:
            return name
    return None


def attach_counts(items: list[Annotation]) -> list[Annotation]:
    """Отдельная строка «6 мест» под размером становится его `count`; присоединённые строки убираются."""
    dims = [a for a in items if a.kind in _DIMENSIONS and a.count is None]
    used = set()
    for c in (a for a in items if a.kind == "count"):
        best, best_d = None, math.inf
        rad = math.radians(c.angle)
        below = (math.sin(rad), -math.cos(rad))
        along = (math.cos(rad), math.sin(rad))
        for d in dims:
            if abs((d.angle - c.angle + 180) % 360 - 180) > 3 or d.id in used:
                continue
            dx, dy = c.bbox.center.x - d.bbox.center.x, c.bbox.center.y - d.bbox.center.y
            perp, par = dx * below[0] + dy * below[1], dx * along[0] + dy * along[1]
            h = max(c.height, d.height, 1.0)
            if 0 < perp <= 2.5 * h and abs(par) <= 6 * h and math.hypot(perp, par) < best_d:
                best, best_d = d, math.hypot(perp, par)
        if best is not None:
            best.count = c.count
            used.add(best.id)
            c.kind = "attached"
    return [a for a in items if a.kind != "attached"]


def diff_annotations(a: list[Annotation], b: list[Annotation]) -> tuple[list[Annotation], list[Annotation]]:
    """Надписи, которые есть только в `a` и только в `b` (по смыслу, без координат) — для сравнения исполнений."""
    def key(x: Annotation):
        return (x.kind, x.value, x.count, x.reference, x.suffix, x.label, x.scale,
                x.text if x.kind == "text" else "")
    ka, kb = Counter(key(x) for x in a), Counter(key(x) for x in b)
    only_a, only_b = ka - kb, kb - ka
    res_a, res_b = [], []
    for x in a:
        if only_a[key(x)] > 0:
            only_a[key(x)] -= 1
            res_a.append(x)
    for x in b:
        if only_b[key(x)] > 0:
            only_b[key(x)] -= 1
            res_b.append(x)
    return res_a, res_b


# --- чтение PDF -----------------------------------------------------------------------------------
def _fitz():
    try:
        import fitz  # PyMuPDF
    except ImportError as e:  # pragma: no cover
        raise ImportError("Для чтения PDF нужен PyMuPDF: pip install kompas-lib[pdf]") from e
    return fitz


def _zone(page: PdfPage, r: Rect) -> str:
    c = r.center
    s, f = page.stamp, page.frame
    if s.x1 <= c.x <= s.x2 and s.y1 <= c.y <= s.y2:
        return "stamp"
    if not (f.x1 <= c.x <= f.x2 and f.y1 <= c.y <= f.y2):
        return "margin"
    return "field"


def _read_page(fitz, pg, index: int) -> PdfPage:
    rot = pg.rotation_matrix                   # текст PyMuPDF отдаёт в неповёрнутой системе
    w_pt, h_pt = pg.rect.width, pg.rect.height
    width, height = w_pt * PT_MM, h_pt * PT_MM
    data = pg.get_text("dict")
    raw_lines = []
    for block in data["blocks"]:
        for line in block.get("lines", []):
            text = " ".join("".join(s["text"] for s in line["spans"]).split())
            if text:
                raw_lines.append((text, line))
    all_text = " ".join(t for t, _ in raw_lines)
    chars = sum(1 for c in all_text if not c.isspace())
    quality = text_quality(all_text)
    area = w_pt * h_pt or 1.0
    covered = 0.0
    for info in pg.get_image_info():
        r = fitz.Rect(info["bbox"]) * rot & pg.rect
        covered += r.width * r.height if not r.is_empty else 0.0
    paths = len(pg.get_cdrawings())
    page = PdfPage(index, round(width, 1), round(height, 1), sheet_format(width, height),
                   classify(chars, quality, paths, covered / area), round(quality, 3), chars, paths,
                   round(min(1.0, covered / area), 3))
    if page.kind != "text":
        return page
    items = []
    for n, (text, line) in enumerate(raw_lines):
        r = fitz.Rect(line["bbox"]) * rot
        bbox = Rect.of(r.x0 * PT_MM, height - r.y1 * PT_MM, r.x1 * PT_MM, height - r.y0 * PT_MM)
        dx, dy = line["dir"]
        dxr = dx * rot.a + dy * rot.c
        dyr = dx * rot.b + dy * rot.d
        angle = round(math.degrees(math.atan2(-dyr, dxr)), 1) % 360
        size = max(s["size"] for s in line["spans"]) * PT_MM
        parsed = parse_annotation(text)
        items.append(Annotation(id=f"p{index + 1}.t{n:03d}", page=index, text=text, bbox=bbox,
                                angle=0.0 if abs(angle) < 0.5 or abs(angle - 360) < 0.5 else angle,
                                height=round(size, 2), zone=_zone(page, bbox), **parsed))
    page.annotations = attach_counts(merge_numbered(dedupe(items)))
    return page


def dedupe(items: list[Annotation], tol: float = 0.5) -> list[Annotation]:
    """Одинаковая надпись в том же месте (CAD часто рисует текст дважды) — оставить одну."""
    seen, result = set(), []
    for a in items:
        key = (a.text, round(a.bbox.x1 / tol), round(a.bbox.y1 / tol), round(a.angle))
        if key not in seen:
            seen.add(key)
            result.append(a)
    return result


def merge_numbered(items: list[Annotation]) -> list[Annotation]:
    """Номер пункта («3» или «3.») слева на одной строке с текстом — склеить: это пункт требований, не размер."""
    numbers = [a for a in items if a.angle == 0 and re.fullmatch(r"\d{1,2}\.?", a.text)]
    texts = [a for a in items if a.angle == 0 and a.kind == "text"]
    drop = set()
    for n in numbers:
        h = max(n.height, 1.0)
        for t in texts:
            gap = t.bbox.x1 - n.bbox.x2
            if -0.2 * h <= gap <= 3 * h and abs(t.bbox.center.y - n.bbox.center.y) <= 0.4 * h:
                t.text = f"{n.text} {t.text}"
                t.bbox = Rect.of(n.bbox.x1, min(n.bbox.y1, t.bbox.y1), t.bbox.x2, max(n.bbox.y2, t.bbox.y2))
                drop.add(n.id)
                break
    return [a for a in items if a.id not in drop]


def read_pdf_drawing(path: str | os.PathLike) -> PdfDrawing:
    """Прочитать PDF-чертёж: тип каждой страницы и, если текстовому слою можно верить, надписи."""
    fitz = _fitz()
    p = Path(path)
    with fitz.open(p) as doc:
        pages = [_read_page(fitz, doc[i], i) for i in range(doc.page_count)]
    return PdfDrawing(p, pages)


# ==================================================================================================================
# === 14/55 kompas_lib.pdf_geometry — kompas_lib/pdf_geometry.py
# ==================================================================================================================
"""Геометрия вида из векторного PDF: отрезки, дуги и окружности в мм модели (чистый Python, без КОМПАСа).

Виды листа находятся сами: `read_pdf_drawing(path).views()` → `PdfView` (габарит, обозначение, масштаб),
`view.geometry()` — тот же `ViewGeometry` с началом в левом нижнем углу габарита вида. Своя область — ниже.

Надписи (`pdf_drawing`) дают номиналы, но не положение элементов: где центр отверстия, где касаются дуги,
каков радиус без размера. Это читается из линий PDF:

    g = view_geometry("Корпус.pdf", Rect(50, 140, 160, 270), scale="1:2", origin=(103.7, 156.5))
    print(g.summary())                 # отрезки и дуги вида: координаты, R, углы, толщина линии
    for c in g.circles():              # дуги одной окружности собраны вместе: центр, R, охват
        print(c)
    g.lines(horizontal=True, min_length=20)

Как устроен PDF из КОМПАСа (проверено на листе A1, `spikes/s108`): кривых Безье нет — дуги выведены ломаными
с шагом ≈0.085 мм листа (0.24 pt); каждый отрезок нарисован дважды (туда и обратно); штрихи осей — отдельные
короткие отрезки; толщины: основная ≈0.42 мм, тонкая ≈0.17 мм, рамка ≈1 мм. Поэтому: дубли убираются, отрезки
одной толщины склеиваются в ломаные через вершины степени 2, ломаная делится на прямые и дуги окружностей
(подгонка МНК с допуском `tol`). Безье других CAD спрямляются.

Координаты: `region` и `origin` — мм листа, начало в левом нижнем углу, Y вверх (как `PdfDrawing.render`).
Результат — мм модели: (точка листа − origin) / масштаб вида; Y вверх, углы дуг — против часовой от +X.
Номиналы округляйте сами: квантование PDF даёт ±0.05 мм листа (у радиуса по многим точкам — меньше).
"""

import math
import os
import re
from collections import Counter, defaultdict
from dataclasses import dataclass, field
from pathlib import Path

# из kompas_lib.geom: Point, Rect

PT_TO_MM = 25.4 / 72.0
_KEY = 1e-3              # мм листа: совпадение концов отрезков
_BEZIER_STEPS = 16
_R_MAX = 1e4             # мм листа: больше — прямая
_CHORD_ABS = 0.25        # мм листа: разброс длины хорд одной дуги из-за округления обоих концов (0.085 мм)
_CHORD_REL = 0.08
_QUANT = 0.24 * 25.4 / 72.0   # мм листа: шаг округления координат в PDF КОМПАСа


@dataclass(frozen=True)
class Stroke:
    """Отрезок, дуга или окружность вида в мм модели. Дуга идёт от `a1` к `a2` против часовой."""
    kind: str                       # line | arc | circle
    start: Point
    end: Point
    width: float                    # толщина линии, мм листа
    center: Point | None = None
    radius: float | None = None
    a1: float | None = None         # градусы, 0…360
    a2: float | None = None
    residual: float = 0.0           # наибольшее отклонение исходных точек от примитива, мм модели
    points: int = 2                 # точек исходной ломаной
    radius_err: float = 0.0         # оценка погрешности радиуса (2σ), мм модели: у короткой дуги большого R — велика

    @property
    def sweep(self) -> float:
        if self.kind == "circle":
            return 360.0
        if self.kind != "arc" or self.a1 is None or self.a2 is None:
            return 0.0
        return (self.a2 - self.a1) % 360.0 or 360.0

    @property
    def length(self) -> float:
        if self.kind == "line":
            return self.start.dist(self.end)
        return math.radians(self.sweep) * (self.radius or 0.0)

    def short(self) -> str:
        w = f"w={self.width:.2f}"
        if self.kind == "line":
            return (f"line ({self.start.x:.3f}, {self.start.y:.3f}) → ({self.end.x:.3f}, {self.end.y:.3f}) "
                    f"L={self.length:.3f} {w}")
        c, r = _arc_of(self)
        head = f"{self.kind} C=({c.x:.3f}, {c.y:.3f}) R={r:.3f}±{self.radius_err:.2g}"
        if self.kind == "circle":
            return f"{head} {w} точек {self.points} откл {self.residual:.3f}"
        return (f"{head} {self.a1:.2f}°→{self.a2:.2f}° ({self.sweep:.2f}°) ({self.start.x:.3f}, {self.start.y:.3f})"
                f" → ({self.end.x:.3f}, {self.end.y:.3f}) {w} откл {self.residual:.3f}")


@dataclass(frozen=True)
class ArcGroup:
    """Дуги и окружности с общим центром и радиусом (одна окружность, разрезанная пересечениями)."""
    center: Point
    radius: float
    sweep: float                    # суммарный охват, градусы (360 — полная окружность)
    strokes: tuple[Stroke, ...]
    radius_err: float = 0.0         # 2σ радиуса по всем кускам, мм модели

    def __str__(self) -> str:
        return (f"C=({self.center.x:.3f}, {self.center.y:.3f}) R={self.radius:.3f}±{self.radius_err:.2g} "
                f"охват {self.sweep:.1f}° кусков {len(self.strokes)}")


@dataclass
class ViewGeometry:
    """Примитивы вида в мм модели и преобразование лист ↔ вид."""
    strokes: list[Stroke]
    region: Rect                    # мм листа
    origin: Point                   # мм листа — точка (0, 0) вида
    scale: float                    # мм листа на мм модели: 1:2 → 0.5
    widths: Counter = field(default_factory=Counter)   # толщины (мм листа) в области до фильтра → отрезков

    def to_view(self, x: float, y: float) -> Point:
        """Точка листа (мм) → мм модели."""
        return Point((x - self.origin.x) / self.scale, (y - self.origin.y) / self.scale)

    def to_sheet(self, x: float, y: float) -> Point:
        """Мм модели → точка листа (мм)."""
        return Point(self.origin.x + x * self.scale, self.origin.y + y * self.scale)

    @property
    def box(self) -> Rect | None:
        pts = [p for s in self.strokes for p in _extent(s)]
        if not pts:
            return None
        return Rect(min(p.x for p in pts), min(p.y for p in pts), max(p.x for p in pts), max(p.y for p in pts))

    def lines(self, *, horizontal: bool | None = None, vertical: bool | None = None, min_length: float = 0.0,
              angle_tol: float = 0.1) -> list[Stroke]:
        """Отрезки; `horizontal`/`vertical` — с допуском `angle_tol`°, `min_length` — мм модели."""
        out = []
        for s in self.strokes:
            if s.kind != "line" or s.length < min_length:
                continue
            a = math.degrees(math.atan2(s.end.y - s.start.y, s.end.x - s.start.x)) % 180.0
            is_h = min(a, 180.0 - a) <= angle_tol
            is_v = abs(a - 90.0) <= angle_tol
            if (horizontal is None or horizontal == is_h) and (vertical is None or vertical == is_v):
                out.append(s)
        return out

    def arcs(self, radius: float | None = None, tol: float = 0.05) -> list[Stroke]:
        """Дуги и окружности, при `radius` — с этим радиусом (± `tol`, мм модели)."""
        return [s for s in self.strokes if s.kind in ("arc", "circle")
                and (radius is None or abs((s.radius or 0.0) - radius) <= tol)]

    def circles(self, tol: float = 0.05, min_sweep: float = 0.0) -> list[ArcGroup]:
        """Дуги одной окружности, собранные вместе, по возрастанию радиуса.

        Куски объединяются, если радиусы и центры совпадают в пределах `tol` (мм модели) или их погрешностей
        (`radius_err`), а по углу куски не перекрываются (концентричные дуги эквидистанты — разные окружности):
        короткие дуги большого радиуса меряются грубо, вместе — точнее. Радиус и центр группы — среднее с весами
        1/σ²."""
        groups: list[list[Stroke]] = []
        for s in sorted(self.arcs(), key=lambda s: s.radius_err):         # сначала точные — они задают группу
            for g in groups:
                r, c, e = _group_estimate(g)
                lim = max(tol, e + s.radius_err)
                sc, sr = _arc_of(s)
                if abs(r - sr) <= lim and c.dist(sc) <= lim and all(_angular_overlap(s, t) <= 2.0 for t in g):
                    g.append(s)
                    break
            else:
                groups.append([s])
        out = []
        for g in groups:
            r, c, e = _group_estimate(g)
            sweep = min(360.0, sum(s.sweep for s in g))
            if sweep >= min_sweep:
                out.append(ArcGroup(c, r, sweep, tuple(g), e))
        return sorted(out, key=lambda g: (g.radius, g.center.x, g.center.y))

    def near(self, x: float, y: float, distance: float) -> list[Stroke]:
        """Примитивы, проходящие ближе `distance` (мм модели) к точке."""
        p = Point(x, y)
        return [s for s in self.strokes if _distance(s, p) <= distance]

    def within(self, x1: float, y1: float, x2: float, y2: float) -> "ViewGeometry":
        """Только примитивы, целиком лежащие в прямоугольнике (мм модели)."""
        r = Rect.of(x1, y1, x2, y2)
        keep = [s for s in self.strokes
                if all(r.x1 - 1e-9 <= p.x <= r.x2 + 1e-9 and r.y1 - 1e-9 <= p.y <= r.y2 + 1e-9 for p in _extent(s))]
        return ViewGeometry(keep, self.region, self.origin, self.scale, self.widths)

    def summary(self, limit: int = 300) -> str:
        """Текстом: толщины линий в области, окружности, затем все примитивы (сначала длинные)."""
        widths = ", ".join(f"{w:.2f} мм ×{n}" for w, n in sorted(self.widths.items(), reverse=True))
        lines = [f"Вид: область листа ({self.region.x1:.1f}, {self.region.y1:.1f})–({self.region.x2:.1f}, "
                 f"{self.region.y2:.1f}) мм, начало вида ({self.origin.x:.2f}, {self.origin.y:.2f}) мм листа, "
                 f"масштаб {_scale_text(self.scale)}; примитивов {len(self.strokes)}",
                 f"  толщины линий в области (мм листа → отрезков): {widths or '—'}"]
        circles = self.circles()
        if circles:
            lines.append("  Окружности (дуги с общим центром):")
            lines += [f"    {c}" for c in circles]
        lines.append("  Примитивы (мм модели):")
        ordered = sorted(self.strokes, key=lambda s: -s.length)
        lines += [f"    {s.short()}" for s in ordered[:limit]]
        if len(ordered) > limit:
            lines.append(f"    … ещё {len(ordered) - limit} (короче {ordered[limit - 1].length:.3f})")
        return "\n".join(lines)


# --- чтение и разбор -------------------------------------------------------------------------------------------
def parse_scale(scale) -> float:
    """Масштаб вида → мм листа на мм модели: "1:2" → 0.5, "2:1" → 2, число — как есть."""
    if isinstance(scale, str):
        a, _, b = scale.replace("М", "").replace(",", ".").partition(":")
        value = float(a) / float(b) if b else float(a)
    else:
        value = float(scale)
    if value <= 0:
        raise ValueError(f"Масштаб вида > 0: {scale!r}")
    return value


def view_geometry(path: str | os.PathLike, region: Rect, *, page: int = 0, scale="1:1",
                  origin: Point | tuple[float, float] | None = None, min_width: float = 0.3,
                  max_width: float | None = None, tol: float = 0.1) -> ViewGeometry:
    """Отрезки, дуги и окружности линий PDF в области `region` (мм листа).

    `scale` — масштаб вида ("1:2", "2:1" или мм листа на мм модели); `origin` — точка листа (мм), которая станет
    (0, 0) вида (по умолчанию левый нижний угол области); берутся линии толщиной от `min_width` до `max_width`
    (мм листа: 0.3 — основные линии КОМПАСа, 0 — все; что есть в области — `ViewGeometry.widths`);
    `tol` — допуск подгонки прямых и дуг, мм листа."""
    k = parse_scale(scale)
    o = Point(*origin) if isinstance(origin, tuple) else (origin or Point(region.x1, region.y1))
    segments, widths = _read_segments(Path(path), page, region)
    chosen = [s for s in segments if s[2] >= min_width - 1e-9 and (max_width is None or s[2] <= max_width + 1e-9)]
    strokes = []
    for width, chain in _chains(chosen):
        for kind, pts, fit in _split(chain, tol):
            strokes.append(_stroke(kind, pts, fit, width, o, k))
    return ViewGeometry(strokes, region, o, k, widths)


# --- виды листа -----------------------------------------------------------------------------------------------
_VIEW_GAP = 3.0          # мм листа: основные линии ближе — один вид (виды разнесены на десятки мм)
_VIEW_MIN = 8.0          # мм листа: группа меньше — обрывок или значок, не вид
_VIEW_PIECE = 20.0       # мм листа: группа меньше — кусок вида (контур выносного элемента прерван штриховкой) …
_VIEW_ATTACH = 10.0      # … и присоединяется к виду ближе этого
_CALLOUT = 15.0          # мм листа: кружок не больше этого с надписью внутри — номер позиции, не вид
_LABEL_ABOVE = 40.0      # мм листа: обозначение вида стоит над его основными линиями не дальше


@dataclass(frozen=True)
class PdfView:
    """Вид листа PDF: габарит основных линий, обозначение и масштаб; `geometry()` — линии вида в мм модели
    с началом в левом нижнем углу габарита (крайние точки вида: X=0 — самая левая, Y=0 — самая нижняя)."""
    path: Path
    page: int
    box: Rect                       # мм листа: габарит основных линий вида
    label: str = ""                 # «А», «Д-Д», «Б(2:1)»; "" — без обозначения: главный, в проекционной связи, аксонометрия
    scale: str = ""                 # из обозначения «(2:1)», иначе масштаб основной надписи; "" — неизвестен
    kind: str = "view"              # view | section (А-А) | detail (выносной элемент Б(2:1))

    @property
    def origin(self) -> Point:
        return Point(self.box.x1, self.box.y1)

    @property
    def size(self) -> tuple[float, float]:
        """Габарит вида в мм модели (по масштабу; без масштаба — мм листа)."""
        k = parse_scale(self.scale) if self.scale else 1.0
        return self.box.width / k, self.box.height / k

    def geometry(self, **kw) -> ViewGeometry:
        """`view_geometry` по области вида; `scale`, `origin`, `min_width`, `tol` можно переопределить."""
        kw.setdefault("scale", self.scale or 1.0)
        kw.setdefault("origin", self.origin)
        return view_geometry(self.path, self.box.inflate(1.0), page=self.page, **kw)

    def __str__(self) -> str:
        w, h = self.size
        b = self.box
        return (f"{self.label or '(без обозначения)'} [{self.kind}] масштаб {self.scale or '?'}: "
                f"{w:.1f}×{h:.1f} мм модели, область листа ({b.x1:.1f}, {b.y1:.1f})–({b.x2:.1f}, {b.y2:.1f})")


def find_views(path: str | os.PathLike, page, min_width: float = 0.3, max_width: float = 0.7) -> list[PdfView]:
    """Виды листа `page` (`PdfPage` из `read_pdf_drawing`): группы основных линий в поле рамки.

    Основные линии (`min_width`…`max_width` мм листа) ближе `_VIEW_GAP` — один вид; тонкие (размеры, оси,
    штриховка), толстые (рамка, линии сечений) и основная надпись не участвуют, группы, касающиеся рамки
    (графы рамки), отброшены. Обозначение — надпись вида («А», «Д-Д», «Б(2:1)») над габаритом по центру.
    Сверху вниз, слева направо. Виды, сросшиеся основными линиями, окажутся одним — сверяйте с `render()`."""
    frame = page.frame
    stamp = page.stamp.inflate(0.5)
    segs, _ = _read_segments(Path(path), page.index, frame)
    keep = [(a, b) for a, b, w in segs if min_width - 1e-9 <= w <= max_width + 1e-9
            and not (_inside(stamp, a) and _inside(stamp, b))]
    boxes = [b for b in map(_box_of, _clusters(keep, _VIEW_GAP)) if not _touches(b, frame, 0.5)]
    texts = [a.bbox.center for a in page.annotations]
    boxes = [b for b in _merge_boxes(boxes, _VIEW_GAP)
             if not (max(b.width, b.height) <= _CALLOUT and min(b.width, b.height) >= 0.7 * max(b.width, b.height)
                     and any(_inside(b, (p.x, p.y)) for p in texts))]
    boxes = [b for b in _attach_pieces(boxes) if max(b.width, b.height) >= _VIEW_MIN]
    sheet_scale = next((a.scale for a in page.annotations if a.kind == "scale" and a.zone == "stamp"), "")
    labels = _view_labels(boxes, [a for a in page.annotations if a.kind == "view" and a.zone == "field"])
    out = []
    for i, b in enumerate(boxes):
        a = labels.get(i)
        text = " ".join(a.text.split()) if a else ""
        kind = "section" if a and re.search(r"[-–]", text) else "detail" if a and a.scale else "view"
        out.append(PdfView(Path(path), page.index, b, text, (a.scale if a and a.scale else sheet_scale), kind))
    return sorted(out, key=lambda v: (-round(v.box.y2 / 20), v.box.x1))


def _inside(r: Rect, p) -> bool:
    return r.x1 <= p[0] <= r.x2 and r.y1 <= p[1] <= r.y2


def _box_of(segs: list) -> Rect:
    xs = [p[0] for s in segs for p in s]
    ys = [p[1] for s in segs for p in s]
    return Rect(min(xs), min(ys), max(xs), max(ys))


def _touches(b: Rect, frame: Rect, tol: float) -> bool:
    return (b.x1 - frame.x1 <= tol or frame.x2 - b.x2 <= tol or b.y1 - frame.y1 <= tol or frame.y2 - b.y2 <= tol)


def _clusters(segs: list, gap: float) -> list[list]:
    """Отрезки, связанные точками ближе ~`gap` (общая клетка сетки шагом `gap` вдоль отрезков)."""
    parent = list(range(len(segs)))

    def root(i: int) -> int:
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    cells: dict = {}
    for i, (a, b) in enumerate(segs):
        steps = max(1, math.ceil(math.dist(a, b) / (gap / 2)))
        for t in range(steps + 1):
            x, y = a[0] + (b[0] - a[0]) * t / steps, a[1] + (b[1] - a[1]) * t / steps
            cell = (math.floor(x / gap), math.floor(y / gap))
            j = cells.setdefault(cell, i)
            parent[root(i)] = root(j)
    groups: dict = defaultdict(list)
    for i, s in enumerate(segs):
        groups[root(i)].append(s)
    return list(groups.values())


def _merge_boxes(boxes: list[Rect], gap: float) -> list[Rect]:
    """Слить габариты, которые перекрываются или ближе `gap` (отверстия внутри контура, штриховые линии)."""
    boxes = list(boxes)
    merged = True
    while merged:
        merged = False
        for i in range(len(boxes)):
            for j in range(i + 1, len(boxes)):
                a, b = boxes[i], boxes[j]
                if a.inflate(gap / 2).intersects(b.inflate(gap / 2)):
                    boxes[i] = Rect(min(a.x1, b.x1), min(a.y1, b.y1), max(a.x2, b.x2), max(a.y2, b.y2))
                    del boxes[j]
                    merged = True
                    break
            if merged:
                break
    return boxes


def _gap(a: Rect, b: Rect) -> float:
    dx = max(0.0, a.x1 - b.x2, b.x1 - a.x2)
    dy = max(0.0, a.y1 - b.y2, b.y1 - a.y2)
    return math.hypot(dx, dy)


def _attach_pieces(boxes: list[Rect]) -> list[Rect]:
    """Мелкие (< `_VIEW_PIECE`) или узкие (одиночная прямая) группы — к ближайшему виду не дальше `_VIEW_ATTACH`."""
    def piece(b: Rect) -> bool:
        return max(b.width, b.height) < _VIEW_PIECE or min(b.width, b.height) < 2.0

    big = [b for b in boxes if not piece(b)]
    rest = []
    for p in filter(piece, boxes):
        near = min(range(len(big)), key=lambda i: _gap(p, big[i]), default=None)
        if near is not None and _gap(p, big[near]) <= _VIEW_ATTACH:
            b = big[near]
            big[near] = Rect(min(b.x1, p.x1), min(b.y1, p.y1), max(b.x2, p.x2), max(b.y2, p.y2))
        else:
            rest.append(p)
    return big + rest


def _view_labels(boxes: list[Rect], labels: list) -> dict:
    """Номер вида → надпись-обозначение над ним (по центру); каждая надпись — одному виду, ближайшему."""
    pairs = []
    for i, b in enumerate(boxes):
        for a in labels:
            c = a.bbox.center
            dy, dx = a.bbox.y1 - b.y2, abs(c.x - b.center.x)
            if -2.0 <= dy <= _LABEL_ABOVE and dx <= max(0.25 * b.width, 10.0):
                pairs.append((dy + 0.5 * dx, i, a))
    out: dict = {}
    used: set = set()
    for _, i, a in sorted(pairs, key=lambda t: t[0]):
        if i not in out and a.id not in used:
            out[i] = a
            used.add(a.id)
    return out


def fit_circle(points) -> tuple[float, float, float, float] | None:
    """Окружность по точкам (МНК Каса): (cx, cy, r, наибольшее отклонение) или None (меньше 3 точек, прямая)."""
    pts = [(p[0], p[1]) for p in points]
    n = len(pts)
    if n < 3:
        return None
    mx, my = sum(p[0] for p in pts) / n, sum(p[1] for p in pts) / n
    u = [(x - mx, y - my) for x, y in pts]
    suu = sum(a * a for a, _ in u)
    svv = sum(b * b for _, b in u)
    suv = sum(a * b for a, b in u)
    suuu = sum(a ** 3 for a, _ in u)
    svvv = sum(b ** 3 for _, b in u)
    suvv = sum(a * b * b for a, b in u)
    svuu = sum(b * a * a for a, b in u)
    det = suu * svv - suv * suv
    if abs(det) < 1e-12 * max(1.0, suu * svv):
        return None
    uc = (0.5 * (suuu + suvv) * svv - 0.5 * (svvv + svuu) * suv) / det
    vc = (0.5 * (svvv + svuu) * suu - 0.5 * (suuu + suvv) * suv) / det
    r = math.sqrt(uc * uc + vc * vc + (suu + svv) / n)
    cx, cy = uc + mx, vc + my
    res = max(abs(math.hypot(x - cx, y - cy) - r) for x, y in pts)
    return cx, cy, r, res


def _read_segments(path: Path, page: int, region: Rect) -> tuple[list[tuple], Counter]:
    """Отрезки линий (мм листа, Y вверх) в области, без дублей: [(a, b, толщина)] и счётчик толщин."""
    # из kompas_lib.pdf_drawing: _fitz
    fitz = _fitz()
    with fitz.open(path) as doc:
        pg = doc[page]
        h = pg.rect.height
        drawings = pg.get_drawings()

    def mm(p) -> tuple[float, float]:
        return (p.x * PT_TO_MM, (h - p.y) * PT_TO_MM)

    inside = lambda p: region.x1 - 1e-6 <= p[0] <= region.x2 + 1e-6 and region.y1 - 1e-6 <= p[1] <= region.y2 + 1e-6  # noqa: E731
    seen: set = set()
    out: list[tuple] = []
    widths: Counter = Counter()
    for d in drawings:
        if "s" not in (d.get("type") or "s"):          # только заливка — стрелки, не линии
            continue
        w = round((d.get("width") or 0.0) * PT_TO_MM, 3)
        for item in d["items"]:
            op = item[0]
            if op == "l":
                pairs = [(mm(item[1]), mm(item[2]))]
            elif op == "c":
                pts = [mm(_bezier(item[1:5], t / _BEZIER_STEPS)) for t in range(_BEZIER_STEPS + 1)]
                pairs = list(zip(pts, pts[1:]))
            elif op == "re":
                r = item[1]
                c = [mm(fitz.Point(r.x0, r.y0)), mm(fitz.Point(r.x1, r.y0)), mm(fitz.Point(r.x1, r.y1)),
                     mm(fitz.Point(r.x0, r.y1))]
                pairs = list(zip(c, c[1:] + c[:1]))
            elif op == "qu":
                q = item[1]
                c = [mm(q.ul), mm(q.ur), mm(q.lr), mm(q.ll)]
                pairs = list(zip(c, c[1:] + c[:1]))
            else:
                continue
            for a, b in pairs:
                if not (inside(a) and inside(b)):
                    continue
                ka, kb = _key(a), _key(b)
                if ka == kb:
                    continue
                key = (min(ka, kb), max(ka, kb), w)
                if key in seen:
                    continue
                seen.add(key)
                widths[w] += 1
                out.append((a, b, w))
    return out, widths


def _bezier(p, t: float):
    s = 1 - t
    x = s ** 3 * p[0].x + 3 * s * s * t * p[1].x + 3 * s * t * t * p[2].x + t ** 3 * p[3].x
    y = s ** 3 * p[0].y + 3 * s * s * t * p[1].y + 3 * s * t * t * p[2].y + t ** 3 * p[3].y
    return type(p[0])(x, y)


def _key(p) -> tuple[int, int]:
    return (round(p[0] / _KEY), round(p[1] / _KEY))


def _chains(segments: list[tuple]) -> list[tuple[float, list]]:
    """Ломаные одной толщины: склейка отрезков через вершины степени 2; замкнутая — начинается в изломе."""
    out = []
    by_width: dict[float, list] = defaultdict(list)
    for a, b, w in segments:
        by_width[w].append((a, b))
    for w, segs in sorted(by_width.items()):
        adj: dict = defaultdict(list)
        for i, (a, b) in enumerate(segs):
            adj[_key(a)].append(i)
            adj[_key(b)].append(i)
        used = [False] * len(segs)
        for i in range(len(segs)):
            if used[i]:
                continue
            used[i] = True
            pts = list(segs[i])
            for forward in (True, False):
                while True:
                    end = pts[-1] if forward else pts[0]
                    k = _key(end)
                    nxt = [j for j in adj[k] if not used[j]]
                    if len(adj[k]) != 2 or not nxt:
                        break
                    j = nxt[0]
                    used[j] = True
                    a, b = segs[j]
                    q = b if _key(a) == k else a
                    if forward:
                        pts.append(q)
                    else:
                        pts.insert(0, q)
            if len(pts) > 3 and _key(pts[0]) == _key(pts[-1]):
                pts = _rotate_to_corner(pts[:-1])
                pts.append(pts[0])
            out.append((w, pts))
    return out


def _rotate_to_corner(ring: list) -> list:
    """Замкнутую ломаную начать в самом резком изломе, чтобы не резать дугу или прямую посередине."""
    n = len(ring)

    def turn(i: int) -> float:
        a, b, c = ring[i - 1], ring[i], ring[(i + 1) % n]
        a1 = math.atan2(b[1] - a[1], b[0] - a[0])
        a2 = math.atan2(c[1] - b[1], c[0] - b[0])
        return abs((a2 - a1 + math.pi) % (2 * math.pi) - math.pi)
    best = max(range(n), key=turn)
    return ring[best:] + ring[:best]


def _line_ok(pts: list, tol: float) -> bool:
    (x1, y1), (x2, y2) = pts[0], pts[-1]
    length = math.hypot(x2 - x1, y2 - y1)
    if length < 1e-12:
        return False
    return all(abs((x2 - x1) * (y1 - y) - (x1 - x) * (y2 - y1)) / length <= tol for x, y in pts[1:-1])


def _split(pts: list, tol: float) -> list[tuple[str, list, tuple | None]]:
    """Ломаную — на прямые и дуги окружностей.

    КОМПАС выводит дугу хордами равной длины, а координаты округляет до 0.085 мм — шум вершин сравним с допуском,
    и жадный критерий «укладывается в tol» на касаниях дуг ошибается. Поэтому сначала ломаная режется на серии
    хорд одной длины (стык дуг — смена длины хорды), серия подгоняется окружностью или прямой (иначе — жадное
    деление), затем соседние куски одной окружности, коллинеарные отрезки и «огрызки» хорд на концах дуг
    склеиваются."""
    n = len(pts)
    closed = n > 3 and _key(pts[0]) == _key(pts[-1])
    pieces = _segment(pts, tol)
    if closed and len(pieces) > 1 and "arc" in (pieces[0][0], pieces[-1][0]):
        # обход начат внутри дуги (у касательных стыков нет излома): начать с границы последнего куска и
        # разобрать заново — части разрезанной дуги окажутся рядом
        ring, k = pts[:-1], pieces[-1][1]
        pts = ring[k:] + ring[:k] + [ring[k]]
        pieces = _segment(pts, tol)
    out: list[tuple[str, list, tuple | None]] = []
    for kind, i, j, fit in pieces:
        if kind == "arc" and closed and i == 0 and j == n - 1:
            kind = "circle"
        out.append((kind, [pts[i], pts[j]] if kind == "line" else pts[i:j + 1], fit))
    return out


def _segment(pts: list, tol: float) -> list[list]:
    """Куски ломаной: [вид, первая точка, последняя точка, подгонка]."""
    pieces: list[list] = []
    for i, j in _chord_runs(pts):
        pieces += _classify_run(pts, i, j, tol)
    return _merge_pieces(pts, pieces, tol)

def _chord_runs(pts: list) -> list[tuple[int, int]]:
    """Серии подряд идущих хорд одной длины: [(первая точка, последняя точка)]."""
    lengths = [math.dist(pts[k], pts[k + 1]) for k in range(len(pts) - 1)]
    runs, i = [], 0
    while i < len(lengths):
        j = i + 1
        while j < len(lengths) and abs(lengths[j] - lengths[i]) <= max(_CHORD_ABS, _CHORD_REL * lengths[i]):
            j += 1
        runs.append((i, j))
        i = j
    return runs


def _classify_run(pts: list, i: int, j: int, tol: float) -> list[list]:
    seg = pts[i:j + 1]
    if j - i == 1 or _line_ok(seg, tol):
        return [["line", i, j, None]]
    f = fit_circle(seg)
    if f is not None and f[3] <= tol and f[2] <= _R_MAX:
        return [["arc", i, j, f]]
    return _greedy(pts, i, j, tol)


def _greedy(pts: list, i0: int, j0: int, tol: float) -> list[list]:
    """Запасное деление точек i0…j0: на каждом шаге самый длинный кусок, укладывающийся в `tol`
    (прямая — при равной длине)."""
    out, i = [], i0
    while i < j0:
        jl = i + 1
        while jl + 1 <= j0 and _line_ok(pts[i:jl + 2], tol):
            jl += 1
        ja, fit = i + 1, None
        j = i + 2
        while j <= j0:
            f = fit_circle(pts[i:j + 1])
            if f is None or f[3] > tol or f[2] > _R_MAX:
                break
            ja, fit = j, f
            j += 1
        if fit is not None and ja - i >= 3 and ja > jl:
            out.append(["arc", i, ja, fit])
            i = ja
        else:
            out.append(["line", i, jl, None])
            i = jl
    return out


def _merge_pieces(pts: list, pieces: list[list], tol: float) -> list[list]:
    """Склеить соседние: прямые на одной прямой; дуги одной окружности; дугу и кусок, принятый за прямую, если
    вместе они ложатся на окружность (остаток хорды у точки касания или пара хорд со стрелкой меньше `tol`).
    Хорды такой «прямой» не длиннее хорд дуги: длинный отрезок даёт подгонке лишь два конца, и окружность через
    них и короткую дугу скругления проходит всегда — прямая кромка стала бы дугой огромного радиуса."""
    def chord(p: list) -> float:
        return max(math.dist(pts[t], pts[t + 1]) for t in range(p[1], p[2]))

    changed = True
    while changed and len(pieces) > 1:
        changed = False
        for k in range(len(pieces) - 1):
            a, b = pieces[k], pieces[k + 1]
            i, j = a[1], b[2]
            merged = None
            if a[0] == b[0] == "line":
                if _line_ok(pts[i:j + 1], tol):
                    merged = ["line", i, j, None]
            elif "arc" in (a[0], b[0]):
                arc, other = (a, b) if a[0] == "arc" else (b, a)
                f = None
                if other[0] == "arc" or chord(other) <= chord(arc) * (1 + _CHORD_REL) + _CHORD_ABS:
                    f = fit_circle(pts[i:j + 1])
                if f is not None and f[3] <= tol and f[2] <= _R_MAX:
                    merged = ["arc", i, j, f]
            if merged is not None:
                pieces[k:k + 2] = [merged]
                changed = True
                break
    return pieces


def _stroke(kind: str, pts: list, fit, width: float, origin: Point, k: float) -> Stroke:
    view = [Point((x - origin.x) / k, (y - origin.y) / k) for x, y in pts]
    if kind == "line":
        return Stroke("line", view[0], view[-1], width)
    cx, cy, r, res = fit
    c = Point((cx - origin.x) / k, (cy - origin.y) / k)
    if kind == "circle":
        err = _radius_err(pts[:-1], cx, cy, r, 360.0) / k
        return Stroke("circle", view[0], view[0], width, c, r / k, 0.0, 360.0, res / k, len(pts) - 1, err)
    # направление обхода — по знаку суммы векторных произведений относительно центра
    turn = sum((a.x - c.x) * (b.y - c.y) - (a.y - c.y) * (b.x - c.x) for a, b in zip(view, view[1:]))
    if turn < 0:
        view = view[::-1]
    a1 = math.degrees(math.atan2(view[0].y - c.y, view[0].x - c.x)) % 360.0
    a2 = math.degrees(math.atan2(view[-1].y - c.y, view[-1].x - c.x)) % 360.0
    sweep = (a2 - a1) % 360.0 or 360.0
    return Stroke("arc", view[0], view[-1], width, c, r / k, a1, a2, res / k, len(pts),
                  _radius_err(pts, cx, cy, r, sweep) / k)


def _arc_of(s: Stroke) -> tuple[Point, float]:
    """Центр и радиус дуги или окружности."""
    if s.center is None or s.radius is None:
        raise ValueError(f"У примитива {s.kind} нет центра и радиуса")
    return s.center, s.radius


def _group_estimate(g: list[Stroke]) -> tuple[float, Point, float]:
    """Радиус, центр и 2σ радиуса группы дуг: среднее с весами 1/σ²."""
    w = [1.0 / max(s.radius_err, 1e-6) ** 2 for s in g]
    arcs = [_arc_of(s) for s in g]
    total = sum(w)
    r = sum(wi * ri for wi, (_, ri) in zip(w, arcs)) / total
    c = Point(sum(wi * ci.x for wi, (ci, _) in zip(w, arcs)) / total,
              sum(wi * ci.y for wi, (ci, _) in zip(w, arcs)) / total)
    return r, c, 1.0 / math.sqrt(total)


def _angular_overlap(s: Stroke, t: Stroke) -> float:
    """Перекрытие угловых интервалов двух дуг, градусы (окружность перекрывает всё)."""
    a, sa, b, sb = s.a1 or 0.0, s.sweep, t.a1 or 0.0, t.sweep
    return max(max(0.0, min(a + sa, b + k + sb) - max(a, b + k)) for k in (-360.0, 0.0, 360.0))


def _radius_err(pts: list, cx: float, cy: float, r: float, sweep: float) -> float:
    """2σ радиуса подогнанной окружности, мм листа. Шум вершин σ — по остаткам подгонки (не меньше шума округления
    координат КОМПАСа 0.085/√12); радиус меряется через стрелку дуги s: σ_R ≈ R·σ_s/s, σ_s ≈ σ·√(11.25/n)
    (дисперсия квадратичного члена МНК на n равномерных точках)."""
    n = len(pts)
    rms = math.sqrt(sum((math.hypot(x - cx, y - cy) - r) ** 2 for x, y in pts) / max(1, n - 3)) if n > 3 else 0.0
    sigma = max(rms, _QUANT / math.sqrt(12.0))
    sagitta = r * (1.0 - math.cos(math.radians(min(sweep, 180.0)) / 2.0))
    return 2.0 * r * sigma * math.sqrt(11.25 / n) / max(sagitta, 1e-9)


def _extent(s: Stroke) -> list[Point]:
    if s.kind == "circle":
        c, r = _arc_of(s)
        return [Point(c.x - r, c.y - r), Point(c.x + r, c.y + r)]
    return [s.start, s.end]


def _distance(s: Stroke, p: Point) -> float:
    if s.kind == "line":
        a, b = s.start, s.end
        dx, dy = b.x - a.x, b.y - a.y
        L2 = dx * dx + dy * dy
        t = 0.0 if L2 == 0 else max(0.0, min(1.0, ((p.x - a.x) * dx + (p.y - a.y) * dy) / L2))
        return math.hypot(a.x + t * dx - p.x, a.y + t * dy - p.y)
    c, r = _arc_of(s)
    d = c.dist(p)
    if s.kind == "circle":
        return abs(d - r)
    ang = math.degrees(math.atan2(p.y - c.y, p.x - c.x)) % 360.0
    if (ang - (s.a1 or 0.0)) % 360.0 <= s.sweep:
        return abs(d - r)
    return min(s.start.dist(p), s.end.dist(p))


def _scale_text(k: float) -> str:
    if k >= 1:
        return f"{k:g}:1"
    return f"1:{1 / k:g}"


# ==================================================================================================================
# === 15/55 kompas_lib.build.threads — kompas_lib/build/threads.py
# ==================================================================================================================
"""Метрическая резьба ГОСТ 24705-2004: разбор обозначения и параметры для KsAPI (без КОМПАСа).

Идентификаторы стандартов — имена таблиц справочника резьб КОМПАСа (`thread.db`), их принимает
`IThreadsParameters.Init(standard, d, p)` (spikes/s97, s98).

    thread_spec("M8")     → d=8, p=1.25 (крупный шаг), внутренний диаметр 6.647
    thread_spec("М16х1,5") → мелкий шаг (кириллица и запятая допускаются)
"""

import re
from dataclasses import dataclass

COARSE_STANDARD = "cil0_24705-2004 coarse"
FINE_STANDARD = "cil0_24705-2004 fine"
# H·5/8·2 = 1.0825·P — разность наружного и внутреннего диаметров (ГОСТ 24705, коэффициент справочника КОМПАСа).
MINOR_COEFF = 1.082531755

# Крупный шаг по ГОСТ 24705-2004 (ряды 1–3).
COARSE_PITCH = {
    1.0: 0.25, 1.1: 0.25, 1.2: 0.25, 1.4: 0.3, 1.6: 0.35, 1.8: 0.35, 2.0: 0.4, 2.2: 0.45, 2.5: 0.45, 3.0: 0.5,
    3.5: 0.6, 4.0: 0.7, 4.5: 0.75, 5.0: 0.8, 6.0: 1.0, 7.0: 1.0, 8.0: 1.25, 9.0: 1.25, 10.0: 1.5, 11.0: 1.5,
    12.0: 1.75, 14.0: 2.0, 16.0: 2.0, 18.0: 2.5, 20.0: 2.5, 22.0: 2.5, 24.0: 3.0, 27.0: 3.0, 30.0: 3.5,
    33.0: 3.5, 36.0: 4.0, 39.0: 4.0, 42.0: 4.5, 45.0: 4.5, 48.0: 5.0, 52.0: 5.0, 56.0: 5.5, 60.0: 5.5,
    64.0: 6.0, 68.0: 6.0,
}

_THREAD_RE = re.compile(r"^\s*[MМ]\s*(\d+(?:[.,]\d+)?)\s*(?:[xхX×Х*]\s*(\d+(?:[.,]\d+)?))?\s*(?:-?\s*\w+)?\s*$")


@dataclass(frozen=True)
class ThreadSpec:
    d: float          # номинальный диаметр, мм
    p: float          # шаг, мм

    @property
    def coarse(self) -> bool:
        return abs(COARSE_PITCH.get(self.d, -1.0) - self.p) < 1e-9

    @property
    def standard(self) -> str:
        return COARSE_STANDARD if self.coarse else FINE_STANDARD

    @property
    def minor(self) -> float:
        """Внутренний диаметр d1 — диаметр отверстия под резьбу в модели КОМПАСа."""
        return round(self.d - MINOR_COEFF * self.p, 6)

    @property
    def designation(self) -> str:
        d = f"{self.d:g}"
        return f"M{d}" if self.coarse else f"M{d}x{self.p:g}"


def thread_spec(spec) -> ThreadSpec:
    """"M8" | "M8x1" | "М8х1" | "M8-6H" | (d, p) | ThreadSpec → ThreadSpec."""
    if isinstance(spec, ThreadSpec):
        return spec
    if isinstance(spec, (tuple, list)):
        d, p = float(spec[0]), float(spec[1])
    else:
        m = _THREAD_RE.match(str(spec))
        if not m:
            raise ValueError(f"Не разобрано обозначение резьбы {spec!r}: ожидается 'M8', 'M8x1' или (d, p)")
        d = float(m.group(1).replace(",", "."))
        if m.group(2):
            p = float(m.group(2).replace(",", "."))
        elif d in COARSE_PITCH:
            p = COARSE_PITCH[d]
        else:
            raise ValueError(f"M{d:g}: крупный шаг неизвестен — укажите шаг явно ('M{d:g}x1.5' или (d, p))")
    if d <= 0 or p <= 0 or p >= d:
        raise ValueError(f"Резьба d={d}, p={p}: недопустимые параметры")
    return ThreadSpec(d, p)


# ==================================================================================================================
# === 16/55 kompas_lib.build.contour — kompas_lib/build/contour.py
# ==================================================================================================================
"""Элементы эскиза и проверка контура до передачи в КОМПАС (чистый Python, без KsAPI).

Координаты — локальные координаты эскиза (мм). Дуги задаются центром, радиусом и углами (градусы,
против часовой от локальной оси X): так KsAPI надёжно собирает замкнутые области; дуги «центр + две
точки» на сложных контурах не замыкались (прошлый сырой скрипт). Для дуги по двум точкам — `arc_by_points`.

    items = rect(0, 0, 100, 60) + [circle(50, 30, 10)]
    check_contour(items)          # [] — замкнутые контуры без разрывов и самопересечений
"""

import math
from dataclasses import dataclass
from typing import Sequence, Union

# из kompas_lib.geom: Point, Segment, arc_polyline, segments_cross

STYLES = ("normal", "construction", "axis")


@dataclass(frozen=True)
class Line:
    x1: float
    y1: float
    x2: float
    y2: float
    style: str = "normal"     # normal — контур, construction — вспомогательная, axis — осевая (ось вращения)

    @property
    def ends(self) -> tuple[Point, Point]:
        return Point(self.x1, self.y1), Point(self.x2, self.y2)

    def segments(self) -> list[Segment]:
        return [Segment(*self.ends)]


@dataclass(frozen=True)
class Arc:
    xc: float
    yc: float
    r: float
    a1: float                 # начальный угол, градусы
    a2: float                 # конечный угол
    ccw: bool = True          # обход от a1 к a2 против часовой
    style: str = "normal"

    def point(self, a: float) -> Point:
        return Point(self.xc + self.r * math.cos(math.radians(a)), self.yc + self.r * math.sin(math.radians(a)))

    @property
    def ends(self) -> tuple[Point, Point]:
        return self.point(self.a1), self.point(self.a2)

    def segments(self) -> list[Segment]:
        return arc_polyline(Point(self.xc, self.yc), self.r, self.a1, self.a2, self.ccw, per_circle=96)


@dataclass(frozen=True)
class Circle:
    xc: float
    yc: float
    r: float
    style: str = "normal"

    @property
    def ends(self) -> tuple:
        return ()

    def segments(self) -> list[Segment]:
        return arc_polyline(Point(self.xc, self.yc), self.r, 0.0, 360.0, True, per_circle=96)


@dataclass(frozen=True)
class SketchText:
    """Надпись в эскизе — профиль для `PartBuilder.relief` (в контур не входит, `check_contour` её пропускает)."""
    x: float                  # точка привязки на базовой линии строки (символы — выше неё), мм
    y: float
    text: str
    height: float = 5.0       # высота символов, мм
    font: str = "GOST type A"
    align: str = "center"     # left | center | right — где точка привязки относительно строки
    angle: float = 0.0        # поворот строки, градусы против часовой
    italic: bool = False
    style: str = "text"

    @property
    def ends(self) -> tuple:
        return ()

    def segments(self) -> list[Segment]:
        return []


Item = Union[Line, Arc, Circle, SketchText]


# --- построители ------------------------------------------------------------------------------------
def line(x1: float, y1: float, x2: float, y2: float, style: str = "normal") -> Line:
    return Line(x1, y1, x2, y2, style)


def circle(xc: float, yc: float, r: float, style: str = "normal") -> Circle:
    return Circle(xc, yc, r, style)


def arc(xc: float, yc: float, r: float, a1: float, a2: float, ccw: bool = True, style: str = "normal") -> Arc:
    return Arc(xc, yc, r, a1, a2, ccw, style)


def arc_by_points(xc: float, yc: float, start: tuple[float, float], end: tuple[float, float], ccw: bool = True,
                  style: str = "normal") -> Arc:
    """Дуга по центру и двум концам (радиус — по началу; конец должен лежать на той же окружности)."""
    r = math.hypot(start[0] - xc, start[1] - yc)
    r2 = math.hypot(end[0] - xc, end[1] - yc)
    if abs(r - r2) > 1e-6 * max(1.0, r):
        raise ValueError(f"Концы дуги на разных радиусах: {r:.6g} и {r2:.6g}")
    a1 = math.degrees(math.atan2(start[1] - yc, start[0] - xc))
    a2 = math.degrees(math.atan2(end[1] - yc, end[0] - xc))
    return Arc(xc, yc, r, a1, a2, ccw, style)


def polygon(points: Sequence[tuple[float, float]], closed: bool = True, style: str = "normal") -> list[Line]:
    pts = list(points)
    pairs = zip(pts, pts[1:] + pts[:1]) if closed else zip(pts, pts[1:])
    return [Line(a[0], a[1], b[0], b[1], style) for a, b in pairs]


def rect(x1: float, y1: float, x2: float, y2: float, style: str = "normal") -> list[Line]:
    return polygon([(x1, y1), (x2, y1), (x2, y2), (x1, y2)], style=style)


def text(x: float, y: float, s: str, height: float = 5.0, *, font: str = "GOST type A", align: str = "center",
         angle: float = 0.0, italic: bool = False) -> SketchText:
    """Надпись в эскизе: `b.relief(b.sketch(плоскость, [text(0, 50, "WOW", 10)]), грани, 0.5)`."""
    return SketchText(float(x), float(y), s, float(height), font, align, float(angle), italic)


# --- проверка ----------------------------------------------------------------------------------------
def check_contour(items: Sequence[Item], tol: float = 1e-4, closed: bool = True, min_size: float = 1e-3,
                  min_gap: float = 1e-3) -> list[str]:
    """Проблемы контура (только элементы стиля normal) — до записи в КОМПАС. Пустой список — контуры замкнуты,
    простые и без микрогеометрии:

    * вырожденные элементы (нулевая длина/радиус) и микроэлементы короче `min_size`;
    * разрывы — свободные концы (зазор меньше 0,01 мм помечается «микрозазор»: точка стыка посчитана неточно);
    * ветвления (в точке больше двух концов), самопересечения, наложения (общий участок у отрезков на одной прямой
      или дуг одной окружности);
    * почти-касания: несмежные элементы ближе `min_gap` — после выдавливания это стенка-«лезвие» или щель.

    Концы ближе `tol` считаются совпавшими; `PartBuilder.sketch` сшивает их точно (`snap_contour`).
    `closed=False` — открытый контур (ребро жёсткости): свободные концы допустимы."""
    issues: list[str] = []
    profile = [it for it in items if it.style == "normal"]
    for i, it in enumerate(items):
        if isinstance(it, SketchText):
            if not it.text.strip() or it.height <= 0 or it.align not in ("left", "center", "right"):
                issues.append(f"#{i} SketchText: пустая строка, высота ≤ 0 или align не left|center|right")
        elif it.style not in STYLES:
            issues.append(f"#{i}: неизвестный стиль {it.style!r}")
    for i, it in enumerate(profile):
        if isinstance(it, (Arc, Circle)) and it.r <= tol:
            issues.append(f"#{i} {type(it).__name__}: радиус {it.r:g}")
        if isinstance(it, Line) and math.hypot(it.x2 - it.x1, it.y2 - it.y1) <= tol:
            issues.append(f"#{i} Line: нулевая длина в ({it.x1:g}, {it.y1:g})")
        if isinstance(it, Arc) and abs((it.a2 - it.a1) % 360.0) < 1e-9:
            issues.append(f"#{i} Arc: начальный и конечный угол совпадают — нужна Circle")
        size = _length(it)
        if tol < size < min_size and not (isinstance(it, (Arc, Circle)) and it.r <= tol):
            issues.append(f"#{i} {type(it).__name__}: микроэлемент длиной {size:.3g} мм (< {min_size:g}) — "
                          "даст микроребро/микрогрань")
    # Концы: в каждой точке контура должно сходиться ровно два конца.
    ends = [(i, p) for i, it in enumerate(profile) for p in it.ends]
    clusters = _end_clusters(ends, tol)
    for cl in clusters:
        p = cl[0][1]
        if len(cl) == 1 and closed:
            near = min(((q.dist(p), j) for j, q in ends if q is not p and q.dist(p) > tol), default=None)
            hint = ""
            if near is not None and near[0] < 1.0:
                hint = f"; ближайший конец (#{near[1]}) в {near[0]:.4g} мм"
                if near[0] < 0.01:
                    hint += " — микрозазор: точка стыка посчитана неточно, задайте общую точку"
            issues.append(f"Разрыв: свободный конец #{cl[0][0]} в ({p.x:.4f}, {p.y:.4f}){hint}")
        elif len(cl) > 2:
            issues.append(f"Ветвление: {len(cl)} конца в ({p.x:.4f}, {p.y:.4f}) — элементы {[c[0] for c in cl]}")
    # Смежность элементов по общим концам — касание в общем конце не пересечение и не «почти касание».
    adjacent: set[tuple[int, int]] = set()
    for cl in clusters:
        ids = sorted({c[0] for c in cl})
        adjacent |= {(a, b) for a in ids for b in ids if a < b}
    # Наложения: отрезки на одной прямой, дуги одной окружности с общим участком.
    for i in range(len(profile)):
        for j in range(i + 1, len(profile)):
            ov = _overlap(profile[i], profile[j], tol)
            if ov > tol:
                issues.append(f"Наложение элементов #{i} и #{j}: общий участок {ov:.4g} мм")
    # Самопересечения и почти-касания (по ломаной аппроксимации дуг).
    segs = [(i, s) for i, it in enumerate(profile) for s in it.segments()]
    crossed: set[tuple[int, int]] = set()
    close: dict[tuple[int, int], float] = {}
    for a in range(len(segs)):
        i, s1 = segs[a]
        for b in range(a + 1, len(segs)):
            j, s2 = segs[b]
            if i == j or (i, j) in crossed:
                continue
            if segments_cross(s1, s2, tol=1e-9):
                crossed.add((i, j))
                issues.append(f"Пересечение элементов #{i} и #{j}")
            elif (min(i, j), max(i, j)) not in adjacent and _bbox_gap(s1, s2) < min_gap:
                d = _seg_seg(s1, s2)
                key = (min(i, j), max(i, j))
                if d < min_gap and d < close.get(key, math.inf):
                    close[key] = d
    for (i, j), d in sorted(close.items()):
        if (i, j) not in crossed:
            issues.append(f"Почти касание элементов #{i} и #{j}: {d:.3g} мм (< {min_gap:g}) — стенка-«лезвие» или "
                          "щель; разведите элементы или соедините их")
    return issues


def snap_contour(items: Sequence[Item], tol: float = 1e-4) -> tuple[list[Item], float]:
    """Сшить концы, совпадающие с точностью `tol`: концы отрезков переносятся точно в общую точку (конец дуги,
    если он есть в стыке, — дугу не двигаем; иначе — среднее). Возвращает (элементы, наибольший сдвиг, мм).
    Так в КОМПАС уходит контур без микрозазоров от погрешностей расчёта точек."""
    items = list(items)
    idx = [k for k, it in enumerate(items) if getattr(it, "style", "") == "normal" and not isinstance(it, SketchText)]
    ends = [((k, n), p) for k in idx for n, p in enumerate(items[k].ends)]
    target: dict[tuple[int, int], Point] = {}     # (элемент, 0|1) → точка
    shift = 0.0
    for cl in _end_clusters(ends, tol):
        if len(cl) < 2:
            continue
        fixed = [p for (k, _), p in cl if not isinstance(items[k], Line)]
        rep = fixed[0] if fixed else Point(sum(p.x for _, p in cl) / len(cl), sum(p.y for _, p in cl) / len(cl))
        for (k, n), p in cl:
            if isinstance(items[k], Line):
                target[(k, n)] = rep
                shift = max(shift, p.dist(rep))
    for k in idx:
        it = items[k]
        if isinstance(it, Line) and ((k, 0) in target or (k, 1) in target):
            a, b = target.get((k, 0), Point(it.x1, it.y1)), target.get((k, 1), Point(it.x2, it.y2))
            items[k] = Line(a.x, a.y, b.x, b.y, it.style)
    return items, shift


def _end_clusters(ends: Sequence[tuple], tol: float) -> list[list[tuple]]:
    clusters: list[list[tuple]] = []
    for i, p in ends:
        for cl in clusters:
            if cl[0][1].dist(p) <= tol:
                cl.append((i, p))
                break
        else:
            clusters.append([(i, p)])
    return clusters


def _length(it) -> float:
    if isinstance(it, Line):
        return math.hypot(it.x2 - it.x1, it.y2 - it.y1)
    if isinstance(it, Arc):
        sweep = (it.a2 - it.a1) % 360.0 if it.ccw else (it.a1 - it.a2) % 360.0
        return math.radians(sweep or 360.0) * it.r
    if isinstance(it, Circle):
        return 2 * math.pi * it.r
    return math.inf


def _overlap(a, b, tol: float) -> float:
    """Длина общего участка двух элементов (0 — нет): отрезки на одной прямой, дуги/окружности одной окружности."""
    if isinstance(a, Line) and isinstance(b, Line):
        dx, dy = a.x2 - a.x1, a.y2 - a.y1
        L = math.hypot(dx, dy)
        if L <= tol:
            return 0.0
        ux, uy = dx / L, dy / L
        off = lambda x, y: abs((x - a.x1) * uy - (y - a.y1) * ux)   # noqa: E731
        if off(b.x1, b.y1) > tol or off(b.x2, b.y2) > tol:
            return 0.0
        t = sorted([(b.x1 - a.x1) * ux + (b.y1 - a.y1) * uy, (b.x2 - a.x1) * ux + (b.y2 - a.y1) * uy])
        return max(0.0, min(L, t[1]) - max(0.0, t[0]))
    round_ = (Arc, Circle)
    if isinstance(a, round_) and isinstance(b, round_):
        if math.hypot(a.xc - b.xc, a.yc - b.yc) > tol or abs(a.r - b.r) > tol:
            return 0.0
        sa, sb = _arc_span_deg(a), _arc_span_deg(b)
        common = sum(min(x2, y2) - max(x1, y1) for x1, x2 in sa for y1, y2 in sb if min(x2, y2) > max(x1, y1))
        return math.radians(common) * a.r
    return 0.0


def _arc_span_deg(it) -> list[tuple[float, float]]:
    """Угловой охват дуги/окружности — интервалы в [0, 360)."""
    if isinstance(it, Circle):
        return [(0.0, 360.0)]
    a1, a2 = (it.a1, it.a2) if it.ccw else (it.a2, it.a1)
    a1 %= 360.0
    a2 = a1 + ((a2 - a1) % 360.0 or 360.0)
    return [(a1, min(a2, 360.0))] + ([(0.0, a2 - 360.0)] if a2 > 360.0 else [])


def _bbox_gap(s1: Segment, s2: Segment) -> float:
    dx = max(min(s1.a.x, s1.b.x) - max(s2.a.x, s2.b.x), min(s2.a.x, s2.b.x) - max(s1.a.x, s1.b.x), 0.0)
    dy = max(min(s1.a.y, s1.b.y) - max(s2.a.y, s2.b.y), min(s2.a.y, s2.b.y) - max(s1.a.y, s1.b.y), 0.0)
    return math.hypot(dx, dy)


def _pt_seg(p: Point, s: Segment) -> float:
    dx, dy = s.b.x - s.a.x, s.b.y - s.a.y
    L2 = dx * dx + dy * dy
    t = 0.0 if L2 < 1e-24 else max(0.0, min(1.0, ((p.x - s.a.x) * dx + (p.y - s.a.y) * dy) / L2))
    return math.hypot(s.a.x + t * dx - p.x, s.a.y + t * dy - p.y)


def _seg_seg(s1: Segment, s2: Segment) -> float:
    """Расстояние между непересекающимися отрезками."""
    return min(_pt_seg(s1.a, s2), _pt_seg(s1.b, s2), _pt_seg(s2.a, s1), _pt_seg(s2.b, s1))


def bounds(items: Sequence[Item]) -> tuple[float, float, float, float]:
    """Габарит элементов (x1, y1, x2, y2) по ломаной аппроксимации."""
    pts = [p for it in items for s in it.segments() for p in (s.a, s.b)]
    return (min(p.x for p in pts), min(p.y for p in pts), max(p.x for p in pts), max(p.y for p in pts))


def area(items: Sequence[Item]) -> float:
    """Площадь области «внешние минус внутренние» для одного внешнего контура с отверстиями (по ломаной).

    Нужна для контроля: объём выдавливания ≈ area × глубина. Контуры собираются по совпадающим концам.
    """
    profile = [it for it in items if it.style == "normal"]
    loops = _loops(profile)
    areas = sorted((abs(_shoelace(loop)) for loop in loops), reverse=True)
    return areas[0] - sum(areas[1:]) if areas else 0.0


def _loops(profile: Sequence[Item], tol: float = 1e-4) -> list[list[Point]]:
    loops: list[list[Point]] = []
    open_items = []
    for it in profile:
        if isinstance(it, Circle):
            loops.append([s.a for s in it.segments()])
        else:
            open_items.append(it)
    used = [False] * len(open_items)
    for start in range(len(open_items)):
        if used[start]:
            continue
        used[start] = True
        pts = [s.a for s in open_items[start].segments()]
        head, tail = open_items[start].ends
        cur = tail
        while cur.dist(head) > tol:
            for k, it in enumerate(open_items):
                if used[k]:
                    continue
                a, b = it.ends
                if a.dist(cur) <= tol:
                    pts += [s.a for s in it.segments()]
                    cur = b
                elif b.dist(cur) <= tol:
                    pts += [s.b for s in reversed(it.segments())]
                    cur = a
                else:
                    continue
                used[k] = True
                break
            else:
                break          # незамкнутый — пропускаем (check_contour сообщит)
        if cur.dist(head) <= tol:
            loops.append(pts)
    return loops


def _shoelace(pts: Sequence[Point]) -> float:
    return 0.5 * sum(p.x * q.y - q.x * p.y for p, q in zip(pts, list(pts[1:]) + [pts[0]]))


