# ==================================================================================================================
"""Переменные детали: создание, изменение (в т.ч. переопределение в зависимом исполнении), привязка
параметров операций к выражениям.

Устройство KsAPI (spikes/s101–s101d):
* переменные детали — `IPart.AddVariable`, читаются `IFeature(part).GetVariables(False, False)`; у каждого
  объекта дерева есть свои переменные-параметры (`v20` «Расстояние 1», `v31` «Радиус»…), их выражение можно
  сослаться на переменные детали (`SetExpression("H")`);
* значение параметра меняется сразу, а геометрия — только после `IKompasDocument3D.RebuildDocument()`
  (`IPart.RebuildModel`, `IModelObject.Update` модель не пересчитывают);
* ⚠ имя, которого нет среди переменных, KsAPI молча **создаёт** новой переменной детали; синтаксически неверное
  выражение молча отклоняется (остаётся прежнее). Поэтому имена проверяются здесь до записи;
* в зависимом исполнении переменная наследует значение (выражение `'|H'`); `SetValue` переопределяет её только
  в этом исполнении. Вернуть наследование через KsAPI не удалось — переопределение необратимо;
* прямой сеттер параметра, привязанного к выражению, игнорируется (`Update() == True`, значение прежнее).

    v = b.vars
    v.add("H", 40, "высота корпуса")
    v.bind("Корпус", "Расстояние 1", "H")
    with emb.use(1):
        v.set("H", 60)             # исполнение 1 выше, дерево не меняется
"""

import re
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Iterable

# из kompas_lib.build.builder: PartBuilder, Step  (только для аннотаций)

# Имена в выражении: идентификатор, за которым не идёт "(" (это функция).
_IDENT = re.compile(r"(?<![\w.])([^\W\d]\w*)(?!\w)(?!\s*\()")
_NUMBER = re.compile(r"^\s*[-+]?(\d+(\.\d*)?|\.\d+)([eE][-+]?\d+)?\s*$")
# Встроенные константы выражений КОМПАСа (не переменные). ⚠ `pi`, `PI`, `e` — не константы: KsAPI молча
# создаёт такие переменные со значением 1 (s102b).
CONSTANTS = frozenset({"M_PI"})


def expression_names(expr: str) -> set[str]:
    """Имена переменных, на которые ссылается выражение (без функций и встроенных констант)."""
    if not expr:
        return set()
    return {m for m in _IDENT.findall(expr.lstrip("|")) if m not in CONSTANTS}


def is_literal(expr: str) -> bool:
    """Выражение — просто число (параметр задан значением, а не через переменные)."""
    return bool(_NUMBER.match(expr or ""))


def _num_text(v) -> str:
    return f"{float(v):.12g}"


@dataclass(frozen=True)
class Variable:
    name: str
    value: float
    expression: str
    note: str = ""
    parameter: str = ""        # у переменной объекта дерева — параметр («Расстояние 1», «Радиус»)
    owner: str = ""            # имя объекта дерева; "" — переменная детали
    inherited: bool = False    # в зависимом исполнении значение берётся из исходного
    information: bool = False  # информационная: KsAPI ставит сам, если выражение ссылается на переменные
    raw: object = field(default=None, repr=False, compare=False)

    @property
    def driven(self) -> bool:
        """Значение вычисляется из других переменных (а не задано числом и не унаследовано)."""
        return not self.inherited and bool(expression_names(self.expression))

    def __str__(self) -> str:
        where = f"{self.owner}." if self.owner else ""
        label = f" «{self.parameter}»" if self.parameter else ""
        expr = "" if is_literal(self.expression) or not self.expression else f" = {self.expression}"
        tail = " (унаследована)" if self.inherited else ""
        return f"{where}{self.name}{label}{expr} → {self.value:.6g}{tail}"


def read_variable(raw, owner: str = "") -> Variable:
    expr = str(raw.GetExpression() or "")
    link = str(raw.GetLinkVariableName() or "")
    return Variable(str(raw.GetName()), float(raw.GetValue()), expr, str(raw.GetNote() or ""),
                    str(raw.GetParameterNote() or "").strip(), owner,
                    inherited=expr.startswith("|") or bool(link), information=bool(raw.IsInformation()), raw=raw)


def variable_usage(ks, part, *, items=None, part_variables=None) -> dict[str, list[str]]:
    """{переменная детали: где используется — «объект.vN» или другая переменная} (текущее исполнение)."""
    # из kompas_lib.build.audit: tree
    raw_vars = part_variables if part_variables is not None else ks.IFeature(part).GetVariables(False, False) or []
    if not raw_vars:
        return {}
    part_vars = [read_variable(v) for v in raw_vars]
    names = {v.name for v in part_vars}
    used: dict[str, list[str]] = {n: [] for n in names}
    for v in part_vars:
        for n in (expression_names(v.expression) & names) - {v.name}:   # '|H' — наследование, не ссылка
            used[n].append(v.name)
    for item in items if items is not None else tree(ks, part):
        for v in ks.IFeature(item.raw).GetVariables(False, False) or []:
            for n in expression_names(str(v.GetExpression() or "")) & names:
                used[n].append(f"{item.name}.{v.GetName()}")
    return used


def unused_variables(ks, part, *, items=None, part_variables=None) -> list[str]:
    """Переменные детали, на которые никто не ссылается (кроме информационных — производных из других
    переменных: их значение для справки)."""
    raw_vars = part_variables if part_variables is not None else ks.IFeature(part).GetVariables(False, False) or []
    if not raw_vars:
        return []
    info = {str(v.GetName()) for v in raw_vars if v.IsInformation()}
    return sorted(n for n, where in variable_usage(ks, part, items=items, part_variables=raw_vars).items()
                  if not where and n not in info)


class Variables:
    """Переменные текущего исполнения детали построителя `b` (`b.vars`)."""

    def __init__(self, builder: "PartBuilder") -> None:
        self.b = builder
        self.ks = builder.ks

    # --- чтение ---------------------------------------------------------------------------------------
    def _feature(self, owner):
        if owner is None or owner == "":
            return self.ks.IFeature(self.b.part), ""
        raw = getattr(owner, "raw", None) or self.b.get(owner)
        f = self.ks.IFeature(raw)
        return f, str(f.GetName())

    def list(self, owner=None) -> list[Variable]:
        """Переменные детали (`owner=None`) или параметры объекта дерева (имя или `Step`)."""
        feat, name = self._feature(owner)
        return [read_variable(v, name) for v in feat.GetVariables(False, False) or []]

    def get(self, name: str, owner=None) -> Variable:
        for v in self.list(owner):
            if v.name == name:
                return v
        raise KeyError(f"Нет переменной {name!r}" + (f" у {owner!r}" if owner else " детали"))

    def __contains__(self, name: str) -> bool:
        return any(v.name == name for v in self.list())

    def parameter(self, owner, parameter: str) -> Variable:
        """Параметр объекта по имени переменной (`v20`) или по названию («Расстояние 1», регистр не важен)."""
        items = self.list(owner)
        hits = [v for v in items if v.name == parameter] or \
               [v for v in items if v.parameter.casefold() == parameter.strip().casefold()]
        if len(hits) != 1:
            avail = ", ".join(f"{v.name} «{v.parameter}»={v.value:g}" for v in items)
            raise KeyError(f"{owner!r}: параметр {parameter!r} " + ("неоднозначен" if hits else "не найден")
                           + f"; есть: {avail}")
        return hits[0]

    def usage(self) -> dict[str, list[str]]:
        """{переменная детали: где используется — «объект.vN» или другая переменная}."""
        return variable_usage(self.ks, self.b.part)

    def unused(self) -> list[str]:
        """Переменные детали, на которые никто не ссылается (кроме информационных)."""
        return unused_variables(self.ks, self.b.part)

    # --- изменение -------------------------------------------------------------------------------------
    def rebuild(self) -> bool:
        """Пересчитать модель после изменения переменных (только так меняется геометрия, s101b)."""
        try:
            return bool(self.b.doc.d3.RebuildDocument())
        finally:
            self.b.invalidate_geometry()

    def _check_names(self, expr: str, allow: Iterable[str] = ()) -> None:
        # из kompas_lib.build.builder: BuildError
        known = {v.name for v in self.list()} | set(allow)
        missing = sorted(expression_names(expr) - known)
        if missing:
            raise BuildError(f"В выражении {expr!r} неизвестные переменные: {', '.join(missing)} "
                             "(KsAPI создал бы их молча — сначала vars.add)")

    def add(self, name: str, value: float | str, note: str = "") -> "Step":
        """Новая переменная детали: число или выражение из уже существующих переменных."""
        # из kompas_lib.build.builder: BuildError
        part = self.b.part
        if not part.IsVariableNameValid(name):
            raise BuildError(f"Имя переменной {name!r} недопустимо или уже занято")
        if isinstance(value, str):
            self._check_names(value)
        before = self.b.metrics()
        self.b.invalidate_geometry()
        raw = part.AddVariable(name, 0.0 if isinstance(value, str) else float(value), note)
        if not raw:
            raise BuildError(f"Переменная {name!r} не создана")
        if isinstance(value, str) and not is_literal(value):
            raw.SetExpression(value)
            if self.get(name).expression.replace(" ", "") != value.replace(" ", ""):
                raw.Delete()
                raise BuildError(f"{name}: выражение {value!r} отклонено KsAPI (синтаксис?)")
        return self._finish(name, "new-variable", before, [])

    def set(self, name: str, value: float | str, owner=None) -> "Step":
        """Изменить переменную детали (число или выражение) и перестроить модель. В зависимом исполнении это
        переопределение только для него (самое дешёвое отличие исполнений: дерево не растёт).

        `owner` — объект дерева (имя или `Step`/эскиз): тогда `name` — его параметр (`v9` или название), например
        ведущий размер эскиза; выражение для него — то же, что `bind`."""
        # из kompas_lib.build.builder: BuildError
        if owner is not None:
            if isinstance(value, str) and not is_literal(value):
                return self.bind(owner, name, value)
            var = self.parameter(owner, name)
            before = self.b.metrics()
            undo = self._remember(var)
            self.b.invalidate_geometry()
            var.raw.SetValue(float(value))
            return self._finish(f"{var.owner}.{var.name}", "variable", before, [undo], owner=var.owner)
        var = self.get(name)
        if isinstance(value, str) and not is_literal(value):
            self._check_names(value)
            if name in expression_names(value):
                raise BuildError(f"{name}: выражение ссылается само на себя")
        before = self.b.metrics()
        undo = self._remember(var)
        self.b.invalidate_geometry()
        if isinstance(value, str) and not is_literal(value):
            var.raw.SetExpression(value)
            got = self.get(name)
            if got.expression.replace(" ", "") != value.replace(" ", ""):
                raise BuildError(f"{name}: выражение {value!r} отклонено KsAPI (синтаксис?)")
        else:
            var.raw.SetValue(float(value))
        return self._finish(name, "variable", before, [undo])

    def bind(self, owner, parameter: str, expression: str) -> "Step":
        """Привязать параметр объекта дерева к выражению из переменных детали: `bind("Корпус", "Расстояние 1", "H")`.

        Пустое выражение отвязывает параметр (значение остаётся текущим числом)."""
        # из kompas_lib.build.builder: BuildError
        var = self.parameter(owner, parameter)
        self._check_names(expression)
        before = self.b.metrics()
        undo = self._remember(var)
        self.b.invalidate_geometry()
        if expression:
            var.raw.SetExpression(expression)
        else:
            var.raw.SetExpression(_num_text(var.value))
        got = self.parameter(owner, var.name)
        want = expression or _num_text(var.value)
        if got.expression.replace(" ", "") != want.replace(" ", "") and not (is_literal(want) and is_literal(got.expression)):
            raise BuildError(f"{var.owner}.{var.name}: выражение {expression!r} отклонено KsAPI (синтаксис?)")
        return self._finish(f"{var.owner}.{var.name}", "bind", before, [undo], owner=var.owner)

    def delete(self, name: str) -> None:
        """Удалить переменную детали текущего исполнения (используемую KsAPI не удаляет — BuildError).
        Пригодится для «сирот»: переменных размеров эскиза, который правили после создания зависимых
        исполнений, — в зависимых после переоткрытия они остаются переменными детали (s104i)."""
        # из kompas_lib.build.builder: BuildError
        var = self.get(name)
        self.b.invalidate_geometry()
        if not var.raw.Delete():
            where = ", ".join(self.usage().get(name, [])) or "?"
            raise BuildError(f"Переменная {name!r} не удалена (используется: {where})")
        self.b.invalidate_geometry()

    # --- служебное ------------------------------------------------------------------------------------
    @staticmethod
    def _remember(var: Variable):
        raw, expr, value = var.raw, var.expression, var.value

        def restore() -> None:
            if expr and not is_literal(expr) and not var.inherited:
                raw.SetExpression(expr)
            else:
                raw.SetValue(value)
        return restore

    def _finish(self, name: str, kind: str, before, undo: list, owner: str = "") -> "Step":
        # из kompas_lib.build.audit: _active_tree_errors
        # из kompas_lib.build.builder: BuildError, Step
        ok = self.rebuild()
        errors = _active_tree_errors(self.ks, self.b.part)
        if not ok or errors:
            for fn in undo:
                fn()
            self.rebuild()
            raise BuildError(f"{name} ({kind}): " + (f"ошибки в дереве: {', '.join(errors)}" if errors
                                                     else "модель не перестроилась") + ". Значение возвращено.")
        after = self.b.metrics()
        raw = self.get(name.split(".", 1)[1], owner).raw if owner else self.get(name).raw
        step = Step(name, kind, raw, before, after)
        if kind == "variable" and abs(after.volume - before.volume) <= self.b.tol and after.faces == before.faces:
            step.warnings.append("геометрия не изменилась — переменная ни к чему не привязана?")
        self.b.steps.append(step)
        return step


