# === 20/55 kompas_lib.build.constraints — kompas_lib/build/constraints.py
# ==================================================================================================================
"""Полное определение эскиза: ограничения и ведущие размеры (spikes/s103–s103f).

Устройство KsAPI:
* ограничение — `IDrawingObject(obj).NewConstraint()` → `SetConstraintType(ksC…)`, `SetIndex` (точка объекта:
  отрезок 0/1 — начало/конец, дуга 0 — центр, 1 — (X1, Y1), 2 — (X2, Y2), окружность 0 — центр),
  `SetPartners([obj2])`, `SetPartnerIndex`, `Create()`;
* ⚠ **избыточное** ограничение `Create()` не создаёт (False) — на этом построен жадный отбор: кандидаты идут по
  приоритету, лишние отбрасываются самим КОМПАСом;
* ведущий размер — размер в `ISymbols2DContainer` вида эскиза + `Associate()` + **оба** ограничения
  `ksCFixedDim` и `ksCDimWithVariable` (только переменная — размер не ведущий, эскиз остаётся недоопределённым;
  только фиксированный — без переменной). Пустое имя переменной — КОМПАС даёт `vN`;
* размер «от начала координат» привязывается только к объекту в этой точке: если в (0, 0) нет точки контура,
  ставится вспомогательная точка с фиксацией;
* состояние эскиза (`ISketch.GetConstraintsState`) обновляется только после `EndEdit()` + `Update()`.

Чистая часть — `plan_constraints(geos)`: по геометрии эскиза (как её отдал КОМПАС) список кандидатов в порядке
приоритета: совпадения → концентричность → горизонталь/вертикаль → касания → привязка к началу координат →
диаметры/радиусы → длины отрезков → проекции наклонных → межцентровые → положение точек от начала координат.
"""

import math
from contextlib import contextmanager, nullcontext
from dataclasses import dataclass, field
from typing import Sequence

SKETCH_TOL = 1e-6
ORIGIN = -1                     # индекс вспомогательной точки начала координат в плане


@dataclass(frozen=True)
class Geo:
    """Объект эскиза: `index` — номер в списке объектов, `pts` — {индекс точки KsAPI: (x, y)}."""
    kind: str                   # line | arc | circle | point
    index: int
    pts: dict
    r: float = 0.0

    @property
    def center(self):
        return self.pts.get(0) if self.kind in ("arc", "circle") else None


@dataclass(frozen=True)
class Con:
    """Геометрическое ограничение: тип ksConstraintTypeEnum (имя), объект/точка, партнёр/точка."""
    type: str
    a: int
    ia: int = -1
    b: int | None = None
    ib: int = -1
    desc: str = ""


@dataclass(frozen=True)
class SketchDim:
    """Ведущий размер: diameter | radius (объект `obj`) или h | v | parallel между точками p1, p2."""
    kind: str
    p1: tuple = (0.0, 0.0)
    p2: tuple = (0.0, 0.0)
    obj: int | None = None
    desc: str = ""

    @property
    def value(self) -> float:
        dx, dy = self.p2[0] - self.p1[0], self.p2[1] - self.p1[1]
        return {"h": abs(dx), "v": abs(dy)}.get(self.kind, math.hypot(dx, dy))


@dataclass
class Plan:
    items: list = field(default_factory=list)     # Con | SketchDim в порядке приоритета
    origin_point: bool = False                    # нужна вспомогательная точка в (0, 0)


def _same_point(p, q) -> bool:
    return abs(p[0] - q[0]) <= SKETCH_TOL and abs(p[1] - q[1]) <= SKETCH_TOL


def _f(p) -> str:
    return f"({p[0]:g}, {p[1]:g})"


def _tangent_at(g: Geo, i: int, p):
    """Направление касательной объекта в его точке i (единичный вектор, знак не важен)."""
    if g.kind == "line":
        (x1, y1), (x2, y2) = g.pts[0], g.pts[1]
        n = math.hypot(x2 - x1, y2 - y1)
        return ((x2 - x1) / n, (y2 - y1) / n) if n > SKETCH_TOL else None
    if g.kind == "arc":
        cx, cy = g.pts[0]
        n = math.hypot(p[0] - cx, p[1] - cy)
        return (-(p[1] - cy) / n, (p[0] - cx) / n) if n > SKETCH_TOL else None
    return None


def plan_constraints(geos: Sequence[Geo]) -> Plan:
    plan = Plan()
    add = plan.items.append
    by = {g.index: g for g in geos}

    # --- совпадения концов (центры не объединяются с концами)
    ends = [(g.index, i, p) for g in geos for i, p in sorted(g.pts.items())
            if not (g.kind in ("arc", "circle") and i == 0)]
    clusters: list[list[tuple[int, int, tuple]]] = []
    for e in ends:
        for c in clusters:
            if _same_point(c[0][2], e[2]):
                c.append(e)
                break
        else:
            clusters.append([e])
    for c in clusters:
        a, ia, p = c[0]
        for b, ib, _ in c[1:]:
            if a != b:
                add(Con("ksCMergePoints", a, ia, b, ib, f"совпадение {_f(p)}"))

    # --- концентричность: общий центр у дуг и окружностей
    centers: list[list[Geo]] = []
    for g in geos:
        if g.center is None:
            continue
        for c in centers:
            if _same_point(c[0].center, g.center):
                c.append(g)
                break
        else:
            centers.append([g])
    for c in centers:
        for g in c[1:]:
            add(Con("ksCMergePoints", c[0].index, 0, g.index, 0, f"общий центр {_f(g.center)}"))

    # --- горизонталь / вертикаль
    for g in geos:
        if g.kind == "line":
            (x1, y1), (x2, y2) = g.pts[0], g.pts[1]
            if abs(y1 - y2) <= SKETCH_TOL:
                add(Con("ksCHorizontal", g.index, desc=f"горизонталь {_f(g.pts[0])}–{_f(g.pts[1])}"))
            elif abs(x1 - x2) <= SKETCH_TOL:
                add(Con("ksCVertical", g.index, desc=f"вертикаль {_f(g.pts[0])}–{_f(g.pts[1])}"))

    # --- касание в общих концах (отрезок–дуга, дуга–дуга)
    for c in clusters:
        for k, (a, ia, p) in enumerate(c):
            for b, ib, _ in c[k + 1:]:
                ga, gb = by[a], by[b]
                if a == b or "arc" not in (ga.kind, gb.kind):
                    continue
                ta, tb = _tangent_at(ga, ia, p), _tangent_at(gb, ib, p)
                if ta and tb and abs(ta[0] * tb[1] - ta[1] * tb[0]) <= 1e-9:
                    add(Con("ksCTangentTwoCurves", a, -1, b, -1, f"касание в {_f(p)}"))

    # --- привязка к началу координат
    reps = [(c[0][0], c[0][1], c[0][2]) for c in clusters] + \
           [(c[0].index, 0, c[0].center) for c in centers]
    at0 = next(((o, i) for o, i, p in reps if _same_point(p, (0.0, 0.0))), None)
    if at0 is None:
        plan.origin_point = True
        add(Con("ksCFixedPoint", ORIGIN, 0, desc="точка начала координат зафиксирована"))
        origin = (ORIGIN, 0)
        # Начало координат в середине отрезка (симметричный контур): размер «от начала» привязался бы к середине
        # отрезка, а не к точке (s104k) — точку ставим в середину отрезка ограничением.
        for g in geos:
            if g.kind == "line":
                (x1, y1), (x2, y2) = g.pts[0], g.pts[1]
                if _same_point(((x1 + x2) / 2, (y1 + y2) / 2), (0.0, 0.0)):
                    add(Con("ksCPointOnCurveMiddle", ORIGIN, 0, g.index, -1,
                            f"начало координат в середине {_f(g.pts[0])}–{_f(g.pts[1])}"))
    else:
        add(Con("ksCFixedPoint", at0[0], at0[1], desc="точка в начале координат зафиксирована"))
        origin = at0

    # --- размеры формы
    for g in geos:
        if g.kind == "circle":
            add(SketchDim("diameter", obj=g.index, desc=f"Ø{2 * g.r:g} в {_f(g.center)}"))
    for g in geos:
        if g.kind == "arc":
            add(SketchDim("radius", obj=g.index, desc=f"R{g.r:g} в {_f(g.center)}"))
    slanted = []
    for g in geos:
        if g.kind != "line":
            continue
        p1, p2 = g.pts[0], g.pts[1]
        if abs(p1[1] - p2[1]) <= SKETCH_TOL:
            add(SketchDim("h", p1, p2, desc=f"длина {_f(p1)}–{_f(p2)}"))
        elif abs(p1[0] - p2[0]) <= SKETCH_TOL:
            add(SketchDim("v", p1, p2, desc=f"длина {_f(p1)}–{_f(p2)}"))
        else:
            add(SketchDim("parallel", p1, p2, desc=f"длина {_f(p1)}–{_f(p2)}"))
            slanted.append((p1, p2))
    for p1, p2 in slanted:
        add(SketchDim("h", p1, p2, desc=f"проекция X {_f(p1)}–{_f(p2)}"))
        add(SketchDim("v", p1, p2, desc=f"проекция Y {_f(p1)}–{_f(p2)}"))
    cs = [c[0] for c in centers]
    for k in range(1, len(cs)):
        p1, p2 = cs[k - 1].center, cs[k].center
        for kind, d in (("h", p2[0] - p1[0]), ("v", p2[1] - p1[1])):
            if abs(d) > SKETCH_TOL:
                add(SketchDim(kind, p1, p2, desc=f"межцентровое {kind.upper()} {_f(p1)}–{_f(p2)}"))

    # --- положение точек от начала координат (центры, затем концы)
    o = (0.0, 0.0)
    ordered = [r for r in reps if r[1] == 0 and by[r[0]].kind in ("arc", "circle")] + \
              [r for r in reps if not (r[1] == 0 and by[r[0]].kind in ("arc", "circle"))]
    for obj, idx, p in ordered:
        if (obj, idx) == origin or _same_point(p, o):
            continue
        for kind, d, align in (("h", p[0], "ksCVAlignPoints"), ("v", p[1], "ksCHAlignPoints")):
            if abs(d) > SKETCH_TOL:
                add(SketchDim(kind, o, p, desc=f"положение {kind.upper()} {_f(p)}"))
            else:
                add(Con(align, obj, idx, origin[0], origin[1],
                        f"{'на оси Y' if kind == 'h' else 'на оси X'}: {_f(p)}"))
    return plan


# --- KsAPI ---------------------------------------------------------------------------------------------
_STATE = {0: "unknown", 1: "defined", 2: "under", 3: "redundant"}


@contextmanager
def sketch_edit(ks, sketch_raw):
    """Редактирование эскиза → (IDrawingContainer, ISymbols2DContainer) вида эскиза.

    ⚠ `EndEdit()` без изменений в эскизе (в т.ч. после `BeginEdit(True)` только для чтения) сбрасывает
    состояние определённого эскиза в «недоопределён», и это сохраняется в файл (s104d). Пересчёт идёт, только
    если объекты эскиза менялись, поэтому перед выходом здесь добавляется и удаляется точка — состояние
    остаётся верным (недоопределённый так и остаётся under, s104e).
    ⚠ Любая правка эскиза в исходном исполнении (даже такое «касание») переносится в зависимые исполнения и
    затирает их переопределения размеров этого эскиза (s104i). Только для чтения эскиз не открывать —
    определённый эскиз описывают его размеры-переменные."""
    frag = sketch_raw.BeginEdit(False)
    view = frag.GetViewsAndLayersManager().GetViews().GetActiveView()
    dc = ks.IDrawingContainer(view)
    try:
        yield dc, ks.ISymbols2DContainer(view)
    finally:
        p = dc.GetPoints().Add()
        p.SetX(0.0); p.SetY(0.0)
        if p.Update():
            ks.IDrawingObject(p).Delete()
        sketch_raw.EndEdit()
    sketch_raw.Update()


def sketch_state(ks, sketch_raw, refresh: bool = False) -> str:
    """defined | under | redundant | unknown. `refresh` — пересчитать (пустое редактирование, см. `sketch_edit`):
    для файлов, где состояние уже испорчено открытием эскиза без изменений. ⚠ В исходном исполнении это
    затирает переопределения эскиза в зависимых исполнениях."""
    if refresh:
        with sketch_edit(ks, sketch_raw):
            pass
    return _STATE.get(int(sketch_raw.GetConstraintsState()), "unknown")


@dataclass
class ConstraintReport:
    sketch: str
    state: str                                                  # defined | under | redundant | unknown
    constraints: list[str] = field(default_factory=list)        # принятые геометрические ограничения
    dimensions: list[tuple[str, float, str]] = field(default_factory=list)   # (переменная, значение, что)
    rejected: list[str] = field(default_factory=list)           # отброшены КОМПАСом как избыточные
    origin_point: bool = False                                  # добавлена точка в начале координат
    unchanged: bool = False  # уже определён: без повторного открытия/ограничений

    @property
    def ok(self) -> bool:
        return self.state == "defined"

    def __str__(self) -> str:
        dims = ", ".join(f"{n}={v:g}" for n, v, _ in self.dimensions)
        return (f"{'✔' if self.ok else '✘'} {self.sketch}: {self.state}; ограничений {len(self.constraints)}, "
                f"размеров {len(self.dimensions)}" + (f" ({dims})" if dims else "")
                + f"; избыточных кандидатов {len(self.rejected)}"
                + ("; уже определён, без повторной правки" if self.unchanged else ""))


def read_geometry(ks, dc) -> tuple[list[Geo], list]:
    """Геометрия вида эскиза: объекты Geo и соответствующие им объекты KsAPI (тот же порядок)."""
    geos, objs = [], []
    for o in dc.GetLineSegments().GetObjects() or []:
        s = ks.ILineSegment(o)
        geos.append(Geo("line", len(objs), {0: (s.GetX1(), s.GetY1()), 1: (s.GetX2(), s.GetY2())}))
        objs.append(o)
    for o in dc.GetArcs().GetObjects() or []:
        a = ks.IArc(o)
        geos.append(Geo("arc", len(objs), {0: (a.GetXc(), a.GetYc()), 1: (a.GetX1(), a.GetY1()),
                                           2: (a.GetX2(), a.GetY2())}, a.GetRadius()))
        objs.append(o)
    for o in dc.GetCircles().GetObjects() or []:
        c = ks.ICircle(o)
        geos.append(Geo("circle", len(objs), {0: (c.GetXc(), c.GetYc())}, c.GetRadius()))
        objs.append(o)
    for o in dc.GetPoints().GetObjects() or []:
        p = ks.IPoint(o)
        geos.append(Geo("point", len(objs), {0: (p.GetX(), p.GetY())}))
        objs.append(o)
    return geos, objs


def _moved(before: Sequence[Geo], after: Sequence[Geo]) -> list[str]:
    out = []
    for g, h in zip(before, after):
        for i, p in g.pts.items():
            q = h.pts.get(i)
            if q is None or not _same_point(p, q):
                out.append(f"{g.kind}#{g.index}.{i} {_f(p)} → {_f(q) if q else '—'}")
    return out


def apply_constraints(ks, sketch_raw, name: str = "", *, force: bool = False) -> ConstraintReport:
    """Полностью определить эскиз `sketch_raw` (ISketch): план → ограничения и ведущие размеры с отбором
    избыточных → проверка, что геометрия не сдвинулась → состояние. Геометрию не меняет; при сдвиге
    всё добавленное удаляется и бросается BuildError."""
    if not force and int(sketch_raw.GetConstraintsState()) == 1:
        return ConstraintReport(name or str(sketch_raw.GetName()), "defined", unchanged=True)
    return _apply_constraints_in_context(ks, sketch_raw, name, sketch_edit(ks, sketch_raw))


def _constrain_open_view(ks, sketch_raw, dc, sym, name: str = "") -> ConstraintReport:
    """Создание и определение за одну правку; состояние читать после EndEdit."""
    return _apply_constraints_in_context(ks, sketch_raw, name, nullcontext((dc, sym)))


def _apply_constraints_in_context(ks, sketch_raw, name, edit_context) -> ConstraintReport:
    # из kompas_lib.enums: raw
    # из kompas_lib.build.builder: BuildError
    CT = raw.ksConstraintTypeEnum
    orient = raw.ksLineDimensionOrientationEnum
    rep = ConstraintReport(name or str(sketch_raw.GetName()), "unknown")
    created: list = []                      # размеры и точка — удалить при откате
    cons: list = []
    with edit_context as (dc, sym):
        geos, objs = read_geometry(ks, dc)
        plan = plan_constraints(geos)
        ref = {i: o for i, o in enumerate(objs)}
        if plan.origin_point:
            pt = dc.GetPoints().Add()
            pt.SetX(0.0); pt.SetY(0.0)
            if not pt.Update():
                raise BuildError(f"{rep.sketch}: точка начала координат не создана")
            ref[ORIGIN] = pt
            created.append(pt)
            rep.origin_point = True

        def constraint(obj, ctype, index=-1, partner=None, pindex=-1, variable=None):
            c = ks.IDrawingObject(obj).NewConstraint()
            c.SetConstraintType(int(getattr(CT, ctype)))
            if index >= 0:
                c.SetIndex(index)
            if partner is not None:
                c.SetPartners([ks.IDrawingObject(partner)])
                if pindex >= 0:
                    c.SetPartnerIndex(pindex)
            if variable is not None:
                c.SetVariable(variable)
            return c if c.Create() else None

        for it in plan.items:
            if isinstance(it, Con):
                c = constraint(ref[it.a], it.type, it.ia, ref.get(it.b) if it.b is not None else None, it.ib)
                (rep.constraints if c else rep.rejected).append(it.desc)
                if c:
                    cons.append(c)
                continue
            d = _make_dim(ks, sym, it, ref, orient)
            if d is None or not ks.IDrawingObject(d).Associate() and it.kind not in ("diameter", "radius"):
                if d is not None:
                    ks.IDrawingObject(d).Delete()
                rep.rejected.append(it.desc + " (не привязался)")
                continue
            if not constraint(d, "ksCFixedDim"):
                ks.IDrawingObject(d).Delete()
                rep.rejected.append(it.desc)
                continue
            c = constraint(d, "ksCDimWithVariable", variable="")
            created.append(d)
            rep.dimensions.append((str(c.GetVariable()) if c else "", it.value if it.obj is None
                                   else (2 * geos[it.obj].r if it.kind == "diameter" else geos[it.obj].r), it.desc))
        moved = _moved(geos, read_geometry(ks, dc)[0])
        if moved:
            for o in objs:
                ks.IDrawingObject(o).DeleteConstraints()
            for o in created:
                ks.IDrawingObject(o).Delete()
            raise BuildError(f"{rep.sketch}: ограничения сдвинули геометрию ({'; '.join(moved[:4])}) — сняты")
    rep.state = _STATE.get(int(sketch_raw.GetConstraintsState()), "unknown")
    return rep


def _make_dim(ks, sym, it: SketchDim, ref: dict, orient):
    if it.kind in ("diameter", "radius"):
        obj = ref[it.obj]
        src = ks.ICircle(obj) if it.kind == "diameter" else ks.IArc(obj)
        d = (sym.GetDiametralDimensions() if it.kind == "diameter" else sym.GetRadialDimensions()).Add()
        d.SetBaseObject(ks.IDrawingObject(obj))
        d.SetXc(src.GetXc()); d.SetYc(src.GetYc()); d.SetRadius(src.GetRadius())
        d.SetAngle(45.0)
        d.SetDimensionType(False)
        return d if d.Update() else None
    d = sym.GetLineDimensions().Add()
    (x1, y1), (x2, y2) = it.p1, it.p2
    d.SetX1(x1); d.SetY1(y1); d.SetX2(x2); d.SetY2(y2)
    d.SetOrientation(int({"h": orient.ksLinDHorizontal, "v": orient.ksLinDVertical,
                          "parallel": orient.ksLinDParallel}[it.kind]))
    off = 0.1 * max(it.value, 10.0)
    d.SetX3((x1 + x2) / 2 + (off if it.kind != "h" else 0.0))
    d.SetY3((y1 + y2) / 2 + (off if it.kind != "v" else 0.0))
    return d if d.Update() else None


