# === 21/55 kompas_lib.build.embodiments — kompas_lib/build/embodiments.py
# ==================================================================================================================
"""Исполнения детали: создание зависимого, переключение, сравнение.

Ключевое (spikes/s90, s91): у каждого исполнения своя верхняя деталь. Новые операции, правка параметров,
эскизов и исключение объектов идут в **текущее** исполнение и не трогают исходное — если брать деталь заново
после `SetCurrentEmbodiment` (это делает `PartDocument.part`). Признаки KsAPI `IsConnectedWithInitialEmbodiment`
и `IFeature.IsModified` отличий не показывают, поэтому `diff` сравнивает снимки параметров объектов.

    emb = Embodiments(part_doc)
    i = emb.add_dependent(number="01")
    with emb.use(i):                       # всё внутри — в исполнении i
        b.modify("Скругление верха", lambda f: f.SetRadius1(3))
        b.cut(b.sketch("XZ", [circle(0, 20, 13)]), 10)
    print(emb.diff(0, i).summary())
"""

from contextlib import contextmanager
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Iterator

# из kompas_lib.enums: by_name
# из kompas_lib.errors: KompasError
# из kompas_lib.build.audit: tree
# из kompas_lib.build.variables: expression_names, read_variable
# из kompas_lib.vec3: rounded

# из kompas_lib.model: PartDocument  (только для аннотаций)


def object_params(ks, mo, t: int, *, variables=None):
    """Снимок параметров объекта дерева для сравнения исполнений (None — тип не сравнивается по параметрам)."""
    if t == 5:
        sk = ks.ISketch(mo)
        if int(sk.GetConstraintsState()) == 1:
            # Определённый эскиз задан своими размерами — сравниваем их, не открывая эскиз: пустое
            # BeginEdit/EndEdit сбрасывает его состояние в «недоопределён» (s104d), а «касание» в исходном
            # исполнении затирает переопределения этого эскиза в зависимых (s104i).
            dims = sorted((str(v.GetName()), rounded(v.GetValue()))
                          for v in (variables if variables is not None else ks.IFeature(mo).GetVariables(False, False) or [])
                          if str(v.GetParameterNote() or "").strip().endswith("размер"))
            return ("sketch", "defined", tuple(dims))
        frag = sk.BeginEdit(True)
        try:
            dc = ks.IDrawingContainer(frag.GetViewsAndLayersManager().GetViews().GetActiveView())
            lines = sorted((rounded(o.GetX1()), rounded(o.GetY1()), rounded(o.GetX2()), rounded(o.GetY2()))
                           for o in (ks.ILineSegment(x) for x in dc.GetLineSegments().GetObjects() or []))
            arcs = sorted((rounded(o.GetXc()), rounded(o.GetYc()), rounded(o.GetRadius()), rounded(o.GetAngle1()), rounded(o.GetAngle2()))
                          for o in (ks.IArc(x) for x in dc.GetArcs().GetObjects() or []))
            circles = sorted((rounded(o.GetXc()), rounded(o.GetYc()), rounded(o.GetRadius()))
                             for o in (ks.ICircle(x) for x in dc.GetCircles().GetObjects() or []))
        finally:
            sk.EndEdit()
        return ("sketch", tuple(lines), tuple(arcs), tuple(circles))
    if t in (24, 25, 26):
        e = ks.IExtrusion(mo)
        blind = by_name("etBlind")

        def side(s: bool):
            t = int(e.GetExtrusionType(s))
            # глубина «насквозь»/«до поверхности» вычисляется по телу — меняется вслед за ним, это не отличие
            return t, (rounded(e.GetDepth(s)) if t == blind else None)
        return ("extrusion", int(e.GetDirection()), *side(True), *side(False))
    if t in (27, 28, 29):
        r = ks.IRotated(mo)
        return ("rotated", int(r.GetDirection()), rounded(r.GetAngle(True)), rounded(r.GetAngle(False)))
    if t == 34:
        f = ks.IFillet(mo)
        return ("fillet", rounded(f.GetRadius1()), rounded(f.GetRadius2()), len(f.GetBaseObjects() or []))
    if t == 33:
        c = ks.IChamfer(mo)
        return ("chamfer", rounded(c.GetDistance1()), rounded(c.GetDistance2()), rounded(c.GetAngle()))
    if t == 14:
        p = ks.IPlane3DByOffset(mo)
        return ("offset", rounded(p.GetOffset()), bool(p.GetDirection()))
    if t == 36:
        c = ks.ICircularPattern(mo)
        return ("circular", int(c.GetCount1()), rounded(c.GetStep1()), int(c.GetCount2()), rounded(c.GetStep2()))
    if t in (48, 49):
        return ("mirror", len(ks.IFeaturePattern(mo).GetInitialObjects() or []))
    if t == 35:
        p = ks.ILinearPattern(mo)
        return ("linear", int(p.GetCount1()), rounded(p.GetStep1()), bool(p.GetDirection1()), int(p.GetCount2()),
                rounded(p.GetStep2()), bool(p.GetDirection2()))
    if t in (52, 583):
        h = ks.IHole3D(mo)
        return ("hole", int(h.GetHoleType()), rounded(h.GetDiameter()), int(h.GetDepthType()), rounded(h.GetDepth()),
                int(h.GetEndFaceType()))
    if t == 43:
        s = ks.IShell(mo)
        return ("shell", rounded(s.GetThickness()), int(s.GetThinType()), len(s.GetDeletedFaces() or []))
    if t == 44:
        r = ks.IRib(mo)
        tp = ks.IThinParameters(mo)
        return ("rib", rounded(r.GetAngle()), int(r.GetSide()), rounded(tp.GetThickness(True)) if tp else None)
    if t == 42:
        i = ks.IIncline(mo)
        return ("draft", rounded(i.GetAngle()), bool(i.GetDirection()), len(i.GetFaces() or []))
    if t == 58:
        th = ks.IThread(mo)
        tp = ks.IThreadsParameters(mo)
        return ("thread", bool(th.IsAutoLength()), rounded(th.GetLength()), tp.GetDesignation() if tp else None)
    return None


@dataclass
class EmbodimentDiff:
    a: int
    b: int
    added: list[str] = field(default_factory=list)       # есть только в b
    removed: list[str] = field(default_factory=list)     # есть только в a
    excluded: list[str] = field(default_factory=list)    # исключены в b, но не в a
    included: list[str] = field(default_factory=list)    # включены в b, исключены в a
    changed: list[tuple[str, object, object]] = field(default_factory=list)
    # переменные детали: (имя, значение в a | None, значение в b | None) — переопределены/добавлены в b
    variables: list[tuple[str, float | None, float | None]] = field(default_factory=list)
    # объекты и производные/унаследованные переменные, изменившиеся только через выражения
    # (следствие `variables`, в `total` не входят)
    driven: list[str] = field(default_factory=list)

    @property
    def total(self) -> int:
        """Число объектов и переменных, которыми исполнение b отличается от a (без `driven`)."""
        return (len(self.added) + len(self.removed) + len(self.excluded) + len(self.included) + len(self.changed)
                + len(self.variables))

    def summary(self) -> str:
        lines = [f"Исполнение {self.b} относительно {self.a}: отличий {self.total}"]
        for name, va, vb in self.variables:
            fa = "—" if va is None else f"{va:g}"
            fb = "—" if vb is None else f"{vb:g}"
            lines.append(f"  переменная: {name}: {fa} → {fb}")
        for title, names in (("добавлены", self.added), ("удалены", self.removed), ("исключены", self.excluded),
                             ("включены", self.included)):
            if names:
                lines.append(f"  {title}: " + ", ".join(names))
        for name, pa, pb in self.changed:
            lines.append(f"  изменён: {name}: {pa} → {pb}")
        if self.driven:
            lines.append("  через переменные: " + ", ".join(self.driven))
        return "\n".join(lines)


class Embodiments:
    def __init__(self, doc: "PartDocument") -> None:
        self.doc = doc
        self.ks = doc.ks
        self.mgr = self.ks.IEmbodimentsManager(doc.raw)

    @property
    def count(self) -> int:
        return int(self.mgr.GetEmbodimentCount())

    @property
    def current(self) -> int:
        return int(self.mgr.GetCurrentEmbodimentIndex())

    def marking(self, i: int) -> str:
        return self.mgr.GetEmbodimentMarking(i, -1, False)

    def add_dependent(self, parent: int = 0, base_marking: str = "", number: str = "", additional: str = "") -> int:
        """Зависимое исполнение от `parent`; возвращает его индекс. Текущее исполнение не меняется
        (KsAPI `AddEmbodiment` делает новое текущим — здесь прежнее восстанавливается, spikes/s96b)."""
        n, prev = self.count, self.current
        self.doc.invalidate_geometry()
        if not self.mgr.AddEmbodiment(parent, True, base_marking, number, additional) or self.count != n + 1:
            raise KompasError(f"Зависимое исполнение от {parent} не создано")
        self.activate(prev)
        return self.count - 1

    def activate(self, i: int) -> None:
        if self.current == i:
            return
        self.doc.invalidate_geometry()
        if not self.mgr.SetCurrentEmbodiment(i) or self.current != i:
            raise KompasError(f"Не удалось сделать текущим исполнение {i}")

    @contextmanager
    def use(self, i: int) -> Iterator[None]:
        """Временно сделать исполнение i текущим (всё построение внутри идёт в него)."""
        prev = self.current
        self.activate(i)
        try:
            yield
        finally:
            self.activate(prev)

    def snapshot(self, i: int) -> dict[str, tuple[int, bool, object]]:
        """{имя: (тип, исключён, параметры)} для объектов дерева исполнения i."""
        return self._state(i)[0]

    def variables(self, i: int) -> dict[str, tuple[float, str, bool]]:
        """{имя переменной детали: (значение, выражение, унаследована)} в исполнении i."""
        return self._state(i)[2]

    def _state(self, i: int):
        """Снимок исполнения: дерево, переменные объектов {объект: {vN: (значение, выражение)}}, переменные детали."""
        with self.use(i):
            part = self.doc.part
            items = tree(self.ks, part)
            raw_vars = {it.name: self.ks.IFeature(it.raw).GetVariables(False, False) or [] for it in items}
            objs = {it.name: (it.type, it.excluded, object_params(self.ks, it.raw, it.type,
                                                              variables=raw_vars[it.name])) for it in items}
            fvars = {it.name: {str(v.GetName()): (round(float(v.GetValue()), 9), str(v.GetExpression() or ""))
                               for v in raw_vars[it.name]}
                     for it in items}
            pvars = {v.name: (v.value, v.expression, v.inherited)
                     for v in (read_variable(x) for x in self.ks.IFeature(part).GetVariables(False, False) or [])}
        return objs, fvars, pvars

    def diff(self, a: int = 0, b: int = 1) -> EmbodimentDiff:
        """Отличия исполнения b от a: объекты дерева, их параметры и переменные детали. Объект, у которого
        изменились только параметры с выражениями из переменных, попадает в `driven`, а не в `changed`."""
        (sa, fa, va), (sb, fb, vb) = self._state(a), self._state(b)
        d = EmbodimentDiff(a, b)
        d.added = [n for n in sb if n not in sa]
        d.removed = [n for n in sa if n not in sb]
        for name in (n for n in sb if n in sa):
            (ta, ea, pa), (tb, eb, pb) = sa[name], sb[name]
            if eb and not ea:
                d.excluded.append(name)
            elif ea and not eb:
                d.included.append(name)
            elif pa != pb:
                xa, xb = fa.get(name, {}), fb.get(name, {})
                moved = [k for k in xb if k in xa and xa[k][0] != xb[k][0]]
                if moved and all(expression_names(xb[k][1]) for k in moved):
                    d.driven.append(name)
                else:
                    d.changed.append((name, pa, pb))
        for name in list(va) + [n for n in vb if n not in va]:
            x, y = va.get(name), vb.get(name)
            if x is None or y is None:
                d.variables.append((name, x[0] if x else None, y[0] if y else None))
            elif abs(x[0] - y[0]) > 1e-9:
                # своё значение в b — отличие; унаследованное/производное (выражение) — следствие других
                if y[2] or expression_names(y[1]):
                    d.driven.append(name)
                else:
                    d.variables.append((name, x[0], y[0]))
        return d


