"""Материал и масса детали по исполнениям: назначение материала, точность МЦХ, сверка с массой чертежа.

Единицы KsAPI (spikes/s99): плотность — г/см³, `IPart.GetMass()` — г, `IMassInertiaParam.GetVolume()` — см³.
Материал «из справочника» отличается от заданного вручную только ссылкой на запись справочника
(`GetMaterialLocation`, например '0^Material:V…'); на массу влияет лишь плотность, а она у справочных
материалов своя (СЧ18 — 7.2, Сталь 40Х — 7.85). Поэтому `check_mass` показывает, какой плотности
соответствует масса с чертежа, и сколько объёма не хватает при заданной.

    set_material(doc, "СЧ20 ГОСТ 1412-85", rho)          # во всех исполнениях; rho — из справочника КОМПАСа
    for r in check_mass(doc, {0: 13.56, 1: 13.53}):      # кг, допуск 0.5 %
        print(r)
"""

from dataclasses import dataclass
from typing import TYPE_CHECKING, Iterable, Mapping

# из kompas_lib.model: PartDocument  (только для аннотаций)


def _embodiments(doc: "PartDocument", which: Iterable[int] | None):
    mgr = doc.ks.IEmbodimentsManager(doc.raw)
    n = int(mgr.GetEmbodimentCount()) if mgr else 1
    return mgr, (list(range(n)) if which is None else list(which))


def _each(doc: "PartDocument", which: Iterable[int] | None):
    """Сделать текущим каждое исполнение по очереди; после — вернуть прежнее."""
    mgr, idx = _embodiments(doc, which)
    current = int(mgr.GetCurrentEmbodimentIndex()) if mgr else 0
    try:
        for i in idx:
            if mgr and int(mgr.GetCurrentEmbodimentIndex()) != i:
                doc.invalidate_geometry()
                mgr.SetCurrentEmbodiment(i)
            yield i, (mgr.GetEmbodimentMarking(i, -1, False) if mgr else "")
    finally:
        if mgr and int(mgr.GetCurrentEmbodimentIndex()) != current:
            doc.invalidate_geometry()
            mgr.SetCurrentEmbodiment(current)


def set_material(doc: "PartDocument", name: str, density: float, embodiments: Iterable[int] | None = None) -> None:
    """Материал и плотность (г/см³) детали — во всех исполнениях (или в перечисленных)."""
    if density <= 0 or density > 30:
        raise ValueError(f"Плотность {density} г/см³ вне разумного диапазона (0, 30]")
    for _ in _each(doc, embodiments):
        part = doc.part
        doc.invalidate_geometry()
        part.SetMaterial(name, float(density))
        part.Update()


def material(doc: "PartDocument") -> tuple[str, float, str]:
    """(название, плотность г/см³, ссылка на справочник или '') текущего исполнения."""
    part = doc.part
    mi = doc.ks.IMassInertiaParam(part)
    return part.GetMaterial(), round(float(part.GetDensity()), 9), mi.GetMaterialLocation() or ""


MASS_ACCURACY = {"high": 100.0, "default": 25.51}   # «Высокая» — правый край шкалы диалога


def mass_accuracy(doc: "PartDocument", value: float | str | None = None) -> float:
    """Точность расчёта МЦХ документа (0…100, по умолчанию ≈25.51); с `value` — установить: число или
    "high" (= 100) | "default".

    В КОМПАСе v24–v26 это шкала «Настройка → Параметры → Текущий документ → Точность отрисовки и МЦХ → Точность
    расчета МЦХ» с полем 0…100; поле показывает то же число, что и API (в поле 100 → API 100, API 25.51 → «25»).
    Подписи «Высокая» у шкалы нет — так пишут задания (конкурс АСКОН): «Высокая» = ползунок вправо до упора = 100.
    Больше 100 КОМПАС обрезает до 100. На проверенных телах (призмы, тела вращения, эллипсоид) объём от неё не
    зависит (spikes/s93, s99)."""
    st = doc.ks.IDocument3DSettings(doc.ks.IKompasDocument(doc.raw).GetDocumentSettings())
    if value is not None:
        if isinstance(value, str):
            if value not in MASS_ACCURACY:
                raise ValueError(f"Точность МЦХ: число 0…100 или одно из {tuple(MASS_ACCURACY)}, а не {value!r}")
            value = MASS_ACCURACY[value]
        doc.invalidate_geometry()
        st.SetAccuracyMassProperties(float(value))
    return float(st.GetAccuracyMassProperties())


@dataclass
class MassCheck:
    embodiment: int
    marking: str
    volume: float          # мм³
    density: float         # г/см³
    mass: float            # г (KsAPI)
    target: float          # г
    tol: float             # относительный допуск

    @property
    def error(self) -> float:
        """Относительное отклонение массы модели от цели."""
        return (self.mass - self.target) / self.target

    @property
    def ok(self) -> bool:
        return abs(self.error) <= self.tol

    @property
    def implied_density(self) -> float:
        """Плотность, при которой масса модели совпала бы с целью (при текущем объёме), г/см³."""
        return self.target / (self.volume / 1000.0) if self.volume else 0.0

    @property
    def volume_needed(self) -> float:
        """Объём, который дала бы цель при текущей плотности, мм³ (минус текущий — чего не хватает)."""
        return self.target / self.density * 1000.0 if self.density else 0.0

    def __str__(self) -> str:
        mark = "✔" if self.ok else "✘"
        s = (f"{mark} исп.{self.embodiment} {self.marking!r}: m={self.mass / 1000:.5g} кг, цель {self.target / 1000:.5g} кг, "
             f"отклонение {self.error * 100:+.3f} % (допуск ±{self.tol * 100:g} %); V={self.volume:.6g} мм³, ρ={self.density:g}")
        if not self.ok:
            s += (f"\n    при ρ={self.density:g} нужен V={self.volume_needed:.6g} мм³ (Δ{self.volume_needed - self.volume:+.6g});"
                  f" при V модели масса совпала бы с ρ={self.implied_density:.4g} г/см³")
        return s


def check_mass(doc: "PartDocument", target: float | Mapping[int, float] | Iterable[float], tol: float = 0.005,
               unit: str = "kg") -> list[MassCheck]:
    """Сверка массы исполнений с целью: одно число — для всех, {индекс: масса} или список по порядку.
    `unit`: "kg" | "g"."""
    k = 1000.0 if unit == "kg" else 1.0
    if isinstance(target, Mapping):
        targets = {int(i): float(v) * k for i, v in target.items()}
    elif isinstance(target, (int, float)):
        _, idx = _embodiments(doc, None)
        targets = {i: float(target) * k for i in idx}
    else:
        targets = {i: float(v) * k for i, v in enumerate(target)}
    result = []
    for i, marking in _each(doc, sorted(targets)):
        part = doc.part
        mi = doc.ks.IMassInertiaParam(part)
        mi.Calculate()
        result.append(MassCheck(i, marking, float(mi.GetVolume()) * 1000.0, round(float(part.GetDensity()), 9),
                                float(part.GetMass()), targets[i], tol))
    return result


