import bisect
import itertools
import math
import re
from collections import defaultdict
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Iterable, Sequence

# из kompas_lib.geom: Rect
# из kompas_lib.pdf_drawing: Annotation, PdfDrawing, PdfPage, parse_annotation
# из kompas_lib.build.threads: thread_spec
# из kompas_lib.vec3: Vec3, cross, dot, vmul, vsub

# из kompas_lib.model: Face, PartDocument  (только для аннотаций)

FULL = 359.5                 # охват, начиная с которого цилиндр полный (Ø), градусы
_AX = "xyz"
_DIMS = ("diameter", "radius", "thread", "angle", "linear")
_DISCRETE = ("diameter", "radius", "thread")
OK, MISMATCH, MANUAL, DONE = "проверен", "расходится", "вручную", "реализован"
# Порядок примеров у совпавшей надписи: элементы и габарит, плоскости, оси, касательные, длины, наклонные проекции.
_PRIORITY = {"cylinder": 0, "arc": 0, "cone": 0, "torus": 0, "sphere": 0, "thread": 0, "box": 0, "plane": 1,
             "axis": 2, "pcd": 2, "tangent": 3, "length": 4, "axis-inclined": 5}


# --- векторы ---------------------------------------------------------------------------------------------
def _unit(a) -> Vec3:
    n = math.sqrt(dot(a, a)) or 1.0
    return (a[0] / n, a[1] / n, a[2] / n)


def _canon(d) -> Vec3:
    """Направление без знака: первая ненулевая компонента положительна."""
    d = _unit(d)
    for c in d:
        if abs(c) > 1e-9:
            return d if c > 0 else (-d[0], -d[1], -d[2])
    return d


def _dkey(d) -> tuple:
    return tuple(round(c, 5) + 0.0 for c in d)


def _angle(a, b) -> float:
    """Угол между прямыми (без знака направлений), 0…90°."""
    return math.degrees(math.acos(min(1.0, abs(dot(a, b)))))


def _basis(d) -> tuple[Vec3, Vec3]:
    e1 = _unit(cross(d, (1.0, 0.0, 0.0) if abs(d[0]) < 0.9 else (0.0, 1.0, 0.0)))
    return e1, cross(d, e1)


def _fmt_num(v: float, nd: int = 3) -> str:
    s = f"{v:.{nd}f}".rstrip("0").rstrip(".")
    return ("0" if s in ("-0", "") else s).replace(".", ",")


def _axis_name(d) -> str | None:
    return next((_AX[i] for i in range(3) if abs(abs(d[i]) - 1.0) < 1e-9), None)


# --- геометрия модели ------------------------------------------------------------------------------------
@dataclass
class _Plane:
    n: Vec3                # каноническая нормаль
    d: float              # n·p
    dkey: tuple
    faces: list[int] = field(default_factory=list)
    area: float = 0.0

    @property
    def desc(self) -> str:
        a = _axis_name(self.n)
        if a:
            return f"{a}={_fmt_num(self.d)}"
        return f"⊥({_fmt_num(self.n[0])}; {_fmt_num(self.n[1])}; {_fmt_num(self.n[2])}) на {_fmt_num(self.d)}"


def _dir_desc(n) -> str:
    a = _axis_name(n)
    return f"⊥{a.upper()}" if a else f"⊥({_fmt_num(n[0])}; {_fmt_num(n[1])}; {_fmt_num(n[2])})"


def _where(line) -> str:
    d, o = line
    a = _axis_name(d)
    if a:
        i = _AX.index(a)
        return f"∥{a.upper()} ({'; '.join(f'{_AX[k]}={_fmt_num(o[k])}' for k in range(3) if k != i)})"
    return (f"({_fmt_num(d[0])}; {_fmt_num(d[1])}; {_fmt_num(d[2])}) через "
            f"({_fmt_num(o[0])}; {_fmt_num(o[1])}; {_fmt_num(o[2])})")


def _line_of(origin, direction) -> tuple[Vec3, Vec3]:
    """Прямая: каноническое направление и её точка, ближайшая к началу координат."""
    d = _canon(direction)
    return d, vsub(origin, vmul(d, dot(origin, d)))


def _lkey(line) -> tuple:
    d, o = line
    return _dkey(d) + tuple(round(c, 3) + 0.0 for c in o)


@dataclass
class _Rev:
    """Грани вращения одного места: цилиндр (ось + радиус), конус (грань), тор, сфера."""
    kind: str
    line: tuple
    lk: tuple             # ключ прямой оси
    key: tuple            # ключ места
    r: float              # радиус; у тора — радиус образующей
    big: float | None = None          # тор: радиус осевой окружности
    half_angle: float | None = None   # конус
    faces: list[int] = field(default_factory=list)
    sweep: float = 0.0
    max_sweep: float = 0.0
    internal: bool | None = None
    ends: list = field(default_factory=list)   # [((s0, r0), (s1, r1))] — s вдоль канонической оси
    arcs: list = field(default_factory=list)   # дуги неполного цилиндра: (начальный угол, охват), рад, в `_basis`

    @property
    def full(self) -> bool:
        return self.max_sweep >= FULL or self.sweep >= FULL

    @property
    def label(self) -> str:
        if self.kind == "cylinder":
            if self.full:
                return f"{'отв.' if self.internal else 'цил.'} Ø{_fmt_num(2 * self.r)}"
            return f"дуга R{_fmt_num(self.r)}"
        if self.kind == "cone":
            return f"конус {_fmt_num(2 * (self.half_angle or 0))}°"
        if self.kind == "torus":
            return f"тор R{_fmt_num(self.r)}"
        return f"сфера R{_fmt_num(self.r)}"


def _planes(faces: Sequence["Face"]) -> list[_Plane]:
    out: dict[tuple, _Plane] = {}
    for f in faces:
        if f.kind != "plane" or not f.normal or not f.point:
            continue
        n = _canon(f.normal)
        d = dot(n, f.point)
        dk = _dkey(n)
        p = out.get(dk + (round(d, 3),))
        if p is None:
            p = out[dk + (round(d, 3),)] = _Plane(n, d, dk)
        p.faces.append(f.index)
        p.area += f.area or 0.0
    return list(out.values())


def _revolutions(faces: Sequence["Face"]) -> list[_Rev]:
    groups: dict[tuple, _Rev] = {}
    for f in faces:
        if f.kind not in ("cylinder", "cone", "torus", "sphere") or not f.axis_origin or not f.axis_dir:
            continue
        line = _line_of(f.axis_origin, f.axis_dir)
        d, lk = line[0], _lkey(line)
        if f.kind == "cylinder":
            key: tuple = ("cylinder", lk, round(f.radius or 0.0, 4))
            r = f.radius or 0.0
        elif f.kind == "cone":
            key, r = ("cone", lk, f.index), f.radius or 0.0
        elif f.kind == "torus":
            key = ("torus", lk, round(dot(f.axis_origin, d), 3), round(f.minor_radius or 0.0, 4),
                   round(f.major_radius or 0.0, 4))
            r = f.minor_radius or 0.0
        else:
            key, r = ("sphere", tuple(round(c, 3) for c in f.axis_origin), round(f.radius or 0.0, 4)), f.radius or 0.0
        g = groups.get(key)
        if g is None:
            g = groups[key] = _Rev(f.kind, line, lk, key, float(r), f.major_radius, f.cone_angle)
        sweep = 360.0 if f.sweep is None else float(f.sweep)
        g.faces.append(f.index)
        g.sweep += sweep
        g.max_sweep = max(g.max_sweep, sweep)
        if g.internal is None:
            g.internal = f.internal
        if f.ends:
            sign = 1.0 if dot(_unit(f.axis_dir), d) > 0 else -1.0
            base = dot(f.axis_origin, d)
            g.ends.append(tuple((base + sign * t, rr) for t, rr in f.ends))
        if f.kind == "cylinder" and getattr(f, "arc", None):
            g.arcs.append(_arc_span(line, f.arc))
    return list(groups.values())


def _arc_span(line, pts) -> tuple[float, float]:
    """Дуга по трём точкам (начало, середина, конец) вокруг оси: (начальный угол, охват против часовой) в
    базисе `_basis(ось)`; середина решает, какая из двух дуг между концами."""
    d, o = line
    e1, e2 = _basis(d)
    a0, am, a1 = (math.atan2(dot(vsub(p, o), e2), dot(vsub(p, o), e1)) for p in pts)
    tau = 2 * math.pi
    span, mid = (a1 - a0) % tau, (am - a0) % tau
    return (a0, span) if mid <= span else (a1, tau - span)


# --- замеры ----------------------------------------------------------------------------------------------
@dataclass
class Measure:
    """Замер модели: род, значение и что измерено."""
    kind: str                     # diameter | radius | linear | angle | thread
    value: float
    what: str
    src: str = ""                 # cylinder arc cone torus sphere pcd thread plane axis tangent length box
    weak: bool = False            # к такому элементу надпись этого рода нетипична (Ø у дуги < 360°…)
    place: tuple | None = None    # Ø, R, резьба: одно место считается один раз
    faces: tuple[int, ...] = ()
    pitch: float | None = None    # резьба
    same: int = 1                 # линейные/угловые: сколько раз это значение встретилось
    axis: tuple | None = None     # ключ оси элемента вращения (соосность)

    def __str__(self) -> str:
        return self.what + (f" (+{self.same - 1} таких же)" if self.same > 1 else "")


class ModelMeasures:
    """Замеры модели с поиском по значению. Линейные и угловые значения хранятся по одному примеру на
    значение (`Measure.same` — сколько раз встретилось), Ø/R/резьбы — все места."""

    def __init__(self) -> None:
        self._items: dict[tuple[str, bool], list[Measure]] = defaultdict(list)
        self._once: dict[tuple, Measure] = {}
        self._index: dict[tuple[str, bool], tuple[list[float], list[Measure]]] = {}

    def add(self, kind: str, value: float, what: str, *, src: str = "", weak: bool = False,
            place: tuple | None = None, faces: Iterable[int] = (), pitch: float | None = None,
            axis: tuple | None = None) -> None:
        if not math.isfinite(value) or value <= 1e-6:
            return
        key = (kind, weak, place) if place is not None else (kind, weak, round(value, 4))
        if kind not in _DISCRETE or place is not None:
            seen = self._once.get(key)
            if seen is not None:
                if place is None:
                    seen.same += 1
                return
        m = Measure(kind, value, what, src, weak, place, tuple(faces), pitch, axis=axis)
        if kind not in _DISCRETE or place is not None:
            self._once[key] = m
        self._items[(kind, weak)].append(m)
        self._index.pop((kind, weak), None)

    def items(self, kind: str, weak: bool | None = False) -> list[Measure]:
        if weak is None:
            return self._items[(kind, False)] + self._items[(kind, True)]
        return list(self._items[(kind, weak)])

    def _sorted(self, kind: str, weak: bool) -> tuple[list[float], list[Measure]]:
        idx = self._index.get((kind, weak))
        if idx is None:
            ms = sorted(self._items[(kind, weak)], key=lambda m: m.value)
            idx = self._index[(kind, weak)] = ([m.value for m in ms], ms)
        return idx

    def find(self, kind: str, lo: float, hi: float, weak: bool = False) -> list[Measure]:
        values, ms = self._sorted(kind, weak)
        return ms[bisect.bisect_left(values, lo):bisect.bisect_right(values, hi)]

    def nearest(self, kind: str, value: float) -> Measure | None:
        for weak in (False, True):
            values, ms = self._sorted(kind, weak)
            if values:
                i = bisect.bisect_left(values, value)
                return min((ms[k] for k in (i - 1, i) if 0 <= k < len(ms)), key=lambda m: abs(m.value - value))
        return None

    def __len__(self) -> int:
        return sum(len(v) for v in self._items.values())

    def summary(self) -> str:
        lines = [f"Замеров {len(self)}: " + ", ".join(f"{k} {len(self.items(k, None))}" for k in _DIMS)]
        for kind, sign in (("diameter", "Ø"), ("radius", "R"), ("thread", "M")):
            groups: dict[float, set] = defaultdict(set)
            for m in self.items(kind):
                groups[round(m.value, 3)].add(m.place)
            if groups:
                lines.append(f"  {kind}: " + ", ".join(f"{sign}{_fmt_num(v)}×{len(p)}" for v, p in sorted(groups.items())))
        return "\n".join(lines)

    def __str__(self) -> str:
        return self.summary()


def measure_faces(faces: Sequence["Face"], threads: Iterable[tuple[str, float, float | None]] = (),
                  box=None, tol: float = 1e-3) -> ModelMeasures:
    """Замеры по распознанным граням (без КОМПАСа). `threads` — (обозначение, d, шаг), `box` — `Box3` тела."""
    m = ModelMeasures()
    planes = _planes(faces)
    revs = _revolutions(faces)
    lines: dict[tuple, tuple[tuple, str]] = {}
    for g in sorted(revs, key=lambda g: (g.kind != "cylinder", not g.full, -g.r)):
        if g.kind != "sphere" and g.lk not in lines:
            lines[g.lk] = (g.line, f"{g.label} {_where(g.line)}")
    if box is not None:
        for i, size in enumerate(box.size):
            m.add("linear", float(size), f"габарит по {_AX[i].upper()}", src="box")
    _features(m, revs, tol)
    for i, (des, d, p) in enumerate(threads):
        if d:
            m.add("thread", float(d), f"резьба {des}" + (f" (P={_fmt_num(p)})" if p else ""), src="thread",
                  place=("M", i), pitch=float(p) if p else None)
    # порядок — приоритет примера: у линейного значения показывается первый найденный замер
    _plane_pairs(m, planes, tol)
    _axes_and_planes(m, lines, planes, tol)
    _axis_pairs(m, lines, planes, tol)
    _patterns(m, revs, lines, tol)
    _extremes(m, revs, lines, planes, tol)
    _lengths(m, revs)
    _axis_pairs(m, lines, planes, tol, inclined=True)
    _angles(m, planes, lines, revs)
    return m


def _features(m: ModelMeasures, revs: list[_Rev], tol: float) -> None:
    for g in sorted(revs, key=lambda g: ("cylinder", "sphere", "torus", "cone").index(g.kind)):   # пример места — цилиндр
        where = _where(g.line)
        kw = {"faces": g.faces, "axis": g.lk}
        if g.kind == "cylinder":
            if g.full:
                m.add("diameter", 2 * g.r, f"{g.label}, ось {where}", src="cylinder",
                      place=("Ø", g.lk, round(2 * g.r, 4)), **kw)
                m.add("radius", g.r, f"{g.label} (полный цилиндр), ось {where}", src="cylinder", weak=True,
                      place=("R", g.key), **kw)
            else:
                arc = f"дуга R{_fmt_num(g.r)} (охват {_fmt_num(g.max_sweep, 1)}°), ось {where}"
                m.add("radius", g.r, arc, src="arc", place=("R", g.key), **kw)
                if g.max_sweep >= 180.0:
                    m.add("diameter", 2 * g.r, arc, src="arc", weak=True, place=("Ø", g.lk, round(2 * g.r, 4)), **kw)
        elif g.kind == "cone":
            for end in g.ends:
                for _s, r in end:
                    if r > tol:
                        m.add("diameter", 2 * r, f"{g.label}, торец Ø{_fmt_num(2 * r)}, ось {where}", src="cone",
                              place=("Ø", g.lk, round(2 * r, 4)), **kw)
        elif g.kind == "torus":
            m.add("radius", g.r, f"скругление R{_fmt_num(g.r)} (тор R{_fmt_num(g.big or 0)}), ось {where}", src="torus",
                  place=("R", g.key), **kw)
            if g.big:
                m.add("radius", g.big, f"тор: осевая окружность R{_fmt_num(g.big)}, ось {where}", src="torus",
                      weak=True, place=("R", g.key, "big"), **kw)
        else:
            m.add("radius", g.r, f"сфера R{_fmt_num(g.r)}", src="sphere", place=("R", g.key), faces=g.faces)
            m.add("diameter", 2 * g.r, f"сфера Ø{_fmt_num(2 * g.r)}", src="sphere", place=("Ø", g.key), faces=g.faces)


def _lengths(m: ModelMeasures, revs: list[_Rev]) -> None:
    for g in revs:
        for (s0, r0), (s1, r1) in g.ends:
            if g.kind == "cylinder":
                m.add("linear", abs(s1 - s0), f"длина {g.label} ({_where(g.line)})", src="length", faces=g.faces)
            elif g.kind == "cone":
                m.add("linear", abs(s1 - s0), f"высота {g.label} Ø{_fmt_num(2 * r0)}→Ø{_fmt_num(2 * r1)} "
                                              f"({_where(g.line)})", src="length", faces=g.faces)


def _plane_pairs(m: ModelMeasures, planes: list[_Plane], tol: float) -> None:
    by_dir: dict[tuple, list[_Plane]] = defaultdict(list)
    for p in planes:
        by_dir[p.dkey].append(p)
    for ps in by_dir.values():
        ps.sort(key=lambda p: p.d)
        for i, a in enumerate(ps):
            for b in ps[i + 1:]:
                if b.d - a.d > tol:
                    m.add("linear", b.d - a.d, f"плоскости {a.desc} и {b.desc}", src="plane",
                          faces=(a.faces[0], b.faces[0]))


def _axes_and_planes(m: ModelMeasures, lines: dict, planes: list[_Plane], tol: float) -> None:
    for line, label in lines.values():
        d, o = line
        for p in planes:
            if abs(dot(p.n, d)) < 1e-6:
                dist = abs(dot(p.n, o) - p.d)
                if dist > tol:
                    m.add("linear", dist, f"ось {label} — плоскость {p.desc}", src="axis")


def _covers(g: _Rev, n: Vec3) -> bool:
    """Есть ли на цилиндре точка, крайняя в направлении `n` (⊥ оси): у полного — всегда, у дуги — если
    направление попадает в её охват (`_Rev.arcs`; без данных о дуге — нет)."""
    if g.full:
        return True
    e1, e2 = _basis(g.line[0])
    th = math.atan2(dot(n, e2), dot(n, e1))
    return any((th - a0) % (2 * math.pi) <= span + 1e-6 for a0, span in g.arcs)


def _extremes(m: ModelMeasures, revs: list[_Rev], lines: dict, planes: list[_Plane], tol: float) -> None:
    """Размеры до крайних точек (образующих) цилиндров и дуг: от плоскостей, от осей и между крайними точками
    разных цилиндров. Направления — нормали плоскостей и оси X/Y/Z; у дуги учитывается только та крайняя
    точка, что лежит на ней самой (R140 в разрезе: 90 от оси симметрии, 180 между дугами)."""
    normals = {p.dkey: p.n for p in planes}
    for i in range(3):
        e = tuple(1.0 if k == i else 0.0 for k in range(3))
        normals.setdefault(_dkey(e), e)
    by_dir: dict[tuple, list[_Plane]] = defaultdict(list)
    for p in planes:
        by_dir[p.dkey].append(p)
    for dk, n in normals.items():
        pts = []        # (координата крайней точки вдоль n, ключ цилиндра, ключ оси, подпись)
        for g in revs:
            if g.kind != "cylinder" or abs(dot(n, g.line[0])) > 1e-6:
                continue
            c = dot(n, g.line[1])
            for s, side in ((1.0, "+"), (-1.0, "−")):
                if _covers(g, vmul(n, s)):
                    pts.append((c + s * g.r, g.key, g.lk,
                                f"образующая {g.label} {_where(g.line)} ({side}{_dir_desc(n)[1:]})"))
        for v, _k, lk, what in pts:
            for p in by_dir.get(dk, ()):
                if abs(v - p.d) > tol:
                    m.add("linear", abs(v - p.d), f"плоскость {p.desc} — {what}", src="tangent")
            for k, (line, label) in lines.items():
                if k != lk and abs(dot(n, line[0])) < 1e-6 and abs(v - dot(n, line[1])) > tol:
                    m.add("linear", abs(v - dot(n, line[1])), f"ось {label} — {what}", src="tangent")
        for (v1, k1, _l1, w1), (v2, k2, _l2, w2) in itertools.combinations(pts, 2):
            if k1 != k2 and abs(v1 - v2) > tol:
                m.add("linear", abs(v1 - v2), f"{w1} — {w2}", src="tangent")


def _axis_pairs(m: ModelMeasures, lines: dict, planes: list[_Plane], tol: float, inclined: bool = False) -> None:
    """Расстояния между параллельными осями и их проекции на нормали плоскостей: на оси X/Y/Z (с истинным
    расстоянием) или, при `inclined`, на наклонные нормали — отдельным проходом, чтобы примером значения
    становились они в последнюю очередь."""
    normals = {p.dkey: p.n for p in planes}
    for i in range(3):
        e = tuple(1.0 if k == i else 0.0 for k in range(3))
        normals.setdefault(_dkey(e), e)
    normals = {k: n for k, n in normals.items() if (_axis_name(n) is None) == inclined}
    for (k1, (l1, t1)), (k2, (l2, t2)) in itertools.combinations(list(lines.items()), 2):
        if k1[:3] != k2[:3]:
            continue
        w = vsub(l2[1], l1[1])
        dist = math.sqrt(dot(w, w))
        if dist <= tol:
            continue
        if not inclined:
            m.add("linear", dist, f"между осями {t1} и {t2}", src="axis")
        for n in normals.values():
            if abs(dot(n, l1[0])) < 1e-6:
                c = abs(dot(w, n))
                if c > tol and abs(c - dist) > tol:
                    m.add("linear", c, f"между осями {t1} и {t2} по {_dir_desc(n)[1:]}",
                          src="axis-inclined" if inclined else "axis")


def _circumcenter(a, b, c) -> tuple[float, float] | None:
    d = 2 * (a[0] * (b[1] - c[1]) + b[0] * (c[1] - a[1]) + c[0] * (a[1] - b[1]))
    if abs(d) < 1e-9:
        return None
    a2, b2, c2 = a[0] ** 2 + a[1] ** 2, b[0] ** 2 + b[1] ** 2, c[0] ** 2 + c[1] ** 2
    return ((a2 * (b[1] - c[1]) + b2 * (c[1] - a[1]) + c2 * (a[1] - b[1])) / d,
            (a2 * (c[0] - b[0]) + b2 * (a[0] - c[0]) + c2 * (b[0] - a[0])) / d)


def _patterns(m: ModelMeasures, revs: list[_Rev], lines: dict, tol: float) -> None:
    """Окружности центров одинаковых отверстий/цилиндров и угловой шаг между ними."""
    groups: dict[tuple, list[_Rev]] = defaultdict(list)
    for g in revs:
        if g.kind == "cylinder" and g.full:
            groups[(g.lk[:3], round(g.r, 4))].append(g)
    for (dk, _r), gs in groups.items():
        if len(gs) < 2:
            continue
        d = gs[0].line[0]
        e1, e2 = _basis(d)
        pts = [(dot(g.line[1], e1), dot(g.line[1], e2)) for g in gs]
        own = {g.lk for g in gs}
        centers = [((dot(line[1], e1), dot(line[1], e2)), label)
                   for lk, (line, label) in lines.items() if lk[:3] == dk and lk not in own]
        for a, b, c in itertools.combinations(pts[:10], 3):
            cc = _circumcenter(a, b, c)
            if cc and not any(math.dist(cc, x) < tol for x, _ in centers):
                p3 = (e1[0] * cc[0] + e2[0] * cc[1], e1[1] * cc[0] + e2[1] * cc[1], e1[2] * cc[0] + e2[2] * cc[1])
                centers.append((cc, f"точки {_where((d, p3))}"))
        label = gs[0].label
        for (cx, cy), clabel in centers:
            by_r: dict[float, list[float]] = defaultdict(list)
            for px, py in pts:
                rad = math.hypot(px - cx, py - cy)
                if rad > tol:
                    by_r[round(rad, 3)].append(math.degrees(math.atan2(py - cy, px - cx)) % 360.0)
            for rad, angs in by_r.items():
                if len(angs) < 2:
                    continue
                m.add("diameter", 2 * rad, f"окружность центров {len(angs)} {label}: Ø{_fmt_num(2 * rad)} вокруг {clabel}",
                      src="pcd", place=("pcd", dk, round(cx, 3), round(cy, 3), round(2 * rad, 3)))
                angs.sort()
                steps = [b - a for a, b in zip(angs, angs[1:])]
                steps = steps + [360.0 - (angs[-1] - angs[0])] if len(angs) > 2 else [min(steps[0], 360 - steps[0])]
                for s in sorted({round(x, 4) for x in steps}):
                    m.add("angle", s, f"шаг {label} по окружности Ø{_fmt_num(2 * rad)} вокруг {clabel}", src="pcd")


def _angles(m: ModelMeasures, planes: list[_Plane], lines: dict, revs: list[_Rev]) -> None:
    eps = 1e-3
    best: dict[tuple, _Plane] = {}
    for p in planes:
        if p.dkey not in best or p.area > best[p.dkey].area:
            best[p.dkey] = p
    plist = list(best.values())
    for a, b in itertools.combinations(plist, 2):
        t = _angle(a.n, b.n)
        if t > eps:
            what = f"между плоскостями {a.desc} и {b.desc}"
            m.add("angle", t, what, src="plane")
            m.add("angle", 180.0 - t, what, src="plane")
            if 90.0 - t > eps:
                m.add("angle", 90.0 - t, what + " (дополнение до 90°)", src="plane", weak=True)
    dirs: dict[tuple, tuple[Vec3, str]] = {}
    for lk, (line, label) in lines.items():
        dirs.setdefault(lk[:3], (line[0], label))
    for d, label in dirs.values():
        for p in plist:
            t = _angle(d, p.n)
            if eps < t < 90.0 - eps:
                m.add("angle", t, f"ось {label} к нормали плоскости {p.desc}", src="axis")
                m.add("angle", 90.0 - t, f"ось {label} к плоскости {p.desc}", src="axis")
    for (d1, l1), (d2, l2) in itertools.combinations(dirs.values(), 2):
        t = _angle(d1, d2)
        if t > eps:
            m.add("angle", t, f"между осями {l1} и {l2}", src="axis")
            m.add("angle", 180.0 - t, f"между осями {l1} и {l2}", src="axis")
    for g in revs:
        if g.kind == "cone" and g.half_angle:
            where = _where(g.line)
            m.add("angle", 2 * g.half_angle, f"{g.label} (угол при вершине), ось {where}", src="cone")
            m.add("angle", g.half_angle, f"{g.label}: образующая к оси {_fmt_num(g.half_angle)}°, ось {where}", src="cone")
            if 90.0 - g.half_angle > eps:
                m.add("angle", 90.0 - g.half_angle, f"{g.label}: образующая к торцу, ось {where}", src="cone",
                      weak=True)


# --- модель КОМПАСа ---------------------------------------------------------------------------------------
def _probe(ks, f: "Face") -> None:
    """Дополнить грань вращения: `ends` — концы вдоль оси и радиусы на них (V — вдоль образующей),
    `arc` — у неполного цилиндра три точки по U (угол вокруг оси, spikes/s105) посередине V."""
    ms = ks.IMathSurface3D(f.raw.GetMathObject())
    if not ms:
        return
    d, o = _unit(f.axis_dir), f.axis_origin
    u0, u1, v0, v1 = ms.GetParamUMin(), ms.GetParamUMax(), ms.GetParamVMin(), ms.GetParamVMax()
    um, vm = (u0 + u1) / 2, (v0 + v1) / 2

    def point(u, v):
        p = ms.GetPoint(u, v, 0, 0, 0)
        return (float(p[1]), float(p[2]), float(p[3])) if p[0] else None

    ends = []
    for v in (v0, v1):
        p = point(um, v)
        if p is None:
            break
        w = vsub(p, o)
        t = dot(w, d)
        r = vsub(w, vmul(d, t))
        ends.append((round(t, 6), round(math.sqrt(dot(r, r)), 6)))
    f.ends = tuple(ends) if len(ends) == 2 else None
    if f.kind == "cylinder" and f.sweep is not None and f.sweep < FULL:
        pts = [point(u, vm) for u in (u0, um, u1)]
        f.arc = tuple(pts) if all(pts) else None


def model_threads(doc: "PartDocument") -> list[tuple[str, float, float | None]]:
    """Резьбы детали (условные и в отверстиях): (обозначение, d, шаг)."""
    ks = doc.ks
    coll = ks.ISymbols3DContainer(doc.part).GetThreads()
    out = []
    for obj in (coll.GetObjects() if coll else None) or []:
        p = ks.IThreadsParameters(obj)
        if p:
            out.append((str(p.GetDesignation()), float(p.GetDiameter()), float(p.GetPitch()) or None))
    return out


def measure_model(doc: "PartDocument") -> ModelMeasures:
    """Замеры текущего исполнения детали."""
    faces = doc.faces()
    for f in faces:
        if f.kind in ("cylinder", "cone") and f.axis_origin and f.axis_dir and f.raw is not None:
            _probe(doc.ks, f)
    return measure_faces(faces, model_threads(doc), doc.box())


# --- реестр надписей -------------------------------------------------------------------------------------
@dataclass
class CheckRow:
    """Строка реестра: одна надпись (или одинаковые надписи с разных видов) и её статус."""
    ids: list[str]
    text: str
    kind: str                       # diameter radius thread angle linear | note
    value: float | None = None
    count: int | None = None
    reference: bool = False
    suffix: str = ""
    status: str = MANUAL
    found: list[Measure] = field(default_factory=list)
    places: int = 0
    nearest: Measure | None = None
    note: str = ""
    rule: float | None = None       # пункт «Неуказанные радиусы скруглений R…»

    @property
    def label(self) -> str:
        if self.kind == "note":
            return self.text if len(self.text) <= 100 else self.text[:97] + "…"
        has_count = bool(re.match(r"^\d+\s*отв", self.text))      # «4 отв. Ø9» — количество уже в тексте
        return self.text + (f" ×{self.count}" if self.count and not has_count else "")

    def __str__(self) -> str:
        ids = ", ".join(self.ids) if len(self.ids) <= 3 else f"{self.ids[0]}…{self.ids[-1]} ({len(self.ids)})"
        out = f"{self.label} [{ids}]"
        if self.status == OK and self.found:
            more = len(self.found) - 1
            mark = "≈ " if all(m.weak for m in self.found) else ""
            out += f" — {mark}{self.found[0]}" + (f"; ещё совпадений {more}" if more else "")
        elif self.status == MISMATCH and self.nearest is not None and not self.note:
            sign = {"diameter": "Ø", "radius": "R"}.get(self.kind, "")
            out += f" — в модели нет; ближайшее {sign}{_fmt_num(self.nearest.value)}: {self.nearest}"
        if self.note:
            out += f" — {self.note}"
        return out


@dataclass
class Extra:
    """Элемент модели, которого на чертеже нет."""
    kind: str
    value: float
    places: int
    example: Measure
    note: str = ""      # «соосна с элементом с чертежа» — производный радиус (стенка), не неуказанное скругление

    def __str__(self) -> str:
        sign = {"diameter": "Ø", "radius": "R", "thread": "M"}[self.kind]
        return f"{sign}{_fmt_num(self.value)} ×{self.places} — {self.example.what}" + (f" ({self.note})" if self.note else "")


@dataclass
class DrawingCheck:
    """Реестр надписей чертежа со статусами и элементы модели без надписи."""
    rows: list[CheckRow]
    extras: list[Extra] = field(default_factory=list)
    source: str = ""
    embodiment: int | None = None
    annotations: int = 0

    @property
    def mismatches(self) -> list[CheckRow]:
        return [r for r in self.rows if r.status == MISMATCH]

    @property
    def ok(self) -> bool:
        return not self.mismatches

    def find(self, ref: str | int) -> CheckRow:
        """Строка по id надписи («p1.t085»), её тексту («R512») или номеру."""
        if isinstance(ref, int):
            return self.rows[ref]
        for r in self.rows:
            if ref in r.ids or ref == r.text or ref == r.label:
                return r
        raise KeyError(f"Нет строки {ref!r}")

    def mark(self, ref: str | int, note: str = "") -> CheckRow:
        """Отметить строку «реализован» (проверено глазами, выполнено иначе…) с пояснением."""
        row = self.find(ref)
        row.status, row.note = DONE, note or row.note
        return row

    def summary(self, brief: bool = False) -> str:
        counts = {s: sum(1 for r in self.rows if r.status == s) for s in (OK, MISMATCH, MANUAL, DONE)}
        where = f" ↔ исполнение {self.embodiment}" if self.embodiment is not None else ""
        head = (f"Сверка {self.source or 'чертежа'}{where}: строк {len(self.rows)} (надписей {self.annotations}) — "
                + ", ".join(f"{s} {n}" for s, n in counts.items() if n))
        out = [head]
        for status, title in ((MISMATCH, "Расходится"), (MANUAL, "Проверить вручную"), (DONE, "Реализован"),
                              (OK, "Проверен")):
            rows = [r for r in self.rows if r.status == status]
            if not rows or (brief and status == OK):
                continue
            out.append(f"{title}:")
            out += [f"  {r}" for r in rows]
        if self.extras:
            out.append("В модели, на чертеже нет:")
            out += [f"  {e}" for e in self.extras]
        return "\n".join(out)

    def __str__(self) -> str:
        return self.summary()


def _minutes(suffix: str) -> float:
    m = re.match(r"^\s*(\d+(?:[.,]\d+)?)\s*[′']", suffix or "")
    return float(m[1].replace(",", ".")) / 60.0 if m else 0.0


def _deviations(suffix: str) -> tuple[float, float]:
    """Предельные отклонения из остатка надписи: «±0,1», «-0,2», «+0,2 -0,1», «H7(+0,021)». Посадка без чисел — 0."""
    s = (suffix or "").replace("−", "-").replace("–", "-")
    m = re.search(r"±\s*(\d+(?:[.,]\d+)?)", s)
    if m:
        v = float(m[1].replace(",", "."))
        return -v, v
    vals = [float(sign + num.replace(",", ".")) for sign, num in re.findall(r"([+-])\s*(\d+(?:[.,]\d+)?)", s)]
    if not vals:
        return 0.0, 0.0
    if len(vals) == 1:
        return (min(vals[0], 0.0), max(vals[0], 0.0))
    return min(vals), max(vals)


def _round_tol(text: str) -> float:
    m = re.search(r"\d+[.,](\d+)", text)
    return 0.5 * 10 ** -len(m[1]) + 1e-9 if m else 0.5


_NOTE_START = re.compile(r"^\d{1,2}\.?\s+\S")
_DEFAULT_R = re.compile(r"радиус\w*\s+скругл\w*.*?\bR\s*(\d+(?:[.,]\d+)?)", re.I)


def _notes(texts: list[Annotation]) -> list[CheckRow]:
    """Пункты технических требований: строка с номером «2 …» и строки под ней без номера."""
    rows: list[CheckRow] = []
    manual = [a for a in texts if a.source == "manual"]
    rows += [CheckRow([a.id], a.text, "note") for a in manual]
    lines = sorted((a for a in texts if a.source != "manual" and a.angle == 0), key=lambda a: -a.bbox.y2)
    cur: CheckRow | None = None
    last: Annotation | None = None
    used = set()
    for a in lines:
        if _NOTE_START.match(a.text):
            cur, last = CheckRow([a.id], a.text, "note"), a
            rows.append(cur)
            used.add(a.id)
        elif cur is not None and last is not None:
            h = max(a.height, last.height, 1.0)
            gap = last.bbox.y1 - a.bbox.y2
            if -0.3 * h <= gap <= 1.5 * h and a.bbox.x1 < last.bbox.x2 and a.bbox.x2 > last.bbox.x1:
                cur.ids.append(a.id)
                cur.text += " " + a.text
                last = a
                used.add(a.id)
    for a in lines:      # требование без номера (единственное) — длинная строка
        if a.id not in used and len(a.text) >= 25:
            rows.append(CheckRow([a.id], a.text, "note"))
    for r in rows:
        m = _DEFAULT_R.search(r.text)
        if m:
            r.rule = float(m[1].replace(",", "."))
    return rows


def _rows(annotations: Iterable[Annotation]) -> tuple[list[CheckRow], int]:
    rows: dict[tuple, CheckRow] = {}
    texts: list[Annotation] = []
    n = 0
    for a in annotations:
        if a.zone != "field":
            continue
        if a.kind in _DIMS and a.value is not None:
            value = a.value + (_minutes(a.suffix) if a.kind == "angle" else 0.0)
            key = (a.kind, round(value, 4), a.count, a.reference, a.suffix)
            if key not in rows:
                rows[key] = CheckRow([], a.text, a.kind, value, a.count, a.reference, a.suffix)
            rows[key].ids.append(a.id)
            n += 1
        elif a.kind == "text":
            texts.append(a)
    notes = _notes(texts)
    return list(rows.values()) + notes, n + sum(len(r.ids) for r in notes)


def _check(row: CheckRow, m: ModelMeasures, tol: float, angle_tol: float) -> None:
    spec = None
    t = angle_tol if row.kind == "angle" else tol
    if row.reference:
        t = max(t, _round_tol(row.text))
    if row.kind == "thread":
        spec = _spec(row.text)
        d = spec.d if spec else float(row.value or 0)
        found = [x for x in m.find("thread", d - t, d + t)
                 if spec is None or x.pitch is None or abs(x.pitch - spec.p) <= 1e-3]
        weak: list[Measure] = []
    else:
        lo_dev, hi_dev = _deviations(row.suffix) if row.kind != "angle" else (0.0, 0.0)
        v = float(row.value or 0.0)
        lo, hi = v + lo_dev - t, v + hi_dev + t
        found, weak = m.find(row.kind, lo, hi), m.find(row.kind, lo, hi, weak=True)
        if lo_dev or hi_dev:
            row.note = f"в поле допуска {_fmt_num(v + lo_dev)}…{_fmt_num(v + hi_dev)}" if found or weak else ""
    target = spec.d if row.kind == "thread" and spec else float(row.value or 0.0)
    for lst in (found, weak):        # первым — самый понятный замер, затем ближайший по значению
        lst.sort(key=lambda x: (_PRIORITY.get(x.src, 3), abs(x.value - target)))
    places = {x.place for x in found if x.place is not None}
    row.found = found or weak
    row.places = len(places) if row.kind in _DISCRETE else len(found)
    if row.kind in _DISCRETE and row.count and len(places) < row.count:
        both = places | {x.place for x in weak if x.place is not None}
        if len(both) >= row.count:
            row.status, row.note = OK, f"мест {len(both)}, из них ≈ {len(both) - len(places)}"
        else:
            row.status = MISMATCH
            row.note = f"в модели мест {len(both)} из {row.count}" + (f": {row.found[0]}" if row.found else "")
        return
    if row.found:
        row.status = OK
        return
    row.status = MISMATCH
    row.nearest = m.nearest(row.kind, float(row.value or 0.0))
    if row.kind == "thread":
        holes = m.find("diameter", *_tap_range(spec)) if spec else []
        row.note = f"резьбы {row.text} в модели нет" + (
            f"; есть отверстия под неё без резьбы: Ø{_fmt_num(holes[0].value)} ×{len({x.place for x in holes})}"
            if holes else "")


def _tap_range(spec) -> tuple[float, float]:
    """Диаметр отверстия под резьбу: от d1 (так строит КОМПАС) до сверла ≈ d − P (ГОСТ 19257)."""
    return spec.minor - 0.1, spec.d - spec.p + 0.1


def _near(v: float, values: Iterable[float], tol: float) -> bool:
    return any(abs(v - x) <= tol for x in values)


def _extras(rows: list[CheckRow], m: ModelMeasures, tol: float) -> list[Extra]:
    """Ø, R и резьбы модели, которых нет на чертеже. Ø и R одного размера взаимозаменяемы (R17,5 на чертеже —
    цилиндр Ø35 в модели), отверстия под резьбы не считаются, радиус «по умолчанию» из требований — тоже."""
    drawn: dict[str, list[float]] = defaultdict(list)
    taps: list[tuple[float, float]] = []
    for r in rows:
        if r.value is None:
            continue
        if r.kind == "diameter":
            drawn["diameter"].append(r.value)
            drawn["radius"].append(r.value / 2)
        elif r.kind == "radius":
            drawn["radius"].append(r.value)
            drawn["diameter"].append(2 * r.value)
        elif r.kind == "thread":
            spec = _spec(r.text)
            drawn["thread"].append(spec.d if spec else r.value)
            if spec:
                taps.append(_tap_range(spec))
    for x in m.items("thread"):
        taps.append((x.value - tol, x.value + tol))
        if x.pitch:
            taps.append(_tap_range(thread_spec((x.value, x.pitch))))
    defaults = [r.rule for r in rows if r.rule]
    matched_axes = {x.axis for r in rows if r.status == OK for x in r.found if x.axis}
    groups: dict[tuple, list[Measure]] = defaultdict(list)
    for x in m.items("diameter"):
        if x.src in ("cylinder", "sphere") and not _near(x.value, drawn["diameter"], tol) \
                and not any(lo <= x.value <= hi for lo, hi in taps):
            groups[("diameter", round(x.value, 3))].append(x)
    for x in m.items("radius"):
        if x.src in ("arc", "torus", "sphere") and not _near(x.value, drawn["radius"], tol) \
                and not _near(x.value, defaults, tol):
            groups[("radius", round(x.value, 3))].append(x)
    for x in m.items("thread"):
        if not _near(x.value, drawn["thread"], tol):
            groups[("thread", round(x.value, 3))].append(x)
    out = []
    for (kind, value), xs in sorted(groups.items()):
        coaxial = kind == "radius" and all(x.axis in matched_axes for x in xs)
        out.append(Extra(kind, value, len({x.place for x in xs}), xs[0],
                         "соосна с элементом с чертежа — стенка, отступ?" if coaxial else ""))
    return out


def _spec(text: str):
    try:
        return thread_spec(text.rstrip("*").strip())
    except ValueError:
        return None


def reconcile(annotations: Iterable[Annotation], measures: ModelMeasures, *, tol: float = 0.01,
              angle_tol: float = 0.05) -> DrawingCheck:
    """Сверить надписи с замерами модели (без КОМПАСа)."""
    rows, n = _rows(annotations)
    for r in rows:
        if r.kind != "note":
            _check(r, measures, tol, angle_tol)
    extras = _extras(rows, measures, tol)
    for r in rows:
        if r.rule:
            others = [e for e in extras if e.kind == "radius" and not e.note]
            same = {x.place for x in measures.find("radius", r.rule - tol, r.rule + tol)}
            if others:
                r.status = MISMATCH
                r.note = "в модели есть радиусы не с чертежа и не R" + _fmt_num(r.rule) + ": " + \
                         ", ".join(f"R{_fmt_num(e.value)} ×{e.places}" for e in others[:8])
            else:
                r.status = OK
                r.note = f"прочие радиусы модели — R{_fmt_num(r.rule)} (мест {len(same)})"
    return DrawingCheck(rows, extras, annotations=n)


def _annotations(source) -> tuple[list[Annotation], str]:
    if isinstance(source, PdfDrawing):
        pages = [p for p in source.pages if p.text_usable]
        if not pages:
            raise ValueError(f"{source.path.name}: текстового слоя нет — прочитайте лист глазами "
                             f"(export_images) и передайте надписи списком строк: ['Ø20', '4 отв. Ø9', …]")
        return [a for p in pages for a in p.annotations], f"«{source.path.name}»"
    if isinstance(source, PdfPage):
        return list(source.annotations), f"листа {source.index + 1}"
    items = list(source)
    if all(isinstance(x, str) for x in items):
        anns = []
        for i, t in enumerate(items):
            p = parse_annotation(t)
            anns.append(Annotation(id=f"m{i + 1}", page=0, text=t, bbox=Rect(0, 0, 0, 0), source="manual", **p))
        return anns, "надписей вручную"
    return items, "надписей"


def check_drawing(doc: "PartDocument", source, *, embodiment: int | None = None, tol: float = 0.01,
                  angle_tol: float = 0.05) -> DrawingCheck:
    """Сверить модель (текущее исполнение или `embodiment`) с надписями чертежа: `PdfDrawing`, `PdfPage`,
    список `Annotation` или строк («Ø20», «4 отв. Ø9», «R5», «40», «17°», «M8», пункты требований)."""
    anns, name = _annotations(source)
    if embodiment is None:
        measures = measure_model(doc)
    else:
        # из kompas_lib.build.embodiments: Embodiments
        with Embodiments(doc).use(embodiment):
            measures = measure_model(doc)
    rep = reconcile(anns, measures, tol=tol, angle_tol=angle_tol)
    rep.source, rep.embodiment = name, embodiment
    return rep


