"""Основная надпись (штамп) листа."""

import re

# из kompas_lib.enums: StampCell
# из kompas_lib.errors: KompasError, check

# Ссылка на свойство/вид внутри текста графы: ^(#3~1:1)brackets=0;param=1;type=view;viewName=2;~
_REF_RE = re.compile(r"\^\(#\d+~(.*?)\)[^~]*~")


def display_text(value: str) -> str:
    """Текст графы так, как он отображается (ссылки заменены их текущим значением)."""
    return _REF_RE.sub(lambda m: m.group(1), value)


def is_linked(value: str) -> bool:
    """Графа содержит ссылку (на свойство модели, вид и т.п.) — значение формирует КОМПАС."""
    return bool(_REF_RE.search(value))


class Stamp:
    """Штамп листа. Графы адресуются StampCell или номером по ГОСТ 2.104.

    Графы ассоциативного чертежа «Наименование», «Обозначение», «Материал», «Масса» КОМПАС
    заполняет из свойств модели; правильный способ изменить их — поменять свойства детали
    (PartDocument.title / designation / set_material). Перезапись таких граф требует force=True.
    """

    def __init__(self, sheet, raw_stamp) -> None:
        self.sheet = sheet
        self.raw = raw_stamp

    def raw_text(self, cell: StampCell | int) -> str:
        """Текст графы как он хранится (со ссылками)."""
        t = self.raw.GetText(int(cell))
        return t.GetStr() if t else ""

    def __getitem__(self, cell: StampCell | int) -> str:
        return display_text(self.raw_text(cell))

    def is_linked(self, cell: StampCell | int) -> bool:
        return is_linked(self.raw_text(cell))

    def has_cell(self, cell: StampCell | int) -> bool:
        return bool(self.raw.IsCellPresent(int(cell)))

    def set(self, cell: StampCell | int, value: str, force: bool = False) -> None:
        if not force and self.is_linked(cell):
            raise KompasError(
                f"Графа {StampCell(cell).name if int(cell) in StampCell._value2member_map_ else cell} "
                "связана со свойством модели/видом; измените источник или передайте force=True")
        t = self.raw.GetText(int(cell))
        if not t:
            raise KompasError(f"В штампе нет графы {int(cell)}")
        t.SetStr(value)
        check(self.raw.Update(), "Обновление штампа")

    def __setitem__(self, cell: StampCell | int, value: str) -> None:
        self.set(cell, value)

    def update(self, values: dict[StampCell | int, str], force: bool = False) -> None:
        """Записать несколько граф и обновить штамп один раз."""
        for cell, value in values.items():
            if not force and self.is_linked(cell):
                raise KompasError(f"Графа {cell} связана с моделью/видом; используйте force=True")
            t = self.raw.GetText(int(cell))
            if not t:
                raise KompasError(f"В штампе нет графы {int(cell)}")
            t.SetStr(value)
        check(self.raw.Update(), "Обновление штампа")

    def to_dict(self) -> dict[str, dict]:
        """Все известные графы: отображаемый текст и признак связи."""
        out = {}
        for cell in StampCell:
            if not self.has_cell(cell):
                continue
            raw_value = self.raw_text(cell)
            out[cell.name] = {"cell": int(cell), "text": display_text(raw_value), "linked": is_linked(raw_value)}
        return out


