"""Лист оформления: формат, рамка, зоны штампа."""

from typing import TYPE_CHECKING

gost = _submodule('gost')
# из kompas_lib.enums: SheetFormat
# из kompas_lib.errors: check
# из kompas_lib.geom: Rect
# из kompas_lib.drawing.stamp: Stamp

# из kompas_lib.drawing.document: Drawing  (только для аннотаций)


class Sheet:
    def __init__(self, drawing: "Drawing", raw_sheet, index: int) -> None:
        self.drawing = drawing
        self.raw = raw_sheet
        self.index = index

    @property
    def _fmt(self):
        return self.raw.GetFormat()

    @property
    def format(self) -> SheetFormat:
        return SheetFormat(self._fmt.GetFormat())

    @property
    def landscape(self) -> bool:
        return not self._fmt.IsVerticalOrientation()

    @property
    def multiplicity(self) -> int:
        return int(self._fmt.GetFormatMultiplicity())

    @property
    def size(self) -> tuple[float, float]:
        """(ширина, высота) листа, мм."""
        f = self._fmt
        return (float(f.GetFormatWidth()), float(f.GetFormatHeight()))

    def set_format(self, fmt: SheetFormat, landscape: bool = True, multiplicity: int = 1) -> None:
        f = self._fmt
        f.SetFormat(int(fmt))
        f.SetVerticalOrientation(not landscape)
        if multiplicity != 1:
            f.SetFormatMultiplicity(multiplicity)
        check(self.raw.Update(), "Изменение формата листа")

    # --- зоны --------------------------------------------------------------------------------
    @property
    def frame(self) -> Rect:
        """Внутренняя рамка (ГОСТ 2.104: слева 20 мм, остальные 5 мм)."""
        w, h = self.size
        return Rect(gost.FRAME_LEFT, gost.FRAME_OTHER, w - gost.FRAME_OTHER, h - gost.FRAME_OTHER)

    @property
    def keepouts(self) -> list[Rect]:
        """Занятые оформлением зоны: основная надпись, доп. графы, графа 26 и т.п. (мм листа).

        Берутся из IStamp.GetTablesGabarits (группы по 4 числа). Зоны вне рамки отбрасываются.
        """
        values = list(self.raw.GetStamp().GetTablesGabarits() or [])
        frame = self.frame
        rects = []
        for i in range(0, len(values) - 3, 4):
            r = Rect.of(*values[i:i + 4])
            if r.area > 0 and frame.intersects(r):
                rects.append(r)
        return rects

    @property
    def stamp(self) -> Stamp:
        return Stamp(self, self.raw.GetStamp())

    def info(self) -> dict:
        return {
            "index": self.index, "format": self.format.name, "landscape": self.landscape,
            "size": self.size, "frame": self.frame.as_tuple(),
            "keepouts": [r.as_tuple() for r in self.keepouts],
        }


# ==================================================================================================================
# === 26/55 kompas_lib.drawing.view — kompas_lib/drawing/view.py
# ==================================================================================================================
"""Вид чертежа (в т.ч. ассоциативный вид модели, разрез/сечение)."""

from dataclasses import dataclass, field
from typing import TYPE_CHECKING

# из kompas_lib.enums: ViewType, raw
# из kompas_lib.errors: OperationFailedError, check
# из kompas_lib.geom: Point, Rect, Segment, arc_extremes, arc_polyline

# из kompas_lib.drawing.document: Drawing  (только для аннотаций)

_DR = raw.DrawingObjectTypeEnum
# Кривые, которые читаются ломаной через IDrawingObject.GetCurve2D().CalculatePolygon (spikes/s21)
_POLY_TYPES = (_DR.ksDrNurbs, _DR.ksDrNurbsByPoints, _DR.ksDrBezier, _DR.ksDrEllipse, _DR.ksDrEllipseArc,
               _DR.ksDrPolyline, _DR.ksDrEquid, _DR.ksDrContour, _DR.ksDrConicCurve, _DR.ksDrSpecialCurve)


@dataclass
class Curve2D:
    """Геометрический объект вида в координатах вида (единицы модели)."""
    kind: str                         # line | circle | arc | poly | other
    style: int | None                 # None — ещё не прочитан (см. is_axial)
    p1: Point | None = None           # line: начало; arc: начало
    p2: Point | None = None           # line: конец;  arc: конец
    center: Point | None = None
    radius: float | None = None
    angles: tuple[float, float] | None = None  # дуга: начальный и конечный угол, градусы
    ccw: bool = True                           # дуга: против часовой стрелки
    # poly: ломаная, аппроксимирующая кривую (NURBS, Безье, эллипс, дуга эллипса, …) с прогибом ≤ sag
    points: tuple[Point, ...] | None = None
    closed: bool = False
    source_type: int = 0                       # DrawingObjectTypeEnum исходного объекта
    raw: object = field(default=None, repr=False, compare=False)

    def extremes(self) -> list[Point]:
        """Точки, задающие габарит кривой (у дуг и окружностей — с квадрантными точками)."""
        if self.kind == "line" and self.p1 and self.p2:
            return [self.p1, self.p2]
        if self.kind in ("circle", "arc") and self.center and self.radius is not None:
            if self.kind == "arc" and self.angles is not None:
                return arc_extremes(self.center, self.radius, self.angles[0], self.angles[1], self.ccw)
            return arc_extremes(self.center, self.radius)
        if self.kind == "poly" and self.points:
            return list(self.points)
        return []

    @property
    def bbox(self) -> Rect | None:
        pts = self.extremes()
        if not pts:
            return None
        return Rect(min(p.x for p in pts), min(p.y for p in pts), max(p.x for p in pts), max(p.y for p in pts))

    @property
    def is_axial(self) -> bool:
        """Осевая (штрихпунктирная) линия. Стиль читается из КОМПАСа при первом обращении."""
        if self.style is None:
            try:
                self.style = int(self.raw.GetStyle()) if self.raw is not None else 0
            except AttributeError:
                self.style = 0
        return self.style == int(raw.ksCurveStyleEnum.ksCSAxial)

    @property
    def is_hidden(self) -> bool:
        if self.style is None:
            _ = self.is_axial
        return self.style in {int(raw.ksCurveStyleEnum.ksCSHidden),int(raw.ksCurveStyleEnum.ksCSUnvisible),
                              int(raw.ksCurveStyleEnum.ksCSDashed),int(raw.ksCurveStyleEnum.ksCSDashedNormal)}

    def segments(self) -> list[Segment]:
        """Аппроксимация отрезками (в тех же координатах)."""
        if self.kind == "line" and self.p1 and self.p2:
            return [Segment(self.p1, self.p2)]
        if self.kind == "circle" and self.center and self.radius:
            return arc_polyline(self.center, self.radius)
        if self.kind == "arc" and self.center and self.radius:
            if self.angles is not None:
                return arc_polyline(self.center, self.radius, self.angles[0], self.angles[1], self.ccw)
            return arc_polyline(self.center, self.radius)
        if self.kind == "poly" and self.points and len(self.points) > 1:
            pts = self.points
            segs = [Segment(pts[i], pts[i + 1]) for i in range(len(pts) - 1)]
            if self.closed and pts[0].dist(pts[-1]) > 1e-9:
                segs.append(Segment(pts[-1], pts[0]))
            return segs
        return []

    def vertices(self) -> list[Point]:
        """Точки, к которым KsAPI привязывает размер через Associate(): концы и середина отрезка, концы дуги, центр.

        У ломаных (NURBS и пр.) — концы незамкнутой кривой; привязка к ним не гарантирована.
        """
        if self.kind == "line" and self.p1 and self.p2:
            return [self.p1, self.p2, Point((self.p1.x + self.p2.x) / 2, (self.p1.y + self.p2.y) / 2)]
        if self.kind == "poly":
            return [] if self.closed or not self.points else [self.points[0], self.points[-1]]
        pts = [p for p in (self.p1, self.p2, self.center) if p is not None]
        return pts


class View:
    def __init__(self, drawing: "Drawing", raw_view) -> None:
        self.drawing = drawing
        self.ks = drawing.ks
        self.raw = raw_view
        av = self.ks.IAssociationView(raw_view)
        self.av = av if av else None

    def __repr__(self) -> str:
        return f"<View #{self.number} {self.name!r} {self.type.name}>"

    def __eq__(self, other) -> bool:
        return isinstance(other, View) and other.number == self.number and other.drawing.raw is self.drawing.raw

    def __hash__(self) -> int:
        return hash(self.number)

    # --- свойства ----------------------------------------------------------------------------
    @property
    def number(self) -> int:
        return int(self.raw.GetNumber())

    @property
    def name(self) -> str:
        return self.raw.GetName()

    @property
    def type(self) -> ViewType:
        try:
            return ViewType(self.raw.GetViewType())
        except ValueError:
            return ViewType.UNKNOWN

    @property
    def origin(self) -> Point:
        """Точка привязки вида на листе (мм)."""
        return Point(self.raw.GetX(), self.raw.GetY())

    @property
    def scale(self) -> float:
        return float(self.raw.GetScale())

    @property
    def angle(self) -> float:
        return float(self.raw.GetAngle())

    @property
    def is_associative(self) -> bool:
        return self.av is not None

    @property
    def projection_name(self) -> str:
        return self.av.GetProjectionName() if self.av else ""

    @property
    def source_file(self) -> str:
        return self.av.GetSourceFileName() if self.av else ""

    @property
    def is_section(self) -> bool:
        """True — сечение, False — разрез или обычный вид."""
        return bool(self.av and self.type == ViewType.SECTION and self.av.IsSection())

    @property
    def is_projection_linked(self) -> bool:
        """Вид в проекционной связи с базовым (сдвигается только вдоль одной оси)."""
        return bool(self.av and self.av.IsProjectionLink())

    @property
    def base_view(self) -> "View | None":
        if not self.av:
            return None
        b = self.av.GetBaseView()
        return View(self.drawing, b) if b else None

    def cut_line(self) -> list[Point]:
        """Для разреза/сечения — точки линии разреза в координатах ЛИСТА (пусто, если нет)."""
        if self.type != ViewType.SECTION:
            return []
        obj = self.raw.GetBaseObject()
        cl = self.ks.ICutLine(obj) if obj else None
        base = self.base_view
        if not cl or base is None:
            return []
        pts = list(cl.GetPoints() or [])
        return [base.to_sheet(pts[i], pts[i + 1]) for i in range(0, len(pts) - 1, 2)]

    def info(self) -> dict:
        bb = self.bbox()
        return {
            "number": self.number, "name": self.name, "type": self.type.name,
            "origin": (self.origin.x, self.origin.y), "scale": self.scale,
            "projection": self.projection_name, "section": self.is_section,
            "linked": self.is_projection_linked,
            "base_view": (self.base_view.number if self.base_view else None),
            "bbox": bb.as_tuple() if bb else None,
        }

    # --- положение ---------------------------------------------------------------------------
    def bbox(self) -> Rect | None:
        """Габарит вида на листе (мм листа), включая все его объекты (размеры, обозначения).

        Считается по объектам вида, а не по объекту вида: после SetScale `GetObjectsGabarit(вид)` возвращает
        устаревший габарит (spikes/s20, s21; docs/ksapi-quirks.md).
        """
        cache = getattr(self.drawing, "_bounds_cache", None)
        key = (self.number, "all", self.scale, self.angle)
        o = self.origin
        if cache is not None and key in cache:
            return cache[key].shift(o.x, o.y) if cache[key] else None
        cont = self.ks.IDrawingContainer(self.raw)
        objs = list(cont.GetObjects([int(_DR.ksAllObj)]) or []) if cont else []
        bb = self.drawing.objects_bbox(objs) if objs else None
        if bb is None or (bb.width == 0 and bb.height == 0):
            bb = self.drawing.objects_bbox([self.raw])
        if cache is not None:
            cache[key] = bb.shift(-o.x, -o.y) if bb else None
        return bb

    def content_bbox(self, curves: "list[Curve2D] | None" = None) -> Rect | None:
        """Габарит геометрии вида (контур детали: все кривые, в т.ч. NURBS) на листе, без обозначений.

        Без `curves` — одним запросом габарита объектов-кривых у КОМПАСа (быстро; учитывает только видимые части
        кривых). С `curves` — по уже прочитанной геометрии: дуги и окружности по квадрантным точкам.
        """
        if curves is None:
            cache = getattr(self.drawing, "_bounds_cache", None)
            key = (self.number, "content", self.angle)
            o, k = self.origin, self.scale
            if cache is not None and key in cache:
                r = cache[key]
                return Rect(r.x1*k+o.x, r.y1*k+o.y, r.x2*k+o.x, r.y2*k+o.y) if r else None
            cont = self.ks.IDrawingContainer(self.raw)
            if cont:
                types = [int(t) for t in (_DR.ksDrLineSeg, _DR.ksDrCircle, _DR.ksDrArc, *_POLY_TYPES)]
                objs = list(cont.GetObjects(types) or [])
                bb = self.drawing.objects_bbox(objs) if objs else None
                if bb is not None and (bb.width > 0 or bb.height > 0):
                    if cache is not None:
                        cache[key] = Rect((bb.x1-o.x)/k, (bb.y1-o.y)/k, (bb.x2-o.x)/k, (bb.y2-o.y)/k)
                    return bb
            curves = self.curves()
        pts = [p for c in curves for p in c.extremes()]
        if not pts:
            return None
        sheet = [self.to_sheet(p.x, p.y) for p in pts] if abs(self.angle) > 1e-9 else None
        if sheet is None:  # без поворота — достаточно углов габарита
            x1 = min(p.x for p in pts); y1 = min(p.y for p in pts)
            x2 = max(p.x for p in pts); y2 = max(p.y for p in pts)
            sheet = [self.to_sheet(x, y) for x, y in ((x1, y1), (x2, y2))]
        return Rect(min(p.x for p in sheet), min(p.y for p in sheet),
                    max(p.x for p in sheet), max(p.y for p in sheet))

    def move_to(self, x: float, y: float) -> Point:
        """Переместить точку привязки. Для вида в проекционной связи КОМПАС игнорирует сдвиг по связанной оси.

        Возвращает фактическое положение.
        """
        o = self.origin
        if abs(o.x - x) < 1e-9 and abs(o.y - y) < 1e-9:
            return o                      # IView.Update() без изменений возвращает False — не вызываем
        self.raw.SetX(x)
        self.raw.SetY(y)
        if not self.raw.Update() and not self.is_projection_linked:
            n = self.origin
            if abs(n.x - o.x) < 1e-9 and abs(n.y - o.y) < 1e-9:   # ничего не сдвинулось — реальный отказ
                raise OperationFailedError("Перемещение вида", self.name)
        return self.origin

    def move_by(self, dx: float, dy: float) -> Point:
        o = self.origin
        return self.move_to(o.x + dx, o.y + dy)

    def set_scale(self, scale: float) -> None:
        if scale <= 0:
            raise ValueError("Масштаб должен быть положительным")
        if abs(scale - self.scale) < 1e-9:
            return
        self.raw.SetScale(scale)
        check(self.raw.Update(), "Изменение масштаба вида", self.name)
        self.drawing.invalidate_geometry(bounds_only=True)

    # --- координаты --------------------------------------------------------------------------
    def to_sheet(self, x: float, y: float) -> Point:
        res = check(self.raw.TransformPointToSheet(x, y), "Преобразование координат вида")
        return Point(res[1], res[2])

    def from_sheet(self, x: float, y: float) -> Point:
        res = check(self.raw.TransformPointFromSheet(x, y), "Преобразование координат листа")
        return Point(res[1], res[2])

    def to_sheet_len(self, length: float) -> float:
        """Длина из единиц вида в мм листа."""
        return length * self.scale

    # --- связь с моделью ---------------------------------------------------------------------
    def project_point(self, x: float, y: float, z: float) -> Point:
        """Проекция точки модели в координаты вида."""
        if not self.av:
            raise OperationFailedError("Проекция точки", f"вид {self.name!r} не ассоциативный")
        res = check(self.av.GetProjectionPoint(x, y, z, 0, 0), "Проекция точки")
        return Point(res[1], res[2])

    def project(self, model_object) -> list[Curve2D]:
        """Кривые вида, порождённые объектом модели (ребро/грань; Edge/Face или raw).

        Пустой список — объект на этом виде не виден (скрыт или вне сечения).
        """
        if not self.av:
            raise OperationFailedError("Проекция объекта", f"вид {self.name!r} не ассоциативный")
        obj = getattr(model_object, "raw", model_object)
        return [self._curve(o) for o in self.av.GetAssociationObjects(obj)]

    # --- геометрия ---------------------------------------------------------------------------
    # Каждый вызов KsAPI стоит ~0.4 мс (при открытой большой сборке), поэтому геометрия читается минимумом вызовов:
    # стиль — лениво (Curve2D.is_axial), тип — из запроса по типам, отрезки — одним CalculatePolygon (spikes/s23).
    def _curve(self, raw_obj, t: int | None = None) -> Curve2D:
        ks = self.ks
        if t is None:
            do = ks.IDrawingObject(raw_obj)
            t = do.GetDrawingObjectType() if do else -1
        if t == _DR.ksDrLineSeg:
            line = self._line(raw_obj)
            if line is not None:
                return line
        if t == _DR.ksDrCircle:
            c = ks.ICircle(raw_obj)
            return Curve2D("circle", None, center=Point(c.GetXc(), c.GetYc()), radius=c.GetRadius(), raw=c)
        if t == _DR.ksDrArc:
            a = ks.IArc(raw_obj)
            return Curve2D("arc", None, Point(a.GetX1(), a.GetY1()), Point(a.GetX2(), a.GetY2()),
                           Point(a.GetXc(), a.GetYc()), a.GetRadius(),
                           # IArc.GetDirection(): true — ПО часовой стрелке (справка KsAPI, проверено s22)
                           angles=(a.GetAngle1(), a.GetAngle2()), ccw=not a.GetDirection(), raw=a)
        if t in _POLY_TYPES:
            return self._poly(raw_obj, int(t), 0.05 / (self.scale or 1.0))
        return Curve2D("other", None, raw=ks.IDrawingObject(raw_obj) or raw_obj)

    def _line(self, raw_obj) -> Curve2D | None:
        # Не через CalculatePolygon: он отдаёт float32 (ошибка ~1e-4 мм на координатах ~1 м), а вершины отрезков нужны
        # точно — к ним привязываются размеры (Associate). ILineSegment + 4 координаты стоят столько же (spikes/s23).
        s = self.ks.ILineSegment(raw_obj)
        if not s:
            return None
        return Curve2D("line", None, Point(s.GetX1(), s.GetY1()), Point(s.GetX2(), s.GetY2()),
                       source_type=int(_DR.ksDrLineSeg), raw=s)

    def _poly(self, raw_obj, t: int, sag: float) -> Curve2D:
        do = self.ks.IDrawingObject(raw_obj)
        c = do.GetCurve2D() if do else None
        flat = list(c.CalculatePolygon(sag) or []) if c else []
        pts = tuple(Point(flat[i], flat[i + 1]) for i in range(0, len(flat) - 1, 2))
        if not pts:
            return Curve2D("other", None, source_type=t, raw=do or raw_obj)
        closed = len(pts) > 2 and pts[0].dist(pts[-1]) < 1e-9
        return Curve2D("poly", None, points=pts, closed=closed, source_type=t, raw=do)

    def curves(self, sag: float = 0.05) -> list[Curve2D]:
        """Геометрия вида (координаты вида): отрезки, окружности, дуги — точно; NURBS, Безье, эллипсы, дуги эллипсов,
        ломаные, эквидистанты, контуры, конические и специальные кривые — ломаной с прогибом ≤ `sag` мм листа.
        """
        k = self.scale or 1.0
        cache = getattr(self.drawing, "_geom_cache", None)     # Drawing.geometry_cache()
        key = (self.number, round(sag / k, 12))
        if cache is not None and key in cache:
            return list(cache[key])
        cont = self.ks.IDrawingContainer(self.raw)
        if not cont:
            return []
        out = []
        for t in (_DR.ksDrLineSeg, _DR.ksDrCircle, _DR.ksDrArc):
            out += [self._curve(o, int(t)) for o in cont.GetObjects([int(t)]) or []]
        for t in _POLY_TYPES:
            out += [self._poly(o, int(t), sag / k) for o in cont.GetObjects([int(t)]) or []]
        if cache is not None:
            cache[key] = out
            return list(out)
        return out

    @property
    def symbols(self):
        """ISymbols2DContainer вида (размеры, обозначения) — для низкоуровневой работы."""
        return self.ks.ISymbols2DContainer(self.raw)

    # --- разрез в виде -----------------------------------------------------------------------
    def cut(self, through: "View", at: tuple[float, float] | Point, region: Rect | None = None,
            half: str | None = None, margin: float = 3.0) -> int:
        """Разрез в самом виде (ГОСТ 2.305): полный, «половина вида — половина разреза» или местный.

        Секущая плоскость проходит через точку `at` (координаты вида `through`) перпендикулярно направлению
        взгляда этого вида — например, через ось детали, указанную на виде слева.
        `region` — область разреза в координатах этого вида (местный разрез); по умолчанию весь вид (+margin).
        `half` — 'below' | 'above' | 'left' | 'right': разрез с одной стороны от точки секущей плоскости,
        спроецированной на этот вид (для симметричных деталей; при горизонтальной оси разрез принято ниже оси).
        Возвращает индекс разреза в ICutViewParam. Всё — одним шагом отмены.
        """
        ks = self.ks
        cvp = ks.ICutViewParam(self.raw)
        if not cvp:
            raise OperationFailedError("Разрез в виде", f"вид {self.name!r} не поддерживает разрезы")
        if region is None:
            pts = [p for c in self.curves() for p in c.extremes()]
            if not pts:
                raise OperationFailedError("Разрез в виде", f"на виде {self.name!r} нет геометрии")
            region = Rect(min(p.x for p in pts), min(p.y for p in pts),
                          max(p.x for p in pts), max(p.y for p in pts)).inflate(margin)
        at = at if isinstance(at, Point) else Point(*at)
        sheet_at = through.to_sheet(at.x, at.y)       # AddCut ждёт точку в координатах ЛИСТА (s25b)
        if half is not None:
            c = self.from_sheet(sheet_at.x, sheet_at.y)
            if half == "below":
                region = Rect(region.x1, region.y1, region.x2, c.y)
            elif half == "above":
                region = Rect(region.x1, c.y, region.x2, region.y2)
            elif half == "left":
                region = Rect(region.x1, region.y1, c.x, region.y2)
            elif half == "right":
                region = Rect(c.x, region.y1, region.x2, region.y2)
            else:
                raise ValueError("half: below | above | left | right")
        with self.drawing.edit():
            before = cvp.GetCutsCount()
            rect = ks.IDrawingContainer(self.raw).GetRectangles().Add()
            rect.SetX(region.x1); rect.SetY(region.y1); rect.SetWidth(region.width); rect.SetHeight(region.height)
            check(rect.Update(), "Контур разреза", self.name)
            idx = cvp.AddCut("", before + 1, sheet_at.x, sheet_at.y, False, ks.IDrawingObject(rect), through.raw)
            if idx < 0 or cvp.GetCutsCount() <= before:
                ks.IDrawingObject(rect).Delete()
                raise OperationFailedError("Разрез в виде", f"КОМПАС не создал разрез на виде {self.name!r}")
        self.drawing.invalidate_geometry(self)
        return int(idx)

    # --- обозначение -------------------------------------------------------------------------
    def set_designation(self, show_scale: bool | None = None, show_name: bool | None = None) -> None:
        """Настроить надпись вида («А-А (2:1)»)."""
        des = self.ks.IViewDesignation(self.raw)
        if not des:
            raise OperationFailedError("Обозначение вида", "интерфейс недоступен")
        if show_scale is not None:
            des.SetShowScale(show_scale)
        if show_name is not None:
            des.SetShowName(show_name)
        check(self.raw.Update(), "Обновление вида", self.name)


