"""Документ-чертёж: листы, виды, разрезы/сечения."""

import os
from pathlib import Path
from contextlib import contextmanager
from typing import Iterable, Iterator, Sequence

# из kompas_lib.core: Document
# из kompas_lib.enums: PROJECTION_NAMES, Projection, ViewType
# из kompas_lib.errors: KompasError, OperationFailedError, check
# из kompas_lib.geom: Point, Rect
# из kompas_lib.drawing.sheet: Sheet
# из kompas_lib.drawing.view: View


class Drawing(Document):
    def __init__(self, kompas, raw_doc) -> None:
        super().__init__(kompas, raw_doc)
        self.d2 = self.ks.IKompasDocument2D(raw_doc)
        self._geom_cache: dict | None = None
        self._bounds_cache: dict | None = None
        # Раскладка поставленных библиотекой размеров: вид -> id объекта -> запрос и положение
        # (dims.api). Нужна, чтобы после переноса вида восстановить, а не пересчитывать раскладку.
        self._dim_layout: dict = {}

    def _undo_iface(self):
        return self.d2

    # --- листы -------------------------------------------------------------------------------
    @property
    def sheets(self) -> list[Sheet]:
        coll = self.raw.GetLayoutSheets()
        return [Sheet(self, coll.GetItem(i), i) for i in range(coll.GetCount())]

    @property
    def sheet(self) -> Sheet:
        """Первый лист."""
        return self.sheets[0]

    @property
    def stamp(self):
        return self.sheet.stamp

    # --- виды --------------------------------------------------------------------------------
    @property
    def _views(self):
        return self.d2.GetViewsAndLayersManager().GetViews()

    def _raw_views(self) -> list:
        """Все виды, включая системный.

        Перечисляем через GetView(i) до первого None и НЕ вызываем IViews.GetCount():
        GetCount() перед AddStandartViews делает создаваемые виды недоступными (см. docs/ksapi-quirks.md).
        """
        coll = self._views
        result, i = [], 0
        while i < 10000:
            v = coll.GetView(i)
            if not v:
                break
            result.append(v)
            i += 1
        return result

    @contextmanager
    def geometry_cache(self) -> Iterator["Drawing"]:
        """Блок, в котором геометрия каждого вида (View.curves) читается из КОМПАСа один раз.

        Чтение геометрии — самое дорогое: ~1–3 мс на кривую (вид сборки — тысячи кривых, секунды–десятки секунд).
        Кривые хранятся в координатах вида и не меняются при перемещении вида, смене масштаба, простановке размеров
        и обозначений — всё это внутри блока безопасно. Нельзя внутри блока перестраивать модель/виды
        (RebuildDocument, изменение модели, пересоздание вида) — геометрия устареет.
        """
        outer = self._geom_cache is not None
        if not outer:
            self._geom_cache = {}
            self._bounds_cache = {}
        try:
            yield self
        finally:
            if not outer:
                self._geom_cache = None
                self._bounds_cache = None

    def invalidate_geometry(self, view: View | None = None, bounds_only: bool = False) -> None:
        """Сброс кэша после низкоуровневых изменений: bounds_only — размеры/обозначения."""
        caches = [self._bounds_cache] if bounds_only else [self._bounds_cache, self._geom_cache]
        for cache in caches:
            if cache is not None:
                for key in list(cache):
                    if view is None or key[0] == view.number:
                        del cache[key]

    @property
    def views(self) -> list[View]:
        """Виды чертежа без системного."""
        result = []
        for raw_view in self._raw_views():
            v = View(self, raw_view)
            if v.type != ViewType.SYSTEM:
                result.append(v)
        return result

    def view(self, key: int | str) -> View:
        """Вид по номеру или имени."""
        coll = self._views
        v = coll.GetViewByNumber(key) if isinstance(key, int) else coll.GetViewByName(key)
        if not v:
            raise KompasError(f"Нет вида {key!r}")
        return View(self, v)

    def objects_bbox(self, raw_objects: Iterable) -> Rect | None:
        """Габарит объектов на листе (мм)."""
        objs = list(raw_objects)
        if not objs:
            return None
        res = self.d2.GetObjectsGabarit(objs, 0, 0, 0, 0)
        if not res[0]:
            return None
        return Rect.of(*res[1:5])

    def add_standard_views(self, model, projections: Sequence[Projection] = (Projection.FRONT, Projection.TOP,
                                                                              Projection.LEFT),
                           scale: float = 1.0, at: tuple[float, float] | None = None,
                           main_projection: str | Projection = Projection.FRONT,
                           gap: float = 20.0) -> dict[Projection, View]:
        """Создать стандартные ассоциативные виды модели.

        `model` — PartDocument или путь к сохранённой модели. Главный вид (FRONT) создаётся всегда.
        `main_projection` — какая проекция модели станет главным видом ('#Спереди', '#Сверху'… или Projection).
        Положение — предварительное; итоговую компоновку делает `layout.arrange_views()`.
        Возвращает {Projection: View}.
        """
        path = getattr(model, "path", None) or os.fspath(model)
        if not path or not Path(path).is_file():
            raise KompasError("Модель должна быть сохранена в файл перед созданием видов")
        projections = list(dict.fromkeys([Projection.FRONT, *projections]))
        main = PROJECTION_NAMES[main_projection] if isinstance(main_projection, Projection) else main_projection
        if at is None:
            c = self.sheet.frame.center
            at = (c.x, c.y)
        before = {v.number for v in self.views}
        with self.kompas.quiet():
            check(self._views.AddStandartViews(str(Path(path).resolve()), main, [int(p) for p in projections],
                                               at[0], at[1], scale, gap, gap),
                  "Создание стандартных видов", path)
        new = [v for v in self.views if v.number not in before]
        new.sort(key=lambda v: v.number)
        if len(new) != len(projections):
            raise OperationFailedError("Создание стандартных видов",
                                       f"ожидалось {len(projections)} видов, создано {len(new)}")
        return dict(zip(projections, new))

    def add_section(self, base: View, points: Sequence[tuple[float, float]], at: tuple[float, float],
                    section: bool = True, scale: float | None = None,
                    arrows_left: bool = False) -> View:
        """Линия разреза на виде `base` и вид разреза/сечения.

        `points` — точки ломаной линии разреза в координатах вида `base` (минимум 2).
        `section=True` — сечение (только фигура в плоскости), False — разрез.
        `arrows_left` — стрелки слева по направлению ломаной (взгляд).
        Обозначение (А-А, Б-Б…) КОМПАС присваивает автоматически.
        """
        if len(points) < 2:
            raise ValueError("Линия разреза задаётся минимум двумя точками")
        cut_line = base.symbols.GetCutLines().Add()
        cut_line.SetPoints([c for p in points for c in p])
        cut_line.SetArrowPos(arrows_left)
        check(cut_line.Update(), "Создание линии разреза")
        raw_view = self._views.Add(int(ViewType.SECTION))
        if not raw_view:
            raise OperationFailedError("Создание вида разреза")
        raw_view.SetBaseObject(self.ks.IDrawingObject(cut_line))
        av = self.ks.IAssociationView(raw_view)
        if av:
            av.SetSection(section)
        raw_view.SetX(at[0])
        raw_view.SetY(at[1])
        raw_view.SetScale(base.scale if scale is None else scale)
        check(raw_view.Update(), "Создание вида разреза")
        view = View(self, raw_view)
        self.invalidate_geometry(base, bounds_only=True)
        self.invalidate_geometry(view)
        # ГОСТ 2.305: масштаб в обозначении — только если отличается от масштаба базового вида.
        if scale is None or abs(scale - base.scale) < 1e-9:
            try:
                view.set_designation(show_scale=False)
            except OperationFailedError:
                pass
        return view

    def rebuild(self) -> None:
        check(self.d2.RebuildDocument(), "Перестроение чертежа")
        self.invalidate_geometry()

    def info(self) -> dict:
        return {
            "name": self.name, "path": self.path,
            "sheets": [s.info() for s in self.sheets],
            "views": [v.info() for v in self.views],
        }

    # --- снимки ------------------------------------------------------------------------------
    def capture_region(self, region: Rect | View, dpi: int = 200, pad: float = 3.0) -> bytes:
        """PNG фрагмента листа (область в мм листа или габарит вида). Требует Pillow."""
        # из kompas_lib.capture: crop_sheet
        rect = region.bbox() if isinstance(region, View) else region
        if rect is None:
            raise KompasError("Пустая область")
        return crop_sheet(self.capture(dpi=dpi), self.sheet.size, rect, pad=pad)

    @staticmethod
    def _pt(p) -> Point:
        return p if isinstance(p, Point) else Point(*p)


