# === 28/55 kompas_lib.layout.views — kompas_lib/layout/views.py
# ==================================================================================================================
"""Компоновка видов на листе (чистый алгоритм, без КОМПАСа).

Правила:
* взаимное расположение видов — ГОСТ 2.305 (вид сверху под главным, слева — справа от главного…);
* у каждого вида по сторонам резерв под размеры (ГОСТ 2.307: 10 мм до первой размерной линии,
  7 мм между линиями) — виды не ставятся впритык;
* между зарезервированными зонами соседних видов — зазор `view_gap`;
* композиция держится на расстоянии `frame_margin` от внутренней рамки и `keepout_margin`
  от основной надписи, графы 26 и доп. граф;
* среди допустимых положений выбирается ближайшее к центру свободного поля.
"""

import math
from dataclasses import dataclass, field
from enum import Enum
from typing import Hashable, Sequence

gost = _submodule('gost')
# из kompas_lib.geom: Rect, union_all

Sides = tuple[float, float, float, float]  # left, bottom, right, top


class Role(str, Enum):
    """Положение вида относительно главного (ГОСТ 2.305, метод первого угла)."""
    MAIN = "main"
    BELOW = "below"    # вид сверху
    ABOVE = "above"    # вид снизу
    RIGHT = "right"    # вид слева (и вид сзади — дальше справа)
    LEFT = "left"      # вид справа
    FREE = "free"      # разрезы, сечения, выносные, изометрия


def _four_sides(v: float | Sequence[float]) -> Sides:
    if isinstance(v, (int, float)):
        return (float(v),) * 4  # type: ignore[return-value]
    t = tuple(float(x) for x in v)
    if len(t) != 4:
        raise ValueError("Ожидалось 4 значения: left, bottom, right, top")
    return t  # type: ignore[return-value]


def dim_reserve(tiers: int, text_height: float = gost.DIM_TEXT_HEIGHT) -> float:
    """Ширина зоны под `tiers` ярусов размеров (мм листа). 0 ярусов — 0."""
    if tiers <= 0:
        return 0.0
    return gost.DIM_FIRST_OFFSET + gost.DIM_STEP * (tiers - 1) + text_height + 1.5


@dataclass
class LayoutConfig:
    """Параметры компоновки (все размеры — мм листа)."""
    frame_margin: float | Sequence[float] = 12.0     # отступ композиции от внутренней рамки (l, b, r, t)
    keepout_margin: float = 6.0                      # зазор до штампа / графы 26 / доп. граф
    view_gap: float = 12.0                           # зазор между зарезервированными зонами видов
    dim_tiers: int | Sequence[int] = 2               # ярусов размеров по сторонам по умолчанию (l, b, r, t)
    reserves: dict[Hashable, Sequence[float]] = field(default_factory=dict)  # явные резервы по видам
    free_side: str = "auto"                          # куда ставить свободные виды: right | below | auto
    step: float = 1.0                                # шаг поиска положения

    def reserve_for(self, key: Hashable) -> Sides:
        if key in self.reserves:
            return _four_sides(self.reserves[key])
        tiers = self.dim_tiers
        t = (tiers,) * 4 if isinstance(tiers, int) else tuple(tiers)
        return tuple(dim_reserve(int(n)) for n in t)  # type: ignore[return-value]


@dataclass
class ViewBox:
    """Вид для компоновки: текущий габарит на листе и роль."""
    key: Hashable
    bbox: Rect
    role: Role = Role.FREE
    order: float = 0.0        # порядок среди видов одной роли (меньше — ближе к главному)
    # Для свободных видов: желаемое положение центра (мм листа, в текущих координатах), например
    # продолжение следа секущей плоскости для сечения (ГОСТ 2.305). None — без предпочтений.
    anchor_x: float | None = None
    anchor_y: float | None = None
    # Геометрический габарит (контур детали без обозначений). Резерв под размеры отсчитывается от него;
    # обозначения, уже выходящие за контур (стрелки разреза, надписи), в резерв «засчитываются».
    content: Rect | None = None


def _ext(b: ViewBox, cfg: LayoutConfig) -> Rect:
    """Зона вида: весь габарит ∪ контур + резерв под размеры."""
    res = cfg.reserve_for(b.key)
    base = b.content if b.content is not None else b.bbox
    return b.bbox.union(base.expand(*res))


@dataclass
class ViewPlacement:
    """Результат: целевой габарит каждого вида и сдвиг относительно текущего."""
    targets: dict[Hashable, Rect]
    shifts: dict[Hashable, tuple[float, float]]
    composition: Rect
    area: Rect

    def as_dict(self) -> dict:
        return {
            "composition": self.composition.as_tuple(), "area": self.area.as_tuple(),
            "views": {str(k): {"target": r.as_tuple(), "shift": self.shifts[k]} for k, r in self.targets.items()},
        }


def _compose(boxes: Sequence[ViewBox], cfg: LayoutConfig, free_side: str,
             use_anchors: bool = True) -> dict[Hashable, Rect]:
    """Относительная раскладка зон видов (зона главного вида — как есть)."""
    gap = cfg.view_gap
    ext = {b.key: _ext(b, cfg) for b in boxes}
    main = next((b for b in boxes if b.role == Role.MAIN), None)
    if main is None:
        raise ValueError("Нет главного вида (Role.MAIN)")
    placed: dict[Hashable, Rect] = {main.key: ext[main.key]}
    m = ext[main.key]

    def by_role(role: Role) -> list[ViewBox]:
        return sorted((b for b in boxes if b.role == role), key=lambda b: b.order)

    # Проекционные виды: связанная координата сохраняется (как у главного), свободная — подряд от главного.
    x = m.x2
    for b in by_role(Role.RIGHT):
        e = ext[b.key]
        r = Rect(x + gap, e.y1, x + gap + e.width, e.y2)
        placed[b.key] = r
        x = r.x2
    x = m.x1
    for b in by_role(Role.LEFT):
        e = ext[b.key]
        r = Rect(x - gap - e.width, e.y1, x - gap, e.y2)
        placed[b.key] = r
        x = r.x1
    y = m.y1
    for b in by_role(Role.BELOW):
        e = ext[b.key]
        r = Rect(e.x1, y - gap - e.height, e.x2, y - gap)
        placed[b.key] = r
        y = r.y1
    y = m.y2
    for b in by_role(Role.ABOVE):
        e = ext[b.key]
        r = Rect(e.x1, y + gap, e.x2, y + gap + e.height)
        placed[b.key] = r
        y = r.y2

    free = by_role(Role.FREE)
    if free:
        comp = union_all(placed.values())
        assert comp is not None
        if free_side == "right":
            x0, ytop = comp.x2 + gap, comp.y2
            for b in free:
                e = ext[b.key]
                y2 = ytop
                if b.anchor_y is not None and use_anchors:  # центр на продолжении горизонтального следа, если не мешает соседу
                    y2 = min(ytop, b.anchor_y + e.height / 2)
                r = Rect(x0, y2 - e.height, x0 + e.width, y2)
                placed[b.key] = r
                ytop = r.y1 - gap
        else:  # below: рядом под композицией, слева направо
            ybot, x0 = comp.y1 - gap, comp.x1
            for b in free:
                e = ext[b.key]
                x1 = x0
                if b.anchor_x is not None and use_anchors:  # центр на продолжении вертикального следа, если не мешает соседу
                    x1 = max(x0, b.anchor_x - e.width / 2)
                r = Rect(x1, ybot - e.height, x1 + e.width, ybot)
                placed[b.key] = r
                x0 = r.x2 + gap
    return placed


def _area(frame: Rect, cfg: LayoutConfig) -> Rect:
    l, b, r, t = _four_sides(cfg.frame_margin)
    return Rect(frame.x1 + l, frame.y1 + b, frame.x2 - r, frame.y2 - t)


def _find_shift(placed: dict[Hashable, Rect], area: Rect, obstacles: list[Rect],
                step: float) -> tuple[float, float] | None:
    """Сдвиг композиции: все зоны внутри area и вне obstacles; ближе всего к центру области."""
    comp = union_all(placed.values())
    assert comp is not None
    if comp.width > area.width + 1e-6 or comp.height > area.height + 1e-6:
        return None
    dx_min, dx_max = area.x1 - comp.x1, area.x2 - comp.x2
    dy_min, dy_max = area.y1 - comp.y1, area.y2 - comp.y2
    cx, cy = area.center.x - comp.center.x, area.center.y - comp.center.y
    rects = list(placed.values())

    def ok(dx: float, dy: float) -> bool:
        return not any(r.shift(dx, dy).intersects(o) for r in rects for o in obstacles)

    def frange(a: float, b: float, s: float) -> list[float]:
        n = max(0, int(math.floor((b - a) / s)))
        return [a + i * s for i in range(n + 1)] + ([b] if b - a > 1e-9 else [])

    best: tuple[float, float, float] | None = None
    for dx in frange(dx_min, dx_max, step):
        for dy in frange(dy_min, dy_max, step):
            d = (dx - cx) ** 2 + (dy - cy) ** 2
            if best is not None and d >= best[0]:
                continue
            if ok(dx, dy):
                best = (d, dx, dy)
    return None if best is None else (best[1], best[2])


def arrange(boxes: Sequence[ViewBox], frame: Rect, keepouts: Sequence[Rect],
            cfg: LayoutConfig | None = None) -> ViewPlacement | None:
    """Рассчитать положения видов. None — не помещается (нужен меньший масштаб или больший формат)."""
    cfg = cfg or LayoutConfig()
    area = _area(frame, cfg)
    obstacles = [k.inflate(cfg.keepout_margin) for k in keepouts]
    sides = ["right", "below"] if cfg.free_side == "auto" else [cfg.free_side]
    has_free = any(b.role == Role.FREE for b in boxes)
    has_anchor = any(b.anchor_x is not None or b.anchor_y is not None for b in boxes)
    variants = [(s, a) for s in (sides if has_free else ["right"])
                for a in ((True, False) if has_anchor else (True,))]
    candidates = []
    for side, use_anchors in variants:
        placed = _compose(boxes, cfg, side, use_anchors)
        shift = _find_shift(placed, area, obstacles, cfg.step)
        if shift is None:
            continue
        comp = union_all(placed.values())
        assert comp is not None
        # «Качество»: насколько композиция заполняет поле (меньше — лучше) + отклонение свободных видов
        # от их якорей (сечение — на продолжении следа секущей плоскости).
        score = max(comp.width / area.width, comp.height / area.height)
        for b in boxes:
            c = placed[b.key].center
            if b.anchor_x is not None:
                score += abs(c.x - b.anchor_x) / area.width
            if b.anchor_y is not None:
                score += abs(c.y - b.anchor_y) / area.height
        candidates.append((score, placed, shift))
    if not candidates:
        return None
    _, placed, (dx, dy) = min(candidates, key=lambda c: c[0])

    targets: dict[Hashable, Rect] = {}
    shifts: dict[Hashable, tuple[float, float]] = {}
    for b in boxes:
        e = _ext(b, cfg)
        p = placed[b.key].shift(dx, dy)
        sx, sy = p.x1 - e.x1, p.y1 - e.y1
        targets[b.key] = b.bbox.shift(sx, sy)
        shifts[b.key] = (sx, sy)
    comp = union_all(r.shift(dx, dy) for r in placed.values())
    assert comp is not None
    return ViewPlacement(targets, shifts, comp, area)


def scaled_boxes(boxes: Sequence[ViewBox], origins: dict[Hashable, tuple[float, float]],
                 k: float) -> list[ViewBox]:
    """Габариты видов при изменении масштаба в k раз (относительно точек привязки видов).

    Масштабируется только геометрия (`content`); обозначения (размеры, надписи, стрелки) от масштаба вида не
    зависят — их выступ за контур сохраняется в мм листа. Без `content` масштабируется весь габарит.
    """
    out = []
    for b in boxes:
        ox, oy = origins[b.key]

        def sc(r: Rect | None) -> Rect | None:
            if r is None:
                return None
            return Rect(ox + (r.x1 - ox) * k, oy + (r.y1 - oy) * k, ox + (r.x2 - ox) * k, oy + (r.y2 - oy) * k)

        content = sc(b.content)
        if content is not None and b.content is not None:
            c0, bb = b.content, b.bbox
            bbox = Rect(content.x1 - max(0.0, c0.x1 - bb.x1), content.y1 - max(0.0, c0.y1 - bb.y1),
                        content.x2 + max(0.0, bb.x2 - c0.x2), content.y2 + max(0.0, bb.y2 - c0.y2))
        else:
            bbox = sc(b.bbox)
        assert bbox is not None
        # якоря (след секущей) задаются относительно главного вида — для проверки вместимости не нужны
        out.append(ViewBox(b.key, bbox, b.role, b.order, content=content))
    return out


def fit_scale(boxes: Sequence[ViewBox], origins: dict[Hashable, tuple[float, float]], current: float,
              frame: Rect, keepouts: Sequence[Rect], cfg: LayoutConfig | None = None,
              max_scale: float | None = None) -> gost.Scale | None:
    """Наибольший стандартный масштаб (≤ max_scale), при котором компоновка помещается."""
    cfg = cfg or LayoutConfig()
    coarse = LayoutConfig(**{**cfg.__dict__, "step": max(cfg.step, 4.0)})
    for s in reversed(gost.STANDARD_SCALES):
        if max_scale is not None and s.factor > max_scale + 1e-9:
            continue
        if arrange(scaled_boxes(boxes, origins, s.factor / current), frame, keepouts, coarse) is not None:
            return s
    return None


