"""Применение компоновки видов к чертежу КОМПАС."""

from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Sequence

gost = _submodule('gost')
# из kompas_lib.enums: SheetFormat
# из kompas_lib.errors: LayoutError
# из kompas_lib.geom: Rect
# из kompas_lib.layout.views: LayoutConfig, ViewPlacement, Role, ViewBox, arrange, fit_scale, scaled_boxes

# из kompas_lib.drawing: Drawing, View  (только для аннотаций)


@dataclass
class LayoutReport:
    placement: ViewPlacement
    scale: float
    scale_changed: bool
    residuals: dict[int, tuple[float, float]] = field(default_factory=dict)  # номер вида -> (dx, dy) недолёт

    @property
    def ok(self) -> bool:
        return all(abs(dx) <= 0.5 and abs(dy) <= 0.5 for dx, dy in self.residuals.values())

    def as_dict(self) -> dict:
        return {"ok": self.ok, "scale": self.scale, "scale_changed": self.scale_changed,
                "residuals": self.residuals, **self.placement.as_dict()}


def find_main_view(drawing: "Drawing") -> "View":
    views = drawing.views
    if not views:
        raise LayoutError("На чертеже нет видов")
    for v in views:
        if v.projection_name == "#Спереди":
            return v
    # вид, к которому привязано больше всего проекционных видов
    counts = {v.number: 0 for v in views}
    for v in views:
        b = v.base_view
        if b is not None and v.is_projection_linked and b.number in counts:
            counts[b.number] += 1
    return max(views, key=lambda v: (counts[v.number], -v.number))


def infer_roles(drawing: "Drawing", main: "View | None" = None) -> dict[int, Role]:
    """Роль каждого вида (по номеру) относительно главного — по проекционной связи и взаимному положению."""
    main = main or find_main_view(drawing)
    roles: dict[int, Role] = {}
    mo = main.origin           # стороны — по точкам привязки: дёшево, а связанный вид смещён по одной оси
    for v in drawing.views:
        if v.number == main.number:
            roles[v.number] = Role.MAIN
            continue
        base = v.base_view
        if v.is_projection_linked and base is not None and base.number == main.number:
            vo = v.origin
            dx = vo.x - mo.x
            dy = vo.y - mo.y
            if abs(dx) >= abs(dy):
                roles[v.number] = Role.RIGHT if dx > 0 else Role.LEFT
            else:
                roles[v.number] = Role.ABOVE if dy > 0 else Role.BELOW
        else:
            roles[v.number] = Role.FREE
    return roles


def _boxes(drawing: "Drawing", roles: dict[int, Role], main: "View") -> tuple[list[ViewBox], dict]:
    boxes, origins = [], {}
    views = [v for v in drawing.views if v.number in roles]
    bbs = {v.number: v.bbox() for v in views}          # габарит вида — дорогой запрос, по разу на вид
    mb = bbs.get(main.number)
    assert mb is not None
    for v in views:
        bb = bbs[v.number]
        if bb is None:
            continue
        order = abs(bb.center.x - mb.center.x) + abs(bb.center.y - mb.center.y) if roles[v.number] != Role.FREE \
            else float(v.number)
        box = ViewBox(v.number, bb, roles[v.number], order, content=v.content_bbox())
        if roles[v.number] == Role.FREE:
            pts = v.cut_line()
            if len(pts) >= 2:  # ГОСТ 2.305: сечение — на продолжении следа секущей плоскости
                xs, ys = [p.x for p in pts], [p.y for p in pts]
                if max(xs) - min(xs) <= max(ys) - min(ys):
                    box.anchor_x = sum(xs) / len(xs)
                else:
                    box.anchor_y = sum(ys) / len(ys)
        boxes.append(box)
        o = v.origin
        origins[v.number] = (o.x, o.y)
    return boxes, origins


def arrange_views(drawing: "Drawing", cfg: LayoutConfig | None = None, roles: dict[int, Role] | None = None,
                  main: "View | None" = None, auto_scale: bool = False,
                  max_scale: float | None = None) -> LayoutReport:
    """Расставить виды на листе по правилам LayoutConfig.

    auto_scale=True — подобрать наибольший стандартный масштаб (≤ max_scale, по умолчанию — текущий
    масштаб главного вида), при котором компоновка помещается; масштаб всех видов меняется пропорционально.
    Без auto_scale при нехватке места бросается LayoutError с рекомендацией.
    """
    cfg = cfg or LayoutConfig()
    main = main or find_main_view(drawing)
    roles = roles or infer_roles(drawing, main)
    sheet = drawing.sheet
    frame, keepouts = sheet.frame, sheet.keepouts
    with drawing.edit():                      # смена масштаба, откат и перемещения — один шаг отмены
        boxes, origins = _boxes(drawing, roles, main)
        start = current = main.scale
        placement = None

        if auto_scale:
            limit = current if max_scale is None else max_scale
            best = fit_scale(boxes, origins, current, frame, keepouts, cfg, max_scale=limit)
            if best is None:
                raise LayoutError("Виды не помещаются на формат ни в одном стандартном масштабе; нужен больший формат")
            # прогноз приблизителен (обозначения, сдвиги связанных видов) — проверяем фактом, при неудаче
            # пробуем следующие меньшие масштабы, в конце — откат к исходному
            cands = [s for s in reversed(gost.STANDARD_SCALES) if s.factor <= best.factor + 1e-9][:4]
            tried = []
            for s in cands:
                if abs(s.factor - current) > 1e-9:
                    _rescale(drawing, roles, s.factor / current)
                    current = s.factor
                    boxes, origins = _boxes(drawing, roles, main)
                tried.append(s.label)
                placement = arrange(boxes, frame, keepouts, cfg)
                if placement is not None:
                    break
            if placement is None:
                if abs(current - start) > 1e-9:
                    _rescale(drawing, roles, start / current)
                raise LayoutError(f"Виды не помещаются на {sheet.format.name}: проверены масштабы {', '.join(tried)}; "
                                  "масштаб возвращён к исходному — нужен больший формат или меньше видов")
        else:
            placement = arrange(boxes, frame, keepouts, cfg)
            if placement is None:
                need = None
                try:
                    need = fit_scale(boxes, origins, current, frame, keepouts, cfg)
                except Exception:  # noqa: BLE001
                    pass
                hint = f"; поместится примерно в масштабе {need.label}" if need else "; нужен больший формат"
                raise LayoutError(f"Виды не помещаются на {sheet.format.name} с заданными отступами{hint}")

        # Перенос вида не меняет его габарит, только сдвигает: текущий габарит = исходный + смещение точки привязки
        # (дешёвый GetX/GetY вместо дорогого габарита объектов вида).
        before = {b.key: b.bbox for b in boxes}

        def now(v: "View") -> Rect:
            o, o0 = v.origin, origins[v.number]
            return before[v.number].shift(o.x - o0[0], o.y - o0[1])

        # 1) главный вид — связанные проекционные виды сдвигаются вместе с ним
        dx, dy = placement.shifts[main.number]
        main.move_by(dx, dy)
        # 2) остальные — по фактическому отклонению от цели
        for v in drawing.views:
            if v.number == main.number or v.number not in placement.targets or v.number not in before:
                continue
            bb = now(v)
            t = placement.targets[v.number]
            ddx, ddy = t.x1 - bb.x1, t.y1 - bb.y1
            if abs(ddx) > 1e-3 or abs(ddy) > 1e-3:
                v.move_by(ddx, ddy)

    residuals = {}
    for v in drawing.views:
        if v.number in placement.targets and v.number in before:
            bb = now(v)
            t = placement.targets[v.number]
            residuals[v.number] = (round(t.x1 - bb.x1, 3), round(t.y1 - bb.y1, 3))
    return LayoutReport(placement, current, abs(current - start) > 1e-9, residuals)


def _rescale(drawing: "Drawing", roles: dict[int, Role], k: float) -> None:
    for v in drawing.views:
        if v.number in roles:
            v.set_scale(v.scale * k)


def arrange_sheet(drawing: "Drawing", formats: Sequence[SheetFormat] = (SheetFormat.A4, SheetFormat.A3,
                  SheetFormat.A2), cfg: LayoutConfig | None = None, main: "View | None" = None,
                  roles: dict[int, Role] | None = None) -> LayoutReport:
    """Сначала натуральный масштаб на A4/A3/A2, затем уменьшение на этих форматах.

    Выбирается наибольший стандартный масштаб и наименьший подходящий формат. При отказе
    возвращаются исходные формат/ориентация/масштабы. Весь подбор — один шаг отмены.
    """
    if not formats:
        raise ValueError("Нужен хотя бы один формат")
    main = main or find_main_view(drawing)
    roles = roles or infer_roles(drawing, main)
    sheet = drawing.sheet
    old = sheet.format, sheet.landscape, sheet.multiplicity
    scales = {v.number: v.scale for v in drawing.views}
    start = main.scale
    annotated = any(
        getattr(v.symbols, getter)().GetCount()
        for v in drawing.views
        for getter in ("GetLineDimensions", "GetDiametralDimensions", "GetRadialDimensions", "GetAngleDimensions")
    )
    # KsAPI не сохраняет размещение размерного текста при смене масштаба вида.
    # После оформления подбираем формат при уже принятом масштабе.
    candidates = [start] if annotated else [s.factor for s in reversed(gost.STANDARD_SCALES) if s.factor <= 1.0]
    with drawing.edit(), drawing.geometry_cache():
        boxes, origins = _boxes(drawing, roles, main)
        try:
            for scale in candidates:
                forecast = scaled_boxes(boxes, origins, scale / start)
                for fmt in formats:
                    for landscape in ((False,) if fmt == SheetFormat.A4 else (True,False)):
                        sheet.set_format(fmt, landscape=landscape)
                        if arrange(forecast,sheet.frame,sheet.keepouts,cfg or LayoutConfig()) is None:
                            continue
                        if abs(main.scale - scale) > 1e-9:
                            _rescale(drawing, roles, scale / main.scale)
                        try:
                            result = arrange_views(drawing, cfg, roles, main)
                        except LayoutError:
                            continue
                        result.scale_changed = abs(scale - start) > 1e-9
                        return result
            raise LayoutError("Виды не помещаются на заданные форматы")
        except Exception:
            sheet.set_format(*old)
            for v in drawing.views:
                if v.number in scales and abs(v.scale - scales[v.number]) > 1e-9:
                    v.set_scale(scales[v.number])
            raise


def check_layout(drawing: "Drawing", cfg: LayoutConfig | None = None) -> list[str]:
    """Проблемы текущей компоновки: выход за рамку, наезд на штамп, пересечение/близость видов."""
    cfg = cfg or LayoutConfig()
    sheet = drawing.sheet
    frame = sheet.frame
    problems = []
    boxes: list[tuple["View", Rect]] = [(v, b) for v in drawing.views if (b := v.bbox()) is not None]
    for v, b in boxes:
        if not frame.contains(b):
            problems.append(f"Вид {v.name!r} выходит за рамку")
        for k in sheet.keepouts:
            if b.intersects(k):
                problems.append(f"Вид {v.name!r} наезжает на основную надпись/графу")
    for i, (v1, b1) in enumerate(boxes):
        for v2, b2 in boxes[i + 1:]:
            if b1.intersects(b2):
                problems.append(f"Виды {v1.name!r} и {v2.name!r} перекрываются")
            elif b1.inflate(cfg.view_gap / 2).intersects(b2.inflate(cfg.view_gap / 2)):
                problems.append(f"Виды {v1.name!r} и {v2.name!r} ближе {cfg.view_gap} мм")
    return problems


