# ==================================================================================================================
"""Геометрия линейного размера на листе и проверка конфликтов (чистый Python, без КОМПАСа).

Все величины — мм листа, ось Y вверх. Поддерживаются размеры вдоль осей листа:
`axis="x"` — горизонтальный размер (измеряет расстояние по X, размерная линия горизонтальна),
`axis="y"` — вертикальный.

Модель надписи откалибрована по КОМПАС-3D v26 (spikes/s13–s15):
- рамка надписи из API: вдоль линии `[start, start + w]`, поперёк `[gap, gap + h]` от размерной линии,
  где `w, h = IDimensionText.GetWidth/GetHeight` (мм листа), `gap = 1`;
- горизонтальный размер — надпись над линией, вертикальный — слева от линии (текст читается снизу вверх);
- реальные глифы меньше рамки примерно на 1 мм поперёк и на 0.4 мм вдоль («ink»-рамка — для проверок);
- выносная линия выходит за размерную на 2 мм; надпись «снаружи» ставится в 5 мм от точки,
  размерная линия продлевается под ней ещё на 2 мм.
"""

import math
from dataclasses import dataclass, field
from typing import Hashable, Iterable, Sequence

# из kompas_lib.geom: OBox, Point, Rect, Segment, as_index, collinear_overlap, near, segment_hits_rect, segments_cross

ERROR, WARNING, INFO = "error", "warning", "info"


@dataclass(frozen=True)
class DimStyle:
    text_gap: float = 1.5          # от размерной линии до рамки надписи (рабочее; минимум 1)
    ink_along: float = 0.4         # рамка API больше глифов вдоль линии (с каждой стороны)
    ink_normal: float = 1.0        # ... и поперёк
    ext_overshoot: float = 2.0     # выход выносной линии за размерную
    arrow: float = 5.0             # длина стрелки
    outside_offset: float = 5.0    # надпись снаружи: от точки до надписи
    outside_tail: float = 2.0      # продление размерной линии за надпись
    first_offset: float = 10.0     # ГОСТ 2.307 п.4.4: контур → первая размерная линия, не менее 10 мм
    min_step: float = 8.0          # между параллельными размерными линиями (ГОСТ 2.307 — не менее 7)
    step_clearance: float = 1.5    # от верха глифов до следующей размерной линии
    text_margin: float = 1.0       # надпись внутри: запас до выносной линии с каждой стороны
    tol: float = 0.05
    # Элемент меньше этого на листе (мм) не образмеривается: стрелки и надпись не помещаются, размер нечитаем.
    # Нужен выносной элемент (ГОСТ 2.305) или более крупный масштаб.
    min_feature: float = 2.0

    def step_for(self, text_h: float) -> float:
        """Шаг между ярусами: не меньше 7 мм и не меньше высоты надписи с зазором (округление до 0.5)."""
        ink_top = self.text_gap + text_h - self.ink_normal
        return max(self.min_step, math.ceil((ink_top + self.step_clearance) * 2 - 1e-9) / 2)


@dataclass(frozen=True)
class Issue:
    kind: str
    severity: str
    message: str
    keys: tuple = ()
    details: tuple[str, ...] = ()

    def as_dict(self) -> dict:
        result = {"kind": self.kind, "severity": self.severity, "message": self.message,
                  "keys": [str(k) for k in self.keys]}
        if self.details:
            result["details"] = list(self.details)
        return result


def group_issues(issues):
    """Повторяющиеся предупреждения — одна запись с полным списком деталей."""
    groups={}
    for issue in issues:
        if issue.severity != ERROR:
            groups.setdefault((issue.severity,issue.kind),[]).append(issue)
    result=[]
    emitted=set()
    for issue in issues:
        group=groups.get((issue.severity,issue.kind),[])
        if len(group)<3:
            result.append(issue)
        elif (issue.severity,issue.kind) not in emitted:
            emitted.add((issue.severity,issue.kind))
            keys=tuple(dict.fromkeys(k for i in group for k in i.keys))
            result.append(Issue(issue.kind,issue.severity,f"{issue.message} (всего {len(group)}; см. details)",
                                keys,tuple(i.message for i in group)))
    return result


TEXT_MODES = ("center", "lo", "hi", "manual")


@dataclass
class LinearDim:
    """Линейный размер на листе.

    p1, p2 — точки привязки (на геометрии); line — координата размерной линии (Y для axis="x", X для "y").
    text_mode: center — по центру; lo/hi — снаружи у меньшей/большей точки; manual — начало надписи text_start.
    """
    key: Hashable
    p1: Point
    p2: Point
    axis: str
    line: float
    text_w: float
    text_h: float
    text_mode: str = "center"
    text_start: float | None = None
    label: str = ""
    inside: bool = False            # размерная линия внутри контура (например, Ø на виде вала)
    meta: dict = field(default_factory=dict, compare=False)

    def __post_init__(self) -> None:
        if self.axis not in ("x", "y"):
            raise ValueError(f"axis должен быть 'x' или 'y', а не {self.axis!r}")
        if self.text_mode not in TEXT_MODES:
            raise ValueError(f"text_mode: {self.text_mode!r}")

    # --- координаты вдоль/поперёк -------------------------------------------------------------
    def along(self, p: Point) -> float:
        return p.x if self.axis == "x" else p.y

    def normal(self, p: Point) -> float:
        return p.y if self.axis == "x" else p.x

    def pt(self, along: float, normal: float) -> Point:
        return Point(along, normal) if self.axis == "x" else Point(normal, along)

    def rect(self, a1: float, a2: float, n1: float, n2: float) -> Rect:
        return Rect.of(a1, n1, a2, n2) if self.axis == "x" else Rect.of(n1, a1, n2, a2)

    @property
    def lo(self) -> float:
        return min(self.along(self.p1), self.along(self.p2))

    @property
    def hi(self) -> float:
        return max(self.along(self.p1), self.along(self.p2))

    @property
    def span(self) -> float:
        return self.hi - self.lo

    @property
    def value(self) -> float:
        return self.span

    # --- надпись ------------------------------------------------------------------------------
    def text_range(self, style: DimStyle) -> tuple[float, float]:
        w = self.text_w
        if self.text_start is not None:          # фактическое положение (прочитано из КОМПАСа или задано)
            s = self.text_start
        elif self.text_mode == "lo":
            s = self.lo - style.outside_offset - w
        elif self.text_mode == "hi":
            s = self.hi + style.outside_offset
        else:
            s = (self.lo + self.hi) / 2 - w / 2
        return s, s + w

    def text_box(self, style: DimStyle, ink: bool = False) -> Rect:
        s, e = self.text_range(style)
        n1, n2 = style.text_gap, style.text_gap + self.text_h
        if ink:
            s, e = s + style.ink_along, e - style.ink_along
            n1, n2 = n1 + style.ink_normal, n2 - style.ink_normal
        # горизонтальный — над линией (+Y), вертикальный — слева (−X)
        if self.axis == "x":
            return self.rect(s, e, self.line + n1, self.line + n2)
        return self.rect(s, e, self.line - n2, self.line - n1)

    def text_fits_inside(self, style: DimStyle) -> bool:
        return self.span >= self.text_w + 2 * style.text_margin

    # --- линии --------------------------------------------------------------------------------
    def line_extent(self, style: DimStyle) -> tuple[float, float]:
        lo, hi = self.lo, self.hi
        s, e = self.text_range(style)
        if self.text_mode == "lo":
            lo = min(lo, s - style.outside_tail)
        elif self.text_mode == "hi":
            hi = max(hi, e + style.outside_tail)
        return lo, hi

    def dim_line(self, style: DimStyle) -> Segment:
        lo, hi = self.line_extent(style)
        return Segment(self.pt(lo, self.line), self.pt(hi, self.line))

    def ext_lines(self, style: DimStyle) -> list[Segment]:
        out = []
        for p in (self.p1, self.p2):
            pn = self.normal(p)
            d = self.line - pn
            if abs(d) <= style.tol:
                continue
            end = self.line + math.copysign(style.ext_overshoot, d)
            out.append(Segment(self.pt(self.along(p), pn), self.pt(self.along(p), end)))
        return out

    def segments(self, style: DimStyle) -> list[tuple[str, Segment]]:
        return [("dim", self.dim_line(style))] + [("ext", s) for s in self.ext_lines(style)]

    def bbox(self, style: DimStyle) -> Rect:
        r = self.text_box(style)
        for _, s in self.segments(style):
            r = r.union(s.bbox)
        return r

    def describe(self) -> str:
        name = self.label or f"{self.value:g}"
        return f"«{name}»"


@dataclass
class DiametralDim:
    """Диаметральный размер окружности на листе (полная размерная линия через центр под углом `angle`).

    Надпись лежит вдоль размерной линии; направление чтения КОМПАС выбирает слева направо (при 90° < угол ≤ 270°
    оно противоположно направлению угла). Параметр t — расстояние от центра вдоль направления угла, мм листа.
    text_mode: out — снаружи окружности на продолжении линии (КОМПАС делает сам у малых окружностей),
               manual — центр надписи в t = text_t (внутри окружности).
    """
    key: Hashable
    center: Point
    radius: float                   # мм листа
    angle: float                    # градусы
    text_w: float
    text_h: float
    text_mode: str = "manual"
    text_t: float | None = None
    label: str = ""
    meta: dict = field(default_factory=dict, compare=False)
    axis = None
    inside = True

    @property
    def u(self) -> tuple[float, float]:
        a = math.radians(self.angle)
        return (math.cos(a), math.sin(a))

    @property
    def reading(self) -> tuple[float, float]:
        ux, uy = self.u
        return (ux, uy) if (ux > 1e-9 or (abs(ux) <= 1e-9 and uy > 0)) else (-ux, -uy)

    @property
    def value(self) -> float:
        return 2 * self.radius

    def text_interval(self, style: DimStyle) -> tuple[float, float]:
        """Надпись вдоль u: [t1, t2]."""
        w = self.text_w
        if self.text_t is not None:
            return self.text_t - w / 2, self.text_t + w / 2
        if self.text_mode == "out":
            t1 = self.radius + style.outside_offset
            return t1, t1 + w
        return -w / 2, w / 2

    def text_box(self, style: DimStyle, ink: bool = False):
        t1, t2 = self.text_interval(style)
        d = self.reading
        same = d == self.u
        a1, a2 = (t1, t2) if same else (-t2, -t1)
        n1, n2 = style.text_gap, style.text_gap + self.text_h
        if ink:
            a1, a2 = a1 + style.ink_along, a2 - style.ink_along
            n1, n2 = n1 + style.ink_normal, n2 - style.ink_normal
        return OBox(self.center, d, a1, a2, n1, n2)

    def _at(self, t: float) -> Point:
        ux, uy = self.u
        return Point(self.center.x + t * ux, self.center.y + t * uy)

    def dim_line(self, style: DimStyle) -> Segment:
        t_end = self.radius
        t1, t2 = self.text_interval(style)
        if t2 > self.radius + 1e-6:
            t_end = t2 + style.outside_tail
        return Segment(self._at(-self.radius), self._at(t_end))

    def ext_lines(self, style: DimStyle) -> list[Segment]:
        return []

    def segments(self, style: DimStyle) -> list[tuple[str, Segment]]:
        return [("dim", self.dim_line(style))]

    def bbox(self, style: DimStyle) -> Rect:
        return self.text_box(style).bbox.union(self.dim_line(style).bbox)

    def describe(self) -> str:
        return f"«{self.label or f'Ø{self.value:g}'}»"


# --- конфликты --------------------------------------------------------------------------------
def _pair_name(a: LinearDim, b: LinearDim) -> str:
    return f"{a.describe()} и {b.describe()}"


def dim_conflicts(a: LinearDim, b: LinearDim, style: DimStyle) -> list[Issue]:
    """Конфликты двух размеров между собой."""
    out: list[Issue] = []
    keys = (a.key, b.key)
    ta, tb = OBox.of(a.text_box(style, ink=True)), OBox.of(b.text_box(style, ink=True))
    if ta.intersects(tb):
        out.append(Issue("text_overlap", ERROR, f"Надписи {_pair_name(a, b)} накладываются", keys))
    # 3D-размеры в разных параллельных плоскостях (meta["depth"]) друг друга не пересекают: проверяем только
    # наложение надписей и диаметры на одной линии (на торцевом виде они сливаются).
    layered = ("depth" in a.meta and "depth" in b.meta and
               abs(a.meta["depth"] - b.meta["depth"]) > style.tol)
    if layered:
        if (isinstance(a, DiametralDim) and isinstance(b, DiametralDim) and a.center.dist(b.center) <= style.tol
                and abs((a.angle - b.angle + 90.0) % 180.0 - 90.0) < 1.0):
            out.append(Issue("lines_overlap", ERROR, f"Размерные линии {_pair_name(a, b)} накладываются", keys))
        return out
    sa, sb = a.segments(style), b.segments(style)
    for kind, s in sb:
        if ta.hits_segment(s, style.tol):
            what = "размерная" if kind == "dim" else "выносная"
            out.append(Issue("line_through_text", ERROR,
                             f"{what.capitalize()} линия {b.describe()} пересекает надпись {a.describe()}", keys))
            break
    for kind, s in sa:
        if tb.hits_segment(s, style.tol):
            what = "размерная" if kind == "dim" else "выносная"
            out.append(Issue("line_through_text", ERROR,
                             f"{what.capitalize()} линия {a.describe()} пересекает надпись {b.describe()}", keys))
            break
    # Диаметры концентрических окружностей проходят через общий центр — там пересечение допустимо;
    # недопустимо, когда линии лежат друг на друге (один угол).
    # То же для 3D-диаметров соосных цилиндров (meta["depth"]): в разных плоскостях, но по оси и при переносе
    # на торцевой вид линии под одним углом сливаются в одну — несколько диаметров на одной линии недопустимы.
    concentric = (isinstance(a, DiametralDim) and isinstance(b, DiametralDim) and
                  a.center.dist(b.center) <= style.tol)
    if concentric and abs((a.angle - b.angle + 90.0) % 180.0 - 90.0) < 1.0:
        out.append(Issue("lines_overlap", ERROR, f"Размерные линии {_pair_name(a, b)} накладываются", keys))
    crossed = concentric
    for ka, s1 in sa:
        for kb, s2 in sb:
            if segments_cross(s1, s2, tol=1e-6):
                if ka == "dim" or kb == "dim":
                    if not crossed:
                        out.append(Issue("lines_cross", ERROR,
                                         f"Размерные/выносные линии {_pair_name(a, b)} пересекаются", keys))
                        crossed = True
                else:
                    out.append(Issue("ext_lines_cross", WARNING,
                                     f"Выносные линии {_pair_name(a, b)} пересекаются", keys))
    if a.axis is not None and a.axis == b.axis:
        da, db = a.dim_line(style), b.dim_line(style)
        if collinear_overlap(da, db, tol=style.tol) > style.tol:
            out.append(Issue("lines_overlap", ERROR, f"Размерные линии {_pair_name(a, b)} накладываются", keys))
        else:
            gap = abs(a.line - b.line)
            la, ha = a.line_extent(style)
            lb, hb = b.line_extent(style)
            overlap = min(ha, hb) - max(la, lb)
            if overlap > style.tol and style.tol < gap < style.min_step - style.tol and not (a.inside or b.inside):
                out.append(Issue("too_close", WARNING,
                                 f"Размерные линии {_pair_name(a, b)} ближе {style.min_step:g} мм ({gap:.1f} мм), "
                                 f"ГОСТ 2.307", keys))
    return out


def model_mismatch(d, style: DimStyle) -> float:
    """Насколько фактический габарит объекта (meta["real"], из КОМПАСа) расходится с моделью, мм листа.

    Модель надписи берётся из API (GetTextPosition), а оно иногда возвращает запрошенную точку, хотя КОМПАС
    нарисовал надпись в другом месте (вынес наружу сам). Габарит объекта честный — сверяем с ним.
    Допуск: за модель могут выходить стрелки, вынесенные наружу (стрелка + запас); модель за габарит — 1.5 мм.
    """
    real = d.meta.get("real") if d.meta else None
    if real is None:
        return 0.0
    m = d.bbox(style)
    beyond_model = max(real.x2 - m.x2, m.x1 - real.x1, real.y2 - m.y2, m.y1 - real.y1) - (style.arrow + 2.0)
    beyond_real = max(m.x2 - real.x2, real.x1 - m.x1, m.y2 - real.y2, real.y1 - m.y1) - 1.5
    return max(0.0, beyond_model, beyond_real)


def align_text_to_extent(d: LinearDim, real: Rect, style: DimStyle) -> None:
    """Надпись, которую КОМПАС вынес наружу сам: API отдаёт запрошенную точку, а габарит объекта — фактическую.
    Если габарит уходит вдоль линии дальше модели больше, чем на вынесенные стрелки, надпись — у этого края
    (размерная линия продлена за неё на `outside_tail`)."""
    a1, a2 = (real.x1, real.x2) if d.axis == "x" else (real.y1, real.y2)
    lo, hi = d.line_extent(style)
    s, e = d.text_range(style)
    lo, hi = min(lo, s), max(hi, e)
    slack = style.arrow + 2.0
    if a2 > hi + slack:
        d.text_mode, d.text_start = "hi", a2 - style.outside_tail - d.text_w
    elif a1 < lo - slack:
        d.text_mode, d.text_start = "lo", a1 + style.outside_tail


def geometry_conflicts(d: LinearDim, obstacles: Sequence[Segment], style: DimStyle) -> list[Issue]:
    """Конфликты размера с геометрией вида (контур, осевые, штриховка — всё, что передано отрезками)."""
    out: list[Issue] = []
    miss = model_mismatch(d, style)
    if miss > 0:
        out.append(Issue("model_mismatch", ERROR, f"Размер {d.describe()} нарисован не там, где его показывает API "
                                                  f"(расхождение габарита {miss:.1f} мм) — наложения не проверяемы",
                         (d.key,)))
    tol = style.tol
    ink = OBox.of(d.text_box(style, ink=True))
    if any(ink.hits_segment(s, tol) for s in near(obstacles, ink.bbox, tol)):
        out.append(Issue("text_crossed_by_geometry", ERROR, f"Линии изображения пересекают надпись {d.describe()}",
                         (d.key,)))
    if not d.inside:
        dl = d.dim_line(style)
        if any(segments_cross(dl, s) for s in near(obstacles, dl.bbox, tol)):
            out.append(Issue("dim_line_crosses_geometry", WARNING,
                             f"Размерная линия {d.describe()} пересекает линии изображения", (d.key,)))
    for e in d.ext_lines(style):
        if any(segments_cross(e, s) and collinear_overlap(e, s, tol=tol) <= tol
               for s in near(obstacles, e.bbox, tol)):
            out.append(Issue("ext_line_crosses_geometry", WARNING,
                             f"Выносная линия {d.describe()} пересекает линии изображения", (d.key,)))
            break
    return out


def keepout_conflicts(d: LinearDim, keepouts: Sequence[Rect], style: DimStyle) -> list[Issue]:
    """Размер заходит в запретные зоны (чужие виды, штамп, обозначения): по надписи и по каждой линии."""
    out = []
    text = OBox.of(d.text_box(style, ink=True))
    segs = [s for _, s in d.segments(style)]
    for r in keepouts:
        if text.intersects(r, tol=style.tol) or any(segment_hits_rect(s, r, style.tol) for s in segs):
            out.append(Issue("in_keepout", ERROR, f"Размер {d.describe()} заходит в чужую зону "
                                                  f"(обозначение, другой вид или основная надпись)", (d.key,)))
            break
    return out


def check_dims(dims: Sequence[LinearDim], obstacles: Sequence[Segment] = (), keepouts: Sequence[Rect] = (),
               style: DimStyle | None = None) -> list[Issue]:
    """Все конфликты набора размеров (попарно + с геометрией + с запретными зонами)."""
    style = style or DimStyle()
    obstacles = as_index(obstacles)
    out: list[Issue] = []
    for i, a in enumerate(dims):
        out += geometry_conflicts(a, obstacles, style)
        out += keepout_conflicts(a, keepouts, style)
        for b in dims[i + 1:]:
            out += dim_conflicts(a, b, style)
    return out


def count(issues: Iterable[Issue]) -> tuple[int, int]:
    """(ошибки, предупреждения)."""
    e = w = 0
    for i in issues:
        if i.severity == ERROR:
            e += 1
        elif i.severity == WARNING:
            w += 1
    return e, w


# ==================================================================================================================
# === 32/55 kompas_lib.dims.stacking — kompas_lib/dims/stacking.py
# ==================================================================================================================
"""Стороны и ярусы внешних линейных размеров без пересечений «размерная × выносная» (чистый Python).

Модель (одна ось, одна сторона изображения). Размер — интервал [lo, hi] вдоль оси, его размерная линия —
на ярусе t (0 — ближайший к контуру). Выносная линия размера A в точке x пересекает размерную линию B,
если x строго внутри (B.lo, B.hi) и A дальше от контура, чем B. Отсюда для пары размеров:

- вложены (концы A внутри B) — A обязан стоять ближе: t(A) < t(B);
- не пересекаются или стыкуются (цепочка) — ограничений нет, можно в один ярус;
- частично перекрываются — на одной стороне без пересечения невозможно ни при каких ярусах.

Значит, стороны — это раскраска графа частичных перекрытий (граф пересечений-перекрытий интервалов,
circle graph) в 2 цвета: чистая раскладка на две противоположные стороны существует тогда и только тогда,
когда граф двудольный. Ярусы на стороне — длиннейший путь в DAG вложенности: минимально возможное число.

Из 2^k ориентаций компонент связности выбирается та, у которой меньше суммарная длина выносных линий
(от точки до размерной линии): она учитывает и близость стороны к элементу, и глубину ярусов —
одна физическая величина вместо набора весов (ср. Kakoulis et al., IJMMT 2023: «как можно ближе к
элементу», «минимум длины выносных линий»).

Пересечения с геометрией, надписями и запретными зонами здесь не решаются — это делает раскладчик
(`plan.py`), получая сторону и нижнюю границу яруса как первый вариант.
"""

from dataclasses import dataclass
from typing import Hashable, Sequence

# из kompas_lib.geom: Point, Rect

OPPOSITE = {"top": "bottom", "bottom": "top", "left": "right", "right": "left"}
SIDE_PAIR = {"x": ("top", "bottom"), "y": ("right", "left")}


@dataclass
class Span:
    """Внешний размер для раскладки: интервал вдоль оси и точки привязки (мм листа)."""
    key: Hashable
    axis: str
    lo: float
    hi: float
    points: tuple[Point, ...]
    side: str | None = None          # задана заранее (явная сторона или уже стоящий размер) — не меняется
    label: str = ""


def inside(x: float, s: Span, tol: float) -> bool:
    return s.lo + tol < x < s.hi - tol


def partial(a: Span, b: Span, tol: float) -> bool:
    """Частичное перекрытие: у каждого конец строго внутри другого (не вложены, не стык, не равны)."""
    return ((inside(b.lo, a, tol) or inside(b.hi, a, tol)) and
            (inside(a.lo, b, tol) or inside(a.hi, b, tol)))


def nested_in(a: Span, b: Span, tol: float) -> bool:
    """Выносная линия b пересечёт размерную a, если b дальше: конец b строго внутри a, но не перекрытие."""
    return (inside(b.lo, a, tol) or inside(b.hi, a, tol)) and not partial(a, b, tol)


def tiers(spans: Sequence[Span], tol: float) -> dict:
    """Минимальные ярусы на одной стороне: t(a) > t(b) для всех b, чей конец внутри a."""
    out: dict = {}
    for a in sorted(spans, key=lambda s: s.hi - s.lo):
        out[a.key] = 1 + max((out[b.key] for b in spans if b.key in out and b is not a and nested_in(a, b, tol)),
                             default=-1)
    return out


def _ext_length(s: Span, side: str, tier: int, content: Rect, first: float, step: float) -> float:
    """Суммарная длина выносных линий размера s на стороне side, ярусе tier."""
    line = {"top": content.y2 + first + tier * step, "bottom": content.y1 - first - tier * step,
            "right": content.x2 + first + tier * step, "left": content.x1 - first - tier * step}[side]
    coord = (lambda p: p.y) if side in ("top", "bottom") else (lambda p: p.x)
    return sum(abs(line - coord(p)) for p in s.points)


@dataclass
class Stacking:
    sides: dict                      # key -> сторона
    tiers: dict                      # key -> минимальный ярус
    conflicts: list                  # пары ключей частично перекрытых размеров, оставшихся на одной стороне


def stack(spans: Sequence[Span], content: Rect, first: float, step: float, tol: float = 0.05,
          max_flip_rounds: int = 4) -> Stacking:
    """Стороны и минимальные ярусы для размеров одной оси.

    Компоненты графа частичных перекрытий красятся BFS; компонента с заданной стороной хотя бы у одного
    размера ориентирована однозначно, свободные — перебираются локальным поиском (переворот компоненты),
    пока уменьшается суммарная длина выносных линий. Недвудольная компонента (нечётный цикл) красится
    с минимумом конфликтов по BFS; конфликты возвращаются — их нужно устранять выбором размеров.
    """
    if not spans:
        return Stacking({}, {}, [])
    axis = spans[0].axis
    pos, neg = SIDE_PAIR[axis]
    n = len(spans)
    adj = [[j for j in range(n) if j != i and partial(spans[i], spans[j], tol)] for i in range(n)]

    color: dict[int, int] = {}
    comps: list[list[int]] = []
    for s0 in sorted(range(n), key=lambda i: spans[i].side is None):     # сначала заданные стороны
        if s0 in color:
            continue
        color[s0] = 0 if spans[s0].side in (None, pos) else 1
        comp, queue = [s0], [s0]
        while queue:
            u = queue.pop(0)
            for w in adj[u]:
                if w not in color:
                    fixed = spans[w].side
                    color[w] = (0 if fixed == pos else 1) if fixed else 1 - color[u]
                    comp.append(w)
                    queue.append(w)
        comps.append(comp)

    free = [c for c in comps if all(spans[i].side is None for i in c)]

    def sides_of(flip: set[int]) -> dict:
        out = {}
        for ci, comp in enumerate(comps):
            f = ci in flip
            for i in comp:
                out[i] = spans[i].side or (pos if color[i] ^ f == 0 else neg)
        return out

    def evaluate(flip: set[int]) -> tuple[float, dict, dict]:
        side = sides_of(flip)
        tier: dict = {}
        for s in (pos, neg):
            tier.update(tiers([spans[i] for i in range(n) if side[i] == s], tol))
        cost = sum(_ext_length(spans[i], side[i], tier[spans[i].key], content, first, step) for i in range(n))
        return cost, side, tier

    flip: set[int] = set()
    for ci, comp in enumerate(comps):
        if comp in free:
            a = sum(_ext_length(spans[i], pos if color[i] == 0 else neg, 0, content, first, step) for i in comp)
            b = sum(_ext_length(spans[i], neg if color[i] == 0 else pos, 0, content, first, step) for i in comp)
            if b < a:
                flip.add(ci)
    best = evaluate(flip)
    free_ids = [ci for ci, comp in enumerate(comps) if comp in free]
    for _ in range(max_flip_rounds):
        improved = False
        for ci in free_ids:
            trial = flip ^ {ci}
            res = evaluate(trial)
            if res[0] < best[0] - 1e-9:
                flip, best, improved = trial, res, True
        if not improved:
            break
    _, side, tier = best
    conflicts = [(spans[i].key, spans[j].key) for i in range(n) for j in adj[i] if i < j and side[i] == side[j]]
    return Stacking({spans[i].key: side[i] for i in range(n)}, tier, conflicts)

try:
    from ortools.sat.python import cp_model as _cp_model
    _ORTOOLS = True
except ImportError:  # noqa: BLE001
    _ORTOOLS = False


def stack_exact(spans: Sequence[Span], content: Rect, first: float, step: float, tol: float = 0.05,
                max_tiers: int = 12, time_limit: float = 1.0):
    """Точная раскладка сторон и ярусов через CP-SAT (OR-Tools); None — нет решателя или не сошёлся.

    Переменные: сторона (pos/neg) и ярус каждого размера. Жёстко: заданные стороны; вложенность на одной
    стороне (внешний ярусом дальше). Мягко (штраф BIG): частично перекрывающиеся на одной стороне.
    Цель — минимум суммарной длины выносных линий + штрафы. Нечётный цикл перекрытий не делает задачу
    неразрешимой: нарушители остаются в conflicts — их устраняет выбор размеров, а не раскладка.
    """
    if not spans or not _ORTOOLS:
        return None
    axis = spans[0].axis
    pos, neg = SIDE_PAIR[axis]
    n = len(spans)
    max_tiers = max(max_tiers, n)
    edge = {"top": content.y2, "bottom": content.y1, "right": content.x2, "left": content.x1}
    S = 100  # CP-SAT целочисленный: сотые мм

    def coords(s: Span, side: str) -> tuple[int, int]:
        c = [(p.y if side in ("top", "bottom") else p.x) for p in s.points]
        base = edge[side] + first if side in ("top", "right") else edge[side] - first
        # длина выносных = n*(base + tier*step) - sum либо sum - n*(base - tier*step): линейна по ярусу
        if side in ("top", "right"):
            return round((len(c) * base - sum(c)) * S), round(len(c) * step * S)
        return round((sum(c) - len(c) * base) * S), round(len(c) * step * S)

    m = _cp_model.CpModel()
    side = [m.NewBoolVar(f"s{i}") for i in range(n)]          # False — pos, True — neg
    tier = [m.NewIntVar(0, max_tiers - 1, f"t{i}") for i in range(n)]
    for i, s in enumerate(spans):
        if s.side == pos:
            m.Add(side[i] == 0)
        elif s.side == neg:
            m.Add(side[i] == 1)
    cost_terms = []
    for i, s in enumerate(spans):
        c_pos, k_pos = coords(s, pos)
        c_neg, k_neg = coords(s, neg)
        c = m.NewIntVar(-10 ** 12, 10 ** 12, f"c{i}")
        cp = m.NewIntVar(-10 ** 12, 10 ** 12, f"cp{i}")
        cn = m.NewIntVar(-10 ** 12, 10 ** 12, f"cn{i}")
        m.Add(cp == c_pos + k_pos * tier[i])
        m.Add(cn == c_neg + k_neg * tier[i])
        m.Add(c == cp).OnlyEnforceIf(side[i].Not())
        m.Add(c == cn).OnlyEnforceIf(side[i])
        cost_terms.append(c)
    BIG = 10 ** 9
    conflicts: list[tuple[int, int]] = []
    for i in range(n):
        for j in range(i + 1, n):
            if partial(spans[i], spans[j], tol):
                pen = m.NewBoolVar(f"p{i}_{j}")
                m.Add(side[i] + side[j] == 1).OnlyEnforceIf(pen.Not())
                cost_terms.append(pen * BIG)
                conflicts.append((i, j))
            elif nested_in(spans[i], spans[j], tol):
                same = m.NewBoolVar(f"e{i}_{j}")
                m.Add(side[i] == side[j]).OnlyEnforceIf(same)
                m.Add(side[i] != side[j]).OnlyEnforceIf(same.Not())
                m.Add(tier[i] >= tier[j] + 1).OnlyEnforceIf(same)
            elif nested_in(spans[j], spans[i], tol):
                same = m.NewBoolVar(f"e{j}_{i}")
                m.Add(side[i] == side[j]).OnlyEnforceIf(same)
                m.Add(side[i] != side[j]).OnlyEnforceIf(same.Not())
                m.Add(tier[j] >= tier[i] + 1).OnlyEnforceIf(same)
    m.Minimize(sum(cost_terms))
    solver = _cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = time_limit
    status = solver.Solve(m)
    if status not in (_cp_model.OPTIMAL, _cp_model.FEASIBLE):
        return None
    sides = {spans[i].key: (neg if solver.Value(side[i]) else pos) for i in range(n)}
    tiers = {spans[i].key: solver.Value(tier[i]) for i in range(n)}
    bad = [(spans[i].key, spans[j].key) for i, j in conflicts if sides[spans[i].key] == sides[spans[j].key]]
    return Stacking(sides, tiers, bad)


class TwoSides:
    """Инкрементальная проверка: можно ли развести набор интервалов одной оси на две стороны.

    `add` принимает интервал, только если граф частичных перекрытий остаётся двудольным
    (DSU с чётностью: соседи по перекрытию — в разных цветах). Порядок вызовов — приоритет.
    """

    def __init__(self, tol: float = 1e-3) -> None:
        self.tol = tol
        self.spans: list[Span] = []
        self.parent: dict = {}
        self.parity: dict = {}

    def _find(self, x):
        if self.parent[x] == x:
            return x, 0
        root, p = self._find(self.parent[x])
        self.parent[x], self.parity[x] = root, self.parity[x] ^ p
        return root, self.parity[x]

    def conflicts(self, key: Hashable, lo: float, hi: float) -> list:
        """Ключи интервалов, с которыми новый замкнёт нечётный цикл (пусто — можно добавить)."""
        new = Span(key, "x", lo, hi, ())
        need: dict = {}
        bad = []
        for s in self.spans:
            if partial(s, new, self.tol):
                root, p = self._find(s.key)
                if need.setdefault(root, p ^ 1) != p ^ 1:
                    bad.append(s.key)
        return bad

    def add(self, key: Hashable, lo: float, hi: float) -> bool:
        if self.conflicts(key, lo, hi):
            return False
        new = Span(key, "x", lo, hi, ())
        self.parent[key], self.parity[key] = key, 0
        for s in self.spans:
            if partial(s, new, self.tol):
                (ra, pa), (rb, pb) = self._find(s.key), self._find(key)
                if ra != rb:
                    self.parent[rb], self.parity[rb] = ra, pa ^ pb ^ 1
        self.spans.append(new)
        return True


# ==================================================================================================================
# === 33/55 kompas_lib.dims.plan — kompas_lib/dims/plan.py
# ==================================================================================================================
"""Раскладка размеров вокруг изображения без пересечений (чистый Python).

Правила (ГОСТ 2.307-2011, п. 4.4–4.6 и практика):
- первая размерная линия — не ближе `first_offset` (10 мм) к контуру, между параллельными — не менее
  `min_step` (8 мм; ГОСТ — не менее 7) и не менее высоты надписи с зазором;
- меньшие размеры — ближе к контуру, большие — дальше (иначе выносные линии большего пересекут меньший);
- цепочки (общие точки) встают в один ярус;
- надпись по центру; если мешает — в ближайший свободный промежуток вдоль линии, затем вынос наружу;
- для `side="inside"` размерная линия задаётся явно (`at`) — например, диаметр на изображении вала.

Поиск без перебора по миллиметрам:
- положения надписи вдоль линии берутся из краёв занятых интервалов (геометрия, чужие линии и надписи,
  запретные зоны), а не сдвигом по 1 мм;
- кандидаты оцениваются по модели (`shapes.py`) — это микросекунды;
- `realize` (адаптер CAD: ставит размер и возвращает фактическое положение) вызывается только для лучших
  по модели кандидатов, не более `max_realize` раз на размер. Если КОМПАС поставил надпись иначе и появились
  конфликты — пробуется следующий кандидат.

Планировщик ничего не решает за конструктора: что образмерить — решает вызывающий,
здесь — только «куда поставить, чтобы ничего не пересекалось».
"""

import math
from dataclasses import dataclass, field, replace
from typing import Callable, Hashable, Iterable, Iterator, Sequence

# из kompas_lib.geom: OBox, Point, Rect, Segment, as_index, near
# из kompas_lib.dims.stacking: Span, stack, stack_exact
# из kompas_lib.dims.shapes: ERROR, WARNING, DiametralDim, DimStyle, Issue, LinearDim, count, dim_conflicts, geometry_conflicts, keepout_conflicts

SIDES_X = ("top", "bottom")     # горизонтальные размеры
SIDES_Y = ("right", "left")     # вертикальные
DIAM_ANGLES = (45.0, 135.0, 225.0, 315.0, 30.0, 60.0, 120.0, 150.0, 210.0, 240.0, 300.0, 330.0)
FREE_GAP = 0.5                  # зазор надписи до занятого интервала, мм листа
LINE_GRID = 12                  # не больше стольких положений линии внутри at_range


@dataclass
class DimRequest:
    """Запрос на размер (координаты — мм листа)."""
    p1: Point
    p2: Point
    axis: str                       # "x" | "y"
    text_w: float
    text_h: float
    key: Hashable = None
    side: str = "auto"              # auto | top | bottom | left | right | inside
    at: float | None = None         # координата размерной линии; обязательна для inside
    label: str = ""
    at_range: tuple[float, float] | None = None

    def span(self) -> tuple[float, float]:
        c = (self.p1.x, self.p2.x) if self.axis == "x" else (self.p1.y, self.p2.y)
        return min(c), max(c)


@dataclass
class DiamRequest:
    """Диаметральный размер окружности (мм листа)."""
    center: Point
    radius: float
    text_w: float
    text_h: float
    key: Hashable = None
    angle: float | None = None      # None — подобрать
    label: str = ""
    outer_radius: float | None = None   # расстояние до внешнего контура всего изображения
    meta: dict = field(default_factory=dict)   # переносится в варианты (например, depth 3D-размера)


@dataclass
class DimPlan:
    dims: list
    issues: list[Issue] = field(default_factory=list)
    sides: dict = field(default_factory=dict)      # key -> сторона
    tiers: dict = field(default_factory=dict)      # key -> номер яруса (0 — ближайший к контуру)
    step: float = 0.0
    realized: int = 0                              # вызовов CAD (для замеров)

    @property
    def ok(self) -> bool:
        return not any(i.severity == ERROR for i in self.issues)


# --- положения размерной линии ---------------------------------------------------------------------
def _base(side: str, content: Rect, r: DimRequest) -> tuple[float, int]:
    """Координата края изображения со стороны `side` и направление наружу."""
    ns = [r.p1.y, r.p2.y] if r.axis == "x" else [r.p1.x, r.p2.x]
    if side == "top":
        return max(content.y2, *ns), 1
    if side == "bottom":
        return min(content.y1, *ns), -1
    if side == "right":
        return max(content.x2, *ns), 1
    return min(content.x1, *ns), -1


def _dim_sides(r: DimRequest, content: Rect) -> list[str]:
    if r.side not in ("auto", "inside"):
        allowed = SIDES_X if r.axis == "x" else SIDES_Y
        if r.side not in allowed:
            raise ValueError(f"Сторона {r.side!r} не подходит для размера по оси {r.axis!r}: {allowed}")
        return [r.side]
    if r.axis == "x":
        return ["top", "bottom"] if (r.p1.y + r.p2.y) / 2 >= content.center.y else ["bottom", "top"]
    return ["right", "left"] if (r.p1.x + r.p2.x) / 2 >= content.center.x else ["left", "right"]


def _fixed_lines(r: DimRequest, style: DimStyle) -> list[tuple[str, int, float]]:
    """Явная линия (`at`) или сетка не более LINE_GRID положений внутри `at_range`, ближние к `at` — первыми."""
    if r.at_range is None:
        return [(r.side if r.side != "auto" else "fixed", 0, r.at)]
    lo, hi = sorted(r.at_range)
    room = style.text_gap + r.text_h - style.ink_normal + style.tol
    if r.axis == "x":
        hi -= room
    else:
        lo += room
    if lo > hi:
        return [(r.side, 0, r.at)]
    preferred = min(hi, max(lo, r.at))
    n = max(1, min(LINE_GRID, math.ceil(hi - lo)))
    values = dict.fromkeys([preferred, *(lo + (hi - lo) * i / n for i in range(n + 1))])
    return [(r.side, 0, v) for v in sorted(values, key=lambda v: abs(v - preferred))]


def _lines(r: DimRequest, content: Rect, style: DimStyle, step: float, max_tiers: int,
           hint: tuple[str, int] | None = None) -> list[tuple[str, int, float]]:
    """(сторона, ярус, координата линии) в порядке предпочтения.

    С подсказкой `hint` (сторона и минимальный ярус из `stacking.stack`) — сначала эта сторона от яруса
    подсказки наружу: ближе ставить нельзя (выносные вложенных размеров пересекут линию), на другой стороне
    размер частично перекроется с соседями. Затем — прочие положения как запасные (если мешает геометрия).
    Без подсказки: ближние ярусы обеих сторон, затем дальние — лучше перенести размер на другую сторону,
    чем уводить его далеко от изображения."""
    if r.at is not None:
        return _fixed_lines(r, style)
    out = []
    sides = _dim_sides(r, content)
    if hint is not None and hint[0] in sides:
        side, t0 = hint
        sides = [side] + [s for s in sides if s != side]
        base, sign = _base(side, content, r)
        out += [(side, k, base + sign * (style.first_offset + k * step)) for k in range(min(t0, max_tiers - 1),
                                                                                     max_tiers)]
    near_tiers = min(3, max_tiers)
    for block in (range(0, near_tiers), range(near_tiers, max_tiers)):
        for side in sides:
            base, sign = _base(side, content, r)
            out += [(side, k, base + sign * (style.first_offset + k * step)) for k in block]
    return list(dict.fromkeys(out))


# --- свободные места вдоль линии -------------------------------------------------------------------
class _Scene:
    """Всё, что занимает лист вокруг размера: линии изображения, запретные зоны, уже поставленные размеры."""

    def __init__(self, obstacles, keepouts: Sequence[Rect], style: DimStyle) -> None:
        self.obstacles, self.keepouts, self.style = obstacles, list(keepouts), style

    def blockers(self, region: Rect, placed: Sequence) -> tuple[list[Segment], list[list[Point]]]:
        st = self.style
        segs = list(near(self.obstacles, region))
        polys = [OBox.of(k).corners() for k in self.keepouts if k.intersects(region)]
        for p in placed:
            if p.bbox(st).intersects(region):
                segs += [s for _, s in p.segments(st)]
                polys.append(OBox.of(p.text_box(st, ink=True)).corners())
        return segs, polys


def _blocked(to_local: Callable[[Point], tuple[float, float]], band: tuple[float, float],
             segs: Iterable[Segment], polys: Iterable[Sequence[Point]]) -> list[tuple[float, float]]:
    """Занятые интервалы вдоль линии в полосе надписи band = (n1, n2) (локальные координаты (вдоль, поперёк))."""
    n1, n2 = band
    out = []
    for s in segs:
        (a1, m1), (a2, m2) = to_local(s.a), to_local(s.b)
        if abs(m2 - m1) < 1e-12:
            if n1 < m1 < n2:
                out.append((min(a1, a2), max(a1, a2)))
            continue
        t1, t2 = sorted(((n1 - m1) / (m2 - m1), (n2 - m1) / (m2 - m1)))
        t1, t2 = max(t1, 0.0), min(t2, 1.0)
        if t1 < t2:
            b1, b2 = a1 + (a2 - a1) * t1, a1 + (a2 - a1) * t2
            out.append((min(b1, b2), max(b1, b2)))
    for corners in polys:
        loc = [to_local(p) for p in corners]
        if min(m for _, m in loc) < n2 and max(m for _, m in loc) > n1:
            out.append((min(a for a, _ in loc), max(a for a, _ in loc)))
    return out


def _free_starts(lo: float, hi: float, w: float, ink: float, preferred: float,
                 blocked: Sequence[tuple[float, float]]) -> list[float]:
    """Начала надписи шириной w в [lo, hi], свободные от занятых интервалов; ближние к `preferred` — первыми.
    Кандидаты — края занятых интервалов (плюс зазор), а не сетка."""
    if hi < lo - 1e-9:
        return []
    cands = {min(hi, max(lo, preferred)), lo, hi}
    for b1, b2 in blocked:
        cands.add(b2 - ink + FREE_GAP)
        cands.add(b1 - w + ink - FREE_GAP)

    def free(s: float) -> bool:
        return all(b2 <= s + ink or b1 >= s + w - ink for b1, b2 in blocked)

    return sorted((s for s in cands if lo - 1e-9 <= s <= hi + 1e-9 and free(s)),
                  key=lambda s: (abs(s - preferred), s))


# --- варианты надписи ------------------------------------------------------------------------------
def _text_variants(d: LinearDim, style: DimStyle, scene: _Scene | None = None, placed: Sequence = (),
                   outside_first: str = "hi") -> Iterator[LinearDim]:
    """Варианты надписи в порядке предпочтения: центр, свободные промежутки вдоль линии, снаружи."""
    fits = d.text_fits_inside(style)
    w = d.text_w
    lo_lim, hi_lim = d.lo + style.text_margin, d.hi - style.text_margin - w
    center = (d.lo + d.hi) / 2 - w / 2
    if fits:
        if d.inside:
            # Диаметр на продольном виде: надпись в верхней/нижней половине, свободной от осевой.
            mid = (d.lo + d.hi) / 2
            for t in ((mid + d.hi) / 2, (d.lo + mid) / 2):
                s = t - w / 2
                if lo_lim <= s <= hi_lim:
                    yield replace(d, text_mode="manual", text_start=s)
        yield replace(d, text_mode="center", text_start=None)
        if scene is not None:
            probe = d.text_box(style, ink=True)
            band = (probe.y1, probe.y2) if d.axis == "x" else (probe.x1, probe.x2)
            region = d.rect(d.lo, d.hi, *band)
            blocked = _blocked(lambda p: (d.along(p), d.normal(p)), band, *scene.blockers(region, placed))
            for s in _free_starts(lo_lim, hi_lim, w, style.ink_along, center, blocked):
                if abs(s - center) > 1e-6:
                    yield replace(d, text_mode="manual", text_start=s)
    for mode in (outside_first, "lo" if outside_first == "hi" else "hi"):
        yield replace(d, text_mode=mode, text_start=None)
    if not fits and d.inside:
        yield replace(d, text_mode="center", text_start=None)


def _diam_variants(r: DiamRequest, key: Hashable, style: DimStyle, scene: _Scene | None = None,
                   placed: Sequence = ()) -> Iterator[DiametralDim]:
    """Варианты: угол линии × положение надписи. Малая окружность — надпись снаружи (как делает КОМПАС),
    большая — внутри, в свободном промежутке вдоль линии (не на центре, где оси), затем снаружи."""
    angles = [r.angle] if r.angle is not None else list(DIAM_ANGLES)
    small = 2 * r.radius < r.text_w + 2 * style.arrow
    w = r.text_w
    beyond = r.outer_radius is not None and r.outer_radius > r.radius
    for a in angles:
        base = DiametralDim(key, r.center, r.radius, a, w, r.text_h, label=r.label, meta=dict(r.meta))
        if not small:
            t_hi, t_lo = r.radius - style.arrow - w / 2, w / 2      # центр надписи вдоль линии
            if t_hi >= t_lo:
                probe = replace(base, text_mode="manual", text_t=0.0)
                box = probe.text_box(style, ink=True)
                sign = 1 if probe.reading == probe.u else -1        # координата вдоль надписи a = sign·t
                ts = [t_hi]
                if scene is not None:
                    band = (box.n1, box.n2)
                    region = OBox(box.o, box.d, -r.radius, r.radius, *band).bbox
                    blocked = _blocked(lambda p: (box.local(p).x, box.local(p).y), band, *scene.blockers(region, placed))
                    a_lo, a_hi = sorted((sign * t_lo, sign * t_hi))
                    ts += [sign * (s + w / 2) for s in
                           _free_starts(a_lo - w / 2, a_hi - w / 2, w, style.ink_along, sign * t_hi - w / 2, blocked)]
                for t in dict.fromkeys(round(t, 6) for t in ts):
                    yield replace(base, text_mode="manual", text_t=t)
            yield replace(base, text_mode="manual", text_t=0.0)
        yield replace(base, text_mode="out")
        if beyond:
            yield replace(base, text_mode="out", text_t=r.outer_radius + style.outside_offset + w / 2)


# --- выбор -----------------------------------------------------------------------------------------
def _evaluate(d, placed: Sequence, obstacles, keepouts: Sequence[Rect], style: DimStyle) -> list[Issue]:
    issues = geometry_conflicts(d, obstacles, style) + keepout_conflicts(d, keepouts, style)
    for p in placed:
        issues += dim_conflicts(d, p, style)
    return issues


def _select(variants: Iterable[tuple], evaluate: Callable, realize: Callable | None, max_realize: int):
    """Лучший вариант: (meta, размер, замечания).

    Без `realize` — первый чистый по модели, иначе лучший по (ошибки, предупреждения, порядок).
    С `realize` — в CAD ставятся только чистые по модели кандидаты (по порядку) до первого чистого факта;
    если таких нет, — лучшие по модели. Всего не более `max_realize` вызовов CAD на размер.
    """
    best = None
    scored = []
    budget = max_realize
    tried = set()

    def attempt(n, meta, cand) -> bool:
        nonlocal best, budget
        tried.add(n)
        budget -= 1
        actual = realize(cand)
        issues = evaluate(actual)
        score = (*count(issues), n)
        if best is None or score < best[0]:
            best = (score, meta, actual, issues)
        return score[:2] == (0, 0)

    for n, (meta, cand) in enumerate(variants):
        issues = evaluate(cand)
        score = (*count(issues), n)
        if realize is None:
            if best is None or score < best[0]:
                best = (score, meta, cand, issues)
            if score[:2] == (0, 0):
                break
            continue
        scored.append((score, meta, cand))
        if score[:2] == (0, 0) and budget > 0 and attempt(n, meta, cand):
            return best[1:]
    if realize is not None:
        for score, meta, cand in sorted(scored, key=lambda x: x[0]):
            if budget <= 0 or (best is not None and best[0][:2] == (0, 0)):
                break
            if score[2] not in tried and attempt(score[2], meta, cand):
                break
    return best[1:] if best is not None else None


# --- стороны и ярусы --------------------------------------------------------------------------------
def _stacking_hints(linear: Sequence[tuple[int, DimRequest]], fixed: Sequence, content: Rect, style: DimStyle,
                    step: float) -> tuple[dict, list]:
    """Сторона и минимальный ярус каждого внешнего линейного размера (точный `stacking.stack_exact`,
    запасной — эвристический `stacking.stack`) по осям.

    Уже стоящие размеры (`fixed`) входят в граф с известной стороной: новый размер, частично перекрытый
    с ними, уходит на противоположную. Размеры с явной линией (`at`, inside) в граф не входят.
    Короткий размер с надписью снаружи входит эффективным интервалом (линия продлевается за надпись):
    иначе его продлённая линия пересечёт размерные линии дальних размеров на любом ярусе.
    """
    hints: dict = {}
    conflicts: list = []
    for axis in ("x", "y"):
        reqs = [(i, r) for i, r in linear if r.axis == axis and r.at is None and r.side != "inside"]
        ends = [e for _, r in reqs for e in r.span()]
        spans = []
        for i, r in reqs:
            lo, hi = r.span()
            if hi - lo < r.text_w + 2 * style.text_margin:
                # надпись не помещается внутри: продление линии в сторону выноса (как outside_first в раскладке)
                joins_hi = any(abs(e - hi) <= style.tol for e in ends)
                joins_lo = any(abs(e - lo) <= style.tol for e in ends)
                tail = r.text_w + style.outside_offset + style.outside_tail
                if joins_hi and not joins_lo:
                    lo -= tail
                else:
                    hi += tail
            spans.append(Span(r.key if r.key is not None else i, axis, lo, hi, (r.p1, r.p2),
                              side=None if r.side == "auto" else r.side, label=r.label))
        if not spans:
            continue
        for n, d in enumerate(fixed):
            if not isinstance(d, LinearDim) or d.axis != axis or d.inside:
                continue
            if axis == "x":
                side = "top" if d.line > content.y2 - style.tol else "bottom" if d.line < content.y1 + style.tol else None
            else:
                side = "right" if d.line > content.x2 - style.tol else "left" if d.line < content.x1 + style.tol else None
            if side is not None:
                spans.append(Span(("fixed", n), axis, d.lo, d.hi, (d.p1, d.p2), side=side, label=d.label))
        res = stack_exact(spans, content, style.first_offset, step, style.tol)
        if res is None:
            res = stack(spans, content, style.first_offset, step, style.tol)
        own = {s.key for s in spans if not (isinstance(s.key, tuple) and s.key[:1] == ("fixed",))}
        hints.update({k: (res.sides[k], res.tiers[k]) for k in own})
        conflicts += [(a, b) for a, b in res.conflicts if a in own or b in own]
    return hints, conflicts


# --- раскладка -------------------------------------------------------------------------------------
def plan_dimensions(requests: Sequence[DimRequest | DiamRequest], content: Rect, obstacles: Sequence[Segment] = (),
                    fixed: Sequence = (), keepouts: Sequence[Rect] = (),
                    style: DimStyle | None = None, max_tiers: int = 8,
                    realize=None, max_realize: int = 8) -> DimPlan:
    """Разложить размеры вокруг изображения `content` (габарит контура, мм листа).

    obstacles — линии изображения (контур, осевые) отрезками; fixed — уже стоящие размеры (не двигаются);
    keepouts — зоны, куда размерам нельзя (чужие виды, штамп, обозначения).
    Порядок: диаметральные (привязаны к окружностям), затем линейные с заданной линией, затем внешние
    по возрастанию длины.
    """
    style = style or DimStyle()
    plan = DimPlan([], step=style.step_for(max((r.text_h for r in requests), default=7.0)))
    if realize is not None:
        cad, cache = realize, {}

        def realize(d):
            sig = ((d.key, d.line, d.text_mode, d.text_start) if isinstance(d, LinearDim)
                   else (d.key, d.angle, d.text_mode, d.text_t))
            if sig not in cache:
                plan.realized += 1
                cache[sig] = cad(d)
            return cache[sig]
    obstacles = as_index(obstacles)           # сетка: каждый вариант проверяется только с ближними отрезками
    scene = _Scene(obstacles, keepouts, style)
    placed: list = list(fixed)

    def evaluator(state):
        return lambda d: _evaluate(d, state, obstacles, keepouts, style)

    for i, r in enumerate(requests):
        if isinstance(r, DiamRequest):
            key = r.key if r.key is not None else i
            _, d, issues = _select(((None, c) for c in _diam_variants(r, key, style, scene, placed)),
                                   evaluator(placed), realize, max_realize)
            placed.append(d)
            plan.dims.append(d)
            plan.sides[key], plan.tiers[key] = f"{d.angle:g}°", 0
            plan.issues += issues

    linear = [(i, r) for i, r in enumerate(requests) if isinstance(r, DimRequest)]
    hints, conflicts = _stacking_hints(linear, fixed, content, style, plan.step)
    for a, b in conflicts:
        plan.issues.append(Issue("dims_overlap_same_side", WARNING,
                                 f"Размеры {a!r} и {b!r} частично перекрываются и не разводятся на две стороны "
                                 f"(нечётный цикл перекрытий): пересечение выносной и размерной линий неизбежно — "
                                 f"измените набор размеров (общая база, цепочка)", (a, b)))
    max_tiers = max(max_tiers, 2 + max((t for _, t in hints.values()), default=0))

    def order(ir: tuple[int, DimRequest]) -> tuple:
        i, r = ir
        lo, hi = r.span()
        enclosing = any(q is not r and q.axis == r.axis and lo - style.tol <= q.span()[0] and
                        q.span()[1] <= hi + style.tol and q.span()[1] - q.span()[0] < hi - lo - style.tol
                        for _, q in linear)
        explicit = r.side == "inside" or r.at is not None
        tier = hints.get(r.key if r.key is not None else i, ("", 0))[1]
        return (0 if explicit else 1, tier, enclosing, hi - lo < r.text_w + 2 * style.text_margin, hi - lo, i)

    def outside_first(r: DimRequest) -> str:
        # Короткое первое звено цепочки выносим к началу цепи, иначе его продлённая линия
        # перекроет выносные соседних звеньев на любом ярусе.
        lo, hi = r.span()
        ends = [e for _, q in linear if q is not r and q.axis == r.axis for e in q.span()]
        joins_hi = any(abs(e - hi) <= style.tol for e in ends)
        joins_lo = any(abs(e - lo) <= style.tol for e in ends)
        return "lo" if joins_hi and not joins_lo else "hi"

    def proto(i, r) -> LinearDim:
        return LinearDim(r.key if r.key is not None else i, r.p1, r.p2, r.axis, 0.0, r.text_w, r.text_h,
                         label=r.label, inside=(r.side == "inside"))

    def variants(i, r, state, first: str = "hi") -> Iterator[tuple]:
        base = proto(i, r)
        hint = hints.get(base.key)
        for side, tier, line in _lines(r, content, style, plan.step, max_tiers, hint):
            for d in _text_variants(replace(base, line=line), style, scene, state, outside_first=first):
                yield (side, tier), d
    def _exact_choice(items, skip=()) -> dict | None:
        """Совместный точный выбор кандидатов всех линейных размеров (CP-SAT), чисто по модели.

        Жадная поочерёдная раскладка может не найти существующую чистую раскладку; здесь каждому размеру
        назначается по одному кандидату сразу с минимумом суммарных нарушений (ошибка 10000,
        предупреждение 50, длина выносных, вынос надписи наружу, квадрат яруса ×10 — глубокие стеки
        дороже, X-позиции предпочитают низ (+15 за верх, габарит сверху не трогается)). None — нет решателя
        """
        try:
            from ortools.sat.python import cp_model
        except ImportError:  # noqa: BLE001
            return None
        cand: dict = {}
        axis_of: dict = {}
        for i, r, key in items:
            if key in skip:
                continue
            first = outside_first(r)
            hint_side = hints.get(key, (None, 0))[0]
            lines, others = [], 0
            for n, (s, t, ln) in enumerate(_lines(r, content, style, plan.step, max_tiers, hints.get(key))):
                if n < 4:
                    lines.append((s, t, ln))
                elif s != hint_side and t <= 2 and others < 4:
                    lines.append((s, t, ln))
                    others += 1
                if len(lines) >= 8:
                    break
            base = proto(i, r)
            ds = []
            for s, t, ln in lines:
                n_same = 0
                for d in _text_variants(replace(base, line=ln), style, scene, (), outside_first=first):
                    ds.append(((s, t), d))
                    n_same += 1
                    if n_same >= 4:
                        break
            if ds:
                cand[key] = ds
                axis_of[key] = r.axis
        if not cand:
            return None
        m = cp_model.CpModel()
        xs: dict = {}
        terms: list = []
        boxes: dict = {}
        for k, ds in cand.items():
            xs[k] = [m.NewBoolVar(f"x{len(xs):02d}_{j}") for j in range(len(ds))]
            m.Add(sum(xs[k]) == 1)
            for j, (meta, d) in enumerate(ds):
                boxes[(k, j)] = d.bbox(style)
                e, w = count(_evaluate(d, [], obstacles, keepouts, style))
                ext = abs(d.line - d.normal(d.p1)) + abs(d.line - d.normal(d.p2))
                side, tier = meta
                axis = axis_of[k]
                terms.append((xs[k][j], e * 10000 + w * 50 + round(ext * 2) +
                              (0 if d.text_mode in ("center", "manual") else 5) +
                              tier * tier * 10 + (15 if axis == "x" and side == "top" else 0)))
        keys = list(cand)
        for a in range(len(keys)):
            for b in range(a + 1, len(keys)):
                ka, kb = keys[a], keys[b]
                for ja, (_, da) in enumerate(cand[ka]):
                    for jb, (_, db) in enumerate(cand[kb]):
                        if not boxes[(ka, ja)].intersects(boxes[(kb, jb)]):
                            continue
                        e, w = count(dim_conflicts(da, db, style))
                        if e or w:
                            pen = m.NewBoolVar(f"p{a}_{b}_{ja}_{jb}")
                            m.Add(pen >= xs[ka][ja] + xs[kb][jb] - 1)
                            terms.append((pen, e * 10000 + w * 50))
        m.Minimize(sum(v * c for v, c in terms))
        solver = cp_model.CpSolver()
        solver.parameters.max_time_in_seconds = 2.0
        if solver.Solve(m) not in (cp_model.OPTIMAL, cp_model.FEASIBLE):
            return None
        return {k: cand[k][next(j for j, v in enumerate(xs[k]) if solver.Value(v))] for k in keys}

    runnable = []
    for i, r in linear:
        key = r.key if r.key is not None else i
        if r.side == "inside" and r.at is None:
            plan.issues.append(Issue("no_position", ERROR, f"Для размера {proto(i, r).describe()} с side='inside' "
                                     f"нужна координата размерной линии at", (key,)))
            continue
        runnable.append((i, r, key))
    exact = _exact_choice(runnable)
    banned: dict = {}
    seq = sorted(runnable, key=lambda t: order((t[0], t[1])))
    if exact is not None:
        # сброс неразмещаемого: цепочка/базовая, участвующая в ошибках, уходит из набора
        # (жёлтое примечание конструктору), красных наложений быть не должно. Габариты, формы,
        # ряды и пары не сбрасываются. Итераций не больше трёх: каждая — чистый пересчёт без CAD.

        def model_issues(choice):
            state, out = list(fixed), []
            for _i, _r, k in seq:
                if k not in choice:
                    continue
                out += _evaluate(choice[k][1], state, obstacles, keepouts, style)
                state.append(choice[k][1])
            return out

        for _ in range(3):
            str2key = {str(k): k for k in exact}
            bad: dict = {}
            for issue in model_issues(exact):
                if issue.severity != ERROR:
                    continue
                for k in issue.keys:
                    ks = str(k)
                    if (ks.startswith("chain_") or ks.startswith("pos_")) \
                            and ":pitch" not in ks and ":pair" not in ks and ks in str2key:
                        bad[ks] = bad.get(ks, 0) + 1
            if not bad:
                break
            victim = sorted(bad.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
            banned[str2key[victim]] = exact[str2key[victim]][1].describe()
            plan.issues.append(Issue("dim_dropped", WARNING,
                                     f"Размер {banned[str2key[victim]]} не размещён без наложений — "
                                     f"вынесите вручную или выносным элементом", (str2key[victim],)))
            nxt = _exact_choice(runnable, skip=set(banned))
            if nxt is None:
                break
            exact = nxt
    if exact is None:
        for i, r, key in runnable:
            (side, tier), d, issues = _select(variants(i, r, placed, outside_first(r)), evaluator(placed),
                                              realize, max_realize)
            placed.append(d)
            plan.dims.append(d)
            plan.sides[key], plan.tiers[key] = side, tier
            plan.issues += issues
    else:
        for i, r, key in seq:
            if key not in exact:
                if key in banned:
                    plan.issues.append(Issue("dim_dropped", WARNING,
                                             f"Размер {banned[key]} не размещён без наложений — "
                                             f"вынесите вручную или выносным элементом", (key,)))
                    continue
                (side, tier), d, issues = _select(variants(i, r, placed, outside_first(r)),
                                                  evaluator(placed), realize, max_realize)
                placed.append(d)
                plan.dims.append(d)
                plan.sides[key], plan.tiers[key] = side, tier
                plan.issues += issues
                continue
            (side, tier), d = exact[key]
            actual = realize(d) if realize is not None else d
            issues = evaluator(placed)(actual)
            if realize is not None and any(x.severity == ERROR for x in issues):
                # CAD поставил иначе, чем просили (надпись переехала): добрать этот размер
                # жадно с проверкой фактического положения, как в старом проходе.
                (side2, tier2), actual2, issues2 = _select(variants(i, r, placed, outside_first(r)),
                                                          evaluator(placed), realize, max_realize)
                if count(issues2) < count(issues):
                    (side, tier), actual, issues = (side2, tier2), actual2, issues2
            placed.append(actual)
            plan.dims.append(actual)
            plan.sides[key], plan.tiers[key] = side, tier
            plan.issues += issues
        # проверка факта: CAD мог поставить иначе, чем просили. Нарушителя чиним жадно
        # с проверкой фактического положения; нечинящееся — вон из набора (add_dimensions удалит
        # объект из CAD). Не больше двух кругов: каждый — только по нарушителям.
        lin_keys = {key for _, _, key in seq}
        for _ in range(2):
            ctx = list(fixed) + [d for d in plan.dims if d.key not in lin_keys]
            joint: list = []
            st = list(ctx)
            for d in [d for d in plan.dims if d.key in lin_keys]:
                joint += evaluator(st)(d)
                st.append(d)
            bad2: dict = {}
            for issue in joint:
                if issue.severity != ERROR:
                    continue
                for k in issue.keys:
                    ks = str(k)
                    if (ks.startswith("chain_") or ks.startswith("pos_")) \
                            and ":pitch" not in ks and ":pair" not in ks:
                        bad2[ks] = bad2.get(ks, 0) + 1
            if not bad2:
                break
            victim = sorted(bad2.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
            req = next((t for t in seq if str(t[2]) == victim), None)
            mended = False
            if req is not None and realize is not None:
                i, r, key = req
                others = [d for d in plan.dims if d.key != key]
                (s2, t2), a2, i2 = _select(variants(i, r, others, outside_first(r)),
                                           evaluator(others), realize, max_realize)
                if not any(x.severity == ERROR for x in i2):
                    plan.dims = [a2 if d.key == key else d for d in plan.dims]
                    plan.sides[key], plan.tiers[key] = s2, t2
                    mended = True
            if not mended and req is not None:
                i, r, key = req
                lbl = next((d.describe() for d in plan.dims if d.key == key), str(key))
                plan.dims = [d for d in plan.dims if d.key != key]
                plan.sides.pop(key, None)
                plan.tiers.pop(key, None)
                plan.issues.append(Issue("dim_dropped", WARNING,
                                         f"Размер {lbl} не размещён без наложений — "
                                         f"вынесите вручную или выносным элементом", (key,)))

    if any(i.severity == ERROR for i in plan.issues) and not any(i.kind == "no_position" for i in plan.issues):
        _repair(plan, linear, fixed, variants, evaluator, realize)
    return plan




def _repair(plan: DimPlan, linear, fixed: Sequence, variants, evaluator, realize, rounds: int = 3) -> None:
    """Жадная раскладка может запереть короткое звено за продлённой линией соседнего.

    Локальный поиск по модели: каждый линейный размер, участвующий в ошибке, ставится в лучшее положение при
    неподвижных остальных — пока ошибок становится меньше. В отличие от поиска «все без ошибок» не сдаётся,
    если одна ошибка неустранима. В CAD ставятся только переставленные размеры.
    """
    requests = {(r.key if r.key is not None else i): (i, r) for i, r in linear}
    dims = list(plan.dims)
    moved = set()

    def issues_of(ds):
        state, out = list(fixed), []
        for d in ds:
            out += evaluator(state)(d)
            state.append(d)
        return out

    for _ in range(rounds):
        bad = {k for issue in issues_of(dims) if issue.severity == ERROR for k in issue.keys} & set(requests)
        improved = False
        for idx, current in enumerate(dims):
            if current.key not in bad:
                continue
            others = list(fixed) + dims[:idx] + dims[idx + 1:]
            evaluate = evaluator(others)
            now = count(evaluate(current))
            best = None
            for n, (meta, d) in enumerate(variants(*requests[current.key], others)):
                score = (*count(evaluate(d)), n)
                if best is None or score < best[0]:
                    best = (score, meta, d)
            if best is not None and best[0][0] < now[0]:
                dims[idx] = best[2]
                plan.sides[current.key], plan.tiers[current.key] = best[1]
                moved.add(current.key)
                improved = True
        if not improved:
            break
    if not moved:
        return
    if realize is not None:
        dims = [realize(d) if d.key in moved else d for d in dims]
    plan.dims, plan.issues = dims, issues_of(dims)


