# === 34/55 kompas_lib.dims.graph — kompas_lib/dims/graph.py
# ==================================================================================================================
"""Граф координат одной оси: общая модель выбора, отсечения лишних и проверки полноты размеров (чистый Python).

ГОСТ 2.307: размеров — минимум, но достаточно; без повторов и замкнутых цепей. Формально по каждой оси модели:
узлы — координаты (плоские грани, оси цилиндров), размер — связь узлов. Набор полный и без лишних тогда и
только тогда, когда связи образуют остовный лес на обязательных узлах: всё связано, циклов нет.

Связь может объединять больше двух узлов:
- обычный размер — 2 узла;
- равношаговый ряд «N×шаг=L» — все N+1 центров одним размером;
- межосевой размер пары, симметричной относительно плоскости симметрии детали, — оба узла и виртуальный узел
  симметрии; он считается привязанным, как только определён габарит, симметричный той же плоскости.

Связь допустима, если все её узлы — в разных компонентах (иначе она что-то определяет повторно — замкнутая цепь).
"""

from dataclasses import dataclass, field
from typing import Hashable, Iterable, Sequence


@dataclass(frozen=True)
class Symmetry:
    """Плоскость симметрии детали вдоль оси: координата m и симметричные крайние узлы (габарит) lo, hi."""
    m: float
    lo: float
    hi: float


class AxisGraph:
    """Координаты одной оси со склейкой по допуску и система непересекающихся множеств со связями."""

    def __init__(self, tol: float = 1e-3, symmetries: Sequence[Symmetry] = ()) -> None:
        self.tol = tol
        self.coords: list[float] = []
        self.parent: list[int] = []
        self.links: list[tuple[Hashable, tuple[int, ...]]] = []
        self.symmetries = list(symmetries)
        self._sym_nodes = {s: self._new_node(None) for s in self.symmetries}

    # --- узлы ----------------------------------------------------------------------------------
    def _new_node(self, c: float | None) -> int:
        self.coords.append(c if c is not None else float("nan"))
        self.parent.append(len(self.parent))
        return len(self.parent) - 1

    def node(self, c: float) -> int:
        for i, x in enumerate(self.coords):
            if abs(x - c) <= self.tol:
                return i
        return self._new_node(c)

    def find(self, i: int) -> int:
        while self.parent[i] != i:
            self.parent[i] = self.parent[self.parent[i]]
            i = self.parent[i]
        return i

    def connected(self, a: float, b: float) -> bool:
        return self.find(self.node(a)) == self.find(self.node(b))

    # --- связи ---------------------------------------------------------------------------------
    def symmetry_of(self, a: float, b: float) -> Symmetry | None:
        """Плоскость симметрии, относительно которой a и b симметричны (межосевой размер пары)."""
        for s in self.symmetries:
            if abs((a + b) / 2 - s.m) <= self.tol and abs(a - b) > self.tol:
                return s
        return None

    def _ids(self, coords: Sequence[float], symmetric: bool) -> list[int]:
        ids = list(dict.fromkeys(self.node(c) for c in coords))
        if symmetric and len(coords) == 2:
            s = self.symmetry_of(*coords)
            if s is not None:
                ids.append(self._sym_nodes[s])
        return ids

    def conflicts(self, coords: Sequence[float], symmetric: bool = False) -> list[Hashable]:
        """Ключи связей, с которыми связь `coords` замкнула бы цепь (пусто — связь допустима)."""
        ids = self._ids(coords, symmetric)
        roots: dict[int, int] = {}
        clash = []
        for i in ids:
            r = self.find(i)
            if r in roots:
                clash.append((roots[r], i))
            roots.setdefault(r, i)
        if not clash or len(ids) < 2:
            return [] if len(ids) >= 2 else ["degenerate"]
        return [k for u, v in clash for k in self.path(u, v)] or ["implicit"]

    def can_link(self, coords: Sequence[float], symmetric: bool = False) -> bool:
        ids = self._ids(coords, symmetric)
        return len(ids) >= 2 and len({self.find(i) for i in ids}) == len(ids)

    def link(self, coords: Sequence[float], key: Hashable, symmetric: bool = False) -> bool:
        """Добавить связь, если она ничего не определяет повторно."""
        if not self.can_link(coords, symmetric):
            return False
        ids = self._ids(coords, symmetric)
        for i in ids[1:]:
            self.parent[self.find(i)] = self.find(ids[0])
        self.links.append((key, tuple(ids)))
        self._close_symmetries()
        return True

    def _close_symmetries(self) -> None:
        # Плоскость симметрии определена, когда определён симметричный ей габарит.
        changed = True
        while changed:
            changed = False
            for s, n in self._sym_nodes.items():
                lo, hi = self.find(self.node(s.lo)), self.find(self.node(s.hi))
                if lo == hi and self.find(n) != lo:
                    self.parent[self.find(n)] = lo
                    self.links.append((None, (n, self.node(s.lo))))
                    changed = True

    def path(self, u: int, v: int) -> list[Hashable]:
        """Ключи связей на пути между узлами (для сообщения о замкнутой цепи)."""
        adj: dict[int, list[tuple[int, Hashable]]] = {}
        for key, ids in self.links:
            for i in ids[1:]:
                adj.setdefault(ids[0], []).append((i, key))
                adj.setdefault(i, []).append((ids[0], key))
        prev: dict[int, tuple[int, Hashable] | None] = {u: None}
        queue = [u]
        while queue:
            x = queue.pop(0)
            if x == v:
                break
            for y, k in adj.get(x, []):
                if y not in prev:
                    prev[y] = (x, k)
                    queue.append(y)
        keys: list[Hashable] = []
        x = v
        while prev.get(x) is not None:
            px, k = prev[x]  # type: ignore[misc]
            if k is not None:
                keys.append(k)
            x = px
        return list(dict.fromkeys(keys))

    def groups(self, coords: Iterable[float]) -> list[list[float]]:
        """Обязательные координаты, разбитые по компонентам (больше одной группы — что-то не привязано)."""
        out: dict[int, list[float]] = {}
        for c in coords:
            out.setdefault(self.find(self.node(c)), []).append(c)
        return sorted(out.values(), key=len, reverse=True)


@dataclass
class Link:
    """Кандидат-связь для выбора: узлы оси модели, стоимость и то, как её поставить (payload)."""
    axis: int
    coords: tuple[float, ...]
    cost: float
    kind: str = "position"          # overall | size | position | pitch | pair
    key: Hashable = None
    payload: object = None
    forced: bool = False            # обязательна (габарит, размер элемента): ставится первой
    symmetric: bool = False


@dataclass
class Selection:
    chosen: list[Link] = field(default_factory=list)
    redundant: list[Link] = field(default_factory=list)     # обязательные, но лишние (уже определены другими)
    unlocated: dict = field(default_factory=dict)           # ось -> группы не привязанных координат


def spanning_forest(required: dict[int, Iterable[float]], candidates: Sequence[Link], tol: float = 1e-3,
           symmetries: dict[int, Sequence[Symmetry]] | None = None, existing: Sequence[Link] = (),
           accept=None) -> Selection:
    """Минимальный остовный лес (Краскал) на обязательных узлах каждой оси.

    Порядок: уже стоящие размеры, затем обязательные связи, затем связи признаков (ряды, пары),
    затем остальные по возрастанию стоимости. Связь берётся, если все её узлы в разных компонентах
    `accept(link)` разрешает её (например, проверка раскладки на две стороны). Связи с узлами вне
    обязательных не используются, кроме обязательных (габарит, размер элемента).
    """
    symmetries = symmetries or {}
    graphs = {ax: AxisGraph(tol, symmetries.get(ax, ())) for ax in required}
    req_ids = {ax: {graphs[ax].node(c) for c in cs} for ax, cs in required.items()}
    sel = Selection()
    for link in existing:
        if link.axis in graphs:
            graphs[link.axis].link(link.coords, link.key, link.symmetric)
    order = sorted(candidates, key=lambda c: (not c.forced, c.kind not in ("pitch", "pair"), c.cost))
    for link in order:
        g = graphs.get(link.axis)
        if g is None:
            continue
        if not link.forced and not all(g.node(c) in req_ids[link.axis] for c in link.coords):
            continue
        if not g.can_link(link.coords, link.symmetric):
            if link.forced:
                sel.redundant.append(link)
            continue
        if accept is not None and not accept(link):
            continue
        g.link(link.coords, link.key, link.symmetric)
        sel.chosen.append(link)
    for ax, cs in required.items():
        grp = graphs[ax].groups(list(cs))
        if len(grp) > 1:
            sel.unlocated[ax] = grp[1:]
    return sel


# ==================================================================================================================
# === 35/55 kompas_lib.dims.redundancy — kompas_lib/dims/redundancy.py
# ==================================================================================================================
"""Проверка состава размеров: лишние (дубликаты, замкнутые цепи) и недостающие (чистый Python).

ГОСТ 2.307-2011:
- общее количество размеров — минимальное, но достаточное для изготовления и контроля;
- не допускается повторять размеры одного элемента на разных изображениях (кроме справочных);
- не допускается замкнутая размерная цепь, кроме случая, когда один из размеров указан как справочный («*»).

Модель: для каждой оси модели (0=X, 1=Y, 2=Z) строится граф — узлы это координаты вдоль оси
(торцы, уступы, оси отверстий), рёбра это линейные размеры. Тогда
- дубликат — два ребра между одними и теми же узлами;
- замкнутая цепь — цикл; число лишних размеров = рёбра − (узлы − компоненты);
- недостающий размер — обязательный узел (плоская грань, ось отверстия), не связанный с остальными.
Диаметр (Ø) — два ребра «край — ось — край» одного размера; плюс это размер элемента (цилиндра):
два Ø одного цилиндра — дубликат, даже если на разных видах.
Справочные размеры в проверку цепей не входят.

Решение «какой размер убрать или сделать справочным» остаётся за вызывающим: здесь — только диагностика.
"""

from dataclasses import dataclass, field
from typing import Hashable, Sequence

# из kompas_lib.dims.graph: AxisGraph, Symmetry
# из kompas_lib.dims.shapes: ERROR, INFO, WARNING, Issue

AXES = "XYZ"


@dataclass
class DimFact:
    """Размер в координатах модели."""
    key: Hashable
    axis: int                       # ось модели, вдоль которой измеряется (0, 1, 2)
    a: float                        # координаты концов вдоль оси
    b: float
    diameter: bool = False          # Ø: a и b — края, ось цилиндра посередине
    cyl_axis: int | None = None     # для Ø: ось цилиндра (обычно известна из вида)
    center: dict = field(default_factory=dict)  # для Ø: известные координаты оси цилиндра {ось: значение}
    reference: bool = False         # справочный («*»)
    label: str = ""
    count: int = 1                   # число отверстий в надписи группы
    view: int | None = None
    extra: tuple = ()                # ещё узлы, связанные этим размером (центры равношагового ряда «N×шаг=L»)
    radial: bool = False             # радиус R (a, b — края по оси, как у Ø): задаёт размер, ничего не привязывает

    @property
    def value(self) -> float:
        return abs(self.b - self.a)

    def describe(self) -> str:
        if self.label:
            return f"«{self.label}»"
        return f"«{'Ø' if self.diameter else ''}{self.value:g}»"


@dataclass
class Requirement:
    """Что должно быть определено размерами (из модели)."""
    nodes: dict = field(default_factory=dict)       # ось -> {координата: описание}
    cylinders: list = field(default_factory=list)   # (ось цилиндра, радиус, {ось: координата оси}, описание)
    patterns: list = field(default_factory=list)    # HolePattern: одно требование на весь массив
    features: list = field(default_factory=list)    # (axis, a, b, описание): паз и пр.
    annotations: list[str] = field(default_factory=list)
    overalls: list = field(default_factory=list)     # (axis, a, b, diameter, description)
    holes: list = field(default_factory=list)
    radii: list = field(default_factory=list)        # (ось, радиус, {ось: координата оси}, описание): неполные цилиндры
    symmetries: dict = field(default_factory=dict)   # ось -> [graph.Symmetry]: плоскости симметрии детали


class _Nodes:
    """Узлы оси: координаты, склеенные с допуском."""

    def __init__(self, tol: float) -> None:
        self.tol = tol
        self.coords: list[float] = []

    def get(self, c: float) -> int:
        for i, x in enumerate(self.coords):
            if abs(x - c) <= self.tol:
                return i
        self.coords.append(c)
        return len(self.coords) - 1


class _Forest:
    def __init__(self) -> None:
        self.parent: dict[int, int] = {}
        self.adj: dict[int, list[tuple[int, Hashable]]] = {}

    def find(self, x: int) -> int:
        self.parent.setdefault(x, x)
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def path(self, u: int, v: int) -> list[Hashable]:
        """Ключи рёбер на пути u→v в лесе (BFS)."""
        prev: dict[int, tuple[int, Hashable] | None] = {u: None}
        queue = [u]
        while queue:
            x = queue.pop(0)
            if x == v:
                break
            for y, k in self.adj.get(x, []):
                if y not in prev:
                    prev[y] = (x, k)
                    queue.append(y)
        keys: list[Hashable] = []
        x = v
        while prev.get(x) is not None:
            px, k = prev[x]  # type: ignore[misc]
            keys.append(k)
            x = px
        return keys

    def add(self, u: int, v: int, key: Hashable) -> bool:
        """Добавить ребро; False — если оно замыкает цикл (тогда не добавляется)."""
        ru, rv = self.find(u), self.find(v)
        if ru == rv:
            return False
        self.parent[ru] = rv
        self.adj.setdefault(u, []).append((v, key))
        self.adj.setdefault(v, []).append((u, key))
        return True


def _same_cylinder(f: DimFact, g: DimFact, tol: float) -> bool:
    if f.cyl_axis is not None and g.cyl_axis is not None and f.cyl_axis != g.cyl_axis:
        return False
    if abs(f.value - g.value) > tol:
        return False
    for ax, c in f.center.items():
        if ax in g.center and abs(g.center[ax] - c) > tol:
            return False
    return True


def check_redundancy(facts: Sequence[DimFact], required: Requirement | None = None,
                     tol: float = 1e-3, annotations: Sequence[str] = ()) -> list[Issue]:
    """Дубликаты, замкнутые цепи, недостающие размеры."""
    out: list[Issue] = []
    by_key = {f.key: f for f in facts}
    active = [f for f in facts if not f.reference]

    # --- дубликаты --------------------------------------------------------------------------
    dup_of: dict[Hashable, Hashable] = {}
    for i, f in enumerate(active):
        for g in active[:i]:
            if g.key in dup_of:
                continue
            if f.diameter and g.diameter:
                same = _same_cylinder(f, g, tol)
            elif f.diameter or g.diameter:
                same = False
            else:
                same = f.axis == g.axis and {round(f.a / tol), round(f.b / tol)} == {round(g.a / tol), round(g.b / tol)}
            if same:
                dup_of[f.key] = g.key
                out.append(Issue("duplicate", ERROR,
                                 f"Размер {f.describe()} повторяет {g.describe()} (ГОСТ 2.307: не повторять размеры "
                                 f"одного элемента; оставьте один или пометьте справочным «*»)", (f.key, g.key)))
                break

    # --- замкнутые цепи (общий граф координат, как при выборе размеров: graph.AxisGraph) -------
    symmetries = required.symmetries if required is not None else {}
    graphs = {ax: AxisGraph(tol, symmetries.get(ax, ())) for ax in range(3)}
    for f in active:
        if f.key in dup_of or f.radial:
            continue
        g = graphs[f.axis]
        coords = (f.a, (f.a + f.b) / 2, f.b) if f.diameter else (f.a, f.b, *f.extra)
        if len({g.node(c) for c in coords}) < 2:
            continue
        if not g.can_link(coords, symmetric=not f.diameter):
            cycle = [k for k in g.conflicts(coords, symmetric=not f.diameter) if k in by_key and k != f.key]
            members = [by_key[k] for k in cycle] + [f]
            text = " + ".join(m.describe() for m in members[:-1]) + f" и {f.describe()}" if cycle else \
                f"{f.describe()} (определён симметрией и габаритом)"
            out.append(Issue("closed_chain", ERROR,
                             f"Замкнутая размерная цепь по оси {AXES[f.axis]}: {text}. Один размер лишний — "
                             f"удалите его или пометьте справочным «*» (ГОСТ 2.307)",
                             tuple(m.key for m in members)))
            continue
        g.link(coords, f.key, symmetric=not f.diameter)

    # --- полнота ----------------------------------------------------------------------------
    if required is not None:
        for ax, req in required.nodes.items():
            if not req:
                continue
            groups = graphs[ax].groups(list(req))
            if len(groups) > 1:
                main = groups[0]
                for grp in groups[1:]:
                    names = ", ".join(f"{AXES[ax]}={c:g} ({req[c]})" for c in sorted(grp))
                    out.append(Issue("not_located", WARNING,
                                     f"Положение не определено размерами относительно {AXES[ax]}={main[0]:g}…: {names}",
                                     ()))
        same: dict[tuple, int] = {}
        for cyl_axis, radius, _, _ in required.cylinders:
            k = (cyl_axis, round(radius / tol))
            same[k] = same.get(k, 0) + 1
        for cyl_axis, radius, center, desc in required.cylinders:
            probe = DimFact("_", 0, 0.0, 2 * radius, diameter=True, cyl_axis=cyl_axis, center=dict(center))
            n = same[(cyl_axis, round(radius / tol))]
            # «N отв. ØD» задаёт все N одинаковых отверстий (ГОСТ 2.307: размер одинаковых элементов — один раз)
            group = any(f.diameter and f.count > 1 and f.count == n and f.cyl_axis == cyl_axis and
                        abs(f.value - 2 * radius) <= tol for f in facts)
            if not group and not any(f.diameter and _same_cylinder(probe, f, tol) for f in facts):
                out.append(Issue("size_missing", WARNING, f"Не задан диаметр Ø{2 * radius:g}: {desc}", ()))
        seen_r: set = set()
        for cyl_axis, radius, center, desc in required.radii:
            k = round(radius / tol)
            if k in seen_r:
                continue
            # одинаковые скругления — один размер на группу; торец паза — ширина паза 2R
            if any(f.diameter and abs(f.value - 2 * radius) <= tol for f in facts) or \
               any(not f.diameter and abs(f.value - 2 * radius) <= tol for f in facts):
                seen_r.add(k)
                continue
            seen_r.add(k)
            out.append(Issue("size_missing", WARNING, f"Не задан радиус R{radius:g}: {desc}", ()))
        for pattern in required.patterns:
            radial = [j for j in range(3) if j != pattern.axis]
            size = any(f.diameter and f.cyl_axis == pattern.axis and abs(f.value-2*pattern.radius)<=tol and
                       f.count == pattern.count and all(abs(f.center.get(j,float("inf"))-p[i])<=tol
                       for i,j in enumerate(radial)) for p in pattern.centers for f in facts)
            pitch = DimFact("_", radial[0], 0, 2*pattern.pitch_radius, diameter=True,
                            cyl_axis=pattern.axis, center=dict(zip(radial,pattern.center)))
            located = any(f.diameter and _same_cylinder(pitch,f,tol) for f in facts)
            if not (size and located):
                missing = []
                if not size: missing.append(f"{pattern.count} отв. Ø{2*pattern.radius:g}")
                if not located: missing.append(f"Ø{2*pattern.pitch_radius:g} окружности центров")
                out.append(Issue("pattern_missing",WARNING,"Круговой массив: не заданы "+", ".join(missing),()))
        for axis, a, b, description in required.features:
            if not any(not f.diameter and f.axis == axis and
                       ((abs(f.a-a)<=tol and abs(f.b-b)<=tol) or (abs(f.a-b)<=tol and abs(f.b-a)<=tol))
                       for f in facts):
                out.append(Issue("feature_missing", WARNING, f"Не задан размер: {description}", ()))
        for label in required.annotations:
            if label not in annotations:
                out.append(Issue("annotation_missing", WARNING, f"Не оформлено: {label}", ()))
        for axis, a, b, diameter, description in required.overalls:
            if not any(f.diameter == diameter and (f.cyl_axis == axis if diameter else f.axis == axis) and
                       abs(f.value-abs(b-a)) <= tol for f in facts):
                out.append(Issue("overall_missing", WARNING,
                                 f"Не задан габарит: {description} ({abs(b-a):g} мм)", ()))
        for hole in required.holes:
            radial = [j for j in range(3) if j != hole.axis]
            probe = DimFact('_', radial[0], 0, 2*hole.radius, diameter=True,
                            cyl_axis=hole.axis, center=dict(zip(radial, hole.center)))
            sizes = [f for f in facts if f.diameter and f.count == 1 and _same_cylinder(probe, f, tol)]
            depths = [f for f in facts if not f.diameter and f.axis == hole.axis and
                      abs(min(f.a, f.b)-hole.t1) <= tol and abs(max(f.a, f.b)-hole.t2) <= tol and
                      any(j in f.center for j in radial) and
                      all(abs(f.center[j]-probe.center[j]) <= tol for j in radial if j in f.center)]
            if sizes and depths and not any(a.view == b.view for a in sizes for b in depths):
                out.append(Issue('element_views', WARNING,
                    f"Диаметр Ø{2*hole.radius:g} и глубина отверстия разнесены на разные изображения; "
                    "предпочтителен вид, где элемент показан наиболее полно (ГОСТ 2.307)",
                    tuple(f.key for f in sizes+depths)))
    return out


def requirement_from_faces(faces: Sequence, tol: float = 1e-3) -> tuple[Requirement, list[Issue]]:
    """Что должно быть определено, по граням модели (`model.Face`).

    - плоская грань, перпендикулярная оси модели → её координата — обязательный узел;
    - цилиндр (вал или отверстие) → его диаметр и положение оси по двум другим осям.
    Конусы (фаски), торы, сферы и наклонные плоскости — пока не проверяются (сообщается в info).
    """
    req = Requirement(nodes={0: {}, 1: {}, 2: {}})
    # из kompas_lib.dims.features: hole_patterns, recognize_gear, recognize_features
    # из kompas_lib.dims.revolution: revolution_profile, is_groove
    gear = recognize_gear(faces,tol)
    profile = revolution_profile(faces,tol) if gear is None else None
    omitted = set(gear.faces) if gear else set()
    features = recognize_features(faces, tol)
    req.holes = features.holes
    body = features.profile or features.body_profile
    if body:
        req.overalls.append((body.axis, body.t_min, body.t_max, False, "полная длина детали"))
        if body.outer:
            radius = max(s.r for s in body.outer)
            req.overalls.append((body.axis,
                                 -radius, radius, True, "наибольший наружный диаметр"))
    elif faces:
        for axis in range(3):
            lo = min((f.box.x1, f.box.y1, f.box.z1)[axis] for f in faces)
            hi = max((f.box.x2, f.box.y2, f.box.z2)[axis] for f in faces)
            if hi-lo > tol:
                req.overalls.append((axis, lo, hi, False, f"габарит по {AXES[axis]}"))
    for keyway in features.keyways:
        omitted.update(keyway.faces)
        center = (features.profile or features.body_profile).center
        c = center[keyway.width_axis]
        req.features.append((keyway.width_axis, c-keyway.width/2, c+keyway.width/2,
                             f"ширина шпоночного паза b={keyway.width:g}"))
        req.features.append((keyway.axis, keyway.t1, keyway.t2,
                             f"длина шпоночного паза l={keyway.length:g}"))
        sign = 1 if keyway.bottom > center[keyway.depth_axis] else -1
        opposite = center[keyway.depth_axis]-sign*keyway.radius
        req.features.append((keyway.depth_axis, opposite, keyway.bottom,
                             f"глубина шпоночного паза t={'2' if keyway.inner else '1'}={keyway.depth:g}"))
        req.nodes[keyway.axis].update({keyway.t1:"начало шпоночного паза",keyway.t2:"конец шпоночного паза"})
    def fmt(v):
        return f"{round(v, 3):g}".replace('.', ',')
    for chamfer in features.chamfers:
        count = f"{len(chamfer.faces)} фаски " if len(chamfer.faces)>1 else ""
        req.annotations.append(f"{count}{fmt(chamfer.size)}×{fmt(chamfer.angle)}°")
    info = []
    if gear:
        radial=[j for j in range(3) if j!=gear.axis]
        req.cylinders.append((gear.axis,gear.outside_radius,dict(zip(radial,gear.center)),"наружный диаметр венца da"))
        req.nodes[gear.axis].update({gear.t1:"торец венца",gear.t2:"торец венца"})
        info.append(Issue("gear_parameters",INFO,f"Венец z={gear.teeth}: таблица параметров (m, z, …), ГОСТ 2.403",()))
    if profile or gear:
        _flat_patterns = flat_patterns
        axis = profile.axis if profile else gear.axis
        center = profile.center if profile else dict(zip(radial,gear.center))
        req.patterns=hole_patterns(faces,axis,center,tol)
        if not req.patterns and gear is None:
            req.patterns = _flat_patterns(faces, tol)
        omitted.update(i for p in req.patterns for i in p.faces)
    else:
        _flat_patterns = flat_patterns
        req.patterns = _flat_patterns(faces, tol)
        omitted.update(i for p in req.patterns for i in p.faces)
    if profile:
        for step in profile.outer:
            if is_groove(profile,step,tol):
                omitted.add(step.face)
                info.append(Issue("detail_required",WARNING,
                    f"Канавка {step.length:g}×Ø{2*step.r:g}: нужен выносной элемент (ГОСТ 2.305)",()))
    skipped: dict[str, int] = {}
    seen_cyl: list[tuple] = []
    extents = _cylinder_extents(faces, tol)

    def _full_cylinder(f, ax, tol):
        return extents.get(_cyl_sig(f, ax, tol), False)

    for f in faces:
        if f.index in omitted:
            continue
        if f.kind == "plane" and f.normal is not None:
            ax = _axis_of(f.normal, tol)
            if ax is None:
                skipped["наклонная плоскость"] = skipped.get("наклонная плоскость", 0) + 1
                continue
            c = (f.box.x1, f.box.y1, f.box.z1)[ax]
            req.nodes[ax].setdefault(_snap_coord(c, tol), f"плоская грань #{f.index}")
        elif f.kind == "cylinder" and f.axis_dir is not None and f.radius:
            ax = _axis_of(f.axis_dir, tol)
            if ax is None:
                skipped["наклонный цилиндр"] = skipped.get("наклонный цилиндр", 0) + 1
                continue
            if features.profile or features.gear:
                legitimate = {i for h in features.holes for i in h.faces}
                if features.profile:
                    legitimate.update(s.face for s in features.profile.outer+features.profile.inner)
                if f.index not in legitimate:
                    skipped["частичный цилиндр (переход)"] = skipped.get("частичный цилиндр (переход)", 0)+1
                    continue
            o = f.axis_origin or (0.0, 0.0, 0.0)
            center = {j: _snap_coord(o[j], tol) for j in range(3) if j != ax}
            sig = (ax, round(f.radius / tol), tuple(sorted((j, round(v / tol)) for j, v in center.items())))
            if sig in seen_cyl:
                continue
            seen_cyl.append(sig)
            desc = (f"цилиндр #{f.index}, ось ∥{AXES[ax]} через "
                    + ", ".join(f"{AXES[j]}={v:g}" for j, v in center.items()))
            if not _full_cylinder(f, ax, tol) and not features.profile:
                # Неполный цилиндр (скругление, торец паза) задаётся радиусом; положение его оси следует
                # из касательных соседних граней и обязательным узлом не является.
                req.radii.append((ax, f.radius, center, desc))
                continue
            req.cylinders.append((ax, f.radius, center, desc))
            for j, v in center.items():
                req.nodes[j].setdefault(v, f"ось цилиндра #{f.index}")
        else:
            skipped[f.kind] = skipped.get(f.kind, 0) + 1
    if skipped:
        names = {"cone": "конус (фаска)", "torus": "тор (скругление)", "sphere": "сфера", "other": "прочие"}
        info.append(Issue("not_checked", INFO, "Не проверяются: " + ", ".join(
            f"{names.get(k, k)} ×{n}" for k, n in skipped.items()), ()))
    req.symmetries = symmetries_from_faces(faces, tol)
    return req, info


def _box(f) -> tuple[tuple[float, float], ...]:
    b = f.box
    return (b.x1, b.x2), (b.y1, b.y2), (b.z1, b.z2)


def _cyl_sig(f, ax: int, tol: float) -> tuple:
    o = f.axis_origin or (0.0, 0.0, 0.0)
    return ax, round(f.radius / tol), tuple(round(_snap_coord(o[j], tol) / tol) for j in range(3) if j != ax)


def _cylinder_extents(faces: Sequence, tol: float) -> dict:
    """Полный ли цилиндр (360°): объединение граней с той же осью и радиусом охватывает 2R по обеим
    радиальным осям (КОМПАС часто делит отверстие на две половины грани)."""
    boxes: dict = {}
    for f in faces:
        if f.kind != "cylinder" or not f.radius or f.axis_dir is None:
            continue
        ax = _axis_of(f.axis_dir, tol)
        if ax is None:
            continue
        sig = _cyl_sig(f, ax, tol)
        ext = boxes.setdefault(sig, {j: [float("inf"), float("-inf")] for j in range(3) if j != ax})
        for j, (lo, hi) in enumerate(_box(f)):
            if j in ext:
                ext[j][0], ext[j][1] = min(ext[j][0], lo), max(ext[j][1], hi)
    return {sig: all(hi - lo >= 2 * sig[1] * tol - 10 * tol for lo, hi in ext.values())
            for sig, ext in boxes.items()}


def symmetries_from_faces(faces: Sequence, tol: float = 1e-3) -> dict:
    """Плоскости симметрии детали, перпендикулярные осям модели: зеркальное отражение каждой грани
    (вид поверхности, радиус, габарит грани) относительно середины габарита есть среди граней."""
    if not faces:
        return {}
    q = 10 * tol

    def key(kind, radius, box):
        return kind, round((radius or 0) / q), tuple((round(lo / q), round(hi / q)) for lo, hi in box)

    out: dict = {}
    for ax in range(3):
        lo = min(_box(f)[ax][0] for f in faces)
        hi = max(_box(f)[ax][1] for f in faces)
        if hi - lo <= tol:
            continue
        m = (lo + hi) / 2
        have = {key(f.kind, f.radius, _box(f)) for f in faces}
        ok = True
        for f in faces:
            box = list(_box(f))
            a, b = box[ax]
            box[ax] = (2 * m - b, 2 * m - a)
            k = key(f.kind, f.radius, box)
            if k not in have and not any(
                    (k[0], k[1], tuple((x + dx, y + dy) if i == ax else (x, y) for i, (x, y) in enumerate(k[2])))
                    in have for dx in (-1, 0, 1) for dy in (-1, 0, 1)):
                ok = False
                break
        if ok:
            out[ax] = [Symmetry(_snap_coord(m, tol), _snap_coord(lo, tol), _snap_coord(hi, tol))]
    return out


def _axis_of(v, tol: float) -> int | None:
    for i in range(3):
        if abs(abs(v[i]) - 1.0) <= 1e-6 and all(abs(v[j]) <= 1e-6 for j in range(3) if j != i):
            return i
    return None


def _snap_coord(c: float, tol: float) -> float:
    r = round(c / tol) * tol
    return 0.0 if abs(r) < tol / 2 else round(r, 9)


# ==================================================================================================================
# === 36/55 kompas_lib.dims.features — kompas_lib/dims/features.py
# ==================================================================================================================
"""Распознавание повторяющихся элементов по инвариантам граней, без имён файлов.

Результаты — черновик. Равномерность кругового массива проверяется по углам,
цилиндры с разрезанными гранями объединяются по оси; зубья не считаются отверстиями.
"""

from dataclasses import dataclass, field
from math import atan2, hypot, pi, log
from typing import Sequence

# из kompas_lib.dims.redundancy: _axis_of


def _coords(box):
    return (box.x1, box.y1, box.z1), (box.x2, box.y2, box.z2)


def _regular_angles(points, center, tol=1e-3):
    angles = sorted(atan2(y-center[1], x-center[0]) % (2*pi) for x,y in points)
    step = 2*pi/len(angles)
    return all(abs((angles[(i+1)%len(angles)]-a) % (2*pi)-step) <= tol
               for i,a in enumerate(angles))


@dataclass(frozen=True)
class HolePattern:
    axis: int
    radius: float
    center: tuple[float, float]
    pitch_radius: float
    centers: tuple[tuple[float, float], ...]
    faces: tuple[int, ...]

    @property
    def count(self):
        return len(self.centers)


def flat_patterns(faces: Sequence, tol: float = 1e-3) -> list[HolePattern]:
    """Круговые массивы отверстий призматической детали (тела вращения нет): ось — любая из трёх,
    центр массива — середина габарита в радиальной плоскости."""
    if not faces:
        return []
    out: list[HolePattern] = []
    for ax in range(3):
        radial = [j for j in range(3) if j != ax]
        lo = [min(_coords(f.box)[0][j] for f in faces) for j in radial]
        hi = [max(_coords(f.box)[1][j] for f in faces) for j in radial]
        center = dict(zip(radial, [(a + b) / 2 for a, b in zip(lo, hi)]))
        out += hole_patterns(faces, ax, center, tol)
    return out

@dataclass(frozen=True)
class Gear:
    axis: int
    center: tuple[float, float]
    teeth: int
    outside_radius: float
    root_radius: float
    t1: float
    t2: float
    faces: tuple[int, ...]

    @property
    def width(self):
        return self.t2-self.t1


def hole_patterns(faces: Sequence, axis: int, center: dict[int, float], tol: float = 1e-3) -> list[HolePattern]:
    """Цилиндры с параллельными осями и одинаковым r на одной окружности центров."""
    radial = [j for j in range(3) if j != axis]
    c0 = tuple(center[j] for j in radial)
    groups = {}
    for f in faces:
        if f.kind != "cylinder" or not f.radius or not f.axis_dir or not f.axis_origin:
            continue
        if _axis_of(f.axis_dir,tol) != axis:
            continue
        p = tuple(f.axis_origin[j] for j in radial)
        pitch = hypot(p[0]-c0[0],p[1]-c0[1])
        if pitch <= tol:
            continue
        if f.internal is False:
            continue
        key = (round(f.radius/tol),round(pitch/tol))
        groups.setdefault(key,{}).setdefault(tuple(round(v/tol) for v in p),[]).append(f)
    out=[]
    for grouped in groups.values():
        if len(grouped)<3:
            continue
        complete = {}
        for point, fs in grouped.items():
            lo = [min(_coords(f.box)[0][j] for f in fs) for j in radial]
            hi = [max(_coords(f.box)[1][j] for f in fs) for j in radial]
            if all(hi[i]-lo[i] >= 2*fs[0].radius-tol for i in range(2)):
                complete[point] = fs
        grouped = complete
        if len(grouped) < 3:
            continue
        samples=[fs[0] for fs in grouped.values()]
        points=tuple(tuple(f.axis_origin[j] for j in radial) for f in samples)
        if not _regular_angles(points,c0):
            continue
        out.append(HolePattern(axis,samples[0].radius,c0,hypot(points[0][0]-c0[0],points[0][1]-c0[1]),
                               points,tuple(f.index for fs in grouped.values() for f in fs)))
    return out


def recognize_gear(faces: Sequence, tol: float = 1e-3) -> Gear | None:
    """Венец: регулярные соосные дуги впадин/вершин + повторяющиеся боковые поверхности.

    Одного повторения граней недостаточно: проверяются две разные окружности с одинаковым
    числом сегментов и минимум две боковые грани на зуб. Фланец с отверстиями не проходит.
    """
    groups={}
    for f in faces:
        if f.kind != "cylinder" or not f.radius or not f.axis_dir or not f.axis_origin:
            continue
        ax=_axis_of(f.axis_dir,tol)
        if ax is None:
            continue
        radial=[j for j in range(3) if j!=ax]
        origin=tuple(f.axis_origin[j] for j in radial)
        key=(ax,tuple(round(v/tol) for v in origin),round(f.radius/tol))
        groups.setdefault(key,[]).append(f)
    rings=[]
    for key,fs in groups.items():
        if len(fs)<6:
            continue
        ax=key[0]
        radial=[j for j in range(3) if j!=ax]
        center=tuple(fs[0].axis_origin[j] for j in radial)
        pts=[tuple(f.box.center[j] for j in radial) for f in fs]
        if _regular_angles(pts,center):
            rings.append((key,fs,center))
    for key,fs,c0 in sorted(rings,key=lambda r:r[1][0].radius,reverse=True):
        ax,n=key[0],len(fs)
        other=next((qs for qk,qs,qc in rings if qk[:2]==key[:2] and len(qs)==n and
                    qs[0].radius < fs[0].radius-tol),None)
        if other is None:
            continue
        radial=[j for j in range(3) if j!=ax]
        lo,hi=_coords(fs[0].box)
        flank=[f for f in faces if f.kind=="cylinder" and f.axis_dir and f.axis_origin and
               _axis_of(f.axis_dir,tol)==ax and
               hypot(*(f.axis_origin[j]-c0[i] for i,j in enumerate(radial)))>tol and
               _coords(f.box)[0][ax] <= lo[ax]+tol and _coords(f.box)[1][ax] >= hi[ax]-tol]
        if len(flank)<2*n:
            continue
        # Орбиты одинаковых граней венца, включая фаски и малые площадки.
        orbits={}
        root=other[0].radius
        for f in faces:
            flo,fhi=_coords(f.box)
            r=hypot(*(f.box.center[j]-c0[i] for i,j in enumerate(radial)))
            if r < root-tol:
                continue
            sig=(f.kind,round(log(max(tol,f.area)),4),
                 round(flo[ax]/tol),round(fhi[ax]/tol),round((f.radius or 0)/tol))
            orbits.setdefault(sig,[]).append(f.index)
        ids={f.index for f in fs+other+flank}
        ids.update(i for inds in orbits.values() if len(inds)>=n for i in inds)
        ranges=[_coords(f.box) for f in fs+other]
        return Gear(ax,c0,n,fs[0].radius,root,min(a[ax] for a,b in ranges),
                    max(b[ax] for a,b in ranges),tuple(sorted(ids)))
    return None


@dataclass(frozen=True)
class Hole:
    axis: int
    radius: float
    center: tuple[float, float]
    t1: float
    t2: float
    faces: tuple[int, ...]


