@dataclass
class ModelFeatures:
    """Общий промежуточный слой. Значения сохраняют геометрию исходной модели."""
    profile: object = None
    body_profile: object = None
    gear: Gear | None = None
    holes: list[Hole] = field(default_factory=list)
    patterns: list[HolePattern] = field(default_factory=list)
    keyways: list[Keyway] = field(default_factory=list)
    chamfers: list[ChamferFeature] = field(default_factory=list)
    fillets: list[Fillet] = field(default_factory=list)
    threads: list[Thread] = field(default_factory=list)
    notes: list[str] = field(default_factory=list)


def recognize_keyways(faces, profile, tol=1e-3):
    """Пара боковых плоскостей + дно, подтверждённые профилем вала/отверстия.

    Замкнутый паз дополнительно связывается с цилиндрическими торцами. Поддерживает
    перестановку/смену знака главных осей и перемещение модели; номера граней не заданы.
    """
    if profile is None:
        return []
    axis = profile.axis
    radial = list(profile.center)
    planes = [f for f in faces if f.kind == "plane" and f.normal]
    result = []
    used = set()
    for bottom in planes:
        depth_axis = _axis_of(bottom.normal, tol)
        if depth_axis not in radial:
            continue
        width_axis = next(j for j in radial if j != depth_axis)
        lo, hi = _coords(bottom.box)
        if hi[axis] - lo[axis] <= tol or hi[width_axis] - lo[width_axis] <= tol:
            continue
        width = hi[width_axis] - lo[width_axis]
        if abs((lo[width_axis] + hi[width_axis])/2 - profile.center[width_axis]) > tol:
            continue
        def joins_bottom(side):
            slo, shi = _coords(side.box)
            coordinate = slo[width_axis]
            edge = lo[width_axis] if coordinate < profile.center[width_axis] else hi[width_axis]
            if abs(coordinate-edge) <= tol and slo[depth_axis]-tol <= lo[depth_axis] <= shi[depth_axis]+tol:
                return []
            # Реальная наклонная грань соединяет стенку с узким плоским дном.
            # Например, фаска 0.4 мм в пазу: ширина измеряется по стенкам,
            # а не по уменьшенной площадке дна. Зазор без такой грани запрещён.
            end = min((slo[depth_axis],shi[depth_axis]),key=lambda value:abs(value-lo[depth_axis]))
            for transition in faces:
                if transition.kind != 'cylinder' or not transition.axis_dir or not transition.axis_origin or not transition.radius:
                    continue
                if _axis_of(transition.axis_dir,tol) != axis:
                    continue
                tlo, thi = _coords(transition.box)
                if (abs(transition.axis_origin[width_axis]-edge) <= tol and
                    abs(transition.axis_origin[depth_axis]-end) <= tol and
                    abs(abs(coordinate-edge)-transition.radius) <= tol and
                    abs(abs(end-lo[depth_axis])-transition.radius) <= tol and
                    abs(tlo[width_axis]-min(coordinate,edge)) <= tol and
                    abs(thi[width_axis]-max(coordinate,edge)) <= tol and
                    abs(tlo[depth_axis]-min(end,lo[depth_axis])) <= tol and
                    abs(thi[depth_axis]-max(end,lo[depth_axis])) <= tol and
                    min(thi[axis],hi[axis],shi[axis])-max(tlo[axis],lo[axis],slo[axis]) > tol):
                    return [transition]
            for transition in planes:
                normal = transition.normal
                if abs(normal[axis]) > tol or abs(normal[width_axis]) <= tol or abs(normal[depth_axis]) <= tol:
                    continue
                tlo, thi = _coords(transition.box)
                if (abs(tlo[width_axis]-min(coordinate,edge)) <= tol and
                    abs(thi[width_axis]-max(coordinate,edge)) <= tol and
                    abs(tlo[depth_axis]-min(end,lo[depth_axis])) <= tol and
                    abs(thi[depth_axis]-max(end,lo[depth_axis])) <= tol and
                    min(thi[axis],hi[axis],shi[axis])-max(tlo[axis],lo[axis],slo[axis]) > tol and
                    abs(normal[width_axis]*(coordinate-edge)+normal[depth_axis]*(end-lo[depth_axis])) <= tol):
                    return [transition]
            return None

        choices = []
        for side in planes:
            if _axis_of(side.normal,tol) != width_axis:
                continue
            slo, shi = _coords(side.box)
            if min(shi[axis],hi[axis])-max(slo[axis],lo[axis]) <= tol:
                continue
            connections = joins_bottom(side)
            if connections is not None:
                choices.append((side,connections))
        left = [item for item in choices if _coords(item[0].box)[0][width_axis] < profile.center[width_axis]-tol]
        right = [item for item in choices if _coords(item[0].box)[0][width_axis] > profile.center[width_axis]+tol]
        if not left or not right:
            continue
        left_side,left_links = max(left,key=lambda item:_coords(item[0].box)[0][width_axis])
        right_side,right_links = min(right,key=lambda item:_coords(item[0].box)[0][width_axis])
        sides = [left_side,right_side]
        side_lo = _coords(left_side.box)[0][width_axis]
        side_hi = _coords(right_side.box)[0][width_axis]
        if abs((side_lo+side_hi)/2-profile.center[width_axis]) > tol:
            continue
        width = side_hi-side_lo
        dist = abs(lo[depth_axis] - profile.center[depth_axis])
        candidates = []
        for step in profile.outer + profile.inner:
            if min(step.t2, hi[axis]) - max(step.t1, lo[axis]) <= tol or width >= 2*step.r:
                continue
            depth = dist-step.r if step.inner else step.r-dist
            if tol < depth < step.r and width < 2*step.r:
                # Боковая плоскость должна выходить на поверхность цилиндра.
                surface = (step.r**2 - (width/2)**2)**0.5
                distances = [abs(c-profile.center[depth_axis]) for f in sides for c in
                             (_coords(f.box)[0][depth_axis], _coords(f.box)[1][depth_axis])]
                reach = min(distances) if step.inner else max(distances)
                if abs(reach-surface) <= max(10*tol, step.r*1e-3):
                    candidates.append((depth, step))
        if not candidates:
            continue
        depth, step = min(candidates, key=lambda p: p[0])
        caps, cap_links = [], []
        for cap in faces:
            if not (cap.kind == "cylinder" and cap.axis_dir and cap.axis_origin and cap.radius and
                    _axis_of(cap.axis_dir,tol) == depth_axis and abs(2*cap.radius-width) <= tol and
                    abs(cap.axis_origin[width_axis]-profile.center[width_axis]) <= tol and
                    lo[axis]-tol <= cap.axis_origin[axis] <= hi[axis]+tol):
                continue
            clo, chi = _coords(cap.box)
            cap_depth = min((clo[depth_axis],chi[depth_axis]),key=lambda value:abs(value-lo[depth_axis]))
            if abs(cap_depth-lo[depth_axis]) <= tol:
                caps.append(cap)
                continue
            # У замкнутого паза со скруглением дно короче стенки. Расширяем длину
            # только при наличии настоящей тороидальной грани между дном и торцом.
            for blend in faces:
                if not (blend.kind == 'torus' and blend.axis_dir and blend.axis_origin and
                        blend.minor_radius and blend.major_radius and
                        _axis_of(blend.axis_dir,tol) == depth_axis):
                    continue
                blo,bhi = _coords(blend.box)
                if (abs(blend.axis_origin[axis]-cap.axis_origin[axis]) <= tol and
                    abs(blend.axis_origin[width_axis]-cap.axis_origin[width_axis]) <= tol and
                    abs(blend.major_radius+blend.minor_radius-cap.radius) <= tol and
                    abs(blend.major_radius-width/2+blend.minor_radius) <= tol and
                    abs(blo[depth_axis]-min(lo[depth_axis],cap_depth)) <= tol and
                    abs(bhi[depth_axis]-max(lo[depth_axis],cap_depth)) <= tol and
                    all(abs(blo[j]-clo[j]) <= tol and abs(bhi[j]-chi[j]) <= tol
                        for j in (axis,width_axis))):
                    caps.append(cap)
                    cap_links.append(blend)
                    break
        t1 = min([lo[axis]]+[_coords(f.box)[0][axis] for f in caps])
        t2 = max([hi[axis]]+[_coords(f.box)[1][axis] for f in caps])
        ids = tuple(sorted({bottom.index, *(f.index for f in sides+caps+left_links+right_links+cap_links)}))
        if any(i in used for i in ids):
            continue
        used.update(ids)
        result.append(Keyway(axis, width_axis, depth_axis, width, depth, t1, t2,
                             lo[depth_axis], step.r, step.inner, ids))
    return result


def recognize_features(faces: Sequence, tol: float = 1e-3) -> ModelFeatures:
    """Распознать элементы один раз для обоих способов оформления."""
    # из kompas_lib.dims.revolution: revolution_profile
    features = ModelFeatures(gear=recognize_gear(faces, tol))
    features.profile = revolution_profile(faces, tol) if features.gear is None else None
    if features.gear:
        features.body_profile = gear_body_profile(features.gear, faces)
    axis = features.profile.axis if features.profile else features.gear.axis if features.gear else None
    center = (features.profile.center if features.profile else
              dict(zip((j for j in range(3) if j != axis), features.gear.center)) if features.gear else None)
    if axis is not None:
        features.patterns = hole_patterns(faces, axis, center, tol)
    else:
        features.patterns = flat_patterns(faces, tol)
    features.keyways = recognize_keyways(faces, features.profile or features.body_profile, tol)
    omitted = {i for k in features.keyways for i in k.faces}
    omitted.update(i for p in features.patterns for i in p.faces)
    if features.gear:
        omitted.update(features.gear.faces)
    groups = {}
    for f in faces:
        if f.index in omitted or f.kind != "cylinder" or not f.axis_dir or not f.axis_origin or not f.radius:
            continue
        ax = _axis_of(f.axis_dir, tol)
        if ax is None:
            continue
        radial = [j for j in range(3) if j != ax]
        lo, hi = _coords(f.box)
        # Не объявляем отверстиями частичные цилиндрические поверхности скруглений.
        if any(abs(hi[j]-lo[j]-2*f.radius) > tol for j in radial):
            continue
        c = tuple(f.axis_origin[j] for j in radial)
        signature = (ax, round(f.radius/tol), tuple(round(v/tol) for v in c))
        groups.setdefault(signature, []).append(f)
    for group in groups.values():
        f = group[0]
        ax = _axis_of(f.axis_dir, tol)
        if axis == ax and all(abs(f.axis_origin[j]-center[j]) <= tol for j in center):
            profile = features.profile or features.body_profile
            if not profile or not any(abs(s.r-f.radius) <= tol for s in profile.inner):
                continue
        radial = [j for j in range(3) if j != ax]
        features.holes.append(Hole(ax, f.radius, tuple(f.axis_origin[j] for j in radial),
            min(_coords(q.box)[0][ax] for q in group), max(_coords(q.box)[1][ax] for q in group),
            tuple(q.index for q in group)))
    chamfers, fillets = {}, {}
    for f in faces:
        if f.index in omitted:
            continue
        if f.kind == "cone" and f.axis_dir and f.cone_angle is not None:
            ax = _axis_of(f.axis_dir, tol)
            if ax is None or abs(f.cone_angle-45) > tol:
                continue
            lo, hi = _coords(f.box)
            size = hi[ax]-lo[ax]
            # Фаска: короткая коническая полоса у границы цилиндрической ступени.
            body = features.profile or features.body_profile
            adjacent = [s for s in (body.outer+body.inner if body else [])
                        if abs(s.r-(f.radius or 0)) <= size+tol and
                        min(abs(t-c) for t in (s.t1,s.t2) for c in (lo[ax],hi[ax])) <= tol]
            at_plane = any(q.kind == "plane" and q.normal and _axis_of(q.normal, tol) == ax and
                           min(abs(_coords(q.box)[0][ax]-lo[ax]), abs(_coords(q.box)[0][ax]-hi[ax])) <= tol
                           for q in faces)
            if adjacent and at_plane and size > tol and size < max(s.r for s in adjacent):
                chamfers.setdefault((ax, round(size/tol), round(f.cone_angle/tol)), []).append(f)
        elif f.kind == "torus" and f.minor_radius and f.minor_radius > tol:
            fillets.setdefault(round(f.minor_radius/tol), []).append(f)
    for (ax, _, _), group in chamfers.items():
        lo, hi = _coords(group[0].box)
        features.chamfers.append(ChamferFeature(ax, hi[ax]-lo[ax], group[0].cone_angle,
                                                tuple(f.index for f in group)))
    features.fillets = [Fillet(fs[0].minor_radius, tuple(f.index for f in fs)) for fs in fillets.values()]
    if features.gear:
        features.notes.append("Параметры зацепления m, угол профиля и точность требуют данных конструктора (ГОСТ 2.403)")
    return features


def gear_body_profile(gear, faces):
    """Профиль ступицы/отверстия; венец остаётся отдельным распознанным элементом."""
    # из kompas_lib.dims.revolution: ProfileStep, RevolutionProfile, _nodes
    axis = gear.axis
    center = dict(zip((j for j in range(3) if j != axis), gear.center))
    lo = lambda f: _coords(f.box)[0][axis]
    hi = lambda f: _coords(f.box)[1][axis]
    profile = RevolutionProfile(axis, center, min(map(lo,faces)), max(map(hi,faces)))
    outside = next(f for f in faces if f.kind == "cylinder" and f.radius and
                   abs(f.radius-gear.outside_radius) <= 1e-3 and f.index in gear.faces)
    profile.outer.append(ProfileStep(gear.outside_radius,gear.t1,gear.t2,False,outside.index))
    for f in faces:
        if f.index in gear.faces:
            continue
        if f.kind == "plane" and f.normal and _axis_of(f.normal,1e-3) == axis:
            profile.planes.append(lo(f))
        elif f.kind == "cylinder" and f.axis_dir and f.axis_origin and _axis_of(f.axis_dir,1e-3) == axis and \
             all(abs(f.axis_origin[j]-c)<1e-3 for j,c in center.items()):
            inner = f.internal if f.internal is not None else f.radius < gear.root_radius
            step = ProfileStep(f.radius,lo(f),hi(f),bool(inner),f.index)
            (profile.inner if step.inner else profile.outer).append(step)
    profile.planes = sorted(set(profile.planes))
    profile.nodes = _nodes(profile,1e-3)
    return profile


