# === 37/55 kompas_lib.dims.revolution — kompas_lib/dims/revolution.py
# ==================================================================================================================
"""Профиль тела вращения по граням модели (чистый Python, без КОМПАСа).

Вал, втулка, шайба, кольцо, крышка: все поверхности вращения соосны одной оси. По профилю строится черновой набор
размеров (ГОСТ 2.307): длины ступеней от торцов, диаметры ступеней и отверстий; фаски, канавки, шпоночные пазы
и отверстия вне оси перечисляются как требующие отдельного оформления.

Вход — `model.Face` (kind, radius, axis_origin, axis_dir, normal, box). Оси модели: 0 — X, 1 — Y, 2 — Z.
"""

from dataclasses import dataclass, field
from typing import Sequence

# из kompas_lib.dims.redundancy: AXES, _axis_of

@dataclass(frozen=True)
class ProfileStep:
    """Цилиндрический участок профиля: радиус и диапазон вдоль оси."""
    r: float
    t1: float
    t2: float
    inner: bool                 # отверстие (внутри более крупного соосного цилиндра на том же участке)
    face: int

    @property
    def length(self) -> float:
        return self.t2 - self.t1


@dataclass(frozen=True)
class Chamfer:
    """Коническая грань малой длины на краю ступени (фаска)."""
    t1: float
    t2: float
    r: float                    # больший радиус
    face: int
    angle: float | None = None

    @property
    def size(self) -> float:
        return self.t2 - self.t1


@dataclass
class RevolutionProfile:
    axis: int                               # ось модели, вдоль которой ось детали
    center: dict[int, float]                # координаты оси детали по двум другим осям
    t_min: float
    t_max: float
    outer: list[ProfileStep] = field(default_factory=list)
    inner: list[ProfileStep] = field(default_factory=list)
    planes: list[float] = field(default_factory=list)       # торцы и уступы (плоскости ⟂ оси), по возрастанию
    nodes: list[float] = field(default_factory=list)        # узлы размеров вдоль оси (торцы, уступы, переходы)
    chamfers: list[Chamfer] = field(default_factory=list)
    others: dict[str, int] = field(default_factory=dict)    # что не входит в профиль: пазы, отверстия вне оси…

    @property
    def length(self) -> float:
        return self.t_max - self.t_min

    @property
    def hollow(self) -> bool:
        return bool(self.inner)

    def outer_radius_at(self, t: float, tol: float = 1e-6) -> float:
        rs = [s.r for s in self.outer if s.t1 - tol <= t <= s.t2 + tol]
        return max(rs) if rs else 0.0

    def describe(self) -> str:
        ax = AXES[self.axis]
        c = ", ".join(f"{AXES[j]}={v:g}" for j, v in self.center.items())
        return (f"тело вращения: ось ∥{ax} через {c}, длина {self.length:g}; "
                f"ступеней {len(self.outer)}, отверстий {len(self.inner)}, торцов/уступов {len(self.planes)}, "
                f"фасок {len(self.chamfers)}")


def _range(box, ax: int) -> tuple[float, float]:
    lo = (box.x1, box.y1, box.z1)[ax]
    hi = (box.x2, box.y2, box.z2)[ax]
    return min(lo, hi), max(lo, hi)


def revolution_profile(faces: Sequence, tol: float = 1e-3, chamfer_max: float = 5.0) -> RevolutionProfile | None:
    """Профиль, если деталь — тело вращения (иначе None).

    Ось детали — ось той группы соосных поверхностей вращения, чей наибольший радиус задаёт габарит детали
    поперёк оси. Поверхности вне этой оси (шпоночные пазы, отверстия во фланце) попадают в `others`.
    """
    # из kompas_lib.dims.features: recognize_gear
    if recognize_gear(faces, tol) is not None:
        return None
    groups: dict[tuple, list] = {}
    for f in faces:
        if f.kind not in ("cylinder", "cone", "torus") or f.axis_dir is None or f.axis_origin is None:
            continue
        ax = _axis_of(f.axis_dir, tol)
        if ax is None:
            continue
        key = (ax,) + tuple(round(f.axis_origin[j] / tol) for j in range(3) if j != ax)
        groups.setdefault(key, []).append(f)
    if not faces or not groups:
        return None
    # габарит детали
    xs = [(f.box.x1, f.box.x2) for f in faces]
    ys = [(f.box.y1, f.box.y2) for f in faces]
    zs = [(f.box.z1, f.box.z2) for f in faces]
    lo = (min(a for a, _ in xs), min(a for a, _ in ys), min(a for a, _ in zs))
    hi = (max(b for _, b in xs), max(b for _, b in ys), max(b for _, b in zs))

    best = None
    for key, fs in groups.items():
        ax = key[0]
        rmax = max((f.radius or 0.0) for f in fs if f.kind == "cylinder") if any(f.kind == "cylinder" for f in fs) \
            else 0.0
        others_ax = [j for j in range(3) if j != ax]
        ext = max(hi[j] - lo[j] for j in others_ax)
        origin = fs[0].axis_origin
        centered = all(abs(origin[j]-(lo[j]+hi[j])/2) <= 0.15*ext for j in others_ax)
        # Приливы фланца могут выходить за основной цилиндр. Ослабление допустимо
        # только для соосной группы с заметной долей поперечного габарита.
        if rmax > 0 and (abs(2 * rmax - ext) <= max(10 * tol, 0.01 * ext) or
                         len(fs) >= 2 and 2*rmax >= 0.7*ext and centered):
            score = rmax * (hi[ax] - lo[ax])
            if best is None or score > best[0]:
                best = (score, key, fs)
    if best is None:
        return None
    _, key, group = best
    ax = key[0]
    o = group[0].axis_origin
    center = {j: (0.0 if abs(o[j]) < tol else round(o[j], 9)) for j in range(3) if j != ax}
    prof = RevolutionProfile(ax, center, lo[ax], hi[ax])

    cyl = []
    for f in group:
        t1, t2 = _range(f.box, ax)
        if f.kind == "cylinder" and f.radius:
            cyl.append((f.radius, t1, t2, f.index))
        elif f.kind == "cone" and f.radius and 0.3 <= t2 - t1 <= chamfer_max:
            prof.chamfers.append(Chamfer(t1, t2, f.radius, f.index, getattr(f, "cone_angle", None)))
        elif f.kind == "cone" and t2 - t1 < 0.3:
            prof.others["конус-переход (канавка, поднутрение)"] = prof.others.get("конус-переход (канавка, поднутрение)",
                                                                                 0) + 1
        else:
            name = {"cone": "конус", "torus": "тор (скругление/переход)"}.get(f.kind, f.kind)
            prof.others[name] = prof.others.get(name, 0) + 1
    # один цилиндр может быть разбит на несколько граней — сливаем участки одного радиуса, касающиеся друг друга
    cyl.sort(key=lambda c: (round(c[0] / tol), c[1]))
    merged: list[list] = []
    for r, t1, t2, idx in cyl:
        if merged and abs(merged[-1][0] - r) <= tol and t1 <= merged[-1][2] + tol:
            merged[-1][2] = max(merged[-1][2], t2)
        else:
            merged.append([r, t1, t2, idx])
    for r, t1, t2, idx in merged:
        source = next(face for face in group if face.index == idx)
        orientation = getattr(source,'internal',None)
        inner = (orientation if orientation is not None else
                 any(r2 > r + tol and min(t2, b) - max(t1, a) > tol for r2, a, b, _ in merged))
        (prof.inner if inner else prof.outer).append(ProfileStep(r, t1, t2, inner, idx))
    prof.outer.sort(key=lambda s: s.t1)
    prof.inner.sort(key=lambda s: s.t1)

    ts: list[float] = []
    for f in faces:
        if f.kind == "plane" and f.normal is not None and _axis_of(f.normal, tol) == ax:
            t = _range(f.box, ax)[0]
            if not any(abs(t - u) <= tol for u in ts):
                ts.append(t)
        elif f.kind == "plane" and f.normal is not None:
            prof.others["плоская грань вдоль оси (лыска, паз)"] = prof.others.get("плоская грань вдоль оси (лыска, паз)",
                                                                                  0) + 1
        elif f.kind == "cylinder" and f.axis_dir is not None and f not in group:
            a2 = _axis_of(f.axis_dir, tol)
            name = "отверстие/скругление ∥ оси вне оси" if a2 == ax else "цилиндр поперёк оси (паз, отверстие)"
            prof.others[name] = prof.others.get(name, 0) + 1
        elif f.kind in ("sphere", "other"):
            prof.others[f.kind] = prof.others.get(f.kind, 0) + 1
    for t in (prof.t_min, prof.t_max):                       # концы детали — узлы, даже если там фаска
        if not any(abs(t - u) <= tol for u in ts):
            ts.append(t)
    prof.planes = sorted(ts)
    prof.nodes = _nodes(prof, tol)
    return prof


def _nodes(prof: RevolutionProfile, tol: float) -> list[float]:
    """Узлы размеров вдоль оси: торцы и уступы + переходы между ступенями без торцевой плоскости.

    Переход через фаску/скругление (конус, тор между ступенями) — узел на конце более толстой ступени: там на виде
    вершина (конец образующей), к ней размер и привязывается.
    """
    nodes = list(prof.planes)
    steps = sorted(prof.outer, key=lambda s: s.t1)
    for a, b in zip(steps, steps[1:]):
        lo, hi = min(a.t2, b.t1), max(a.t2, b.t1)
        if any(lo - tol <= t <= hi + tol for t in nodes):
            continue
        t = a.t2 if a.r >= b.r else b.t1
        nodes.append(t)
    return sorted(nodes)


@dataclass(frozen=True)
class LengthDim:
    """Черновой размер вдоль оси: между узлами a и b (координаты вдоль оси детали)."""
    a: float
    b: float
    key: str
    overall: bool = False


@dataclass(frozen=True)
class DiameterDim:
    step: ProfileStep
    key: str
    end_view: bool = False


def is_groove(prof: RevolutionProfile, step: ProfileStep, tol: float = 1e-3) -> bool:
    """Короткое уменьшение диаметра между двумя более толстыми ступенями."""
    if step.inner or step.length > 5.0 + tol:
        return False
    before = [s for s in prof.outer if s is not step and s.t2 <= step.t1 + tol]
    after = [s for s in prof.outer if s is not step and s.t1 >= step.t2 - tol]
    if not before or not after:
        return False
    a, b = max(before, key=lambda s: s.t2), min(after, key=lambda s: s.t1)
    return a.r > step.r + tol and b.r > step.r + tol and step.t1 - a.t2 <= 5 and b.t1 - step.t2 <= 5


def draft_dimensions(prof: RevolutionProfile, tol: float = 1e-3, scale: float = 1.0,
                     text_height: float | None = None) -> tuple[list[LengthDim], list[DiameterDim], list[str]]:
    """Черновой набор размеров тела вращения без избыточности (ГОСТ 2.307).

    Длины: габаритная + цепочка между соседними торцами/уступами без одного звена (самого длинного — как правило,
    свободного участка), так что цепь не замыкается. Диаметры: каждой наружной ступени и каждого отверстия.
    Возвращает (длины, диаметры, заметки — что требует отдельного оформления).
    """
    nodes = prof.nodes or prof.planes
    lengths = [LengthDim(prof.t_min, prof.t_max, "L", overall=True)]
    links = [(a, b) for a, b in zip(nodes, nodes[1:]) if b - a > tol]
    if len(links) > 1:
        skip = max(range(len(links)), key=lambda i: links[i][1] - links[i][0])
        for i, (a, b) in enumerate(links):
            if i != skip:
                lengths.append(LengthDim(a, b, f"l{i + 1}"))
    if scale <= 0:
        raise ValueError("scale должен быть положительным")
    # из kompas_lib.dims.shapes: DimStyle
    # До создания CAD-надписи известна только минимальная длина под стрелки.
    # add_dimensions использует фактическую высоту текста, прочитанную из API.
    short_limit = text_height+4.0 if text_height is not None else 2*DimStyle().arrow
    diams = []
    notes = []
    seen: set[tuple] = set()
    for i, s in enumerate(prof.outer + prof.inner):
        if is_groove(prof, s, tol):
            notes.append(f"канавка {round(s.length, 3):g}×Ø{round(2 * s.r, 3):g} — выносной элемент (ГОСТ 2.305)")
            continue
        sig = (s.inner, round(s.r / tol))
        if sig in seen:
            continue
        seen.add(sig)
        # Среди одинаковых диаметров выбираем самый длинный участок.
        step = max((q for q in prof.outer + prof.inner if q.inner == s.inner and abs(q.r - s.r) <= tol
                    and not is_groove(prof, q, tol)), key=lambda q: q.length)
        diams.append(DiameterDim(step, f"{'d' if s.inner else 'D'}{i + 1}",
                                 step.length * scale < short_limit))
    chamfers: dict[tuple, int] = {}
    for c in prof.chamfers:
        size = round(c.size, 3)
        signature = (size, c.angle)
        chamfers[signature] = chamfers.get(signature, 0) + 1
    for (size, angle), n in chamfers.items():
        designation = f"{size:g}×{angle:g}°" if angle is not None else f"c={size:g}, угол неизвестен"
        notes.append(f"конический переход {designation} ×{n} — проверить и оформить отдельно")
    for name, n in prof.others.items():
        notes.append(f"{name} ×{n} — не входит в профиль, оформляется отдельно (сечение, местный вид)")
    return lengths, diams, notes


