"""Черновой минимальный набор видов тела вращения; выбор исправляет вызывающий."""
from dataclasses import dataclass
from typing import Sequence

# из kompas_lib.enums: Projection
# из kompas_lib.dims.revolution: draft_dimensions


@dataclass(frozen=True)
class RevolutionViews:
    main_projection: Projection
    projections: tuple[Projection, ...]
    cut_normal: int
    needs_end: bool
    reasons: tuple[str, ...]


def suggest_revolution_views(profile, faces: Sequence = (), scale: float = 1.0) -> RevolutionViews:
    """Продольный вид + торец для полости, коротких ступеней или отверстий во фланце.

    Секущая плоскость проходит через ось. Из двух стандартных продольных проекций выбирается
    та, чья плоскость дальше от граней пазов/прорезей. Смещение от оси не применяется:
    оно превратило бы истинный диаметр отверстия в хорду.
    """
    radial = [j for j in range(3) if j != profile.axis]
    local = [f for f in faces if f.kind == "plane" and f.normal and
             abs(f.normal[profile.axis]) < 0.9]
    local += [f for f in faces if f.kind == "cylinder" and f.axis_dir and
              abs(f.axis_dir[profile.axis]) < 0.9]

    def score(n):
        return sum(1.0 / (abs(f.box.center[n] - profile.center[n]) + 0.1) for f in local)

    normal = min(radial, key=lambda n: (score(n), n != 2))
    main = {0: Projection.LEFT, 1: Projection.TOP, 2: Projection.FRONT}[normal]
    _, diams, _ = draft_dimensions(profile, scale=scale)
    reasons = []
    if profile.hollow:
        reasons.append("полость: торцевой вид задаёт секущую плоскость")
    if any(d.end_view for d in diams):
        reasons.append("диаметры коротких ступеней на торцевом виде")
    if profile.others.get("отверстие/скругление ∥ оси вне оси"):
        reasons.append("отверстия во фланце")
    # При главном виде сверху ось Z идёт вертикально; торец — относительный вид сверху.
    # При остальных главных видах продольная ось горизонтальна, торец справа от главного.
    horizontal_axis = {0: 2, 1: 0, 2: 0}[normal]
    end = Projection.LEFT if profile.axis == horizontal_axis else Projection.TOP
    return RevolutionViews(main, (Projection.FRONT, end) if reasons else (Projection.FRONT,),
                           normal, bool(reasons), tuple(reasons))


