"""Размеры на чертеже КОМПАС: чтение, создание с раскладкой, проверка (ГОСТ 2.307).

Связка чистых модулей (`shapes`, `plan`, `redundancy`) с документом:
- `read_dims(view)` — линейные размеры вида в модели `LinearDim` (мм листа, фактическая геометрия);
- `add_dimensions(view, [Dim(...)])` — создать размеры: привязка к вершинам вида (`Associate`),
  раскладка по ярусам без пересечений, применение, проверка того, что получилось;
- `check_dimensions(drawing)` — отчёт: пересечения, выход за рамку, лишние и недостающие размеры.

Координаты в `Dim` — координаты ВИДА (как у `View.project_point`, `View.curves`).
Поддерживаются неповёрнутые виды; размеры — горизонтальные и вертикальные.
"""

import math
import os
import re
from dataclasses import dataclass, field, replace
from typing import TYPE_CHECKING, Hashable, Sequence

# из kompas_lib.enums: raw
# из kompas_lib._compat: position_dimension_text
# из kompas_lib.errors: OperationFailedError, check
# из kompas_lib.geom: Point, Rect, Segment
# из kompas_lib.dims.plan: DiamRequest, DimRequest, plan_dimensions
# из kompas_lib.dims.redundancy: DimFact, check_redundancy, requirement_from_faces
# из kompas_lib.dims.shapes: ERROR, INFO, WARNING, DiametralDim, DimStyle, Issue, LinearDim, align_text_to_extent, check_dims, keepout_conflicts, group_issues, model_mismatch

# из kompas_lib.drawing.document: Drawing  (только для аннотаций)
# из kompas_lib.drawing.view: View  (только для аннотаций)
# из kompas_lib.model: PartDocument  (только для аннотаций)

_ORIENT = raw.ksLineDimensionOrientationEnum
_H, _V, _P = int(_ORIENT.ksLinDHorizontal), int(_ORIENT.ksLinDVertical), int(_ORIENT.ksLinDParallel)
_PT = raw.ksDimensionPointEnum
_TT = raw.ksDimensionTextTypeEnum
DIAMETER_SIGN = "\u00d8"   # «Ø»: IDimensionText.SetSign(1) в v26 не рисуется — только префикс-строкой
SNAP_TOL = 0.05            # допуск привязки точки к вершине (единицы вида)
LEADER_TEXT_H = 8.0        # высота надписи на полке выноски, мм листа (шрифт 5 мм с рамкой ≈ 7.4)


@dataclass
class Dim:
    """Размер, который нужно поставить (координаты вида).

    axis: "x" — горизонтальный, "y" — вертикальный, "auto" — по точкам (если они на одной горизонтали/вертикали).
    side: auto | top | bottom | left | right | inside; для inside обязательно `at` — координата размерной линии
    (вида): Y для горизонтального, X для вертикального. Для внешних размеров `at` фиксирует положение линии.
    """
    p1: tuple[float, float] | Point
    p2: tuple[float, float] | Point
    axis: str = "auto"
    side: str = "auto"
    at: float | None = None
    diameter: bool = False
    reference: bool = False          # справочный: «*» после значения
    key: Hashable = None
    prefix: str = ""
    suffix: str = ""
    at_range: tuple[float, float] | None = None


@dataclass
class Diameter:
    """Диаметральный размер окружности вида.

    center — центр окружности (координаты вида); radius — уточнить, если окружностей с этим центром несколько
    (концентрические); angle — угол размерной линии, None — подобрать без пересечений.
    """
    center: tuple[float, float] | Point
    radius: float | None = None
    angle: float | None = None
    reference: bool = False
    key: Hashable = None
    suffix: str = ""


@dataclass
class DimReport:
    created: list[dict] = field(default_factory=list)
    issues: list[Issue] = field(default_factory=list)

    @property
    def errors(self) -> list[Issue]:
        return [i for i in self.issues if i.severity == ERROR]

    @property
    def warnings(self) -> list[Issue]:
        return [i for i in self.issues if i.severity == WARNING]

    @property
    def ok(self) -> bool:
        return not self.errors

    def as_dict(self) -> dict:
        return {"ok": self.ok, "created": self.created,
                "errors": [i.as_dict() for i in self.errors],
                "warnings": [i.as_dict() for i in self.warnings],
                "info": [i.as_dict() for i in self.issues if i.severity == INFO]}

    def summary(self) -> str:
        lines = [f"Размеров создано: {len(self.created)}; ошибок: {len(self.errors)}, "
                 f"предупреждений: {len(self.warnings)}"]
        lines += [f"  [{i.severity}] {i.message}" for i in self.issues]
        return "\n".join(lines)


# --- координаты вида ------------------------------------------------------------------------
class _Frame:
    """Вид без поворота: лист = origin + scale · вид."""

    def __init__(self, view: "View") -> None:
        if abs(view.angle) > 1e-9:
            raise OperationFailedError("Размеры", f"вид {view.name!r} повёрнут — пока не поддерживается")
        self.o = view.origin
        self.k = view.scale

    def sheet(self, x: float, y: float) -> Point:
        return Point(self.o.x + x * self.k, self.o.y + y * self.k)

    def view(self, p: Point) -> Point:
        return Point((p.x - self.o.x) / self.k, (p.y - self.o.y) / self.k)

    def seg(self, s: Segment) -> Segment:
        return Segment(self.sheet(s.a.x, s.a.y), self.sheet(s.b.x, s.b.y))


def _pt(p) -> Point:
    return p if isinstance(p, Point) else Point(float(p[0]), float(p[1]))


def _text_parts(ks, dim_obj) -> tuple[str, str, int, float, float, float]:
    dt = ks.IDimensionText(dim_obj)
    pre, suf = dt.GetPrefix(), dt.GetSuffix()
    return (pre.GetStr() if pre else "", suf.GetStr() if suf else "", int(dt.GetSign()),
            float(dt.GetNominalValue()), float(dt.GetWidth()), float(dt.GetHeight()))


def _fmt(v: float) -> str:
    return f"{round(v, 3):g}".replace(".", ",")


# --- чтение ---------------------------------------------------------------------------------
def view_obstacles(view: "View", curves: Sequence | None = None) -> list[Segment]:
    """Линии изображения вида в мм листа: контур (окружности — ломаными), осевые линии, обозначения центров.

    Осевые и центры в ассоциативном виде — отдельные объекты (IAxisLine, ICentreMarker), а не кривые;
    берём их габариты: осевая — отрезок по длинной стороне, центр — перекрестие.
    """
    fr = _Frame(view)
    curves = view.curves() if curves is None else curves
    out = [fr.seg(s) for c in curves for s in c.segments()]
    ks, sym, drawing = view.ks, view.symbols, view.drawing
    for obj in _objects(ks, sym.GetAxisLines()):
        bb = drawing.objects_bbox([obj])
        if bb is None:
            continue
        c = bb.center
        if bb.width >= bb.height:
            out.append(Segment(Point(bb.x1, c.y), Point(bb.x2, c.y)))
        else:
            out.append(Segment(Point(c.x, bb.y1), Point(c.x, bb.y2)))
    for obj in _objects(ks, sym.GetCentreMarkers()):
        bb = drawing.objects_bbox([obj])
        if bb is None:
            continue
        c = bb.center
        out += [Segment(Point(bb.x1, c.y), Point(bb.x2, c.y)), Segment(Point(c.x, bb.y1), Point(c.x, bb.y2))]
    out += leader_segments(view)
    for getter in ('GetRadialDimensions','GetAngleDimensions'):
        for obj in _objects(ks,getattr(sym,getter)()):
            params = ks.IDimensionParams(obj)
            if params.GetTextType() == int(raw.ksDimensionTextTypeEnum.ksDTPOnShelf):
                tip = ks.IDimension2D(obj).GetTextPosition(0,0)
                if tip[0]:
                    out.append(Segment(fr.sheet(tip[1],tip[2]),fr.sheet(obj.GetShelfX(),obj.GetShelfY())))
    return out


def leader_segments(view: "View") -> list[Segment]:
    """Ветви и полки выносок вида отрезками (мм листа)."""
    ks, fr, out = view.ks, _Frame(view), []
    for obj in _objects(ks, view.symbols.GetLeaders()):
        branch = ks.IBranchs(obj)
        shelf = fr.sheet(branch.GetX0(), branch.GetY0())
        for i in range(branch.GetBranchCount()):
            values = branch.GetBranchPoints(i)
            points = [fr.sheet(values[j], values[j+1]) for j in range(0, len(values)-1, 2)]
            if not points:
                points = [fr.sheet(branch.GetBranchX(i), branch.GetBranchY(i))]
            points.append(shelf)
            out.extend(Segment(a, b) for a, b in zip(points, points[1:]))
    return out


def read_dims(view: "View", content: Rect | None = None) -> list[LinearDim]:
    """Горизонтальные и вертикальные линейные размеры вида (мм листа, фактическое положение надписей).

    В `meta` — raw-объект, точки в координатах вида, признаки диаметра и справочного размера.
    """
    ks = view.ks
    fr = _Frame(view)
    content = content if content is not None else view.content_bbox()
    coll = view.symbols.GetLineDimensions()
    out: list[LinearDim] = []
    for i in range(coll.GetCount()):
        d = coll.GetLineDimension(i)
        o = int(d.GetOrientation())
        if o == _P:
            # «Параллельный» (так приходят размеры, перенесённые из 3D-модели, s88): горизонтальный или
            # вертикальный по факту точек; наклонные пропускаем, как и раньше.
            dx, dy = abs(d.GetX2() - d.GetX1()), abs(d.GetY2() - d.GetY1())
            o = _H if dy <= 1e-4 * max(1.0, dx) else _V if dx <= 1e-4 * max(1.0, dy) else o
        if o not in (_H, _V):
            continue
        axis = "x" if o == _H else "y"
        out.append(_read_linear(view, d, f"{view.number}:L{i}", axis, content))
    return out


def _read_linear(view, d, key, axis, content):
    ks, fr = view.ks, _Frame(view)
    v1, v2 = Point(d.GetX1(), d.GetY1()), Point(d.GetX2(), d.GetY2())
    p1, p2 = fr.sheet(v1.x, v1.y), fr.sheet(v2.x, v2.y)
    d2 = ks.IDimension2D(d)
    lp = d2.GetDimensionPoint(int(_PT.ksDimensionLinePoint), 0, 0, 0)
    lpt = fr.sheet(lp[1], lp[2]) if lp and lp[0] else fr.sheet(d.GetX3(), d.GetY3())
    line = lpt.y if axis == "x" else lpt.x
    tp = d2.GetTextPosition(0, 0)
    tpt = fr.sheet(tp[1], tp[2])
    start = tpt.x if axis == "x" else tpt.y
    pre, suf, sign, nominal, w, h = _text_parts(ks, d)
    diameter = DIAMETER_SIGN in pre or sign == 1
    label = f"{pre if pre else (DIAMETER_SIGN if sign == 1 else '')}{_fmt(nominal)}{suf}"
    ld = LinearDim(key, p1, p2, axis, line, w, h, text_mode="manual", text_start=start,
                   label=label)
    if start + w <= ld.lo + 0.05:
        ld.text_mode = "lo"
    elif start >= ld.hi - 0.05:
        ld.text_mode = "hi"
    mid = ld.pt((ld.lo + ld.hi) / 2, line)
    ld.inside = bool(content and content.contains_point(mid, tol=-0.01))
    ld.meta.update(raw=d, v1=v1, v2=v2, diameter=diameter, reference="*" in suf, nominal=nominal,
                   view=view.number)
    real = view.drawing.objects_bbox([d])
    if real is not None:
        ld.meta["real"] = real
        align_text_to_extent(ld, real, DimStyle())
    return ld


def read_diametral(view: "View") -> list[DiametralDim]:
    """Диаметральные размеры вида (мм листа, фактическое положение надписи)."""
    ks = view.ks
    fr = _Frame(view)
    out: list[DiametralDim] = []
    for i, obj in enumerate(_objects(ks, view.symbols.GetDiametralDimensions())):
        out.append(_read_diameter(view, obj, f"{view.number}:D{i}"))
    return out


def _read_diameter(view, obj, key):
    ks, fr = view.ks, _Frame(view)
    dd = ks.IDiametralDimension(obj)
    c = fr.sheet(dd.GetXc(), dd.GetYc())
    r = float(dd.GetRadius()) * fr.k
    pre, suf, sign, nominal, w, h = _text_parts(ks, obj)
    label = f"{pre}{_fmt(nominal)}{suf}"
    dm = DiametralDim(key, c, r, float(dd.GetAngle()), w, h, label=label)
    tp = ks.IDimension2D(obj).GetTextPosition(0, 0)
    p = fr.sheet(tp[1], tp[2])
    ux, uy = dm.u
    ts = (p.x - c.x) * ux + (p.y - c.y) * uy
    t1, t2 = (ts, ts + w) if dm.reading == dm.u else (ts - w, ts)
    dm.text_t = (t1 + t2) / 2
    dm.text_mode = "out" if t1 >= r - 0.05 else "manual"
    dm.meta.update(raw=obj, reference="*" in suf, nominal=nominal, view=view.number,
                   broken=bool(dd.GetDimensionType()))
    real = view.drawing.objects_bbox([obj])
    if real is not None:
        dm.meta["real"] = real
    return dm


def annotation_keepouts(view: "View", content: Rect | None = None) -> list[tuple[Rect, str]]:
    """Зоны прочих обозначений вида, куда нельзя ставить размеры.

    Нелинейные размеры — целиком; линии разреза, выноски, шероховатости, базы — части габарита вне контура
    (сама линия разреза внутри контура размерам не мешает, мешают штрихи, стрелки и буквы снаружи).
    """
    ks = view.ks
    sym = view.symbols
    drawing = view.drawing
    content = content if content is not None else view.content_bbox()
    out: list[tuple[Rect, str]] = []
    for getter, name in (("GetRadialDimensions", "радиус"), ("GetAngleDimensions", "угловой размер"),
                         ("GetArcDimensions", "размер дуги")):
        for obj in _objects(ks, getattr(sym, getter)()):
            bb = drawing.objects_bbox([obj])
            if bb:
                params = ks.IDimensionParams(obj)
                if getter != 'GetArcDimensions' and params.GetTextType() == int(raw.ksDimensionTextTypeEnum.ksDTPOnShelf):
                    text = ks.IDimensionText(obj)
                    # Надпись — у полки (а не в углу габарита: ветвь может уходить выше и правее надписи).
                    w, h = text.GetWidth(), text.GetHeight()
                    shelf = _Frame(view).sheet(obj.GetShelfX(), obj.GetShelfY())
                    left = params.GetShelfDirection() == int(raw.ksShelfDirectionEnum.ksLSLeft)
                    x1 = shelf.x - w if left else shelf.x
                    out.append((Rect(x1, shelf.y, x1 + w, shelf.y + h), name))
                    continue
                out.append((bb, name))
    for getter, name in (("GetCutLines", "линия разреза"), ("GetLeaders", "выноска"), ("GetRoughs", "шероховатость"),
                         ("GetBases", "база"), ("GetTolerances", "допуск формы"), ("GetViewPointers", "стрелка вида")):
        for obj in _objects(ks, getattr(sym, getter)()):
            bb = drawing.objects_bbox([obj])
            if not bb:
                continue
            if getter == "GetLeaders":
                leader=ks.ILeader(obj)
                branch=ks.IBranchs(obj)
                shelf=_Frame(view).sheet(branch.GetX0(),branch.GetY0())
                # Габарит выноски включает диагональную ветвь — как зона он накрывает соседние размеры.
                # Запретна только полоса надписи над полкой (высотой не больше LEADER_TEXT_H);
                # ветвь проверяется отрезком из view_obstacles.
                if leader.GetTextOnShelf().GetStr() and not leader.GetTextUnderShelf().GetStr():
                    direction=leader.GetShelfDirection()
                    measured=leader_texts(drawing).get(_obj_id(ks,obj))
                    if measured:            # ширина надписи измерена при создании (add_leaders)
                        w=measured[0]
                        x1,x2=(shelf.x-w,shelf.x) if direction==int(raw.ksShelfDirectionEnum.ksLSLeft) else (shelf.x,shelf.x+w)
                    else:
                        x1,x2=(bb.x1,shelf.x) if direction==int(raw.ksShelfDirectionEnum.ksLSLeft) else (shelf.x,bb.x2)
                    y2=min(bb.y2,shelf.y+(measured[1] if measured else LEADER_TEXT_H))
                    if x2>x1 and y2>shelf.y:
                        out.append((Rect(x1,shelf.y+DimStyle().text_gap,x2,y2),name))
                        continue
            if content is None:
                out.append((bb, name))
                continue
            for part in _outside_parts(bb, content):
                out.append((part, name))
    return out


def leader_cost(line: Segment, crossings: int, above_contour: bool) -> float:
    """Цена ветви выноски/полки радиуса, мм: пересечение размерной линии или другой выноски — как 30 мм длины,
    полка над изображением (мешает выносным линиям длин) — как 15 мм. Короткая ветвь с одним пересечением
    лучше ветви через полчертежа."""
    return line.length + 30.0 * crossings + (15.0 if above_contour else 0.0)


def leader_texts(drawing) -> dict:
    """Размеры надписей выносок, поставленных библиотекой: id объекта -> (ширина, высота), мм листа.
    API выноски ширину надписи не отдаёт, а по габариту её не отделить от ветви."""
    store = getattr(drawing, "_leader_texts", None)
    if store is None:
        store = drawing._leader_texts = {}
    return store


def view_title_bbox(view: "View") -> Rect | None:
    """Габарит надписи вида («А–А», «Б (2:1)») на листе; у вида без надписи — None."""
    des = view.ks.IViewDesignation(view.raw)
    text = des.GetDrawingText() if des else None
    bb = view.drawing.objects_bbox([text]) if text else None
    return bb if bb is not None and bb.width > 1e-6 and bb.height > 1e-6 else None


def scene_keepouts(view: "View", content: Rect | None = None,
                   style: DimStyle | None = None) -> list[tuple[Rect, str]]:
    """Все зоны листа, куда размерам вида нельзя: одна сцена для раскладки, выносок и проверки.

    Обозначения этого вида (линии разреза, выноски, …), надписи всех видов («А–А»), другие виды целиком
    (с их размерами и обозначениями), основная надпись.
    """
    style = style or DimStyle()
    drawing = view.drawing
    margin = style.text_gap / 2
    # Полосы обозначений примыкают к изображению вплотную — без запаса, иначе они зайдут на контур,
    # вдоль которого законно идут выносные линии.
    out = list(annotation_keepouts(view, content))
    for other in drawing.views:
        title = view_title_bbox(other)
        if title is not None:
            out.append((title.inflate(margin), f"надпись вида {other.name!r}"))
        if other.number != view.number and (bb := other.bbox()) is not None:
            out.append((bb.inflate(style.text_margin), f"вид {other.name!r}"))
    out += [(r, "основная надпись") for r in drawing.sheet.keepouts]
    return out


def _objects(ks, coll) -> list:
    """Объекты коллекции ISymbols2DContainer: ICutLines.GetCutLine(i), IRoughs.GetRough(i) и т.п."""
    if not coll:
        return []
    name = type(coll).__name__
    getter = getattr(coll, f"Get{name[1:-1]}", None) if name.startswith("I") and name.endswith("s") else None
    if getter is None:
        return []
    return [o for o in (getter(i) for i in range(coll.GetCount())) if o]


def _outside_parts(bb: Rect, content: Rect) -> list[Rect]:
    """Части прямоугольника вне `content` (до 4 полос)."""
    parts = []
    if bb.y2 > content.y2:
        parts.append(Rect(bb.x1, max(bb.y1, content.y2), bb.x2, bb.y2))
    if bb.y1 < content.y1:
        parts.append(Rect(bb.x1, bb.y1, bb.x2, min(bb.y2, content.y1)))
    y1, y2 = max(bb.y1, content.y1), min(bb.y2, content.y2)
    if y2 > y1:
        if bb.x2 > content.x2:
            parts.append(Rect(max(bb.x1, content.x2), y1, bb.x2, y2))
        if bb.x1 < content.x1:
            parts.append(Rect(bb.x1, y1, min(bb.x2, content.x1), y2))
    return [p for p in parts if p.width > 1e-6 and p.height > 1e-6]


# --- создание -------------------------------------------------------------------------------
def _snap_vertex(p: Point, verts: Sequence[Point]) -> tuple[Point, bool]:
    best, dist = None, SNAP_TOL
    for v in verts:
        d = p.dist(v)
        if d <= dist:
            best, dist = v, d
    return (best, True) if best is not None else (p, False)


def _hidden_point(point: Point, curves: Sequence) -> bool:
    """Точка относится только к скрытому контуру; совпавший видимый имеет приоритет."""
    matched = [curve for curve in curves if any(v.dist(point) <= SNAP_TOL for v in curve.vertices())]
    return bool(matched) and all(curve.is_hidden for curve in matched)


def _axis(spec: Dim, p1: Point, p2: Point) -> str:
    """Ось размера: заданная или по преобладающему направлению между точками."""
    if spec.axis in ("x", "y"):
        return spec.axis
    if spec.axis != "auto":
        raise ValueError(f"Размер {spec.key!r}: axis должен быть 'x', 'y' или 'auto'")
    dx, dy = abs(p1.x - p2.x), abs(p1.y - p2.y)
    if dx < 1e-9 and dy < 1e-9:
        raise ValueError(f"Размер {spec.key!r}: точки совпадают")
    return "x" if dx >= dy else "y"


def _find_circle(spec: Diameter, curves: Sequence):
    c0 = _pt(spec.center)
    cands = [c for c in curves if c.kind in ("circle", "arc") and c.center is not None and c.center.dist(c0) <= SNAP_TOL]
    if spec.radius is not None:
        cands = [c for c in cands if abs(c.radius - spec.radius) <= SNAP_TOL]
    if not cands:
        raise ValueError(f"Размер {spec.key!r}: на виде нет окружности с центром {c0}"
                         + (f" и радиусом {spec.radius:g}" if spec.radius is not None else ""))
    if len(cands) > 1 and max(c.radius for c in cands)-min(c.radius for c in cands) > SNAP_TOL:
        raise ValueError(f"Размер {spec.key!r}: несколько окружностей с центром {c0} "
                         f"(радиусы {sorted(c.radius for c in cands)}) — укажите radius")
    # Проекция цилиндра может состоять из нескольких дуг одной окружности.
    # У диаметра есть прямая связь с опорной дугой; синтетическая окружность не нужна.
    return next((curve for curve in cands if curve.kind == 'circle'), cands[0])

def overall_dims(view: "View", curves: Sequence | None = None, side_x: str = "top", side_y: str = "left",
                 key_prefix: str = "overall") -> list[Dim]:
    """Габаритные размеры изображения: ширина (по X вида) и высота (по Y вида).

    Крайние точки — истинные, с квадрантными точками окружностей и дуг (у круглых деталей крайняя точка —
    не вершина: по вершинам ширина круглого фланца выходит меньше настоящей, spikes/s19_reducer).
    Из точек на крайней линии берётся вершина, если она есть (тогда размер привяжется через Associate());
    иначе — точка дуги, и add_dimensions предупредит, что размер не связан с геометрией.
    Среди равноправных точек выбирается ближайшая к стороне размера — выносные линии короче и не пересекаются.
    """
    curves = view.curves() if curves is None else curves
    geo = [c for c in curves if not c.is_axial]
    pts = [p for c in geo for p in c.extremes()]
    if not pts:
        raise OperationFailedError("Габаритные размеры", f"на виде {view.name!r} нет геометрии")
    verts = [p for c in geo for p in c.vertices()]

    def pick(coord: str, lo: bool, toward: str) -> Point:
        val = (min if lo else max)(getattr(p, coord) for p in pts)
        on = [p for p in verts if abs(getattr(p, coord) - val) <= SNAP_TOL] or \
             [p for p in pts if abs(getattr(p, coord) - val) <= SNAP_TOL]
        key = {"top": lambda p: -p.y, "bottom": lambda p: p.y, "left": lambda p: p.x, "right": lambda p: -p.x}[toward]
        return min(on, key=key)

    w1, w2 = pick("x", True, side_x), pick("x", False, side_x)
    h1, h2 = pick("y", True, side_y), pick("y", False, side_y)
    return [Dim(w1, w2, axis="x", side=side_x, key=f"{key_prefix}_x"),
            Dim(h1, h2, axis="y", side=side_y, key=f"{key_prefix}_y")]

def suggest_revolution_dims(view: "View", profile, curves: Sequence | None = None,
                            tol: float = 0.01, end_view: "View | None" = None,
                            diameter_policy: str = "section") -> tuple[list[Dim | Diameter], list[str]]:
    """Черновой набор размеров тела вращения на виде, где ось детали лежит в плоскости вида.

    `profile` — `dims.revolution.revolution_profile(model.faces())`. Длины — между торцами/уступами (цепочка без
    одного звена + габарит), диаметры — каждой ступени и отверстия, линия Ø внутри изображения посередине ступени.
    Точки берутся в настоящих вершинах вида (размеры привязываются к геометрии). Отверстия видны только в разрезе
    (`View.cut`). Возвращает (задания для add_dimensions, заметки: что не поставлено и почему, что оформить иначе).
    Это черновик: что оставить, перенести или сделать справочным — решает агент/конструктор.
    """
    # из kompas_lib.dims.revolution: draft_dimensions
    if diameter_policy not in ("section", "end"):
        raise ValueError("diameter_policy: section | end")

    curves = view.curves() if curves is None else curves
    ax = profile.axis
    proj_cache: dict = {}

    def P(t: float, j: int | None = None, r: float = 0.0) -> Point:
        key = (round(t, 9), j, round(r, 9))
        if key not in proj_cache:
            c = [0.0, 0.0, 0.0]
            c[ax] = t
            for jj, v in profile.center.items():
                c[jj] = v
            if j is not None:
                c[j] += r
            proj_cache[key] = view.project_point(*c)
        return proj_cache[key]

    p0, p1 = P(profile.t_min), P(profile.t_max)
    dx, dy = p1.x - p0.x, p1.y - p0.y
    if math.hypot(dx, dy) < 1e-6 * max(1.0, profile.length):
        return [], [f"Вид {view.name!r}: ось детали перпендикулярна виду (вид с торца) — профиль на нём не образмеривается"]
    horizontal = abs(dx) >= abs(dy)
    if min(abs(dx), abs(dy)) > 1e-6 * max(abs(dx), abs(dy)):
        return [], [f"Вид {view.name!r}: ось детали наклонена на виде — нужен вид, где она горизонтальна или вертикальна"]

    def along(q: Point) -> float:
        return q.x if horizontal else q.y

    def perp(q: Point) -> float:
        return (q.y - p0.y) if horizontal else (q.x - p0.x)

    verts: list[Point] = []
    for c in curves:
        if c.is_axial:
            continue
        for v in c.vertices():
            if not any(abs(v.x - u.x) <= 1e-9 and abs(v.y - u.y) <= 1e-9 for u in verts):
                verts.append(v)

    def node_vertex(t: float, outer: bool = False) -> Point | None:
        a = along(P(t))
        cands = [v for v in verts if abs(along(v) - a) <= tol]
        # Габарит вынесен с противоположной стороны от цепочки длин.
        # Берём вершину именно на этой стороне, чтобы выносная не шла через тело.
        return (min if outer else max)(cands, key=perp) if cands else None

    lengths, diams, notes = draft_dimensions(profile, scale=view.scale)
    len_axis, len_side = ("x", "top") if horizontal else ("y", "right")
    specs: list[Dim] = []
    for ld in lengths:
        va, vb = node_vertex(ld.a, ld.overall), node_vertex(ld.b, ld.overall)
        if va is None or vb is None:
            notes.append(f"Длина {ld.key} ({ld.b - ld.a:g}): на виде нет линии торца/уступа "
                         f"при {AXES_NAME[ax]}={ld.a if va is None else ld.b:g} — размер не предложен")
            continue
        side = ("bottom" if horizontal else "left") if ld.overall else "auto"
        specs.append(Dim(va, vb, axis=len_axis, side=side, key=ld.key))
    d_axis = "y" if horizontal else "x"
    # стороны «у начала» и «у конца» оси на виде (для Ø снаружи изображения)
    lo_side, hi_side = ("left", "right") if horizontal else ("bottom", "top")
    if along(P(profile.t_max)) < along(P(profile.t_min)):
        lo_side, hi_side = hi_side, lo_side
    ends_tol = 1e-3
    for dd in diams:
        s = dd.step
        if dd.end_view and diameter_policy == "end":
            if end_view is not None:
                c = [0.0, 0.0, 0.0]
                c[ax] = (s.t1 + s.t2) / 2
                for j, val in profile.center.items():
                    c[j] = val
                center = end_view.project_point(*c)
                circles = end_view.curves()
                if any(q.kind == "circle" and q.center.dist(center) <= tol and abs(q.radius - s.r) <= tol
                       for q in circles):
                    # Торцевые задания возвращает suggest_end_dimensions; на продольном виде не дублируем.
                    continue
            notes.append(f"Ø{_fmt(2 * s.r)}: короткая ступень {s.length:g} мм — Diameter на виде с торца")
            continue
        a1, a2 = sorted((along(P(s.t1)), along(P(s.t2))))
        over_bore = (not s.inner) and any(min(s.t2, b.t2) - max(s.t1, b.t1) > ends_tol for b in profile.inner)
        side, at, near = "inside", along(P((s.t1 + s.t2) / 2)), a1
        if over_bore:
            # над отверстием Ø внутри лёг бы на размер отверстия: снаружи у торца, если ступень на него выходит,
            # иначе — внутри со сдвигом на четверть длины от середины (там Ø отверстия)
            if abs(s.t1 - profile.t_min) <= ends_tol:
                side, near = lo_side, along(P(s.t1))
            elif abs(s.t2 - profile.t_max) <= ends_tol:
                side, near = hi_side, along(P(s.t2))
            else:
                at = along(P(s.t1 + 0.25 * s.length))
        if dd.end_view:
            side = lo_side if s.inner else hi_side
        top = [v for v in verts if abs(perp(v) - s.r) <= tol and a1 - tol <= along(v) <= a2 + tol]
        pair = None
        for q in sorted(top, key=lambda v: abs(along(v) - near)):
            bot = [v for v in verts if abs(perp(v) + s.r) <= tol and abs(along(v) - along(q)) <= tol]
            if bot:
                pair = (q, bot[0])
                break
        what = "отверстия" if s.inner else "ступени"
        if pair is None:
            hint = " — нужен разрез (View.cut)" if s.inner else ""
            notes.append(f"Ø{_fmt(2 * s.r)} {what} ({AXES_NAME[ax]}={s.t1:g}…{s.t2:g}) не виден на виде {view.name!r}{hint}")
            continue
        specs.append(Dim(pair[0], pair[1], axis=d_axis, side=side, at=at if side == "inside" else None,
                         diameter=True, key=dd.key, at_range=(a1,a2) if side == "inside" else None))
    return specs, notes


def suggest_end_dimensions(view: "View", profile, scale: float | None = None,
                           tol: float = 0.01, diameter_policy: str = "section") -> tuple[list[Diameter], list[str]]:
    """Диаметры коротких ступеней/колец на торцевом виде; scale — масштаб продольного вида."""
    # из kompas_lib.dims.revolution: draft_dimensions
    if diameter_policy == "section":
        return [], []
    _, diams, _ = draft_dimensions(profile, scale=view.scale if scale is None else scale)
    curves = view.curves()
    out, notes = [], []
    for dd in diams:
        if not dd.end_view:
            continue
        c = [0.0, 0.0, 0.0]
        c[profile.axis] = (dd.step.t1 + dd.step.t2) / 2
        for j, val in profile.center.items():
            c[j] = val
        center = view.project_point(*c)
        if any(q.kind == "circle" and q.center.dist(center) <= tol and abs(q.radius - dd.step.r) <= tol
               for q in curves):
            out.append(Diameter(center, dd.step.r, key=dd.key))
        else:
            notes.append(f"Ø{_fmt(2 * dd.step.r)}: окружность не видна на торцевом виде — нужен разрез/местный вид")
    return out, notes


AXES_NAME = "XYZ"


def _too_small(key, what: str, on_sheet: float, style: DimStyle) -> Issue:
    return Issue("feature_too_small", ERROR,
                 f"Размер {key!r} не поставлен: {what} на листе {on_sheet:.2f} мм (< {style.min_feature:g} мм) — "
                 f"нечитаемо; нужен выносной элемент (ГОСТ 2.305) или более крупный масштаб", (key,))


def prune_redundant(specs: Sequence[Dim | Diameter], existing: Sequence[tuple[str, float, float]] = (),
                    policy: str = "drop", tol: float = 1e-3) -> tuple[list[Dim | Diameter], list[Issue]]:
    """Убрать из набора лишние линейные размеры до постановки (ГОСТ 2.307: без повторов и замкнутых цепей).

    Порядок `specs` — приоритет: размеры идут по очереди, и размер, все концы которого уже связаны
    предыдущими (дубликат или замыкание цепи), считается лишним. Поэтому габариты и размеры формы
    ставьте раньше координат. По каждой оси вида строится лес, как в `redundancy.check_redundancy`.
    `existing` — уже стоящие на виде размеры: (ось вида 'x'|'y', a, b).
    policy: "drop" — не ставить; "reference" — оставить справочным («*»).
    Диаметральные размеры окружностей (`Diameter`) и справочные не проверяются и проходят как есть.
    """
    if policy not in ("drop", "reference"):
        raise ValueError("policy: drop | reference")
    # из kompas_lib.dims.redundancy: _Forest, _Nodes
    nodes = {"x": _Nodes(tol), "y": _Nodes(tol)}
    forests = {"x": _Forest(), "y": _Forest()}
    for n, (axis, a, b) in enumerate(existing):
        u, v = nodes[axis].get(a), nodes[axis].get(b)
        if u != v:
            forests[axis].add(u, v, f"existing{n}")
    kept: list[Dim | Diameter] = []
    issues: list[Issue] = []
    for spec in specs:
        if not isinstance(spec, Dim) or spec.reference:
            kept.append(spec)
            continue
        p1, p2 = _pt(spec.p1), _pt(spec.p2)
        axis = _axis(spec, p1, p2)
        a, b = (p1.x, p2.x) if axis == "x" else (p1.y, p2.y)
        ns, fr = nodes[axis], forests[axis]
        ends = [a, (a + b) / 2, b] if spec.diameter else [a, b]     # Ø: край — ось — край
        edges = [(ns.get(s), ns.get(t)) for s, t in zip(ends, ends[1:])]
        edges = [(u, v) for u, v in edges if u != v]
        if not edges:
            kept.append(spec)
            continue
        if all(fr.find(u) == fr.find(v) for u, v in edges):
            label = (DIAMETER_SIGN if spec.diameter else "") + spec.prefix + _fmt(abs(b - a))
            if policy == "reference":
                spec.reference = True
                kept.append(spec)
                action = "оставлен справочным «*»"
            else:
                action = "не ставится"
            issues.append(Issue("redundant", INFO, f"Размер «{label}» по оси {axis} вида уже определён другими "
                                                   f"размерами (повтор или замкнутая цепь) — {action}", (spec.key,)))
            continue
        for u, v in edges:
            fr.add(u, v, spec.key)
        kept.append(spec)
    return kept, issues



def add_dimensions(view: "View", specs: Sequence[Dim | Diameter], style: DimStyle | None = None,
                   max_tiers: int = 8) -> DimReport:
    """Поставить размеры на вид: привязка, раскладка без пересечений, проверка результата.

    Dim — линейный (горизонтальный/вертикальный), Diameter — диаметр окружности.
    Всё — одним шагом отмены. Уже стоящие размеры вида не двигаются (учитываются как препятствия).
    """
    style = style or DimStyle()
    ks = view.ks
    drawing = view.drawing
    fr = _Frame(view)
    curves = view.curves()
    verts = [v for c in curves for v in c.vertices()]
    content = view.content_bbox(curves)
    if content is None:
        raise OperationFailedError("Размеры", f"на виде {view.name!r} нет геометрии")
    obstacles = view_obstacles(view, curves)
    existing = read_dims(view, content) + read_diametral(view)
    keepouts = scene_keepouts(view, content, style)
    report = DimReport()

    # проверка входа до каких-либо изменений документа
    prepared = []
    prepared_diam = []
    for n, spec in enumerate(specs):
        spec.key = spec.key if spec.key is not None else f"dim{n + 1}"
        if isinstance(spec, Diameter):
            circ = _find_circle(spec, curves)
            if circ.is_hidden:
                report.issues.append(Issue("hidden_contour", ERROR,
                    f"Размер {spec.key!r} относится к скрытой окружности: нужен разрез или другой вид", (spec.key,)))
                continue
            if 2 * circ.radius * fr.k < style.min_feature:
                report.issues.append(_too_small(spec.key, f"окружность Ø{_fmt(2 * circ.radius)}",
                                                2 * circ.radius * fr.k, style))
                continue
            prepared_diam.append((spec, circ))
            continue
        p1, ok1 = _snap_vertex(_pt(spec.p1), verts)
        p2, ok2 = _snap_vertex(_pt(spec.p2), verts)
        if _hidden_point(p1, curves) or _hidden_point(p2, curves):
            report.issues.append(Issue("hidden_contour",ERROR,
                f"Размер {spec.key!r} относится к невидимому контуру: нужен разрез или другой вид",(spec.key,)))
            continue
        axis = _axis(spec, p1, p2)
        size = abs(p1.x - p2.x) if axis == "x" else abs(p1.y - p2.y)
        if size * fr.k < style.min_feature:
            report.issues.append(_too_small(spec.key, f"расстояние {_fmt(size)}", size * fr.k, style))
            continue
        prepared.append((spec, p1, ok1, p2, ok2, axis))

    with drawing.edit():
        coll = view.symbols.GetLineDimensions()
        made: list[tuple[Dim, object, str, Point, Point, bool]] = []
        requests: list[DimRequest] = []
        for spec, p1, ok1, p2, ok2, axis in prepared:
            key = spec.key
            d = coll.Add()
            d.SetX1(p1.x); d.SetY1(p1.y); d.SetX2(p2.x); d.SetY2(p2.y)
            d.SetOrientation(_H if axis == "x" else _V)
            if axis == "x":
                d.SetX3((p1.x + p2.x) / 2); d.SetY3(max(p1.y, p2.y) + 10 / fr.k)
            else:
                d.SetX3(max(p1.x, p2.x) + 10 / fr.k); d.SetY3((p1.y + p2.y) / 2)
            dt = ks.IDimensionText(d)
            pre = (DIAMETER_SIGN if spec.diameter else "") + spec.prefix
            suf = spec.suffix + ("*" if spec.reference else "")
            if pre:
                dt.GetPrefix().SetStr(pre)
            if suf:
                dt.GetSuffix().SetStr(suf)
            check(d.Update(), "Создание размера", str(key))
            assoc = bool(ks.IDrawingObject(d).Associate()) if (ok1 and ok2) else False
            params = ks.IDimensionParams(d)
            params.SetTextType(int(_TT.ksDimTAuto))
            params.SetArrowPos(int(raw.ksDimensionArrowPosEnum.ksDimArrowAuto))
            check(d.Update(), "Настройка размера", str(key))
            _, _, _, nominal, w, h = _text_parts(ks, d)
            label = f"{pre}{_fmt(nominal)}{suf}"
            s1, s2 = fr.sheet(p1.x, p1.y), fr.sheet(p2.x, p2.y)
            at = None
            if spec.at is not None:
                at = fr.sheet(spec.at, 0).x if axis == "y" else fr.sheet(0, spec.at).y
            at_range = None
            side = spec.side
            if spec.at_range is not None:
                a,b = spec.at_range
                at_range = ((fr.sheet(a,0).x, fr.sheet(b,0).x) if axis == "y" else
                            (fr.sheet(0,a).y, fr.sheet(0,b).y))
                if abs(at_range[1]-at_range[0]) < style.text_gap+h-style.ink_normal+style.tol:
                    side,at,at_range = "auto",None,None
            requests.append(DimRequest(s1, s2, axis, w, h, key=key, side=side, at=at, label=label,at_range=at_range))
            made.append((spec, d, axis, p1, p2, assoc))
            if not (ok1 and ok2):
                report.issues.append(Issue("not_associated", WARNING,
                                           f"Размер «{label}»: точка не совпадает с вершиной/серединой линии вида — "
                                           f"размер не связан с геометрией и не обновится при изменении модели",
                                           (key,)))
            elif not assoc:
                report.issues.append(Issue("not_associated", WARNING,
                                           f"Размер «{label}»: Associate() не создал связей", (key,)))
        made_diam = []
        dcoll = view.symbols.GetDiametralDimensions()
        for spec, circ in prepared_diam:
            d = dcoll.Add()
            d.SetBaseObject(ks.IDrawingObject(circ.raw))
            d.SetXc(circ.center.x); d.SetYc(circ.center.y); d.SetRadius(circ.radius)
            d.SetAngle(spec.angle if spec.angle is not None else 45.0)
            d.SetDimensionType(False)           # полная размерная линия через центр
            dt = ks.IDimensionText(d)
            dt.GetPrefix().SetStr(DIAMETER_SIGN)
            suf = spec.suffix + ("*" if spec.reference else "")
            if suf:
                dt.GetSuffix().SetStr(suf)
            check(d.Update(), "Создание диаметрального размера", str(spec.key))
            params = ks.IDimensionParams(d)
            params.SetTextType(int(_TT.ksDimTAuto))
            params.SetArrowPos(int(raw.ksDimensionArrowPosEnum.ksDimArrowAuto))
            check(d.Update(), "Настройка диаметрального размера", str(spec.key))
            assoc = bool(ks.IDrawingObject(d).GetConstraints())
            _, _, _, nominal, w, h = _text_parts(ks, d)
            label = f"{DIAMETER_SIGN}{_fmt(nominal)}{suf}"
            c = fr.sheet(circ.center.x, circ.center.y)
            outer_radius = max(c.dist(fr.sheet(point.x,point.y)) for curve in curves for point in curve.extremes())
            requests.append(DiamRequest(c, circ.radius * fr.k, w, h, key=spec.key, angle=spec.angle,
                                        label=label,outer_radius=outer_radius))
            made_diam.append((spec, d, circ, assoc))
            if not assoc:
                report.issues.append(Issue("not_associated", WARNING,
                                           f"Размер «{label}» не связан с окружностью", (spec.key,)))

        objects = {spec.key: (d, p1, p2) for spec, d, axis, p1, p2, _ in made}
        objects.update({spec.key: (d, None, None) for spec, d, circ, _ in made_diam})
        realize = _make_realize(view, objects, style, content)
        plan = plan_dimensions(requests, content, obstacles, fixed=existing, keepouts=[r for r, _ in keepouts],
                               style=style, max_tiers=max_tiers, realize=realize)
        by_key = {d.key: d for d in plan.dims}
        for spec, d, axis, p1, p2, assoc in made:
            ld = by_key.get(spec.key)
            if ld is None:
                ks.IDrawingObject(d).Delete()
                continue
            report.created.append({"key": str(spec.key), "label": ld.label, "associated": assoc,
                                   "side": plan.sides.get(spec.key), "tier": plan.tiers.get(spec.key),
                                   "text": ld.text_mode})
        for spec, d, circ, assoc in made_diam:
            dm = by_key[spec.key]
            report.created.append({"key": str(spec.key), "label": dm.label, "associated": assoc,
                                   "side": f"{dm.angle:g}°", "tier": 0, "text": dm.text_mode})
        _apply(view, plan.dims, realize, objects, {r.key: r for r in requests})
        report.issues += [i for i in plan.issues if i.kind in ("no_position", "dim_dropped")]

    drawing.invalidate_geometry(view, bounds_only=True)
    # проверяем то, что реально получилось в КОМПАСе; ключи спек сохраняем перечитыванием
    # известных объектов (read_dims даёт безликие 1:L5). Неразмещаемое без наложений сбрасывается.
    kept = {d.key for d in plan.dims} | {spec.key for spec, _d, _c, _a in made_diam}
    actual = [_read_linear(view, d, spec.key, axis, content)
              for spec, d, axis, _p1, _p2, _a in made if spec.key in kept] + \
             [_read_diameter(view, d, spec.key) for spec, d, _c, _a in made_diam]
    issues = check_dims(actual, obstacles, [r for r, _ in keepouts], style)
    notes, actual, issues = _drop_actual_violators(
        ks, made, actual, issues,
        lambda a: check_dims(a, obstacles, [r for r, _ in keepouts], style))
    report.created = [c for c in report.created
                      if c.get("key") not in {str(k) for n in notes for k in n.keys}]
    report.issues += notes + issues
    return report

def _drop_actual_violators(ks, made, actual, issues, check, rounds: int = 3):
    """Сброс неразмещаемого по факту: линейная цепочка/базовая, участвующая в ошибках
    проверки реально поставленного, удаляется из CAD (красных наложений быть не должно).
    Габариты, формы, ряды, пары и диаметры не сбрасываются. Возвращает примечания.
    `check` — callable(actual) -> issues для перепроверки после удаления.
    """
    _LD = LinearDim
    notes: list[Issue] = []
    doomed: set[str] = set()
    for _ in range(rounds):
        bad: dict[str, int] = {}
        for issue in issues:
            if issue.severity != ERROR:
                continue
            for k in issue.keys:
                ks_ = str(k)
                if (ks_.startswith("chain_") or ks_.startswith("pos_")) \
                        and ":pitch" not in ks_ and ":pair" not in ks_:
                    bad[ks_] = bad.get(ks_, 0) + 1
        bad = {ks_: n for ks_, n in bad.items() if ks_ not in doomed}
        if not bad:
            break
        victim = sorted(bad.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
        doomed.add(victim)
        for spec, d, *_rest in made:
            if str(spec.key) == victim:
                ks.IDrawingObject(d).Delete()
                break
        actual = [a for a in actual
                  if not (isinstance(a, _LD) and str(a.key) in doomed)]
        notes.append(Issue("dim_dropped", WARNING,
                           f"Размер «{victim}» не размещён без наложений — "
                           f"вынесите вручную или выносным элементом", (victim,)))
        issues = check(actual)
    return notes, actual, issues

# --- постановка в CAD и запомненная раскладка -------------------------------------------------
def _make_realize(view: "View", objects: dict, style: DimStyle, content: Rect | None):
    """Адаптер CAD для plan_dimensions: поставить размер в положение кандидата, вернуть факт (мм листа).

    objects: key -> (объект, v1, v2); v1, v2 — точки линейного размера в координатах вида (у диаметра — None).
    """
    ks, fr = view.ks, _Frame(view)
    bases = raw.ksDimensionBaseEnum

    def realize(c):
        actual = put(c)
        if model_mismatch(actual, style) > 0:
            # После перестановки с другой стороны КОМПАС может оставить в габарите след прошлого положения
            # (не рисуется, но габарит врёт). Повторная постановка в то же положение его снимает.
            actual = put(c)
        return actual

    def put(c):
        obj, v1, v2 = objects[c.key]
        if isinstance(c, DiametralDim):
            # В ручном режиме положение текста участвует в вычислении угла: сначала фиксируем
            # направление в автоматическом режиме, затем задаём положение надписи на этой линии.
            ks.IDimensionParams(obj).SetTextType(int(_TT.ksDimTAuto))
            check(obj.Update(), "Режим диаметрального размера")
            obj.SetAngle(c.angle)
            check(obj.Update(), "Направление диаметрального размера")
            s, e = c.text_interval(style)
            position_dimension_text(ks, obj, "manual", anchor=fr.view(c._at((s + e) / 2)))
            actual = _read_diameter(view, obj, c.key)
            actual.meta["placement"] = (c.angle, c.text_mode, c.text_t)
            return actual
        line = fr.view(c.pt(0, c.line))
        if c.axis == "x":
            obj.SetY3(line.y); obj.SetX3((v1.x + v2.x) / 2)
        else:
            obj.SetX3(line.x); obj.SetY3((v1.y + v2.y) / 2)
        base = int(bases.ksDimBaseCenter)
        if c.text_mode in ("lo", "hi"):
            first_low = (v1.x <= v2.x) if c.axis == "x" else (v1.y <= v2.y)
            base = int(bases.ksDimBaseP1 if (c.text_mode == "lo") == first_low else bases.ksDimBaseP2)
        s, e = c.text_range(style)
        position_dimension_text(ks, obj, c.text_mode, base=base, anchor=fr.view(c.pt((s + e) / 2, c.line)))
        actual = _read_linear(view, obj, c.key, c.axis, content)
        actual.meta["placement"] = (c.line, c.text_mode, c.text_start)
        return actual

    return realize


def _placed(d):
    """Кандидат с выбранным режимом надписи (meta["placement"]) — для повторной постановки в CAD.
    Ручное чтение геометрии не должно превращать автоматическое положение в ручное."""
    a, mode, t = d.meta["placement"]
    if isinstance(d, DiametralDim):
        return replace(d, angle=a, text_mode=mode, text_t=t, meta={})
    return replace(d, line=a, text_mode=mode, text_start=t, meta={})


def _shift(d, dx: float, dy: float):
    """Размер или запрос, перенесённый вместе с видом (мм листа)."""
    def p(q: Point) -> Point:
        return Point(q.x + dx, q.y + dy)

    if isinstance(d, (DiametralDim, DiamRequest)):
        return replace(d, center=p(d.center), **({"meta": {}} if isinstance(d, DiametralDim) else {}))
    along, normal = (dx, dy) if d.axis == "x" else (dy, dx)
    if isinstance(d, DimRequest):
        return replace(d, p1=p(d.p1), p2=p(d.p2), at=None if d.at is None else d.at + normal,
                       at_range=None if d.at_range is None else tuple(v + normal for v in d.at_range))
    return replace(d, p1=p(d.p1), p2=p(d.p2), line=d.line + normal, meta={},
                   text_start=None if d.text_start is None else d.text_start + along)


def _layout(view: "View") -> dict:
    """Запомненная раскладка вида: id объекта -> запрос, положение, точка привязки вида."""
    store = getattr(view.drawing, "_dim_layout", None)
    if store is None:
        store = view.drawing._dim_layout = {}
    return store.setdefault(view.number, {})


def _obj_id(ks, obj) -> int:
    return int(ks.IDrawingObject(obj).GetId())


def _apply(view: "View", dims: Sequence, realize, objects: dict, requests: dict) -> None:
    """Поставить выбранные положения (в CAD остался последний опробованный кандидат) и запомнить раскладку."""
    layout, origin = _layout(view), view.origin
    for d in dims:
        if d.key not in objects:
            continue
        actual = realize(_placed(d))
        obj, v1, v2 = objects[d.key]
        layout[_obj_id(view.ks, obj)] = {"obj": obj, "v1": v1, "v2": v2, "request": requests[d.key],
                                         "placed": _placed(actual), "actual": actual, "origin": origin}


def _same_place(a, b, style: DimStyle, tol: float = 0.2) -> bool:
    if isinstance(a, DiametralDim):
        return abs(a.angle - b.angle) < 0.01 and abs(sum(a.text_interval(style)) - sum(b.text_interval(style))) < 2 * tol
    return abs(a.line - b.line) < tol and abs(a.text_range(style)[0] - b.text_range(style)[0]) < tol


def restore_dimensions(view: "View", style: DimStyle | None = None) -> int:
    """После переноса вида вернуть размеры, поставленные библиотекой, в запомненные положения.

    В координатах вида раскладка от переноса не меняется, поэтому заново не планируется: размер ставится
    повторно, только если его надпись разошлась с запомненной или с фактическим габаритом объекта.
    Возвращает число переставленных размеров. Проверку и при необходимости `arrange_dimensions` — после.
    """
    style = style or DimStyle()
    layout = _layout(view)
    if not layout:
        return 0
    content = view.content_bbox()
    origin = view.origin
    todo, objects = [], {}
    for oid, entry in list(layout.items()):
        try:
            alive = bool(view.ks.IDrawingObject(entry["obj"]).IsValid())
        except Exception:  # noqa: BLE001 — объект удалён пользователем
            alive = False
        if not alive:
            del layout[oid]
            continue
        dx, dy = origin.x - entry["origin"].x, origin.y - entry["origin"].y
        want, expect = _shift(entry["placed"], dx, dy), _shift(entry["actual"], dx, dy)
        objects[want.key] = (entry["obj"], entry["v1"], entry["v2"])
        todo.append((entry, want, expect))
    realize = _make_realize(view, objects, style, content)
    moved = 0
    with view.drawing.edit():
        for entry, want, expect in todo:
            obj = entry["obj"]
            have = (_read_diameter(view, obj, want.key) if isinstance(want, DiametralDim)
                    else _read_linear(view, obj, want.key, want.axis, content))
            if not _same_place(have, expect, style) or model_mismatch(have, style) > 0:
                have = realize(want)
                moved += 1
            dx, dy = origin.x - entry["origin"].x, origin.y - entry["origin"].y
            entry.update(placed=want, actual=have, origin=origin, request=_shift(entry["request"], dx, dy))
    if moved:
        view.drawing.invalidate_geometry(view, bounds_only=True)
    return moved


# --- проверка чертежа -----------------------------------------------------------------------
def arrange_dimensions(view: "View", style: DimStyle | None = None, max_tiers: int = 8,
                       diameters_only: bool = False) -> DimReport:
    """Разложить размеры вида заново, сохраняя их связи (например, когда восстановление не помогло).

    Размеры, поставленные библиотекой, сохраняют исходный запрос (сторону, диапазон линии); для прочих
    сторона подбирается. Вызывать явно: размеры пользователя не перемещаются при add_dimensions.
    diameters_only оставляет линейные размеры фиксированными препятствиями.
    """
    style = style or DimStyle()
    ks, drawing, frame = view.ks, view.drawing, _Frame(view)
    content = view.content_bbox()
    if content is None:
        return DimReport()
    linear, circular = read_dims(view, content), read_diametral(view)
    selected = circular if diameters_only else linear + circular
    fixed = linear if diameters_only else []
    layout, origin = _layout(view), view.origin
    outline = None
    objects, requests = {}, {}
    for dim in selected:
        entry = layout.get(_obj_id(ks, dim.meta["raw"]))
        if entry is not None:
            shifted = _shift(entry["request"], origin.x - entry["origin"].x, origin.y - entry["origin"].y)
            request = replace(shifted, key=dim.key)
        elif isinstance(dim, DiametralDim):
            if outline is None:
                outline = [frame.sheet(p.x, p.y) for curve in view.curves() for p in curve.extremes()]
            request = DiamRequest(dim.center, dim.radius, dim.text_w, dim.text_h, key=dim.key, label=dim.label,
                                  outer_radius=max(dim.center.dist(p) for p in outline))
        else:
            side, at = ("inside", dim.line) if dim.inside else ("auto", None)
            request = DimRequest(dim.p1, dim.p2, dim.axis, dim.text_w, dim.text_h, key=dim.key, label=dim.label,
                                 side=side, at=at)
        requests[dim.key] = request
        objects[dim.key] = (dim.meta["raw"], dim.meta.get("v1"), dim.meta.get("v2"))
    realize = _make_realize(view, objects, style, content)
    with drawing.edit():
        obstacles = view_obstacles(view)
        keepouts = [r for r, _ in scene_keepouts(view, content, style)]
        plan = plan_dimensions(list(requests.values()), content, obstacles, fixed=fixed, keepouts=keepouts,
                               style=style, max_tiers=max_tiers, realize=realize)
        _apply(view, plan.dims, realize, objects, requests)
    drawing.invalidate_geometry(view, bounds_only=True)
    return DimReport(issues=check_dims(read_dims(view, content) + read_diametral(view), obstacles, keepouts, style))


def _model_axes(view: "View") -> dict | None:
    """Какие оси модели идут вдоль осей вида: {'x': (ось, знак·масштаб), 'y': (...), 'n': ось, 'o': P0}."""
    try:
        p0 = view.project_point(0, 0, 0)
        vs = [view.project_point(*e) for e in ((1, 0, 0), (0, 1, 0), (0, 0, 1))]
    except Exception:  # noqa: BLE001
        return None
    vs = [Point(v.x - p0.x, v.y - p0.y) for v in vs]
    res: dict = {"o": p0}
    used = set()
    for name, comp, other in (("x", "x", "y"), ("y", "y", "x")):
        for i, v in enumerate(vs):
            a, b = getattr(v, comp), getattr(v, other)
            if abs(abs(a) - 1) < 1e-6 and abs(b) < 1e-6:
                res[name] = (i, a)
                used.add(i)
                break
        else:
            return None
    rest = [i for i in range(3) if i not in used]
    res["n"] = rest[0] if len(rest) == 1 else None
    return res


def _facts_for_view(view: "View", dims: Sequence[LinearDim],
                    curves: Sequence | None = None) -> tuple[list[DimFact], list[Issue]]:
    ax = _model_axes(view)
    if ax is None:
        return [], [Issue("not_checked", INFO, f"Вид {view.name!r}: оси вида не совпадают с осями модели — "
                                                f"состав размеров на нём не проверяется", ())]
    o = ax["o"]
    circles = [c for c in (view.curves() if curves is None else curves)
               if c.kind in ("circle", "arc") and c.center and c.radius]

    def model(view_axis: str, value: float) -> tuple[int, float]:
        i, s = ax[view_axis]
        return i, (value - (o.x if view_axis == "x" else o.y)) / s

    facts = []
    for d in dims:
        v1, v2 = d.meta["v1"], d.meta["v2"]
        comp = d.axis
        i, a = model(comp, v1.x if comp == "x" else v1.y)
        _, b = model(comp, v2.x if comp == "x" else v2.y)
        f = DimFact(d.key, i, a, b, diameter=d.meta["diameter"], reference=d.meta["reference"],
                    label=f"{d.label} [{view.name}]", view=view.number)
        if f.diameter:
            circ = next((c for c in circles if abs(v1.dist(c.center) - c.radius) < 1e-3
                         and abs(v2.dist(c.center) - c.radius) < 1e-3), None)
            if circ is not None and ax["n"] is not None:       # Ø поперёк окружности — ось цилиндра по нормали вида
                f.cyl_axis = ax["n"]
                ix, cx = model("x", circ.center.x)
                iy, cy = model("y", circ.center.y)
                f.center = {ix: cx, iy: cy}
            else:                                             # Ø по образующим — ось цилиндра вдоль другой оси вида
                f.cyl_axis = ax["y" if comp == "x" else "x"][0]
                f.center = {i: (a + b) / 2}
        else:
            other = 'y' if comp == 'x' else 'x'
            a_other = v1.y if comp == 'x' else v1.x
            b_other = v2.y if comp == 'x' else v2.x
            if abs(a_other-b_other) <= SNAP_TOL:
                j, coordinate = model(other, (a_other+b_other)/2)
                f.center[j] = coordinate
            run = re.match(r"(\d+)\s*×\s*([\d.,]+)\s*=", d.label)
            if run and abs(int(run[1]) * float(run[2].replace(",", ".")) - abs(b - a)) <= 0.01 * max(1.0, abs(b - a)):
                n, sign = int(run[1]), (1 if b >= a else -1)
                f.extra = tuple(a + sign * k * abs(b - a) / n for k in range(1, n))
        facts.append(f)
    # диаметральные размеры окружностей
    ks = view.ks
    for n, obj in enumerate(_objects(ks, view.symbols.GetDiametralDimensions())):
        dd = ks.IDiametralDimension(obj)
        if not dd or ax["n"] is None:
            continue
        r = float(dd.GetRadius())
        ix, cx = model("x", dd.GetXc())
        iy, cy = model("y", dd.GetYc())
        suf = ks.IDimensionText(obj).GetSuffix()
        suffix = suf.GetStr() if suf else ""
        group = re.search(r"(\d+)\s*отв", suffix)
        facts.append(DimFact(f"{view.number}:D{n}", ix, cx - r, cx + r, diameter=True, cyl_axis=ax["n"],
                             center={ix: cx, iy: cy}, reference="*" in suffix,
                             count=int(group[1]) if group else 1, view=view.number,
                             label=f"{DIAMETER_SIGN}{_fmt(2 * r)} [{view.name}]"))
    # радиусы: задают размер неполного цилиндра (скругление, торец паза), ничего не привязывают
    for n, obj in enumerate(_objects(ks, view.symbols.GetRadialDimensions())):
        if ax["n"] is None:
            break
        r = float(obj.GetRadius())
        ix, cx = model("x", obj.GetXc())
        iy, cy = model("y", obj.GetYc())
        facts.append(DimFact(f"{view.number}:R{n}", ix, cx - r, cx + r, diameter=True, radial=True,
                             cyl_axis=ax["n"], center={ix: cx, iy: cy}, view=view.number,
                             label=f"R{_fmt(r)} [{view.name}]"))
    # Групповая выноска отверстий: диаметр берётся с связанной окружности,
    # число отверстий — из надписи. Произвольный текст не становится размером.
    for n, obj in enumerate(_objects(ks, view.symbols.GetLeaders())):
        label = ks.ILeader(obj).GetTextOnShelf().GetStr()
        match = re.fullmatch(r"(\d+)\s*отв\.\s*Ø([\d,.]+)", label)
        if not match or ax["n"] is None:
            continue
        branch = ks.IBranchs(obj)
        source = branch.GetBaseObject(0)
        circle = next((c for c in circles if source and ks.GetReference(c.raw)==ks.GetReference(source)), None)
        if circle is None and ks.IDrawingObject(obj).GetConstraints():
            tip=Point(branch.GetBranchX(0),branch.GetBranchY(0))
            diameter=float(match[2].replace(',', '.'))
            circle=next((c for c in circles if abs(2*c.radius-diameter)<=1e-3 and
                         abs(c.center.dist(tip)-c.radius)<=SNAP_TOL),None)
        if circle is None or abs(2*circle.radius-float(match[2].replace(',', '.'))) > 1e-3:
            continue
        ix, cx = model("x", circle.center.x)
        iy, cy = model("y", circle.center.y)
        facts.append(DimFact(f"{view.number}:P{n}", ix, cx-circle.radius, cx+circle.radius,
            diameter=True, cyl_axis=ax["n"], center={ix:cx, iy:cy}, count=int(match[1]), label=label, view=view.number))
    return facts, []


def _find_model(drawing: "Drawing") -> "PartDocument | None":
    # из kompas_lib.model: PartDocument
    for v in drawing.views:
        src = v.source_file
        if src and os.path.exists(src):
            doc = drawing.kompas.find_open(src)
            if isinstance(doc, PartDocument):
                return doc
    return None


def check_dimensions(drawing: "Drawing", model: "PartDocument | None" = None, style: DimStyle | None = None,
                     completeness: bool = True) -> DimReport:
    """Проверка размеров всего чертежа.

    - оформление: пересечения линий и надписей, надписи на линиях изображения, близость линий (< 7 мм),
      заход в чужие виды и обозначения, выход за рамку;
    - состав (ГОСТ 2.307): повторы (в т.ч. на разных видах), замкнутые цепи;
    - полнота (если доступна модель — открыта в КОМПАСе или передана): все торцы/уступы привязаны,
      все диаметры заданы.
    """
    style = style or DimStyle()
    report = DimReport()
    sheet = drawing.sheet
    frame = sheet.frame
    views = [v for v in drawing.views if abs(v.angle) < 1e-9]
    for view in drawing.views:
        if abs(view.angle)>1e-9:
            report.issues.append(Issue('not_checked',INFO,f"Повернутый вид {view.name!r}: геометрия размеров пока не проверяется"))
    curves = {v.number: v.curves() for v in views}           # геометрия вида читается один раз (~5 с на 3000 кривых)
    contents = {v.number: v.content_bbox(curves[v.number]) for v in views}
    facts: list[DimFact] = []
    for v in views:
        content = contents[v.number]
        dims = read_dims(v, content)
        diams = read_diametral(v)
        for dim in dims:
            if _hidden_point(dim.meta['v1'], curves[v.number]) or _hidden_point(dim.meta['v2'], curves[v.number]):
                report.issues.append(Issue('hidden_contour', ERROR,
                    f"Размер {dim.describe()} относится к невидимому контуру (ГОСТ 2.307)", (dim.key,)))
        for obj in _objects(v.ks, v.symbols.GetDiametralDimensions()):
            source = obj.GetBaseObject()
            if source and any(curve.is_hidden and v.ks.GetReference(curve.raw) == v.ks.GetReference(source)
                              for curve in curves[v.number]):
                report.issues.append(Issue('hidden_contour', ERROR,
                    f"Вид {v.name!r}: диаметр привязан к невидимому контуру (ГОСТ 2.307)"))
        for obj in _objects(v.ks,v.symbols.GetLineDimensions()):
            if obj.GetOrientation() == int(raw.ksLineDimensionOrientationEnum.ksLinDParallel):
                params=v.ks.IDimensionParams(obj)
                if (params.GetTextOnLine()==int(raw.ksDimensionTextPosEnum.ksDimTextHorizontalInCut) and
                    params.GetTextType()!=int(raw.ksDimensionTextTypeEnum.ksDTPOnShelf)):
                    report.issues.append(Issue('text_orientation',WARNING,
                        f"Вид {v.name!r}: проверьте горизонтальную надпись наклонного размера (ГОСТ 2.307)"))
        if not dims and not diams:
            continue
        names = scene_keepouts(v, content, style)
        allv = dims + diams
        issues = check_dims(allv, view_obstacles(v, curves[v.number]), [r for r, _ in names], style)
        for issue in issues:
            if issue.kind == "in_keepout":
                dim=next(d for d in allv if d.key==issue.keys[0])
                hit=[name for r,name in names if keepout_conflicts(dim,[r],style)]
                issue=replace(issue,message=issue.message+": "+", ".join(dict.fromkeys(hit)))
            report.issues.append(issue)
        for d in allv:
            if not frame.contains(d.bbox(style)):
                report.issues.append(Issue("outside_frame", ERROR, f"Размер {d.describe()} на виде {v.name!r} "
                                                                    f"выходит за рамку", (d.key,)))
        f, info = _facts_for_view(v, dims, curves[v.number])
        facts += f
        report.issues += info
    model = model or (_find_model(drawing) if completeness else None)
    required = None
    if completeness:
        if model is None:
            report.issues.append(Issue("not_checked", INFO, "Модель не открыта — полнота размеров не проверялась", ()))
        elif getattr(getattr(model, "type", None), "name", "") == "ASSEMBLY":
            report.issues.append(Issue("not_checked", INFO,
                                       "Сборка: полнота по граням модели не проверяется — на сборочном чертеже "
                                       "ставят габаритные, установочные и присоединительные размеры (ГОСТ 2.109)", ()))
        else:
            required, info = requirement_from_faces(model.faces())
            report.issues += info
    labels = [drawing.ks.ILeader(o).GetTextOnShelf().GetStr() for v in views
              for o in _objects(drawing.ks, v.symbols.GetLeaders())]
    report.issues += check_redundancy(facts, required, annotations=labels)
    report.issues = group_issues(report.issues)
    return report


# ==================================================================================================================
# === 40/55 kompas_lib.dims.flat — kompas_lib/dims/flat.py
# ==================================================================================================================
"""Образмеривание плоского/призматического изображения по кривым вида (ГОСТ 2.307).

Распознавание идёт только по геометрии вида — замкнутым контурам из отрезков, дуг и окружностей:
- внешний контур: габариты, фаски у углов, наклонные кромки (катетами), уступы, радиусы скруглений;
- внутренние контуры: отверстия (группы по диаметру, «Ø N отв.»), продолговатые пазы (ширина и
  межцентровое расстояние), прямоугольные окна (ширина × высота), прочие вырезы (габарит);
- положение элементов: кандидаты (ряды, пары, цепочки между соседними координатами, привязки
  от баз) со стоимостью «цена размера + длина»; выбирается минимальный остовный лес (Краскал):
  короткие местные размеры выигрывают у длинных базовых, ряд — у поштучных цепочек; симметричные
  пары — только при симметрии самого контура, ряды — только на одной прямой; разводимость набора
  на две стороны проверяется сразу (stacking.TwoSides). Лишних нет по построению;

Все точки берутся в вершинах вида (концы и середины отрезков, концы и центры дуг), поэтому размеры
ассоциативны. Результат — черновик: выбор баз и простановка допусков остаются за конструктором.
"""

from collections import defaultdict
from dataclasses import dataclass, field
from typing import Sequence

# из kompas_lib.geom: Point, Rect
# из kompas_lib.dims.api: Diameter, Dim, DimReport, _axis, _fmt, _pt, add_dimensions, overall_dims
# из kompas_lib.dims.graph: Link, Symmetry
select_links = spanning_forest
# из kompas_lib.dims.stacking: TwoSides
# из kompas_lib.dims.shapes: INFO, WARNING, Issue

FLAT_TOL = 0.01


def _k(v: float) -> int:
    return round(v / FLAT_TOL)


def _close(a: float, b: float, tol: float = FLAT_TOL * 2) -> bool:
    return abs(a - b) <= tol


def _axis_line(c) -> str | None:
    """'h' — горизонтальный отрезок, 'v' — вертикальный, None — наклонный/не отрезок."""
    if c.kind != "line":
        return None
    if _close(c.p1.y, c.p2.y):
        return "h"
    if _close(c.p1.x, c.p2.x):
        return "v"
    return None


def _mid(c) -> Point:
    return Point((c.p1.x + c.p2.x) / 2, (c.p1.y + c.p2.y) / 2)


@dataclass
class Loop:
    curves: list

    @property
    def bbox(self) -> Rect:
        pts = [p for c in self.curves for p in c.extremes()]
        return Rect(min(p.x for p in pts), min(p.y for p in pts), max(p.x for p in pts), max(p.y for p in pts))

    @property
    def kinds(self) -> dict:
        out = defaultdict(int)
        for c in self.curves:
            out[c.kind] += 1
        return out


@dataclass
class FlatFeature:
    kind: str                       # hole | slot | window | cutout
    label: str                      # «Ø18», «паз 18×28», …
    size_key: tuple                 # одинаковые элементы — одна группа
    pos_x: Point                    # вершина с x-координатой положения
    pos_y: Point                    # вершина с y-координатой положения
    centered: bool                  # положение задаётся центром (для симметрии)
    loop: Loop
    radius: float | None = None
    center: Point | None = None
    specs: list = field(default_factory=list)   # размеры формы (для одного представителя группы)


def build_loops(curves: Sequence) -> list[Loop]:
    """Связать кривые в контуры по общим концам; окружности и замкнутые ломаные — отдельные контуры."""
    geo = [c for c in curves if not c.is_axial and not c.is_hidden and c.kind in ("line", "arc", "circle", "poly")]
    parent = list(range(len(geo)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    ends: dict[tuple, list[int]] = defaultdict(list)
    for i, c in enumerate(geo):
        pts = ([c.p1, c.p2] if c.kind in ("line", "arc") else
               [c.points[0], c.points[-1]] if c.kind == "poly" and c.points and not c.closed else [])
        for p in pts:
            if p is not None:
                ends[(round(p.x / 0.02), round(p.y / 0.02))].append(i)
    for idx in ends.values():
        for j in idx[1:]:
            parent[find(j)] = find(idx[0])
    groups: dict[int, list] = defaultdict(list)
    for i, c in enumerate(geo):
        groups[find(i)].append(c)
    return [Loop(g) for g in groups.values()]


def _classify(loop: Loop) -> FlatFeature | None:
    cs, kinds, bb = loop.curves, loop.kinds, loop.bbox
    round_ = [c for c in cs if c.kind in ("arc", "circle")]
    # отверстие: дуги/окружность одного центра и радиуса
    if round_ and len(round_) == len(cs):
        c0 = round_[0]
        if all(c.center.dist(c0.center) <= FLAT_TOL * 2 and _close(c.radius, c0.radius) for c in round_):
            d = 2 * c0.radius
            return FlatFeature("hole", f"Ø{_fmt(d)}", ("hole", _k(d)), c0.center, c0.center, True, loop,
                               radius=c0.radius, center=c0.center)
    # продолговатый паз: две дуги одного радиуса + два параллельных отрезка
    lines = [c for c in cs if c.kind == "line"]
    if kinds.get("arc") == 2 and len(lines) == 2 and len(cs) == 4:
        a1, a2 = [c for c in cs if c.kind == "arc"]
        o1, o2 = _axis_line(lines[0]), _axis_line(lines[1])
        if _close(a1.radius, a2.radius) and o1 and o1 == o2:
            r = a1.radius
            l1, l2 = lines
            if o1 == "h":    # паз вдоль X
                width = Dim(_mid(l1), _mid(l2), axis="y")
                length = Dim(l1.p1, l1.p2, axis="x")
                pos_x, pos_y = _mid(l1), a1.center
                size = (abs(l1.p1.x - l1.p2.x), 2 * r)
            else:            # паз вдоль Y
                width = Dim(_mid(l1), _mid(l2), axis="x")
                length = Dim(l1.p1, l1.p2, axis="y")
                pos_x, pos_y = a1.center, _mid(l1)
                size = (2 * r, abs(l1.p1.y - l1.p2.y))
            ft = FlatFeature("slot", f"паз {_fmt(2 * r)}", ("slot", o1, _k(r), _k(max(size))), pos_x, pos_y, True,
                             loop, radius=r)
            ft.specs = [width, length]
            return ft
    # прямоугольное окно: четыре отрезка вдоль осей
    if len(cs) == 4 and len(lines) == 4 and all(_axis_line(c) for c in lines):
        h = [c for c in lines if _axis_line(c) == "h"]
        v = [c for c in lines if _axis_line(c) == "v"]
        if len(h) == 2 and len(v) == 2:
            bottom = min(h, key=lambda c: c.p1.y)
            left = min(v, key=lambda c: c.p1.x)
            ft = FlatFeature("window", f"окно {_fmt(bb.width)}×{_fmt(bb.height)}",
                             ("window", _k(bb.width), _k(bb.height)), _mid(left), _mid(bottom), False, loop)
            ft.specs = [Dim(bottom.p1, bottom.p2, axis="x"), Dim(left.p1, left.p2, axis="y")]
            return ft
    # прочий вырез: габарит по крайним вершинам
    verts = [p for c in cs for p in c.vertices()]
    if not verts:
        return None
    lo_x = min(verts, key=lambda p: (p.x, p.y))
    hi_x = max(verts, key=lambda p: (p.x, -p.y))
    lo_y = min(verts, key=lambda p: (p.y, p.x))
    hi_y = max(verts, key=lambda p: (p.y, -p.x))
    ft = FlatFeature("cutout", f"вырез {_fmt(bb.width)}×{_fmt(bb.height)}",
                     ("cutout", _k(bb.width), _k(bb.height), len(cs)), lo_x, lo_y, False, loop)
    ft.specs = [Dim(lo_x, hi_x, axis="x"), Dim(lo_y, hi_y, axis="y")]
    return ft


def _symmetric(loop: Loop, axis: str, mid: float) -> bool:
    """Контур зеркально симметричен относительно прямой axis = mid (x = mid для 'x', y = mid для 'y').

    Проверяются концы, середины и центры всех кривых: межосевой размер симметричной пары
    вместо координат от базы допустим, только если симметрия есть у самой детали (ГОСТ 2.307),
    а не совпала случайно у двух координат.
    """
    pts = []
    for c in loop.curves:
        pts += list(c.vertices()) + list(c.extremes())
        if getattr(c, "center", None) is not None:
            pts.append(c.center)
    keys = {(_k(p.x) // 2, _k(p.y) // 2) for p in pts}

    def mirrored(p: Point) -> tuple:
        q = Point(2 * mid - p.x, p.y) if axis == "x" else Point(p.x, 2 * mid - p.y)
        return _k(q.x) // 2, _k(q.y) // 2

    def near(key: tuple) -> bool:
        return any((key[0] + dx, key[1] + dy) in keys for dx in (-1, 0, 1) for dy in (-1, 0, 1))

    return bool(pts) and all(near(mirrored(p)) for p in pts)


@dataclass
class FlatPlan:
    specs: list = field(default_factory=list)          # Dim | Diameter для add_dimensions (уже без лишних)
    radii: list = field(default_factory=list)          # кривые для Radius
    leaders: list = field(default_factory=list)        # (точка, текст, кривая)
    notes: list = field(default_factory=list)
    features: list = field(default_factory=list)
    pruned: list = field(default_factory=list)         # Issue: размеры, отсечённые как лишние


def suggest_flat_dims(view, curves: Sequence | None = None, max_positions: int = 24,
                      redundant: str = "drop", skip: Sequence = (),
                      min_readable: float | None = None) -> FlatPlan:
    """Черновой набор размеров изображения, ограниченного прямыми и дугами (координаты вида).

    redundant: "drop" — лишние размеры не включаются; "reference" — включаются справочными («*»).
    skip: точки вида (центры отверстий круговых массивов) — их положение задаёт диаметр окружности
    центров, координаты от базы по ним не строятся.
    min_readable: минимальная длина позиционной связи в единицах вида; короче — не ставить
    (непривязанные координаты уходят в notes жёлтым предупреждением, а не красной ошибкой
    feature_too_small). Габариты и размеры формы обязательны и фильтром не трогаются.
    """
    skip_keys = {(_k(s.x), _k(s.y)) for s in skip}

    def readable(a: float, b: float) -> bool:
        return min_readable is None or abs(b - a) >= min_readable
    curves = view.curves() if curves is None else curves
    loops = build_loops(curves)
    if not loops:
        return FlatPlan(notes=["Нет видимой геометрии"])
    outer = max(loops, key=lambda lp: lp.bbox.area)
    ob = outer.bbox
    plan = FlatPlan()
    plan.specs += overall_dims(view, curves, side_x="top", side_y="left")

    # --- внутренние контуры ------------------------------------------------------------------
    inner = []
    for lp in loops:
        if lp is outer:
            continue
        b = lp.bbox
        if b.x1 < ob.x1 - FLAT_TOL or b.x2 > ob.x2 + FLAT_TOL or b.y1 < ob.y1 - FLAT_TOL or b.y2 > ob.y2 + FLAT_TOL:
            continue        # не внутри внешнего контура (другое тело/линия перехода)
        ft = _classify(lp)
        if ft:
            inner.append(ft)
    # концентрические окружности (фаска/зенковка у отверстия): размер ставится меньшему диаметру
    holes = [f for f in inner if f.kind == "hole"]
    drop = set()
    for f in holes:
        for g in holes:
            if g is not f and g.center.dist(f.center) <= FLAT_TOL * 2 and g.radius > f.radius + FLAT_TOL:
                drop.add(id(g))
                plan.notes.append(f"{f.label}: концентрическая окружность Ø{_fmt(2 * g.radius)} "
                                  "(фаска/зенковка) — оформите обозначением фаски")
    inner = [f for f in inner if id(f) not in drop]
    plan.features = inner

    groups: dict[tuple, list[FlatFeature]] = defaultdict(list)
    for f in inner:
        groups[f.size_key].append(f)
    for n, (key, fs) in enumerate(groups.items()):
        rep = min(fs, key=lambda f: (f.pos_x.x, f.pos_y.y))
        if rep.kind == "hole" and len(fs) > 1:
            # группа отверстий — выноской «N отв. ØD» (её понимает check_dimensions); точка на окружности
            circle = next(c for c in rep.loop.curves if c.kind in ("circle", "arc"))
            tip = Point(rep.center.x + rep.radius * 0.7071, rep.center.y + rep.radius * 0.7071)
            plan.leaders.append((tip, f"{len(fs)} отв. Ø{_fmt(2 * rep.radius)}", circle))
        elif rep.kind == "hole":
            plan.specs.append(Diameter(rep.center, rep.radius, key=f"hole{n}"))
        else:
            for i, s in enumerate(rep.specs):
                s.key = f"{rep.kind}{n}:{i}"
                plan.specs.append(s)
            if len(fs) > 1:
                plan.notes.append(f"{rep.label}: {len(fs)} одинаковых — размеры формы у одного")

    # --- внешний контур ----------------------------------------------------------------------
    outer_lines = [c for c in outer.curves if c.kind == "line"]
    at_vertex = defaultdict(list)
    for c in outer_lines:
        for p in (c.p1, c.p2):
            at_vertex[(_k(p.x), _k(p.y))].append(c)
    chamfers = defaultdict(list)
    edge_points: list[Point] = []
    corner_pts: set[tuple] = set()      # вершины, заданные фаской/скосом угла — повторно не образмериваются

    def on_x_edge(p):
        return _close(p.x, ob.x1) or _close(p.x, ob.x2)

    def on_y_edge(p):
        return _close(p.y, ob.y1) or _close(p.y, ob.y2)

    for c in outer_lines:
        if _axis_line(c):
            continue
        dx, dy = abs(c.p2.x - c.p1.x), abs(c.p2.y - c.p1.y)
        neigh = [o for p in (c.p1, c.p2) for o in at_vertex[(_k(p.x), _k(p.y))] if o is not c]
        between_axes = len(neigh) == 2 and {_axis_line(o) for o in neigh} == {"h", "v"}
        # срезан угол габарита: один конец на вертикальной кромке, другой — на горизонтальной
        corner = between_axes and ((on_x_edge(c.p1) and on_y_edge(c.p2)) or (on_y_edge(c.p1) and on_x_edge(c.p2)))
        small = max(dx, dy) <= 0.2 * min(ob.width, ob.height)
        if corner and _close(dx, dy, 0.05) and small:
            chamfers[_k(dx)].append(c)
        elif corner:
            # скос угла — катетами
            plan.specs.append(Dim(c.p1, c.p2, axis="x", key=f"bevel{len(plan.specs)}:x"))
            plan.specs.append(Dim(c.p1, c.p2, axis="y", key=f"bevel{len(plan.specs)}:y"))
        else:
            edge_points += [c.p1, c.p2]
            continue
        corner_pts.update({(_k(c.p1.x), _k(c.p1.y)), (_k(c.p2.x), _k(c.p2.y))})
    for leg, cs in chamfers.items():
        c = cs[0]
        text = (f"{len(cs)} фаски " if len(cs) > 1 else "") + f"{_fmt(abs(c.p2.x - c.p1.x))}×45°"
        plan.leaders.append((_mid(c), text, c))
    chamfer_pts = corner_pts
    # уступы: концы осевых отрезков внутри габарита, не принадлежащие фаскам/дугам
    arc_pts = {(_k(p.x), _k(p.y)) for c in outer.curves if c.kind == "arc" for p in (c.p1, c.p2)}
    for c in outer_lines:
        if _axis_line(c):
            for p in (c.p1, c.p2):
                kp = (_k(p.x), _k(p.y))
                if kp not in chamfer_pts and kp not in arc_pts:
                    edge_points.append(p)
    radii = {}
    for c in outer.curves:
        if c.kind == "arc":
            radii.setdefault(_k(c.radius), []).append(c)
    for r, cs in radii.items():
        plan.radii.append(cs[0])
        if len(cs) > 1:
            plan.notes.append(f"R{_fmt(cs[0].radius)}: {len(cs)} скругления — размер у одного")

    # монотонные изломы скатов узлами не становятся: вершина с двумя неосевыми соседями,
    # строго внутри их диапазона по обеим осям, — мелкая деталь профиля, заданная моделью
    # (неуказанные предельные отклонения). Углы, экстремумы и стыки с осевыми рёбрами остаются.
    kept, nkink = [], 0
    for p in edge_points:
        kp = (_k(p.x), _k(p.y))
        segs = at_vertex.get(kp, [])
        others = [q for c in segs for q in (c.p1, c.p2) if (_k(q.x), _k(q.y)) != kp]
        if len(others) == 2 and all(_axis_line(c) is None for c in segs) \
                and min(q.x for q in others) < p.x < max(q.x for q in others) \
                and min(q.y for q in others) < p.y < max(q.y for q in others):
            nkink += 1
            continue
        kept.append(p)
    edge_points[:] = kept
    if nkink:
        plan.notes.append(f"Монотонные изломы контура ({nkink}) — заданы моделью, "
                          f"неуказанные предельные отклонения")
    # микроступени — не узлы: вершина, все касающиеся осевые рёбра которой короче читаемого, —
    # деталь, заданная моделью (неуказанные предельные отклонения). Вершины длинных рёбер, скосов
    # и вершины без осевых соседей (апексы) остаются. Работает при известном масштабе.
    if min_readable is not None:
        kept2, nmicro = [], 0
        for p in edge_points:
            kp = (_k(p.x), _k(p.y))
            axis_len = [((c.p2.x - c.p1.x) ** 2 + (c.p2.y - c.p1.y) ** 2) ** 0.5
                        for c in at_vertex.get(kp, []) if _axis_line(c) is not None]
            if axis_len and min(axis_len) < min_readable:
                nmicro += 1
                continue
            kept2.append(p)
        edge_points[:] = kept2
        if nmicro:
            plan.notes.append(f"Микроступени ({nmicro}) — заданы моделью, неуказанные предельные отклонения")
    # --- положение: минимальный остовный лес (graph.select) ----------------------------------
    # Обязательные узлы — все координаты элементов и уступов + края габарита. Кандидаты: ряды, пары,
    # координаты от баз. Берётся cheapest-набор без циклов (Краскал); разводимость на две стороны
    # проверяется сразу через TwoSides в accept. Лишних (повторов, замкнутых цепей) нет по построению.
    ROW_TOL = 0.5  # строка визуального ряда: грубее шума перепроецирования вида, мельче проектного шага строк
    datum_x = min((p for c in outer_lines for p in (c.p1, c.p2) if _close(p.x, ob.x1)), key=lambda p: p.y,
                  default=None)
    datum_y = min((p for c in outer_lines for p in (c.p1, c.p2) if _close(p.y, ob.y1)), key=lambda p: p.x,
                  default=None)
    datum_x2 = min((p for c in outer_lines for p in (c.p1, c.p2) if _close(p.x, ob.x2)), key=lambda p: p.y,
                   default=None)
    datum_y2 = min((p for c in outer_lines for p in (c.p1, c.p2) if _close(p.y, ob.y2)), key=lambda p: p.x,
                   default=None)
    cx, cy = ob.center.x, ob.center.y
    FIXED = 50.0  # цена одного размера: сначала меньше размеров, затем короче (в единицах вида)
    ts = {"x": TwoSides(FLAT_TOL), "y": TwoSides(FLAT_TOL)}
    existing: list = []
    for spec in plan.specs:
        sp = _span(spec)
        if sp is None:
            continue
        ax, lo, hi = sp
        key = spec.key if spec.key is not None else id(spec)
        existing.append(Link(ax, (lo, hi), 0.0, kind="size", key=key, forced=True))
        ts[ax].add(key, lo, hi)
    required: dict = {}
    candidates: list = []
    symmetries: dict = {}
    for axis, datum, alt_datum, lo, hi, mid in (("x", datum_x, datum_x2, ob.x1, ob.x2, cx),
                                                 ("y", datum_y, datum_y2, ob.y1, ob.y2, cy)):
        symmetric = _symmetric(outer, axis, mid)
        if symmetric:
            symmetries[axis] = [Symmetry(mid, lo, hi)]
        values: dict[int, tuple[Point, bool, tuple]] = {}
        for f in inner:
            if f.centered and f.center is not None and (_k(f.center.x), _k(f.center.y)) in skip_keys:
                continue        # круговой массив: положение задаёт диаметр окружности центров
            p = f.pos_x if axis == "x" else f.pos_y
            values.setdefault(_k(getattr(p, axis)), (p, f.centered, f.size_key))
        for p in edge_points:
            v = getattr(p, axis)
            if not (_close(v, lo) or _close(v, hi)):
                values.setdefault(_k(v), (p, False, ("edge",)))
        for kv, (p, centered, _tag) in list(values.items()):
            if centered and symmetric and _close(getattr(p, axis), mid):
                del values[kv]
                plan.notes.append(f"Элемент на оси симметрии ({axis}={_fmt(getattr(p, axis) - lo)} от кромки) — "
                                  "положение задано симметрией")
        # слияние микро-узлов: координаты ближе читаемого — одна позиция для образмеривания
        # (мельче 2 мм на листе всё равно не различить); привязывается представитель, остальные уходят
        # в примечание, а не в красную ошибку и не в базовую через весь лист.
        # Приоритет записей: кромка (2) > элемент (отверстие/паз/окно, 1) > уступ контура (0).
        # Элемент не глотается кромкой; элементы разных типов/размеров не сливаются друг с другом
        # (только одинаковые); кромка глотает только уступы. Иначе ряд отверстий теряет конец,
        # слившись с соседними вершинами контура.
        entries = [(getattr(p, axis), p, kv, 1 if t != ("edge",) else 0, False, t)
                   for kv, (p, _c, t) in values.items()]
        if datum is not None:
            entries.append((getattr(datum, axis), datum, None, 2, True, None))
        if alt_datum is not None:
            entries.append((getattr(alt_datum, axis), alt_datum, None, 2, True, None))
        entries.sort(key=lambda e: e[0])
        clumps: list = []
        for coord, p, kv, rank, is_datum, tag in entries:
            open_cl = clumps[-1] if clumps else None
            join = (open_cl is not None and min_readable is not None
                    and coord - open_cl[-1][0] < min_readable)
            if join:
                ranks = {m[3] for m in open_cl}
                if rank == 1:
                    ftags = {m[5] for m in open_cl if m[3] == 1}
                    join = 2 not in ranks and (not ftags or ftags == {tag})
                elif rank == 2:
                    join = not ranks - {0}      # кромка глотает только уступы
            if join:
                open_cl.append((coord, p, kv, rank, is_datum, tag))
            else:
                clumps.append([(coord, p, kv, rank, is_datum, tag)])
        nodes_by_key: dict = {}
        rep_of: dict = {}
        for cl in clumps:
            own = [(c, q, kk, rk) for c, q, kk, rk, _d, _t in cl if not _d]
            base = [(c, q) for c, q, kk, rk, _d, _t in cl if _d]
            feats = [(c, q, kk) for c, q, kk, rk in own if rk == 1]
            if feats:
                mean = sum(c for c, _q, _kk in feats) / len(feats)
                rep_c, rep_p, rep_kk = min(feats, key=lambda m: (abs(m[0] - mean), m[0]))
            elif base:
                rep_c, rep_p, rep_kk = base[0][0], base[0][1], None
            else:
                mean = sum(c for c, _q, _kk, _rk in own) / len(own)
                rep_c, rep_p, rep_kk = min(own, key=lambda m: (abs(m[0] - mean), m[0]))[:3]
            node = {"coord": rep_c, "point": rep_p, "key": _k(rep_c), "datum": bool(base),
                    "members": [c for c, _q, _kk, _rk in own]}
            if rep_kk in values:
                node["tag"], node["centered"] = values[rep_kk][2], values[rep_kk][1]
            else:
                node["tag"], node["centered"] = ("edge",), False
            for _c, _q, kk, _rk in own:
                rep_of[kk] = node
            nodes_by_key[node["key"]] = node
            if len(own) > 1 or (base and own):
                offs = sorted(_fmt(c - lo) for c, _q, _kk, _rk in own)
                plan.notes.append(f"Координаты {axis} {', '.join(offs)} от кромки ближе читаемого — "
                                  f"привязана одна позиция, остальные — выносным элементом (ГОСТ 2.305)")
        required[axis] = [lo, hi] + [n["coord"] for n in nodes_by_key.values() if not n["datum"]]
        other = "y" if axis == "x" else "x"
        runs = []
        for fs in groups.values():
            if not fs[0].centered:
                continue
            rows: dict[int, list[FlatFeature]] = defaultdict(list)
            for f in fs:
                rows[round(getattr(f.pos_x if axis == "x" else f.pos_y, other) / ROW_TOL)].append(f)
            for row in rows.values():
                node_keys = set()
                for f in row:
                    kv = _k(getattr(f.pos_x if axis == "x" else f.pos_y, axis))
                    node = rep_of.get(kv)
                    if node is not None and not node["datum"]:
                        node_keys.add(node["key"])
                runs += [r for r in _even_runs(sorted(node_keys))]
        in_run = set()
        for run in runs:
            if in_run.intersection(run):
                continue
            pts = [nodes_by_key[k]["point"] for k in run if k in nodes_by_key]
            if len(pts) < 3:
                continue
            coords = [getattr(p, axis) for p in pts]
            first, last = pts[0], pts[-1]
            step = abs(coords[1] - coords[0])
            key = f"pos_{axis}{run[0]}:pitch"
            if not readable(coords[0], coords[-1]):
                continue        # ряд короче читаемого — отверстия образмериваются поштучно
            candidates.append(Link(axis, tuple(coords), FIXED, kind="pitch", key=key,
                                   payload=Dim(first, last, axis=axis, prefix=f"{len(run) - 1}×{_fmt(step)}=",
                                               key=key)))
            if datum is not None:
                dv = getattr(datum, axis)
                dkey = f"pos_{axis}{run[0]}"
                if readable(dv, coords[0]):
                    candidates.append(Link(axis, (dv, coords[0]), FIXED + abs(coords[0] - dv), kind="position",
                                           key=dkey, payload=Dim(datum, first, axis=axis, key=dkey)))
            in_run.update(run)
        for node in nodes_by_key.values():
            if node["datum"]:
                continue        # кромка привязана габаритом
            rk = node["key"]
            if rk in in_run:
                continue
            p, tag, v = node["point"], node["tag"], node["coord"]
            mirror = _k(2 * mid - v)
            mnode = nodes_by_key.get(mirror)
            if (symmetric and mnode is not None and mnode is not node and mnode["tag"] == tag
                    and not mnode["datum"] and mirror not in in_run):
                qv = mnode["coord"]
                key = f"pos_{axis}{rk}:pair"
                if readable(v, qv):
                    candidates.append(Link(axis, (v, qv), FIXED + abs(qv - v) * 0.9, kind="pair", key=key,
                                           symmetric=True,
                                           payload=Dim(p, mnode["point"], axis=axis, key=key)))
                    in_run.update({rk, mirror})
                    continue
            if datum is not None and rk not in in_run:
                dv = getattr(datum, axis)
                key = f"pos_{axis}{rk}"
                if readable(dv, v):
                    candidates.append(Link(axis, (dv, v), FIXED + abs(v - dv), kind="position", key=key,
                                           payload=Dim(datum, p, axis=axis, key=key)))
                    if alt_datum is not None:
                        av = getattr(alt_datum, axis)
                        if readable(av, v):
                            candidates.append(Link(axis, (av, v), FIXED + abs(v - av) + 2.0, kind="position",
                                                   key=f"{key}:alt",
                                                   payload=Dim(alt_datum, p, axis=axis, key=key)))
        # цепочки между соседними координатами: короткие местные размеры вместо длинных базовых
        pts = []
        if datum is not None:
            pts.append((getattr(datum, axis), datum))
        if alt_datum is not None:
            pts.append((getattr(alt_datum, axis), alt_datum))
        pts += [(n["coord"], n["point"]) for n in nodes_by_key.values() if not n["datum"]]
        seen = {}
        for c, p in pts:
            seen.setdefault(_k(c), (c, p))
        ordered = [seen[k] for k in sorted(seen)]
        for n, ((c1, p1), (c2, p2)) in enumerate(zip(ordered, ordered[1:])):
            if c2 - c1 > FLAT_TOL and readable(c1, c2):
                key = f"chain_{axis}{n}"
                candidates.append(Link(axis, (c1, c2), FIXED + (c2 - c1), kind="chain", key=key,
                                       payload=Dim(p1, p2, axis=axis, key=key)))

    def accept(link) -> bool:
        lo, hi = min(link.coords), max(link.coords)
        return ts[link.axis].add(link.key if link.key is not None else id(link), lo, hi)

    sel = select_links(required, candidates, symmetries=symmetries, existing=existing, tol=FLAT_TOL, accept=accept)
    for link in sel.chosen:
        if link.payload is not None:
            plan.specs.append(link.payload)
    for ax, groups_ in sel.unlocated.items():
        flat = sorted(c for g in groups_ for c in g)
        plan.notes.append(f"Координаты по {ax} не привязаны: {', '.join(_fmt(c) for c in flat)}")
    return plan


def _span(spec: Dim) -> tuple[str, float, float] | None:
    if not isinstance(spec, Dim) or spec.reference or spec.side == "inside" or spec.at is not None:
        return None
    p1, p2 = _pt(spec.p1), _pt(spec.p2)
    axis = _axis(spec, p1, p2)
    a, b = (p1.x, p2.x) if axis == "x" else (p1.y, p2.y)
    return axis, min(a, b), max(a, b)


def _even_runs(keys: Sequence[int], min_len: int = 3, tol: int = 2) -> list[list[int]]:
    """Максимальные ряды значений с постоянным шагом (ключи `_k`) длиной ≥ min_len."""
    runs, i = [], 0
    while i < len(keys) - 1:
        step, j = keys[i + 1] - keys[i], i + 1
        while j + 1 < len(keys) and abs(keys[j + 1] - keys[j] - step) <= tol:
            j += 1
        if j - i + 1 >= min_len and step > tol:
            runs.append(list(keys[i:j + 1]))
            i = j + 1
        else:
            i += 1
    return runs

def flat_dim_tiers(plan: FlatPlan) -> tuple[int, int, int, int]:
    """Оценка ярусов размеров по сторонам (л, н, п, в) для резерва при компоновке."""
    nx = sum(1 for s in plan.specs if isinstance(s, Dim) and s.axis == "x")
    ny = sum(1 for s in plan.specs if isinstance(s, Dim) and s.axis == "y")
    tx, ty = max(2, (nx + 1) // 2 + 1), max(2, (ny + 1) // 2 + 1)
    return (ty, tx, ty, tx)


def dimension_flat_view(view, style=None, plan: FlatPlan | None = None) -> tuple[DimReport, list[str]]:
    """Поставить на вид набор `suggest_flat_dims`: линейные/диаметры, радиусы, выноски фасок."""
    # из kompas_lib.dims.annotations: Leader, add_leaders
    # из kompas_lib.dims.curved: Radius, add_curved_dimensions
    plan = plan or suggest_flat_dims(view)
    report = add_dimensions(view, plan.specs, style=style)
    if plan.radii:
        try:
            placed = add_curved_dimensions(view, [Radius(c, key=f"radius{i}") for i, c in enumerate(plan.radii)],
                                           style=style)
            report.created += placed.created
            report.issues += placed.issues
        except Exception as e:  # noqa: BLE001
            report.issues.append(Issue("radius_failed", WARNING, f"Радиусы не поставлены: {e}"))
    if plan.leaders:
        placed = add_leaders(view, [Leader(p, t, getattr(c, "raw", None), key=f"chamfer{i}")
                                    for i, (p, t, c) in enumerate(plan.leaders)], style=style)
        report.created += placed.created
        report.issues += placed.issues
    report.issues += plan.pruned
    report.issues += [Issue("flat_note", INFO, n) for n in plan.notes]
    return report, plan.notes


