"""Ассоциативные радиальные и угловые размеры с полкой по габариту CAD-текста."""

from dataclasses import dataclass
from itertools import chain
from math import atan2, cos, degrees, hypot, radians, sin

# из kompas_lib.enums: raw
# из kompas_lib.errors: check
# из kompas_lib.geom: OBox, Point, Rect, Segment, as_index, near, segment_hits_rect, segments_cross
# из kompas_lib.dims.api: DimReport, _Frame, _fmt, _objects, _pt, leader_cost, leader_segments, read_diametral, read_dims, scene_keepouts, view_obstacles
# из kompas_lib.dims.shapes: ERROR, WARNING, DiametralDim, DimStyle, Issue


@dataclass(frozen=True)
class Radius:
    curve: object
    key: str = ''
    angle: float | None = None
    shelf: Point | tuple[float, float] | None = None


@dataclass(frozen=True)
class Angle:
    first: object
    second: object
    key: str = ''
    shelf: Point | tuple[float, float] | None = None


def angle_geometry(first, second, tol=1e-9):
    """Пересечение прямых и два направленных луча; параллельные отклоняются."""
    if any(curve.kind != 'line' or curve.p1 is None or curve.p2 is None for curve in (first, second)):
        raise ValueError('Угловой размер требует двух отрезков')
    p, q = first.p1, second.p1
    u = Point(first.p2.x-p.x, first.p2.y-p.y)
    v = Point(second.p2.x-q.x, second.p2.y-q.y)
    cross = u.x*v.y-u.y*v.x
    if abs(cross) <= tol*max(1., hypot(u.x,u.y)*hypot(v.x,v.y)):
        raise ValueError('Угловой размер: прямые параллельны или совпадают')
    t = ((q.x-p.x)*v.y-(q.y-p.y)*v.x)/cross
    center = Point(p.x+t*u.x, p.y+t*u.y)
    ends = [max((curve.p1,curve.p2), key=center.dist) for curve in (first,second)]
    angles = [degrees(atan2(end.y-center.y,end.x-center.x)) % 360 for end in ends]
    sweep = (angles[1]-angles[0]) % 360
    if sweep > 180:
        ends.reverse()
        angles.reverse()
        sweep = 360-sweep
    return center, ends, angles, sweep


def _same_line(a: float, b: float) -> bool:
    """Направления a и b (градусы) лежат на одной прямой (совпадают или противоположны)."""
    return abs((a - b + 90.0) % 180.0 - 90.0) < 1.0


def _free_angle(curve, preferred: float, center: Point, rays, tol: float, fixed: bool = False) -> float | None:
    """Угол радиуса, не лежащий на одной прямой с другими диаметрами/радиусами того же центра.

    Дуга — ищем внутри её размаха, окружность — поворотом от предпочтительного. Заданный явно угол
    не меняем: конфликт — None.
    """
    used = [a for c, a in rays if c.dist(center) <= tol]
    if not any(_same_line(preferred, a) for a in used):
        return preferred
    if fixed:
        return None
    if curve.angles:
        a, b = curve.angles
        sweep = (b - a) % 360 if curve.ccw else -((a - b) % 360)
        options = [a + sweep * f for f in (0.35, 0.65, 0.25, 0.75, 0.15, 0.85)]
    else:
        options = [preferred + d for d in (30, -30, 60, -60, 15, -15, 75, -75)]
    return next((o % 360 for o in options if not any(_same_line(o, x) for x in used)), None)


def _shelf_candidates(target: Point, content: Rect, width: float, height: float, style: DimStyle,
                      max_tiers: int) -> list[tuple[int, Point]]:
    """Начала полки (надпись справа над ней): у самой точки и по сторонам изображения, по ярусам."""
    out = []
    for tier in range(max_tiers):
        shift = style.first_offset + tier * style.step_for(height)
        xs = (target.x + shift, target.x - shift - width,
              content.x2 + style.first_offset, content.x1 - width - style.first_offset)
        ys = (target.y + shift, target.y - shift - height, content.y2 + shift, content.y1 - shift - height)
        out += [(tier, Point(x, y)) for x in xs for y in ys]
    return out


def add_curved_dimensions(view, specs, style=None, max_tiers=12, max_realize=6):
    """Создать Radius/Angle, проверить связи и выбрать полку без пересечения текста.

    Использует настоящие кривые вида. Повторный вызов с теми же опорными объектами
    не дублирует размер. Нет места — новый объект удаляется и возвращается ошибка.
    """
    style = style or DimStyle()
    frame, ks, drawing = _Frame(view), view.ks, view.drawing
    content = view.content_bbox()
    if content is None:
        raise ValueError('Пустой вид')
    obstacles = view_obstacles(view)
    dimensions = read_dims(view, content)+read_diametral(view)
    dim_lines = [segment for dim in dimensions for _,segment in dim.segments(style)]
    obstacles += dim_lines
    forbidden = [rect for rect,_ in scene_keepouts(view,content,style)]
    forbidden += [OBox.of(dim.text_box(style,ink=True)).bbox for dim in dimensions]
    # Ветвь может входить в изображение, но не должна пересекать размерные линии и выноски.
    crossing = dim_lines+leader_segments(view)
    grid, added = as_index(obstacles), []
    # Линии диаметров и радиусов с общим центром (в координатах листа) — новый радиус не кладём на ту же прямую.
    rays = [(dim.center, dim.angle) for dim in dimensions if isinstance(dim, DiametralDim)]
    rays += [(frame.sheet(obj.GetXc(), obj.GetYc()), obj.GetAngle())
             for obj in _objects(ks, view.symbols.GetRadialDimensions())]

    def hits(rectangle):
        return chain(near(grid, rectangle, style.tol), added)
    report = DimReport()
    with drawing.edit():
        for index, spec in enumerate(specs):
            key = spec.key or f'curved{index}'
            sources = [spec.curve] if isinstance(spec,Radius) else [spec.first,spec.second]
            if any(curve.is_hidden for curve in sources):
                report.issues.append(Issue('hidden_contour',ERROR,'Радиус/угол относится к скрытому контуру',(key,)))
                continue
            if isinstance(spec,Radius):
                curve = spec.curve
                if curve.kind not in ('arc','circle') or not curve.center or not curve.radius:
                    raise ValueError('Радиальный размер требует дуги или окружности')
                existing = _objects(ks,view.symbols.GetRadialDimensions())
                if any((obj.GetBaseObject() and ks.GetReference(obj.GetBaseObject()) == ks.GetReference(curve.raw)) or
                       (obj.GetConstraints() and abs(obj.GetRadius()-curve.radius) <= style.tol and
                        Point(obj.GetXc(),obj.GetYc()).dist(curve.center) <= style.tol)
                       for obj in existing):
                    continue
                angle = spec.angle
                if angle is None:
                    if curve.angles:
                        a,b = curve.angles
                        sweep = (b-a) % 360 if curve.ccw else -((a-b) % 360)
                        angle = a+sweep/2
                    else:
                        angle = 45.
                center_sheet = frame.sheet(curve.center.x, curve.center.y)
                angle = _free_angle(curve, angle, center_sheet, rays, style.tol, fixed=spec.angle is not None)
                if angle is None:
                    report.issues.append(Issue('lines_overlap', ERROR,
                                               f'R{_fmt(curve.radius)}: нет угла, на котором линия не легла бы на '
                                               f'другой размер того же центра', (key,)))
                    continue
                tip = Point(curve.center.x+curve.radius*cos(radians(angle)),
                            curve.center.y+curve.radius*sin(radians(angle)))
                obj = view.symbols.GetRadialDimensions().Add()
                obj.SetBaseObject(ks.IDrawingObject(curve.raw))
                obj.SetXc(curve.center.x)
                obj.SetYc(curve.center.y)
                obj.SetRadius(curve.radius)
                obj.SetAngle(angle)
                obj.SetDimensionType(False)
                nominal, prefix, suffix = curve.radius, 'R', ''
            else:
                center, ends, angles, nominal = angle_geometry(spec.first,spec.second)
                existing = _objects(ks,view.symbols.GetAngleDimensions())
                refs = {ks.GetReference(curve.raw) for curve in sources}
                if any(({ks.GetReference(source) for source in (obj.GetBaseObject1(),obj.GetBaseObject2()) if source} == refs) or
                       (obj.GetConstraints() and Point(obj.GetXc(),obj.GetYc()).dist(center) <= style.tol and
                        abs(ks.IDimensionText(obj).GetNominalValue()-nominal) <= style.tol and
                        all(min(abs(actual-expected) % 180,180-(abs(actual-expected) % 180)) <= style.tol
                            for actual,expected in zip((obj.GetAngle1(),obj.GetAngle2()),angles)))
                       for obj in existing):
                    continue
                obj = view.symbols.GetAngleDimensions().Add(int(raw.DrawingObjectTypeEnum.ksDrADimension))
                obj.SetBaseObject1(ks.IDrawingObject(spec.first.raw))
                obj.SetBaseObject2(ks.IDrawingObject(spec.second.raw))
                obj.SetXc(center.x)
                obj.SetYc(center.y)
                obj.SetX1(ends[0].x)
                obj.SetY1(ends[0].y)
                obj.SetX2(ends[1].x)
                obj.SetY2(ends[1].y)
                obj.SetAngle1(angles[0])
                obj.SetAngle2(angles[1])
                obj.SetDirection(False)
                obj.SetDimensionType(int(raw.ksAngleDimTypeEnum.ksADMaxAngle if nominal > 90 else raw.ksAngleDimTypeEnum.ksADMinAngle))
                radius = max(center.dist(end) for end in ends)+style.first_offset/frame.k
                theta = radians(angles[0]+nominal/2)
                tip = Point(center.x+radius*cos(theta),center.y+radius*sin(theta))
                obj.SetRadius(radius)
                obj.SetX3(tip.x)
                obj.SetY3(tip.y)
                prefix, suffix = '', '°'
            try:
                text = ks.IDimensionText(obj)
                text.GetPrefix().SetStr(prefix)
                text.GetSuffix().SetStr(suffix)
                check(obj.Update(),'Создание радиуса/угла')
                if abs(text.GetNominalValue()-nominal)>style.tol:
                    raise ValueError(f'{key}: КОМПАС вычислил другое значение размера')
                width, height = text.GetWidth(), text.GetHeight()
                target = frame.sheet(tip.x,tip.y)
                params = ks.IDimensionParams(obj)
                params.SetTextType(int(raw.ksDimensionTextTypeEnum.ksDTPOnShelf))
                params.SetShelfDirection(int(raw.ksShelfDirectionEnum.ksLSRight))
                explicit = _pt(spec.shelf) if spec.shelf else None
                candidates = ([(0, frame.sheet(explicit.x, explicit.y))] if explicit else
                              _shelf_candidates(target, content, width, height, style, max_tiers))
                # Оценка по модели (надпись справа над полкой), в CAD — только лучшие, с проверкой габарита.
                scored = []
                for tier, shelf in candidates:
                    # с тем же запасом, с которым надпись радиуса проверяет scene_keepouts
                    rectangle = Rect(shelf.x, shelf.y, shelf.x+width, shelf.y+height).inflate(style.text_gap/2)
                    line = Segment(target, shelf)
                    if not drawing.sheet.frame.contains(rectangle):
                        continue
                    if any(rectangle.intersects(rect,tol=style.tol) or segment_hits_rect(line,rect,style.tol)
                           for rect in forbidden):
                        continue
                    if any(segment_hits_rect(segment,rectangle,style.tol) for segment in hits(rectangle)):
                        continue
                    crossings = sum(segments_cross(line, segment) for segment in crossing)
                    above = rectangle.x1 < content.x2 and rectangle.x2 > content.x1
                    scored.append(((leader_cost(line, crossings, above), tier), shelf))
                selected = None
                for _, shelf in sorted(scored, key=lambda item: item[0])[:max_realize]:
                    local = frame.view(shelf)
                    obj.SetShelfX(local.x)
                    obj.SetShelfY(local.y)
                    check(obj.Update(),'Полка радиуса/угла')
                    bounds = drawing.objects_bbox([obj])
                    if bounds is None or not drawing.sheet.frame.contains(bounds):
                        continue
                    actual = frame.sheet(obj.GetShelfX(),obj.GetShelfY())
                    rectangle = Rect(actual.x, actual.y, actual.x+width, actual.y+height).inflate(style.text_gap/2)
                    position = ks.IDimension2D(obj).GetTextPosition(0,0)
                    actual_tip = frame.sheet(position[1],position[2]) if position[0] else target
                    line = Segment(actual_tip,actual)
                    if any(rectangle.intersects(rect,tol=style.tol) or segment_hits_rect(line,rect,style.tol)
                           for rect in forbidden):
                        continue
                    if any(segment_hits_rect(segment,rectangle,style.tol) for segment in hits(rectangle)):
                        continue
                    selected = (rectangle, line)
                    break
                if selected is None:
                    obj.Delete()
                    report.issues.append(Issue('no_position',ERROR,f'Нет места для {prefix}{_fmt(nominal)}{suffix}',(key,)))
                    continue
                forbidden.append(selected[0])
                if isinstance(spec, Radius):
                    rays.append((center_sheet, angle))
                added.append(selected[1])
                crossing.append(selected[1])
                associated = bool(obj.GetConstraints())
                report.created.append({'key':key,'label':prefix+_fmt(nominal)+suffix,'associated':associated})
                if not associated:
                    report.issues.append(Issue('not_associated',WARNING,'Радиус/угол не связан с геометрией',(key,)))
            except Exception:
                obj.Delete()
                raise
        drawing.invalidate_geometry(view,bounds_only=True)
    return report


