"""Ассоциативные размеры 3D: черновик, создание, чтение и проверка.

Выбор элементов общий с 2D (ModelFeatures). Аннотации размещаются в главных
плоскостях, геометрия проверяется после применения API. Файл не сохраняется.
"""

from dataclasses import dataclass, field, replace
from math import atan2, degrees, hypot
from typing import Sequence

# из kompas_lib.enums: DocumentType, raw
# из kompas_lib.errors: OperationFailedError, check
# из kompas_lib.geom: Point, Rect, Segment
# из kompas_lib.dims.api: DimReport, _fmt
# из kompas_lib.dims.features: ModelFeatures, recognize_features
# из kompas_lib.dims.plan: DiamRequest, DimRequest, plan_dimensions
# из kompas_lib.dims.redundancy: DimFact, _axis_of, check_redundancy, requirement_from_faces
# из kompas_lib.dims.shapes: ERROR, INFO, WARNING, DiametralDim, DimStyle, Issue, LinearDim, check_dims, group_issues


@dataclass(frozen=True)
class ModelDim:
    """Задание по индексам граней: linear — две плоскости, diameter — цилиндр."""
    kind: str
    faces: tuple[int, ...]
    axis: int
    plane_normal: int
    value: float
    key: str = ""
    count: int = 1
    reference: bool = False
    plane_face: int | None = None


@dataclass
class ModelDimension:
    key: int
    kind: str
    value: float
    label: str
    faces: tuple[int, ...]
    points: tuple[tuple[float, float, float], ...]
    text_position: tuple[float, float, float] | None
    text_width: float
    text_height: float
    plane_normal: int | None
    reference: bool = False
    count: int = 1
    visible: bool = True
    raw: object = field(default=None, repr=False, compare=False)


def _lo(face):
    return face.box.x1, face.box.y1, face.box.z1


def _hi(face):
    return face.box.x2, face.box.y2, face.box.z2


def suggest_model_dimensions(faces: Sequence, features: ModelFeatures | None = None,
                             tol: float = 1e-3) -> tuple[list[ModelDim], list[str]]:
    """План по граням без КОМПАСа: цепи плоскостей и неповторяющиеся цилиндры.

    Из цепи исключается самое длинное звено и добавляется габарит. Пазы не
    превращаются в отверстия, зубья — в сотни цилиндров. Неизвестное отмечается.
    """
    features = features or recognize_features(faces, tol)
    omitted = {i for k in features.keyways for i in k.faces}
    if features.gear:
        omitted.update(features.gear.faces)
    specs, notes = [], list(features.notes)
    profile = features.profile or features.body_profile
    for axis in range(3):
        planes = {}
        for f in faces:
            if f.index in omitted or f.kind != "plane" or not f.normal or _axis_of(f.normal, tol) != axis:
                continue
            coordinate = round(_lo(f)[axis]/tol)
            old = planes.get(coordinate)
            if old is None or f.area > old.area:
                planes[coordinate] = f
        ordered = sorted(planes.values(), key=lambda f: _lo(f)[axis])
        if len(ordered) < 2:
            continue
        normal = next(j for j in (2, 1, 0) if j != axis)
        links = list(zip(ordered, ordered[1:]))
        if len(links) > 1:
            skip = max(range(len(links)), key=lambda i: _lo(links[i][1])[axis]-_lo(links[i][0])[axis])
            links = [pair for i, pair in enumerate(links) if i != skip]
        else:
            links = []
        links.append((ordered[0], ordered[-1]))
        for a, b in links:
            specs.append(ModelDim("linear", (a.index, b.index), axis, normal,
                                  _lo(b)[axis]-_lo(a)[axis], f"L{axis}:{a.index}:{b.index}"))
    patterns = {i: pattern for pattern in features.patterns for i in pattern.faces}
    cylinders = {i for h in features.holes for i in h.faces}
    if profile:
        # из kompas_lib.dims.revolution: is_groove
        cylinders.update(s.face for s in profile.outer + profile.inner if not is_groove(profile, s))
    seen = set()
    for f in sorted(faces, key=lambda f: -max(f.box.size)):
        if f.index in omitted or f.kind != "cylinder" or not f.radius or not f.axis_dir or not f.axis_origin:
            continue
        if f.index not in cylinders and f.index not in patterns:
            continue
        axis = _axis_of(f.axis_dir, tol)
        if axis is None:
            notes.append(f"Цилиндр #{f.index}: нужна произвольная плоскость аннотации")
            continue
        radial = [j for j in range(3) if j != axis]
        signature = (axis, round(f.radius/tol), tuple(round(f.axis_origin[j]/tol) for j in radial))
        pattern = patterns.get(f.index)
        if pattern:
            signature = ("pattern", pattern)
        if signature in seen:
            continue
        seen.add(signature)
        specs.append(ModelDim("diameter", (f.index,), axis, axis, 2*f.radius,
                              f"D{f.index}", pattern.count if pattern else 1))
    for p in features.patterns:
        notes.append(f"Массив {p.count} отв. Ø{2*p.radius:g}: нужна окружность центров Ø{2*p.pitch_radius:g}")
    if features.gear:
        outside = max(profile.outer, key=lambda s:s.r)
        specs.append(ModelDim("diameter", (outside.face,), profile.axis, profile.axis,
                              2*outside.r, f"gear:da:{outside.face}"))
    for k in features.keyways:
        sides = [f for f in faces if f.index in k.faces and f.kind == "plane" and f.normal and
                 _axis_of(f.normal, tol) == k.width_axis]
        if len(sides) == 2:
            bottom = next(f for f in faces if f.index in k.faces and f.kind == "plane" and f.normal and
                          _axis_of(f.normal, tol) == k.depth_axis)
            specs.append(ModelDim("linear", tuple(f.index for f in sides), k.width_axis, k.depth_axis,
                                  k.width, f"keyway:{k.faces[0]}:width", plane_face=bottom.index))
        notes.append(f"Шпоночный паз {k.width:g}×{k.depth:g}×{k.length:g}: глубина и положение — на сечении")
    for c in features.chamfers:
        notes.append(f"{len(c.faces)} фаски {c.size:g}×{c.angle:g}°: нужна выноска")
    if features.gear:
        notes.append(f"Венец: da={2*features.gear.outside_radius:g}, b={features.gear.width:g}; требуется оформление зубчатого колеса")
    return specs, notes


def _point(ks, obj, point_type, index=0):
    result = ks.IDimension3D(obj).GetDimensionPoint(int(point_type), index, 0, 0, 0)
    return tuple(result[1:]) if result[0] else None


def read_model_dimensions(part, faces=None) -> list[ModelDimension]:
    """Прочитать все модельные размеры, включая существующие размеры пользователя."""
    ks = part.ks
    faces = part.faces() if faces is None else faces
    face_by_ref = {ks.GetReference(f.raw): f for f in faces}
    sym = ks.ISymbols3DContainer(part.part)
    result = []
    getters = (("linear", "GetLineDimensions3D", "ILineDimension3D"),
               ("diameter", "GetDiametralDimensions3D", "IDiametralDimension3D"),
               ("radius", "GetRadialDimensions3D", "IRadialDimension3D"),
               ("angle", "GetAngleDimensions3D", "IAngleDimension3D"))
    for kind, getter, interface in getters:
        for raw_obj in getattr(sym, getter)().GetObjects():
            obj = getattr(ks, interface)(raw_obj)
            text = ks.IDimensionText(obj)
            prefix = text.GetPrefix().GetStr()
            suffix = text.GetSuffix().GetStr()
            value = float(text.GetNominalValue())
            linked = []
            for getter_name in ("GetObject1", "GetObject2") if kind in ("linear", "angle") else ("GetObject1",):
                source = getattr(obj, getter_name)()
                f = face_by_ref.get(ks.GetReference(source)) if source else None
                if f:
                    linked.append(f)
            points = tuple(p for i in range(2) if (p := _point(ks, obj, raw.ksDimensionPointEnum.ksDimensionBasePoint, i)) is not None)
            normal = None
            if kind == "diameter" and linked:
                normal = _axis_of(linked[0].axis_dir, 1e-3)
            elif kind == "linear":
                plane = obj.GetPlane()
                if plane:
                    surface = ks.IMathSurface3D(plane.GetMathObject())
                    if surface:
                        n = surface.GetNormal(surface.GetParamUMin(), surface.GetParamVMin(), 0, 0, 0)
                        if n[0]:
                            normal = _axis_of(n[1:], 1e-3)
            sign = "Ø" if kind == "diameter" and "Ø" not in prefix else "R" if kind == "radius" else ""
            count = 1
            import re
            if match := re.search(r"(\d+)\s*отв", prefix+suffix):
                count = int(match.group(1))
            result.append(ModelDimension(ks.GetReference(obj), kind, value, prefix+sign+_fmt(value)+suffix,
                tuple(f.index for f in linked), points,
                _point(ks, obj, raw.ksDimensionPointEnum.ksDimensionTextPoint),
                float(text.GetWidth()), float(text.GetHeight()), normal, "*" in suffix, count,
                not (obj.IsHidden() or part.d3.IsHideAllDimensions()), raw=obj))
    return result


def _fact(dim, faces):
    by_index = {f.index: f for f in faces}
    if dim.kind == "diameter" and dim.faces:
        f = by_index[dim.faces[0]]
        axis = _axis_of(f.axis_dir, 1e-3)
        if axis is not None:
            radial = [j for j in range(3) if j != axis]
            c = f.axis_origin[radial[0]]
            return DimFact(dim.key, radial[0], c-dim.value/2, c+dim.value/2, diameter=True,
                cyl_axis=axis, center={j: f.axis_origin[j] for j in radial},
                reference=dim.reference, label=dim.label, count=dim.count)
    if dim.kind == "linear" and len(dim.points) == 2:
        delta = [abs(a-b) for a, b in zip(*dim.points)]
        axis = max(range(3), key=delta.__getitem__)
        if abs(delta[axis]-dim.value) <= 1e-3:
            return DimFact(dim.key, axis, dim.points[0][axis], dim.points[1][axis],
                           reference=dim.reference, label=dim.label)
    return None


def _shape(part, dim):
    normal = dim.plane_normal
    if normal is None or dim.text_position is None:
        return None
    axes = [j for j in range(3) if j != normal]
    P = lambda p: Point(p[axes[0]], p[axes[1]])
    text = P(dim.text_position)
    if dim.kind == "linear":
        a, b = map(P, dim.points)
        delta = (abs(a.x-b.x), abs(a.y-b.y))
        axis = "x" if delta[0] >= delta[1] else "y"
        line = _point(part.ks, dim.raw, raw.ksDimensionPointEnum.ksDimensionLinePoint)
        line = P(line)
        shape = LinearDim(dim.key, a, b, axis, line.y if axis == "x" else line.x,
                          dim.text_width, dim.text_height, text_mode="manual",
                          text_start=text.x if axis == "x" else text.y, label=dim.label)
        if shape.text_start+shape.text_w <= shape.lo+0.05:
            shape.text_mode = "lo"
        elif shape.text_start >= shape.hi-0.05:
            shape.text_mode = "hi"
        return shape
    if dim.kind == "diameter":
        a3 = _point(part.ks, dim.raw, raw.ksDimensionPointEnum.ksDimensionLinePoint, 0)
        a = P(a3)
        b = P(_point(part.ks, dim.raw, raw.ksDimensionPointEnum.ksDimensionLinePoint, 1))
        c = Point((a.x+b.x)/2, (a.y+b.y)/2)
        angle = degrees(atan2(a.y-c.y, a.x-c.x)) % 360
        shape = DiametralDim(dim.key, c, dim.value/2, angle, dim.text_width, dim.text_height, label=dim.label)
        u = shape.u
        start = (text.x-c.x)*u[0]+(text.y-c.y)*u[1]
        shape.text_t = start + (shape.text_w/2 if shape.reading == u else -shape.text_w/2)
        shape.text_mode = "manual"
        shape.meta["depth"] = a3[normal]       # плоскость размера вдоль нормали: параллельные плоскости не мешают
        return shape
    return None


def check_model_dimensions(part, completeness=True, style=None, faces=None) -> DimReport:
    """Проверка значений, связей, повторов и читаемости в плоскостях аннотаций."""
    style = style or DimStyle()
    faces = part.faces() if faces is None else faces
    dimensions = read_model_dimensions(part, faces)
    report = DimReport()
    facts = [f for d in dimensions if (f := _fact(d, faces)) is not None]
    required, info = requirement_from_faces(faces) if completeness else (None, [])
    report.issues.extend(info)
    report.issues.extend(check_redundancy(facts, required))
    groups = {}
    for dim in dimensions:
        if not dim.raw.IsValid():
            report.issues.append(Issue("invalid_dimension", ERROR, f"Повреждён 3D-размер «{dim.label}»", (dim.key,)))
        if not dim.visible:
            report.issues.append(Issue("hidden_dimension", WARNING, f"3D-размер «{dim.label}» скрыт", (dim.key,)))
        shape = _shape(part, dim)
        if shape is not None:
            groups.setdefault(dim.plane_normal, []).append(shape)
        else:
            report.issues.append(Issue("not_checked", INFO, f"3D-размер «{dim.label}»: плоскость/тип пока не проверяется", (dim.key,)))
    for shapes in groups.values():
        report.issues.extend(check_dims(shapes, style=style))
    return report


def add_model_dimensions(part, specs: Sequence[ModelDim], style=None, max_tiers=8) -> DimReport:
    """Создать и разместить явно выбранные задания; один шаг отмены, без Save."""
    part.require(DocumentType.PART)
    style = style or DimStyle()
    ks = part.ks
    faces = part.faces()
    by_index = {f.index: f for f in faces}
    if len({s.key for s in specs}) != len(specs):
        raise ValueError("Ключи заданий должны быть уникальными")
    for spec in specs:
        if spec.kind not in ("linear", "diameter") or spec.axis not in range(3) or spec.plane_normal not in range(3):
            raise ValueError(f"Неподдерживаемое задание: {spec}")
        fs = [by_index[i] for i in spec.faces]
        if spec.kind == "linear":
            if len(fs) != 2 or any(f.kind != "plane" or _axis_of(f.normal, 1e-3) != spec.axis for f in fs):
                raise ValueError("Линейный размер требует двух параллельных плоских граней")
            if spec.plane_normal == spec.axis:
                raise ValueError("Ось размера должна лежать в плоскости аннотации")
        elif len(fs) != 1 or fs[0].kind != "cylinder" or spec.plane_normal != spec.axis:
            raise ValueError("Диаметральный размер требует цилиндра и поперечной плоскости")
    report = DimReport()
    if not specs:
        return report
    existing = read_model_dimensions(part, faces)
    sym = ks.ISymbols3DContainer(part.part)
    objects = {}
    plane_types = (raw.ksObj3dTypeEnum.o3d_planeYOZ, raw.ksObj3dTypeEnum.o3d_planeXOZ,
                   raw.ksObj3dTypeEnum.o3d_planeXOY)
    with part.edit():
        part.d3.SetHideAllDimensions(False)
        part.d3.SetHideAllAuxiliaryGeom(False)
        try:
            for spec in specs:
                fs = [by_index[i] for i in spec.faces]
                if spec.kind == "linear":
                    obj = ks.ILineDimension3D(sym.GetLineDimensions3D().Add(int(raw.ksObj3dTypeEnum.o3d_lineDimension3D)))
                    obj.SetObject1(fs[0].raw)
                    obj.SetObject2(fs[1].raw)
                    plane = (by_index[spec.plane_face].raw if spec.plane_face is not None else
                             part.part.GetDefaultObject(int(plane_types[spec.plane_normal])))
                    obj.SetPlane(plane)
                    obj.SetLength(style.first_offset)
                else:
                    obj = sym.GetDiametralDimensions3D().Add()
                    obj.SetObject1(fs[0].raw)
                    # Плоскость размера — торец ступени: внутри длины цилиндра, иначе ближайший к нему торец
                    # (у ступени с канавкой/фаской торец не совпадает с концом цилиндра). Плоскость по умолчанию
                    # (начало координат) — крайний случай: размер повисает вне ступени (s89).
                    lo_c, hi_c = _lo(fs[0])[spec.axis], _hi(fs[0])[spec.axis]
                    ends = [f for f in faces if f.kind == "plane" and f.normal and
                            _axis_of(f.normal, 1e-3) == spec.axis]
                    gap = lambda f: max(lo_c - _lo(f)[spec.axis], _lo(f)[spec.axis] - hi_c, 0.0)  # noqa: E731
                    plane = (min(ends, key=lambda f: (round(gap(f), 3), -f.area)).raw if ends else
                             part.part.GetDefaultObject(int(plane_types[spec.plane_normal])))
                    obj.SetPlaneObject(plane)
                    obj.SetDimensionType(False)
                    obj.SetCenterPoint(*fs[0].box.center)
                objects[spec.key] = obj
                obj.SetHidden(False)
                obj.SetVisibleState(int(raw.ksVisibleStateEnum.ksVSVisible))
                obj.SetProjected(int(raw.ksProjectionOptionEnum.ksPOEnable))
                text = ks.IDimensionText(obj)
                if spec.count > 1:
                    text.GetPrefix().SetStr(f"{spec.count} отв. ")
                if spec.reference:
                    text.GetSuffix().SetStr("*")
                check(obj.Update(), "Создание 3D-размера", spec.key)
                check(obj.IsValid(), "Связи 3D-размера", spec.key)
                nominal = float(text.GetNominalValue())
                if abs(nominal-spec.value) > 1e-3:
                    raise OperationFailedError("Значение 3D-размера", f"{spec.key}: ожидалось {spec.value:g}, получено {nominal:g}")
            dimensions = read_model_dimensions(part, faces)
            by_ref = {d.key: d for d in dimensions}
            groups = {}
            for spec in specs:
                dim = by_ref[ks.GetReference(objects[spec.key])]
                # Нормаль линейной аннотации известна из выбранного задания.
                dim.plane_normal = spec.plane_normal
                groups.setdefault(spec.plane_normal, []).append((spec, dim))
            box = part.box()
            lo, hi = (box.x1, box.y1, box.z1), (box.x2, box.y2, box.z2)
            for normal, group in groups.items():
                axes = [j for j in range(3) if j != normal]
                content = Rect(lo[axes[0]], lo[axes[1]], hi[axes[0]], hi[axes[1]])
                requests = []
                lookup = {}
                for spec, dim in group:
                    shape = _shape(part, dim)
                    shape.key = spec.key
                    lookup[spec.key] = dim
                    if isinstance(shape, LinearDim):
                        requests.append(DimRequest(shape.p1, shape.p2, shape.axis, shape.text_w,
                                                   shape.text_h, key=spec.key, label=dim.label))
                    else:
                        requests.append(DiamRequest(shape.center, shape.radius, shape.text_w,
                                                    shape.text_h, key=spec.key, label=dim.label,
                                                    meta={"depth": shape.meta["depth"]}))

                def realize(candidate):
                    dim = lookup[candidate.key]
                    obj = dim.raw
                    anchor = list(dim.points[0])
                    if isinstance(candidate, LinearDim):
                        s, e = candidate.text_range(style)
                        p = candidate.pt((s+e)/2, candidate.line)
                        placement = (candidate.line, candidate.text_mode, candidate.text_start)
                    else:
                        s, e = candidate.text_interval(style)
                        p = candidate._at((s+e)/2)
                        # Угол API отсчитывается в локальной системе плоскости.
                        plane = obj.GetPlaneObject()
                        surface = ks.IMathSurface3D(plane.GetMathObject())
                        placement3d = surface.GetPlacement()
                        vx = placement3d.GetVector(int(raw.ksObj3dTypeEnum.o3d_axisOX), 0, 0, 0)[1:]
                        vy = placement3d.GetVector(int(raw.ksObj3dTypeEnum.o3d_axisOY), 0, 0, 0)[1:]
                        vector = [0., 0., 0.]
                        vector[axes[0]], vector[axes[1]] = candidate.u
                        angle = degrees(atan2(sum(a*b for a,b in zip(vector,vy)),
                                              sum(a*b for a,b in zip(vector,vx))))
                        obj.SetAngle(angle)
                        check(obj.Update(), "Направление 3D-диаметра")
                        placement = (candidate.angle, candidate.text_mode, candidate.text_t)
                    anchor[axes[0]], anchor[axes[1]] = p.x, p.y
                    check(ks.IDimension3D(obj).SetTextPosition(*anchor), "Положение 3D-размера")
                    check(obj.Update(), "Размещение 3D-размера")
                    dim.text_position = _point(ks, obj, raw.ksDimensionPointEnum.ksDimensionTextPoint)
                    actual = _shape(part, dim)
                    actual.key = candidate.key
                    actual.meta["placement"] = placement
                    return actual

                fixed = [_shape(part, d) for d in existing if d.plane_normal == normal]
                plan = plan_dimensions(requests, content, fixed=[d for d in fixed if d is not None],
                                       style=style, max_tiers=max_tiers, realize=realize)
                for shape in plan.dims:
                    a, mode, t = shape.meta["placement"]
                    candidate = (replace(shape, line=a, text_mode=mode, text_start=t)
                                 if isinstance(shape, LinearDim) else replace(shape, angle=a, text_mode=mode, text_t=t))
                    realize(candidate)
                    dim = lookup[shape.key]
                    report.created.append({"key": shape.key, "label": dim.label, "associated": True,
                                           "plane_normal": normal, "faces": dim.faces})
        except Exception:
            for obj in reversed(list(objects.values())):
                check(ks.IFeature(obj).Delete(), "Удаление незавершённого 3D-размера")
            raise
    report.issues.extend(check_model_dimensions(part, completeness=False, style=style, faces=faces).issues)
    return report


def auto_dimension_model(part, style=None, completeness=True, max_tiers=8) -> DimReport:
    """Автоматический черновик размеров 3D-модели без дублей и автосохранения.

    Повторный вызов добавляет только недостающие размеры. Существующие аннотации
    не двигаются. Неизвестные элементы/требования остаются в отчёте.
    """
    part.require(DocumentType.PART)
    faces = part.faces()
    features = part.features(faces=faces)
    specs, notes = suggest_model_dimensions(faces, features)
    existing = [f for d in read_model_dimensions(part, faces) if (f := _fact(d, faces)) is not None]
    selected = []
    by_index = {f.index: f for f in faces}
    for spec in specs:
        fs = [by_index[i] for i in spec.faces]
        if spec.kind == "linear":
            probe = DimFact(spec.key, spec.axis, _lo(fs[0])[spec.axis], _lo(fs[1])[spec.axis])
            active = [f for f in existing if not f.diameter]
        else:
            f = fs[0]
            radial = [j for j in range(3) if j != spec.axis]
            c = f.axis_origin[radial[0]]
            probe = DimFact(spec.key, radial[0], c-f.radius, c+f.radius, diameter=True,
                            cyl_axis=spec.axis, center={j: f.axis_origin[j] for j in radial}, count=spec.count)
            active = existing
        redundant = check_redundancy([*active, probe])
        if any(spec.key in issue.keys and issue.kind in ("duplicate", "closed_chain") for issue in redundant):
            continue
        selected.append(spec)
        existing.append(probe)
    report = add_model_dimensions(part, selected, style=style, max_tiers=max_tiers)
    checked = check_model_dimensions(part, completeness=completeness, style=style, faces=faces)
    report.issues = checked.issues
    report.issues.extend(Issue("detail_required", WARNING, note) for note in notes)
    report.issues = group_issues(report.issues)
    return report


