"""Выноски и оформление распознанных элементов на выбранном виде."""

from dataclasses import dataclass
from math import cos, sin, radians
from itertools import product

# из kompas_lib.enums: raw
# из kompas_lib.errors: OperationFailedError, check
# из kompas_lib.geom: OBox, Point, Rect, Segment, segment_hits_rect, segments_cross
# из kompas_lib.dims.api: Diameter, DimReport, _Frame, _fmt, _model_axes, _objects, _pt, _obj_id, add_dimensions, leader_cost, leader_segments, leader_texts, read_diametral, read_dims, scene_keepouts, view_obstacles
# из kompas_lib.dims.shapes: ERROR, WARNING, DimStyle, Issue
# из kompas_lib.dims.redundancy: _axis_of


@dataclass
class Leader:
    point: Point | tuple[float, float]
    text: str
    source: object = None
    key: str = ""


def add_leaders(view, specs, style=None, max_tiers=12):
    """Полки по измеренному габариту текста; связи с проекцией грани/ребра."""
    style = style or DimStyle()
    ks, drawing, frame = view.ks, view.drawing, _Frame(view)
    content = view.content_bbox()
    if content is None:
        raise OperationFailedError("Выноски", "Пустой вид")
    report = DimReport()
    obstacles = view_obstacles(view)
    dims = read_dims(view, content) + read_diametral(view)
    forbidden = [r for r, _ in scene_keepouts(view, content, style)]
    forbidden += [OBox.of(d.text_box(style, ink=True)).bbox for d in dims]
    dim_lines = [s for d in dims for _, s in d.segments(style)]
    obstacles += dim_lines
    # Ветвь выноски может входить в изображение, но не должна пересекать размерные линии и другие выноски.
    crossing = dim_lines + leader_segments(view)
    existing = {ks.ILeader(o).GetTextOnShelf().GetStr() for o in _objects(ks, view.symbols.GetLeaders())}
    with drawing.edit():
        for i, spec in enumerate(specs):
            if spec.text in existing:
                continue
            p = _pt(spec.point)
            obj = view.symbols.GetLeaders().Add(int(raw.DrawingObjectTypeEnum.ksDrLeader))
            branch, leader = ks.IBranchs(obj), ks.ILeader(obj)
            leader.SetShelfDirection(int(raw.ksShelfDirectionEnum.ksLSRight))
            leader.GetTextOnShelf().SetStr(spec.text)
            branch.SetX0(p.x+style.first_offset/frame.k)
            branch.SetY0(p.y+style.first_offset/frame.k)
            check(branch.AddBranchByPoint(0, p.x, p.y), "Ответвление выноски")
            check(obj.Update(), "Создание выноски")
            initial = drawing.objects_bbox([obj])
            shelf = frame.sheet(branch.GetX0(), branch.GetY0())
            width, height = initial.x2-shelf.x, initial.y2-shelf.y
            target = frame.sheet(p.x, p.y)
            candidates = []
            for tier in range(max_tiers):
                left, right = drawing.sheet.frame.x1+style.text_margin, drawing.sheet.frame.x2-width-style.text_margin
                xs = (target.x, content.x2+style.first_offset, content.x1-width-style.first_offset,
                      min(right,max(left,target.x-width/2)),left,right)
                shift = style.first_offset+tier*style.step_for(height)
                ys = (content.y2+shift,target.y+shift,target.y-shift-height)
                for x,y in product(xs,ys):
                    # с тем же запасом, с которым надпись выноски проверяет scene_keepouts
                    text = Rect(x, y+style.text_gap, x+width, y+height).inflate(style.text_gap/2)
                    line = Segment(target, Point(x, y))
                    if not drawing.sheet.frame.contains(text):
                        continue
                    if any(text.intersects(r, tol=style.tol) or segment_hits_rect(line, r, style.tol) for r in forbidden):
                        continue
                    if any(segment_hits_rect(s, text, style.tol) for s in obstacles):
                        continue
                    # Полка вне поперечного габарита оставляет у торцов место
                    # для выносных линий длин. Ветвь может входить в изображение.
                    above_contour = text.x1 < content.x2 and text.x2 > content.x1
                    crossings = sum(segments_cross(line, s) for s in crossing)
                    score = (leader_cost(line, crossings, above_contour), tier, crossings)
                    candidates.append((score, text, line))
                if any(score[2] == 0 for score, _, _ in candidates):
                    break
            if not candidates:
                ks.IDrawingObject(obj).Delete()
                report.issues.append(Issue("no_position", ERROR, f"Нет места для выноски «{spec.text}»", (spec.key,)))
                continue
            _, text, line = min(candidates, key=lambda c: c[0])
            shelf_v = frame.view(line.b)
            branch.SetX0(shelf_v.x)
            branch.SetY0(shelf_v.y)
            # Индекс сегмента нужен лишь для полилинии; -1 задаёт сам объект.
            associated = bool(spec.source and branch.SetBaseObject(0, ks.IDrawingObject(spec.source), -1))
            check(obj.Update(), "Размещение выноски")
            if not associated and spec.source:
                drawing_object = ks.IDrawingObject(obj)
                drawing_object.Associate()
                associated = bool(drawing_object.GetConstraints())
            forbidden.append(text)
            # Линии ранее поставленных выносок также препятствуют новым надписям.
            obstacles.append(line)
            crossing.append(line)
            existing.add(spec.text)
            leader_texts(drawing)[_obj_id(ks, obj)] = (width, height)
            report.created.append({"key": spec.key or f"leader{i}", "label": spec.text, "associated": associated})
            if not associated:
                report.issues.append(Issue("not_associated", WARNING, f"Выноска «{spec.text}» не связана с геометрией", (spec.key,)))
        drawing.invalidate_geometry(view, bounds_only=True)
    return report


def annotate_hole_patterns(view, features, by_index, style=None) -> tuple:
    """Круговые массивы отверстий на торцевом виде: диаметр окружности центров + выноска «N отв. ØD».

    Возвращает (DimReport, [Leader]): выноски ставит вызывающий вместе с остальными (один add_leaders),
    диаметры ставятся сразу. Окружность центров достраивается осевой линией при её отсутствии.
    """
    style = style or DimStyle()
    report = DimReport()
    leaders = []
    axes = _model_axes(view)
    for pattern in features.patterns:
        if not axes or axes["n"] != pattern.axis:
            continue
        radial = [j for j in range(3) if j != pattern.axis]
        origin = [0., 0., 0.]
        origin[pattern.axis] = by_index[pattern.faces[0]].box.center[pattern.axis]
        for j, value in zip(radial, pattern.center):
            origin[j] = value
        center = view.project_point(*origin)
        circles = view.curves()
        pitch = next((c for c in circles if c.kind == "circle" and c.center.dist(center) <= style.tol and
                      abs(c.radius - pattern.pitch_radius) <= style.tol), None)
        if pitch is None:
            circle = view.ks.IDrawingContainer(view.raw).GetCircles().Add()
            circle.SetXc(center.x)
            circle.SetYc(center.y)
            circle.SetRadius(pattern.pitch_radius)
            circle.SetStyle(int(raw.ksCurveStyleEnum.ksCSAxial))
            check(circle.Update(), "Окружность центров отверстий")
            view.drawing.invalidate_geometry(view)
            report.issues.append(Issue("construction_geometry", WARNING,
                "Окружность центров рассчитана по модели; при её изменении повторите оформление массива"))
        present = [d for d in read_diametral(view) if abs(d.radius / view.scale - pattern.pitch_radius) <= style.tol
                   and d.center.dist(_Frame(view).sheet(center.x, center.y)) <= style.tol]
        if not present:
            dims = add_dimensions(view, [Diameter(center, pattern.pitch_radius, key=f"pitch:{pattern.faces[0]}")],
                                  style)
            report.created += dims.created
            report.issues += dims.issues
        holes = []
        for point in pattern.centers:
            for j, value in zip(radial, point):
                origin[j] = value
            projected = view.project_point(*origin)
            holes += [c for c in circles if c.kind == "circle" and c.center.dist(projected) <= style.tol and
                      abs(c.radius - pattern.radius) <= style.tol]
        if holes:
            circle = max(holes, key=lambda c: c.center.y)
            target = Point(circle.center.x, circle.center.y + circle.radius)
            leaders.append(Leader(target, f"{pattern.count} отв. Ø{_fmt(2 * pattern.radius)}",
                                  circle.raw, f"pattern:{pattern.faces[0]}"))
        else:
            report.issues.append(Issue("feature_not_visible", WARNING,
                f"{pattern.count} отв. Ø{_fmt(2 * pattern.radius)}: отверстия скрыты, нужен разрез/другой торцевой вид"))
    return report, leaders


def annotate_features(view, features, faces, style=None):
    """Фаски, резьбы и круговые массивы из общего промежуточного слоя.

    Вызывающий выбирает вид: отверстия — на торцевом, фаски — на продольном.
    Невидимые элементы пропускаются с объяснением в отчёте.
    """
    style = style or DimStyle()
    report = DimReport()
    leaders = []
    by_index = {f.index: f for f in faces}
    # из kompas_lib.dims.curved: Radius, add_curved_dimensions
    radii = []
    with view.drawing.edit():
        existing_radii = {round(obj.GetRadius()/style.tol) for other in view.drawing.views
                          for obj in _objects(view.ks, other.symbols.GetRadialDimensions())}
        for fillet in features.fillets:
            if round(fillet.radius/style.tol) in existing_radii:
                continue
            projected = [curve for index in fillet.faces
                         for edge in view.ks.IFace(by_index[index].raw).GetLimitingEdges()
                         for curve in view.project(edge)]
            for index in fillet.faces:
                box = by_index[index].box
                points = [view.project_point(*point) for point in product((box.x1,box.x2),(box.y1,box.y2),(box.z1,box.z2))]
                bounds = Rect(min(point.x for point in points),min(point.y for point in points),
                              max(point.x for point in points),max(point.y for point in points)).inflate(style.tol)
                projected += [curve for curve in view.curves() if curve.kind == 'arc' and curve.bbox and bounds.contains(curve.bbox)]
            visible = [curve for curve in projected if curve.kind == 'arc' and not curve.is_hidden and
                       abs(curve.radius-fillet.radius) <= style.tol]
            if visible:
                radii.append(Radius(visible[0],key=f'fillet:{fillet.faces[0]}'))
        if radii:
            result = add_curved_dimensions(view,radii,style)
            report.created += result.created
            report.issues += result.issues
        if features.gear:
            axes=_model_axes(view)
            if axes and axes['n']==features.gear.axis:
                gear=features.gear
                radial=[j for j in range(3) if j!=gear.axis]
                p=[0.,0.,0.]
                p[gear.axis]=(gear.t1+gear.t2)/2
                for j,value in zip(radial,gear.center):
                    p[j]=value
                center=view.project_point(*p)
                circle=next((c for c in view.curves() if c.kind=='circle' and c.center.dist(center)<=style.tol and
                             abs(c.radius-gear.outside_radius)<=style.tol),None)
                if circle is None:
                    circle=view.ks.IDrawingContainer(view.raw).GetCircles().Add()
                    circle.SetXc(center.x);circle.SetYc(center.y);circle.SetRadius(gear.outside_radius)
                    circle.SetStyle(int(raw.ksCurveStyleEnum.ksCSNormal))
                    check(circle.Update(),'Окружность вершин зубьев')
                    view.drawing.invalidate_geometry(view)
                    report.issues.append(Issue('construction_geometry',WARNING,
                        'Окружность вершин da рассчитана по венцу; при изменении модели повторите оформление'))
                result=add_dimensions(view,[Diameter(center,gear.outside_radius,key='gear:da')],style)
                report.created+=result.created
                report.issues+=result.issues
        for feature in features.chamfers:
            projected = [c for i in feature.faces for edge in view.ks.IFace(by_index[i].raw).GetLimitingEdges()
                         for c in view.project(edge)]
            # В разрезе линия фаски порождается пересечением поверхности, а не
            # проекцией исходного ребра. Находим её в проецированном габарите грани.
            for i in feature.faces:
                face = by_index[i]
                b=face.box
                points=[view.project_point(*p) for p in product((b.x1,b.x2),(b.y1,b.y2),(b.z1,b.z2))]
                bounds=Rect(min(p.x for p in points),min(p.y for p in points),
                            max(p.x for p in points),max(p.y for p in points)).inflate(style.tol)
                projected += [c for c in view.curves() if c.kind=="line" and c.bbox and bounds.contains(c.bbox)]
            visible = [c for c in projected
                       if c.kind == "line" and c.p1 and c.p2 and
                       abs(c.p1.x-c.p2.x) > style.tol and abs(c.p1.y-c.p2.y) > style.tol]
            if not visible:
                continue
            c = max(visible, key=lambda c: c.p1.y+c.p2.y)
            target = Point((c.p1.x+c.p2.x)/2, (c.p1.y+c.p2.y)/2)
            count = f"{len(feature.faces)} фаски " if len(feature.faces)>1 else ""
            leaders.append(Leader(target, f"{count}{_fmt(feature.size)}×{_fmt(feature.angle)}°",
                                  c.raw, f"chamfer:{feature.faces[0]}"))
        axes = _model_axes(view)
        labels = {view.ks.ILeader(obj).GetTextOnShelf().GetStr()
                  for other in view.drawing.views for obj in _objects(view.ks, other.symbols.GetLeaders())}
        for thread in features.threads:
            if not thread.designation:
                report.issues.append(Issue('detail_required', WARNING,
                    'У резьбы в модели отсутствует обозначение стандарта; проверьте её параметры'))
                continue
            label = thread.designation
            if thread.left and 'LH' not in label:
                label += ' LH'
            if label in labels:
                continue
            sources = [by_index[index] for index in thread.faces if index in by_index]
            if axes and sources and all(face.axis_dir and _axis_of(face.axis_dir, style.tol) == axes['n']
                                        for face in sources):
                continue
            curves = [curve for face in sources for edge in view.ks.IFace(face.raw).GetLimitingEdges()
                      for curve in view.project(edge) if not curve.is_hidden]
            if curves:
                curve = max(curves, key=lambda curve: curve.bbox.y2 if curve.bbox else float('-inf'))
                if curve.p1 and curve.p2:
                    point = Point((curve.p1.x+curve.p2.x)/2, (curve.p1.y+curve.p2.y)/2)
                elif curve.center and curve.radius:
                    point = Point(curve.center.x, curve.center.y+curve.radius)
                else:
                    continue
                leaders.append(Leader(point, label, curve.raw, f'thread:{thread.faces}'))
                labels.add(label)
        pat_report, pat_leaders = annotate_hole_patterns(view, features, by_index, style)
        report.created += pat_report.created
        report.issues += pat_report.issues
        leaders += pat_leaders
        result = add_leaders(view, leaders, style)
        report.created += result.created
        report.issues += result.issues
    return report


