"""Черновой чертёж из общего слоя конструктивных элементов."""

from dataclasses import dataclass
from contextlib import contextmanager

# из kompas_lib.enums: DocumentType, Projection, SheetFormat
# из kompas_lib.errors: LayoutError
# из kompas_lib.layout: LayoutConfig, arrange_sheet, dim_reserve
# из kompas_lib.dims.api: Dim, Diameter, DimReport, add_dimensions, check_dimensions, _fmt, overall_dims, suggest_revolution_dims, arrange_dimensions, restore_dimensions, _model_axes, prune_redundant
