# Ошибки оформления, ради которых вид стоит разложить заново.
_LAYOUT_ERRORS = {'text_overlap', 'line_through_text', 'lines_cross', 'lines_overlap', 'text_crossed_by_geometry',
                  'in_keepout', 'outside_frame', 'model_mismatch'}

# Проекция модели, в которой ось с данным номером (0 — X, 1 — Y, 2 — Z) смотрит на зрителя.
# Проверяется после создания вида через _model_axes.
_PLAN_PROJECTION = {0: '#Спереди', 1: '#Слева', 2: '#Сверху'}
FLAT_RATIO = 0.2   # толщина ≤ 20 % меньшего размера в плане — плоская деталь


def _flat_axis(part):
    """Номер оси толщины плоской детали или None."""
    box = part.box()
    sizes = [box.x2-box.x1, box.y2-box.y1, box.z2-box.z1]
    thin = min(range(3), key=lambda i: sizes[i])
    rest = sorted(s for i, s in enumerate(sizes) if i != thin)
    return thin if rest[0] > 0 and sizes[thin] <= FLAT_RATIO*rest[0] else None


@dataclass
class DrawingDraft:
    drawing: object
    features: object
    report: DimReport


@contextmanager
def _draft_edit(drawing):
    """Ошибка генерации не оставляет незавершённый документ без владельца."""
    try:
        with drawing.edit():
            yield
    except Exception:
        drawing.close(save=False)
        raise


def _keyway_dimensions(drawing, main, profile, keyways, faces):
    report = DimReport()
    main_specs = []
    sections = []
    for number, k in enumerate(keyways):
        def world(t, width=None, depth=None):
            c=[0.,0.,0.]
            c[k.axis]=t
            for j,value in profile.center.items():
                c[j]=value
            if width is not None:
                c[k.width_axis]+=width
            if depth is not None:
                c[k.depth_axis]=depth
            return c
        middle=(k.t1+k.t2)/2
        center=main.project_point(*world(middle))
        end=main.project_point(*world(middle+1))
        horizontal=abs(end.x-center.x)>abs(end.y-center.y)
        # След пересекает всё изображение и проходит внутри прямого участка паза.
        reach=k.radius+10/main.scale
        points=([(center.x,center.y-reach),(center.x,center.y+reach)] if horizontal else
                [(center.x-reach,center.y),(center.x+reach,center.y)])
        section=drawing.add_section(main,points,at=(main.origin.x+number*70,main.origin.y-90),section=True)
        if not section.curves():
            # Некоторые сохранённые тела v26 не дают геометрии vt_Section.
            # Явный разрез ICutViewParam работает с тем же телом и сохраняет связи.
            cut_line = drawing.ks.IDrawingObject(section.raw.GetBaseObject())
            section.raw.Delete()
            cut_line.Delete()
            drawing.invalidate_geometry()
            section=drawing.add_section(main,points,at=(main.origin.x+number*70,main.origin.y-90),
                                        section=False,arrows_left=True)
            section.cut(main,center)
            report.issues.append(Issue('section_fallback',INFO,
                'KsAPI вернул пустое сечение паза: создан ассоциативный поперечный разрез'))
        # из kompas_lib.dims.redundancy: _axis_of
        side_faces = [face for face in faces if face.index in k.faces and face.normal and
                      _axis_of(face.normal,0.001) == k.width_axis]
        side_depths = [value for face in side_faces for value in
                      ((face.box.x1,face.box.y1,face.box.z1)[k.depth_axis],
                       (face.box.x2,face.box.y2,face.box.z2)[k.depth_axis])]
        width_depth = min(side_depths,key=lambda value:abs(value-k.bottom)) if side_depths else k.bottom
        a=section.project_point(*world(middle,-k.width/2,width_depth))
        b=section.project_point(*world(middle,k.width/2,width_depth))
        bottom=section.project_point(*world(middle,0,k.bottom))
        sign=1 if k.bottom>profile.center[k.depth_axis] else -1
        opposite=section.project_point(*world(middle,0,profile.center[k.depth_axis]-sign*k.radius))
        specs=[Dim(a,b,key=f"keyway{number}:width"),Dim(opposite,bottom,key=f"keyway{number}:depth")]
        sections.append((section,specs))
        a=main.project_point(*world(k.t1,0,k.bottom))
        b=main.project_point(*world(k.t2,0,k.bottom))
        origin=main.project_point(*world(profile.t_min,0,k.bottom))
        if abs(k.t1-profile.t_min)>0.001 or abs(k.t2-profile.t_max)>0.001:
            main_specs.append(Dim(a,b,key=f"keyway{number}:length"))
        if origin.dist(a)>0.001:
            main_specs.append(Dim(origin,a,key=f"keyway{number}:position"))
    return report, main_specs, sections


def _pattern_skip_points(view, features, faces) -> list:
    """Центры отверстий круговых массивов в координатах вида: их положение задаёт диаметр окружности
    центров, координаты от базы по ним не строятся (см. flat.suggest_flat_dims(skip=...))."""
    by_index = {f.index: f for f in faces}
    out = []
    for pattern in features.patterns:
        radial = [j for j in range(3) if j != pattern.axis]
        origin = [0., 0., 0.]
        try:
            origin[pattern.axis] = by_index[pattern.faces[0]].box.center[pattern.axis]
        except (KeyError, AttributeError):  # noqa: BLE001
            continue
        for point in pattern.centers:
            for j, value in zip(radial, point):
                origin[j] = value
            try:
                out.append(view.project_point(*origin))
            except Exception:  # noqa: BLE001
                continue
    return out


def create_dimensioned_drawing(part, diameter_policy="section", include_keyways=True):
    """Создать проверяемый черновик; вернуть документ, элементы и отчёт.

    Функция не сохраняет файлы. Для отливок/неопознанной формы — габариты и отчёт.
    Данные зацепления, допуски и технологические базы остаются решением конструктора.
    """
    part.require(DocumentType.PART)
    faces=part.faces()
    features=part.features(faces=faces)
    profile=features.profile or features.body_profile
    drawing=part.kompas.new_drawing(SheetFormat.A3)
    report=DimReport()
    with _draft_edit(drawing):
        if profile:
            suggestion=suggest_revolution_views(profile,faces)
            projections=list(suggestion.projections)
            if features.patterns and len(projections)==1:
                projections.append(Projection.LEFT)
            views=drawing.add_standard_views(part,projections,main_projection=suggestion.main_projection)
        else:
            thin = _flat_axis(part)
            if thin is not None:
                # Плоская деталь: главный вид — в плане, один боковой вид — под толщину.
                box = part.box()
                sizes = [box.x2-box.x1, box.y2-box.y1, box.z2-box.z1]
                plan_w, plan_h = [s for i, s in enumerate(sizes) if i != thin][:2]
                side = Projection.TOP if plan_w >= plan_h else Projection.LEFT
                views=drawing.add_standard_views(part,[Projection.FRONT,side],
                                                 main_projection=_PLAN_PROJECTION[thin])
                axes=_model_axes(views[Projection.FRONT])
                if not axes or axes['n']!=thin:
                    # Соответствие проекций осям модели не подтвердилось — исходный набор видов.
                    for v in list(views.values()):
                        v.raw.Delete()
                    drawing.invalidate_geometry()
                    views=drawing.add_standard_views(part,[Projection.FRONT,Projection.TOP,Projection.LEFT])
            else:
                views=drawing.add_standard_views(part,[Projection.FRONT,Projection.TOP,Projection.LEFT])
        main=views[Projection.FRONT]
        end=next((v for p,v in views.items() if p!=Projection.FRONT),None)
        if profile and profile.hollow and end:
            c=[0.,0.,0.]
            c[profile.axis]=(profile.t_min+profile.t_max)/2
            for j,value in profile.center.items():
                c[j]=value
            main.cut(end,end.project_point(*c))
        keyway_specs=[]
        keyway_sections=[]
        if include_keyways and profile and features.keyways:
            placed,keyway_specs,keyway_sections=_keyway_dimensions(drawing,main,profile,features.keyways,faces)
            report.created+=placed.created
            report.issues+=placed.issues
        flat_plan=None
        layout_cfg=None
        pattern_skip=[]
        if not profile:
            # Набор размеров известен до выбора масштаба: резерв ярусов по сторонам главного вида.
            pattern_skip = _pattern_skip_points(main, features, faces)
            flat_plan=suggest_flat_dims(main, skip=pattern_skip)
            layout_cfg=LayoutConfig(reserves={main.number:[dim_reserve(n) for n in flat_dim_tiers(flat_plan)]})
        with drawing.geometry_cache():
            arrange_sheet(drawing,main=main,cfg=layout_cfg)
            for section, specs in keyway_sections:
                placed = add_dimensions(section,specs)
                report.created += placed.created
                report.issues += placed.issues
            if profile:
                specs,notes=suggest_revolution_dims(main,profile,end_view=end,diameter_policy=diameter_policy)
                if features.gear:
                    # da уже определён на торцевом виде по окружности вершин.
                    tooth_diameter=2*features.gear.outside_radius
                    specs=[s for s in specs if not (isinstance(s,Dim) and s.diameter and
                            abs(abs(s.p1.x-s.p2.x)+abs(s.p1.y-s.p2.y)-tooth_diameter)<=0.01)]
                    # Диаметры ступицы/отверстия лучше вынести за сложный разрез.
                    for spec in specs:
                        if isinstance(spec,Dim) and spec.diameter:
                            spec.side,spec.at,spec.at_range='auto',None,None
            else:
                # Контуры главного вида: отверстия, пазы, окна, фаски, уступы и их положение.
                # Масштаб уже выбран компоновкой: перестраиваем набор с фильтром читаемости
                # (позиционные связи короче 2 мм на листе не предлагаются).
                # из kompas_lib.dims.shapes: DimStyle
                flat_plan = suggest_flat_dims(main, skip=pattern_skip,
                                              min_readable=DimStyle().min_feature / main.scale)
                flat_report, notes = dimension_flat_view(main, plan=flat_plan)
                if features.patterns:
                    # из kompas_lib.dims.annotations: add_leaders, annotate_hole_patterns
                    pat_report, pat_leaders = annotate_hole_patterns(main, features,
                                                                     {f.index: f for f in faces})
                    flat_report.created += pat_report.created
                    flat_report.issues += pat_report.issues
                    if pat_leaders:
                        placed = add_leaders(main, pat_leaders)
                        flat_report.created += placed.created
                        flat_report.issues += placed.issues
                report.created += flat_report.created
                report.issues += flat_report.issues
                specs = []
                axes = _model_axes(main)
                covered = {axes[name][0] for name in ('x','y')} if axes else set()
                for other in drawing.views:
                    if other.number == main.number:
                        continue
                    mapping = _model_axes(other)
                    if not mapping:
                        continue
                    extra = [spec for spec in overall_dims(other,key_prefix=f'overall{other.number}')
                             if mapping[spec.axis][0] not in covered]
                    if extra:
                        placed = add_dimensions(other,extra)
                        report.created += placed.created
                        report.issues += placed.issues
                        covered.update(mapping[spec.axis][0] for spec in extra)
            if specs or keyway_specs:
                specs, pruned = prune_redundant(specs+keyway_specs)
                report.issues += pruned
                placed=add_dimensions(main,specs)
                report.created+=placed.created
                report.issues+=placed.issues
            for view in (main,end) if end else (main,):
                if profile:
                    placed=annotate_features(view,features,faces)
                    report.created+=placed.created
                    report.issues+=placed.issues
            if profile and profile.outer and end:
                largest = max(profile.outer, key=lambda step: step.r)
                label = f"Ø{_fmt(2*largest.r)}"
                if not any(item['label'] == label for item in report.created):
                    # Контур максимальной ступени может быть прерван приливом
                    # или пазом на продольном виде. Проверяем торцевую проекцию.
                    c = [0., 0., 0.]
                    c[profile.axis] = (largest.t1+largest.t2)/2
                    for axis, coordinate in profile.center.items():
                        c[axis] = coordinate
                    center = end.project_point(*c)
                    if any(curve.kind in ('circle','arc') and curve.center.dist(center) <= 0.01 and
                           abs(curve.radius-largest.r) <= 0.01 for curve in end.curves()):
                        placed = add_dimensions(end, [Diameter(center, largest.r, key='maximum_diameter')])
                        report.created += placed.created
                        report.issues += placed.issues
                        notes = [note for note in notes if not note.startswith(label)]
            if diameter_policy == "end" and profile and end:
                # из kompas_lib.dims.api: suggest_end_dimensions
                specs2,notes2=suggest_end_dimensions(end,profile,diameter_policy="end")
                placed=add_dimensions(end,specs2)
                report.created+=placed.created
                report.issues+=placed.issues
                notes+=notes2
            try:
                arrange_sheet(drawing,main=main)
            except LayoutError:
                # Масштаб уже принят; оформленные виды не влезли — следующий формат.
                arrange_sheet(drawing,main=main,formats=(SheetFormat.A2,SheetFormat.A1))
                report.issues.append(Issue('sheet_enlarged',WARNING,
                    'Оформленные виды не поместились на A2 при выбранном масштабе: формат увеличен'))
            # Компоновка только сдвигает виды (масштаб принят до оформления): в координатах вида раскладка
            # не меняется. Восстанавливаем запомненные положения и раскладываем заново лишь виды с ошибками.
            moved={view.number for view in drawing.views if restore_dimensions(view)}
            checked=check_dimensions(drawing,part)
            # Заново — только вид, где восстановление не удалось (КОМПАС пересчитал надписи): иначе
            # раскладка та же, что уже выбрана, и повтор её не улучшит.
            broken={str(key).split(':')[0] for issue in checked.errors if issue.kind in _LAYOUT_ERRORS
                    for key in issue.keys} & {str(number) for number in moved}
            for view in drawing.views:
                if str(view.number) in broken:
                    arrange_dimensions(view)
            if broken:
                checked=check_dimensions(drawing,part)
            # Текущая проверка заменяет промежуточные конфликты до компоновки.
            geometry_issues = {'text_overlap','line_through_text','lines_cross','ext_lines_cross','lines_overlap',
                               'too_close','text_crossed_by_geometry','dim_line_crosses_geometry',
                               'ext_line_crosses_geometry','in_keepout','outside_frame','model_mismatch'}
            report.issues=[issue for issue in report.issues if issue.kind not in geometry_issues]
            report.issues+=checked.issues
            report.issues.extend(Issue("detail_required",WARNING,note) for note in features.notes)
            report.issues.extend(Issue("detail_required",WARNING,note) for note in notes
                                 if 'не виден' in note or 'не предложен' in note)
    return DrawingDraft(drawing,features,report)


