# === 47/55 kompas_lib.assembly.ports — kompas_lib/assembly/ports.py
# ==================================================================================================================
"""Порты — посадочные места детали для сопряжений (чистый код, без KsAPI).

Порт объединяет грани одной поверхности: разрезанный цилиндр — один порт, торец из нескольких граней — один порт.
Координаты порта — в собственной СК файла детали, поэтому порты считаются один раз на файл и годятся для всех его
вставок; в СК сборки их переводит матрица компонента (`Port.placed(matrix)`).

Имена портов (id) построены по смыслу, а не по номерам граней:

    ext Ø40        наружный цилиндр Ø40 (единственный такой)
    int Ø9#3       третье по оси отверстие Ø9 (номер — по положению вдоль оси, затем по координатам)
    plane +X#1     крайняя плоскость с наружной нормалью +X (#1 — самая дальняя в направлении нормали)
    plane n(0.707,0.707,0)#1   наклонная плоскость

Разбор запроса `find()` прощает регистр, лишние пробелы, `d`/`D` вместо `Ø` и `cyl`; при неоднозначности или
промахе ошибка перечисляет подходящие порты.
"""

import math
import re
from dataclasses import dataclass, field, replace
from typing import Iterable, Sequence
# из kompas_lib.vec3: Vec3, cross, dot, norm, rounded, unit, vadd, vmul, vsub

Matrix = Sequence[float]  # 4×4 по строкам, перенос в последней строке (KsAPI GetSummMatrix / GetMatrix3D)

LINEAR_TOL = 1e-2   # мм: одна поверхность, одинаковый диаметр
ANGLE_TOL = 1e-4    # |1 - cos|: параллельность направлений


# --- векторная арифметика ------------------------------------------------------------------------------
def _vec3(it) -> Vec3:
    a, b, c = (rounded(float(v)) for v in it)
    return (a, b, c)


def canonical_dir(d: Vec3) -> Vec3:
    """Направление прямой без знака: первая ненулевая компонента положительна."""
    d = unit(d)
    for c in d:
        if abs(c) > 1e-9:
            return d if c > 0 else vmul(d, -1.0)
    return d


def apply(m: Matrix, p: Vec3) -> Vec3:
    """Точка из СК компонента в СК сборки (матрица KsAPI: строки — оси, последняя строка — перенос)."""
    x, y, z = p
    return (x * m[0] + y * m[4] + z * m[8] + m[12],
            x * m[1] + y * m[5] + z * m[9] + m[13],
            x * m[2] + y * m[6] + z * m[10] + m[14])


def apply_dir(m: Matrix, v: Vec3) -> Vec3:
    x, y, z = v
    return (x * m[0] + y * m[4] + z * m[8], x * m[1] + y * m[5] + z * m[9], x * m[2] + y * m[6] + z * m[10])


PORT_AXES = {"+X": (1.0, 0.0, 0.0), "-X": (-1.0, 0.0, 0.0), "+Y": (0.0, 1.0, 0.0), "-Y": (0.0, -1.0, 0.0),
        "+Z": (0.0, 0.0, 1.0), "-Z": (0.0, 0.0, -1.0)}


def dir_label(d: Vec3, signed: bool = True) -> str:
    """'+X' для осевого направления, иначе 'n(0.707,0.707,0)'."""
    d = unit(d)
    for name, a in PORT_AXES.items():
        if dot(d, a) > 1 - ANGLE_TOL:
            return name if signed else name[1]
    return "n(" + ",".join(f"{rounded(c, 3):g}" for c in d) + ")"


def fmt_mm(v: float) -> str:
    return f"{round(v, 3):g}"


# --- порт ---------------------------------------------------------------------------------------------------------
@dataclass(frozen=True)
class Port:
    """Посадочное место детали: цилиндр (ось + Ø) или плоскость (точка + нормаль наружу)."""
    id: str
    kind: str                          # cylinder | plane
    origin: Vec3                       # цилиндр: точка оси в начале участка; плоскость: точка на ней
    direction: Vec3                    # цилиндр: ось (канонический знак); плоскость: нормаль наружу из тела
    side: str | None = None            # цилиндр: ext | int
    diameter: float | None = None
    length: float | None = None        # цилиндр: длина участка вдоль оси
    area: float = 0.0
    faces: tuple[int, ...] = ()        # индексы граней в порядке IFeature.GetModelObjects(o3d_face)
    group: str = ""                    # 'ext Ø40' — общая часть id без номера

    @property
    def radius(self) -> float | None:
        return None if self.diameter is None else self.diameter / 2

    def placed(self, m: Matrix) -> "Port":
        """Тот же порт в СК сборки."""
        return replace(self, origin=apply(m, self.origin), direction=unit(apply_dir(m, self.direction)))

    def describe(self) -> str:
        """Строка для списка портов: id и где он находится (в СК детали)."""
        if self.kind == "cylinder":
            ax = dir_label(self.direction, signed=False)
            if len(ax) == 1:
                i = "XYZ".index(ax)
                a, b = self.origin[i], self.origin[i] + (self.length or 0.0)
                where = f"{ax.lower()} {fmt_mm(a)}..{fmt_mm(b)}"
                off = [fmt_mm(self.origin[j]) for j in range(3) if j != i]
                if any(o != "0" for o in off):
                    where += f" ось ({', '.join(off)})"
            else:
                where = f"ось {ax} через ({', '.join(fmt_mm(c) for c in self.origin)}), L={fmt_mm(self.length or 0)}"
            return f"{self.id:<16} {where}"
        lab = dir_label(self.direction)
        if len(lab) == 2:
            i = "XYZ".index(lab[1])
            where = f"{lab[1].lower()}={fmt_mm(self.origin[i])}"
        else:
            where = f"d={fmt_mm(dot(self.origin, self.direction))}"
        return f"{self.id:<16} {where}  S={fmt_mm(self.area)} мм²"


class PortNotFound(LookupError):
    """Порт не найден или запрос неоднозначен; текст перечисляет подходящие варианты."""


@dataclass
class PortList:
    """Порты одной детали. `str(ports)` — компактная таблица для агента."""
    ports: list[Port] = field(default_factory=list)
    title: str = ""

    def __iter__(self):
        return iter(self.ports)

    def __len__(self) -> int:
        return len(self.ports)

    def __getitem__(self, i):
        return self.ports[i]

    def by_id(self) -> dict[str, Port]:
        return {p.id: p for p in self.ports}

    def cylinders(self, side: str | None = None) -> list[Port]:
        return [p for p in self.ports if p.kind == "cylinder" and (side is None or p.side == side)]

    def planes(self) -> list[Port]:
        return [p for p in self.ports if p.kind == "plane"]

    def find(self, query: str | Port) -> Port:
        """Порт по id или по неполному запросу ('Ø54', 'int d9#2', 'plane +x')."""
        if isinstance(query, Port):
            return query
        want = parse_query(query)
        exact = [p for p in self.ports if _norm_id(p.id) == want["norm"]]
        if exact:
            return exact[0]
        cand = [p for p in self.ports if _matches(p, want)]
        if want.get("n") is not None:
            cand = [p for p in cand if _number(p.id) == want["n"]]
        if len(cand) == 1:
            return cand[0]
        if not cand:
            near = _nearest(self.ports, want)
            raise PortNotFound(f"Порт {query!r} не найден{(' у ' + self.title) if self.title else ''}. "
                               f"Ближайшие: {', '.join(p.id for p in near) or 'нет портов'}")
        listing = "; ".join(p.describe() for p in cand[:8])
        raise PortNotFound(f"Запрос {query!r} неоднозначен ({len(cand)} портов): {listing}. Уточните номером #n.")

    def select(self, kind: str | None = None, side: str | None = None, d: float | None = None,
               normal: str | Vec3 | None = None, tol: float = LINEAR_TOL) -> list[Port]:
        """Фильтр по признакам: kind='cylinder'|'plane', side='ext'|'int', d=Ø, normal='+X' или вектор."""
        out = []
        nv = PORT_AXES[normal.upper()] if isinstance(normal, str) else normal
        for p in self.ports:
            if kind and p.kind != _kind_alias(kind):
                continue
            if side and p.side != side:
                continue
            if d is not None and (p.diameter is None or abs(p.diameter - d) > tol):
                continue
            if nv is not None and (p.kind != "plane" or dot(unit(nv), p.direction) < 1 - ANGLE_TOL):
                continue
            out.append(p)
        return out

    def summary(self, limit: int = 40) -> str:
        """Сводка: одинаковые порты свёрнуты в строку 'int Ø9 ×6 (#1..#6)'."""
        lines = [self.title] if self.title else []
        groups: dict[str, list[Port]] = {}
        for p in self.ports:
            groups.setdefault(p.group, []).append(p)
        shown = 0
        for g, ps in groups.items():
            if shown >= limit:
                lines.append(f"... ещё {len(groups) - shown} групп")
                break
            if len(ps) <= 3:
                lines.extend(p.describe() for p in ps)
            else:
                lines.append(f"{g} ×{len(ps)} (#1..#{len(ps)}): {ps[0].describe().split(maxsplit=2)[-1]} … "
                             f"{ps[-1].describe().split(maxsplit=2)[-1]}")
            shown += 1
        return "\n".join(lines)

    def __str__(self) -> str:
        return self.summary()


# --- построение портов из граней -----------------------------------------------------------------------------------
def _box_corners(box) -> list[Vec3]:
    return [(x, y, z) for x in (box.x1, box.x2) for y in (box.y1, box.y2) for z in (box.z1, box.z2)]


def build_ports(faces: Iterable, title: str = "", tol: float = LINEAR_TOL) -> PortList:
    """Порты из граней `model.Face` (в СК файла детали).

    Цилиндры объединяются по (сторона, Ø, ось), плоскости — по (нормаль наружу, расстояние). Конусы, торы и
    сложные поверхности портами не считаются.
    """
    cyl: dict[tuple, dict] = {}
    pln: dict[tuple, dict] = {}
    key: tuple
    for f in faces:
        if f.kind == "cylinder" and f.axis_dir and f.axis_origin and f.radius:
            d = canonical_dir(f.axis_dir)
            o = f.axis_origin
            foot = vsub(o, vmul(d, dot(o, d)))            # точка оси, ближайшая к началу координат
            side = "int" if f.internal else "ext"
            key = (side, round(2 * f.radius / tol), tuple(round(c / tol) for c in d),
                   tuple(round(c / tol) for c in foot))
            proj = [dot(c, d) for c in _box_corners(f.box)]
            # для оси вдоль координатной оси габарит грани точен; для наклонной — грубая оценка
            lo, hi = min(proj), max(proj)
            g = cyl.setdefault(key, {"d": d, "foot": foot, "r": f.radius, "side": side, "parts": []})
            g["parts"].append((lo, hi, f.area, f.index))
        elif f.kind == "plane" and (f.outward or f.normal) and f.point:
            n = unit(f.outward or f.normal)
            off = dot(f.point, n)
            key = (tuple(round(c / ANGLE_TOL / 10) for c in n), round(off / tol))
            g = pln.setdefault(key, {"n": n, "off": off, "point": f.point, "area": 0.0, "faces": [],
                                     "best": -1.0})
            g["area"] += f.area
            g["faces"].append(f.index)
            if f.area > g["best"]:
                g["best"], g["point"] = f.area, f.point
    ports: list[Port] = []
    # цилиндры: группа = сторона + Ø; номер — по положению вдоль оси, затем по координатам оси
    by_group: dict[str, list[dict]] = {}
    for g in cyl.values():
        name = f"{g['side']} Ø{fmt_mm(2 * g['r'])}"
        # одна ось и Ø, но участки вдоль оси разнесены (две шейки Ø40) — разные порты;
        # перекрывающиеся участки (цилиндр, разрезанный на половины) — один порт
        for lo, hi, area, idx in sorted(g["parts"]):
            runs = by_group.setdefault(name, [])
            run = next((r for r in runs if r["key"] == id(g) and lo <= r["hi"] + tol), None)
            if run is None:
                runs.append({"key": id(g), "d": g["d"], "foot": g["foot"], "r": g["r"], "side": g["side"], "lo": lo, "hi": hi, "area": area,
                             "faces": [idx]})
            else:
                run["hi"] = max(run["hi"], hi)
                run["area"] += area
                run["faces"].append(idx)
    for name in sorted(by_group, key=lambda s: (s.split()[0], float(s.split("Ø")[1]))):
        items = sorted(by_group[name], key=lambda g: (round(g["lo"], 3), round(g["hi"], 3),
                                                      tuple(round(c, 3) for c in g["foot"])))
        for i, g in enumerate(items, 1):
            pid = name if len(items) == 1 else f"{name}#{i}"
            origin = vadd(g["foot"], vmul(g["d"], g["lo"]))
            ports.append(Port(pid, "cylinder", _vec3(origin), g["d"], g["side"],
                              rounded(2 * g["r"]), rounded(g["hi"] - g["lo"]), rounded(g["area"], 3),
                              tuple(sorted(g["faces"])), name))
    # плоскости: группа = нормаль; номер — от самой дальней в направлении нормали
    by_n: dict[str, list[dict]] = {}
    for g in pln.values():
        by_n.setdefault(f"plane {dir_label(g['n'])}", []).append(g)
    order = {f"plane {k}": i for i, k in enumerate(PORT_AXES)}
    for name in sorted(by_n, key=lambda s: (order.get(s, 99), s)):
        items = sorted(by_n[name], key=lambda g: -g["off"])
        for i, g in enumerate(items, 1):
            pid = f"{name}#{i}"
            ports.append(Port(pid, "plane", _vec3(g["point"]),
                              _vec3(g["n"]), area=rounded(g["area"], 3),
                              faces=tuple(sorted(g["faces"])), group=name))
    return PortList(ports, title)


# --- разбор запросов -------------------------------------------------------------------------------------------------
def _kind_alias(kind: str) -> str:
    k = kind.lower()
    return {"cyl": "cylinder", "цилиндр": "cylinder", "плоскость": "plane", "face": "plane"}.get(k, k)


def _norm_id(s: str) -> str:
    return s.strip().lower().replace("ø", "d").replace("⌀", "d").replace(" ", "")


def _number(pid: str) -> int | None:
    m = re.search(r"#(\d+)$", pid)
    return int(m.group(1)) if m else None


def parse_query(q: str) -> dict:
    """'int Ø9#2' → {'side': 'int', 'd': 9.0, 'n': 2}; 'plane +x' → {'kind': 'plane', 'normal': '+X'}."""
    s = q.strip()
    out: dict = {"norm": _norm_id(s)}
    low = s.lower()
    m = re.search(r"#\s*(\d+)\s*$", low)
    if m:
        out["n"] = int(m.group(1))
        low = low[:m.start()]
    if re.search(r"\b(ext|наруж\w*)\b", low):
        out["side"] = "ext"
    if re.search(r"\b(int|внутр\w*|отв\w*|hole)\b", low):
        out["side"] = "int"
    m = re.search(r"(?:ø|⌀|\bd|\bdia)\s*(\d+(?:[.,]\d+)?)", low)
    if m:
        out["d"] = float(m.group(1).replace(",", "."))
        out["kind"] = "cylinder"
    if re.search(r"\b(plane|плоск\w*|face|торец)\b", low):
        out["kind"] = "plane"
    m = re.search(r"([+-])\s*([xyz])\b", low)
    if m:
        out["normal"] = (m.group(1) + m.group(2)).upper()
        out.setdefault("kind", "plane")
    if re.search(r"\b(cyl\w*|цилиндр\w*)\b", low):
        out["kind"] = "cylinder"
    return out


def _matches(p: Port, w: dict) -> bool:
    if w.get("kind") and p.kind != w["kind"]:
        return False
    if w.get("side") and p.side != w["side"]:
        return False
    if w.get("d") is not None and (p.diameter is None or abs(p.diameter - w["d"]) > max(LINEAR_TOL, 1e-3 * w["d"])):
        return False
    if w.get("normal") and not p.id.startswith(f"plane {w['normal']}"):
        return False
    return any(k in w for k in ("kind", "side", "d", "normal"))


def _nearest(ports: Sequence[Port], w: dict, k: int = 6) -> list[Port]:
    def score(p: Port) -> float:
        s = 0.0
        if w.get("kind") and p.kind != w["kind"]:
            s += 1000
        if w.get("side") and p.side != w["side"]:
            s += 100
        if w.get("d") is not None:
            s += abs((p.diameter if p.diameter is not None else 1e6) - w["d"])
        if w.get("normal") and not p.id.startswith(f"plane {w['normal']}"):
            s += 50
        return s
    return sorted(ports, key=score)[:k]


# --- геометрия пары портов (проверка сопряжений по факту) ----------------------------------------------------------
def angle_deg(a: Vec3, b: Vec3, unsigned: bool = False) -> float:
    c = max(-1.0, min(1.0, dot(unit(a), unit(b))))
    if unsigned:
        c = abs(c)
    return math.degrees(math.acos(c))


def line_distance(o1: Vec3, d1: Vec3, p: Vec3) -> float:
    """Расстояние от точки p до прямой (o1, d1)."""
    return norm(cross(vsub(p, o1), unit(d1)))


def plane_distance(o: Vec3, n: Vec3, p: Vec3) -> float:
    """Знаковое расстояние от плоскости (o, n) до точки p."""
    return dot(vsub(p, o), unit(n))


# ==================================================================================================================
# === 48/55 kompas_lib.assembly.mates — kompas_lib/assembly/mates.py
# ==================================================================================================================
"""Виды сопряжений, проверка допустимости баз и проверка результата по факту (чистый код).

Проверка по факту нужна потому, что KsAPI не гарантирует результат флагами: `Update()` возвращает True и при
противоречии, а `mc_Distance` между цилиндрами молча ставит деталь «куда-то» (spikes/s82).
"""

from dataclasses import dataclass
from typing import Optional

# из kompas_lib.enums: raw
# из kompas_lib.assembly.ports: Port, angle_deg, line_distance, plane_distance

MT = raw.MateConstraintType
AL = raw.ksMateConstraintAlignmentEnum

# имя → (тип KsAPI, нужен ли value, допустимые пары видов баз)
KINDS: dict[str, tuple[int, bool, set[tuple[str, str]]]] = {
    "coincident": (MT.mc_Coincidence, False, {("plane", "plane"), ("cylinder", "cylinder"), ("axis", "axis"),
                                              ("cylinder", "axis"), ("plane", "ref_plane")}),
    "concentric": (MT.mc_Concentric, False, {("cylinder", "cylinder"), ("cylinder", "axis"), ("axis", "axis"),
                                             ("edge", "edge"), ("edge", "cylinder")}),
    "distance": (MT.mc_Distance, True, {("plane", "plane"), ("plane", "ref_plane")}),
    "parallel": (MT.mc_Parallel, False, {("plane", "plane"), ("cylinder", "cylinder"), ("plane", "ref_plane"),
                                         ("cylinder", "axis"), ("axis", "axis"), ("cylinder", "plane")}),
    "perpendicular": (MT.mc_Perpendicular, False, {("plane", "plane"), ("cylinder", "plane"),
                                                   ("cylinder", "cylinder"), ("plane", "ref_plane"),
                                                   ("cylinder", "ref_plane")}),
    "angle": (MT.mc_Angle, True, {("plane", "plane"), ("cylinder", "cylinder"), ("plane", "ref_plane")}),
    "tangent": (MT.mc_Tangency, False, {("cylinder", "plane"), ("cylinder", "cylinder")}),
    "in_place": (MT.mc_InPlace, False, set()),
}
ALIASES = {
    "совпадение": "coincident", "coincidence": "coincident", "соосность": "concentric", "coaxial": "concentric",
    "расстояние": "distance", "параллельность": "parallel", "перпендикулярность": "perpendicular",
    "угол": "angle", "касание": "tangent", "tangency": "tangent", "на месте": "in_place", "inplace": "in_place",
}
ALIGN = {None: None, "closest": AL.ksMCAlignmentClosest, "auto": AL.ksMCAlignmentClosest,
         "same": AL.ksMCAlignmentCooriented, "cooriented": AL.ksMCAlignmentCooriented,
         "opposite": AL.ksMCAlignmentOpposite, "flip": AL.ksMCAlignmentOpposite}
NAMES = {int(v[0]): k for k, v in KINDS.items()}

ANGLE_OK = 0.05      # градусы
DIST_OK = 0.01       # мм


def kind_of(name: str) -> str:
    k = name.strip().lower().replace("-", "_")
    k = ALIASES.get(k, k)
    if k not in KINDS:
        raise ValueError(f"Неизвестный вид сопряжения {name!r}. Есть: {', '.join(KINDS)} "
                         f"(или по-русски: {', '.join(ALIASES)})")
    return k


def align_of(name: Optional[str]):
    key = None if name is None else name.strip().lower()
    if key not in ALIGN:
        raise ValueError(f"align={name!r}: допустимо None, 'same', 'opposite', 'closest'")
    return ALIGN[key]


def validate(kind: str, a: str, b: str, value: float | None) -> None:
    """Проверить сочетание видов баз (plane/cylinder/axis/edge/ref_plane) и наличие value."""
    _, needs_value, pairs = KINDS[kind]
    if needs_value and value is None:
        raise ValueError(f"Сопряжение {kind!r} требует value (мм или градусы)")
    if not needs_value and value is not None:
        raise ValueError(f"Сопряжение {kind!r} не принимает value")
    if pairs and (a, b) not in pairs and (b, a) not in pairs:
        ok = ", ".join(f"{x}–{y}" for x, y in sorted(pairs))
        hint = " (для расстояния между осями используйте плоскости или parallel + distance)" \
            if kind == "distance" and "cylinder" in (a, b) else ""
        raise ValueError(f"{kind}: базы {a}–{b} не поддерживаются; допустимо: {ok}{hint}")


@dataclass(frozen=True)
class Fact:
    """Проверка сопряжения по геометрии в СК сборки."""
    ok: bool | None          # None — проверить нечем (системные плоскости/оси, рёбра)
    detail: str


def verify(kind: str, a: Port | None, b: Port | None, value: float | None = None) -> Fact:
    """Выполнено ли сопряжение `kind` между портами a и b (уже в СК сборки)."""
    if a is None or b is None:
        return Fact(None, "базы без геометрии порта — проверка по факту не выполнялась")
    pair = {a.kind, b.kind}
    if kind in ("concentric", "coincident") and pair == {"cylinder"}:
        ang = angle_deg(a.direction, b.direction, unsigned=True)
        dist = line_distance(a.origin, a.direction, b.origin)
        return Fact(ang < ANGLE_OK and dist < DIST_OK, f"угол осей {ang:.3f}°, расстояние осей {dist:.3f} мм")
    if kind in ("coincident", "distance") and pair == {"plane"}:
        ang = angle_deg(a.direction, b.direction, unsigned=True)
        dist = plane_distance(b.origin, b.direction, a.origin)
        want = 0.0 if kind == "coincident" else abs(value or 0.0)
        ok = ang < ANGLE_OK and abs(abs(dist) - want) < DIST_OK
        return Fact(ok, f"угол нормалей {ang:.3f}°, расстояние {dist:.3f} мм (нужно {want:g})")
    if kind == "parallel":
        ang = angle_deg(a.direction, b.direction, unsigned=True)
        if pair == {"cylinder", "plane"}:
            ang = abs(90.0 - ang)
        return Fact(ang < ANGLE_OK, f"отклонение от параллельности {ang:.3f}°")
    if kind == "perpendicular":
        ang = angle_deg(a.direction, b.direction, unsigned=True)
        if pair == {"cylinder", "plane"}:
            dev = ang
        else:
            dev = abs(90.0 - ang)
        return Fact(dev < ANGLE_OK, f"отклонение от перпендикулярности {dev:.3f}°")
    if kind == "angle":
        ang = angle_deg(a.direction, b.direction, unsigned=True)
        want = abs(value or 0.0) % 180
        dev = min(abs(ang - want), abs(180 - ang - want))
        return Fact(dev < ANGLE_OK, f"угол {ang:.3f}° (нужно {want:g}°)")
    if kind == "tangent" and pair == {"cylinder", "plane"}:
        c, p = (a, b) if a.kind == "cylinder" else (b, a)
        ang = angle_deg(c.direction, p.direction, unsigned=True)
        dist = abs(plane_distance(p.origin, p.direction, c.origin))
        ok = abs(ang - 90.0) < ANGLE_OK and abs(dist - (c.radius or 0)) < DIST_OK
        return Fact(ok, f"ось ∥ плоскости: {abs(ang - 90):.3f}°, ось–плоскость {dist:.3f} мм, R={c.radius:g}")
    if kind == "tangent" and pair == {"cylinder"}:
        ang = angle_deg(a.direction, b.direction, unsigned=True)
        dist = line_distance(a.origin, a.direction, b.origin)
        want = (a.radius or 0) + (b.radius or 0)
        alt = abs((a.radius or 0) - (b.radius or 0))
        ok = ang < ANGLE_OK and min(abs(dist - want), abs(dist - alt)) < DIST_OK
        return Fact(ok, f"оси {ang:.3f}°, расстояние осей {dist:.3f} мм (R1±R2 = {want:g}/{alt:g})")
    return Fact(None, f"проверка {kind} для {a.kind}–{b.kind} не реализована")


