# === 53/55 kompas_lib.build.topology — kompas_lib/build/topology.py
# ==================================================================================================================
"""Топология рёбер без координат: цепочки по общим вершинам, касательная достройка, проверки перед операцией.

Чистый Python над `model.Edge` (ключи `key`, `faces`, `vertices`, касательные `tangents`, `convexity` заполняет
`read_edges`, spikes/s112). Зачем: скругление/фаска по части касательной цепочки KsAPI строит **без ошибки** —
`Update() == True`, тело целое, а на обрыве цепочки появляются плоские торцы-«ступени» (s112, стык бобышки-
«стадиона»: две дуги без двух прямых). `IFillet.SetTangent(True)` через API цепочку не продолжает (s112) — её
достраивает `complete_chains`.

    chains = edge_chains(selected)                      # связные цепочки выбранных рёбер
    full, added = complete_chains(selected, b.edges())  # + касательные продолжения на открытых концах
    issues = chain_issues(selected, b.edges())          # что сломает операцию: обрывы, гладкие рёбра, …
"""

import math
from dataclasses import dataclass, field
from typing import Iterable, Sequence

# из kompas_lib.model: Edge

TANGENT_ANGLE = 1.0          # °: стык рёбер с углом касательных меньше — гладкий (продолжение цепочки)


@dataclass
class Chain:
    """Связная цепочка рёбер (общие вершины). `closed` — замкнута; `ends` — (вершина, ребро) открытых концов;
    `corners` — внутренние вершины с изломом (касательные не совпадают)."""
    edges: list[Edge]
    closed: bool
    ends: list[tuple] = field(default_factory=list)
    corners: list = field(default_factory=list)

    @property
    def length(self) -> float:
        return sum(e.length for e in self.edges)

    def __str__(self) -> str:
        kinds = "+".join(sorted({e.kind for e in self.edges}))
        state = "замкнута" if self.closed else f"открыта ({len(self.ends)} конца)"
        corners = f", изломов {len(self.corners)}" if self.corners else ""
        return f"цепочка {len(self.edges)} рёб. ({kinds}, L={self.length:.4g}) {state}{corners}"


def tangent_at(edge: Edge, vertex) -> tuple | None:
    """Касательная ребра в его вершине `vertex` (ключ), направленная от вершины внутрь ребра."""
    if not edge.vertices or not edge.tangents or len(edge.tangents) != 2:
        return None
    t0, t1 = edge.tangents
    if edge.vertices[0] == vertex and t0 is not None:
        return t0
    if edge.vertices[1] == vertex and t1 is not None:
        return (-t1[0], -t1[1], -t1[2])
    return None


def smooth_joint(a: Edge, b: Edge, vertex, angle: float = TANGENT_ANGLE) -> bool:
    """Рёбра `a` и `b` стыкуются в `vertex` по касательной (одна гладкая линия, а не излом)."""
    ta, tb = tangent_at(a, vertex), tangent_at(b, vertex)
    if ta is None or tb is None:
        return False
    # от вершины внутрь рёбер: у продолжения касательные противоположны
    return -(ta[0] * tb[0] + ta[1] * tb[1] + ta[2] * tb[2]) >= math.cos(math.radians(angle))


def _by_vertex(edges: Iterable[Edge]) -> dict:
    out: dict = {}
    for e in edges:
        for v in set(e.vertices or ()):
            if v is not None:
                out.setdefault(v, []).append(e)
    return out


def edge_chains(edges: Sequence[Edge], angle: float = TANGENT_ANGLE) -> list[Chain]:
    """Разбить рёбра на связные цепочки по общим вершинам (ключам, не координатам)."""
    edges = _unique(edges)
    at_vertex = _by_vertex(edges)
    seen: set = set()
    chains = []
    for start in edges:
        if start.key in seen:
            continue
        comp, stack = [], [start]
        seen.add(start.key)
        while stack:
            e = stack.pop()
            comp.append(e)
            for v in set(e.vertices or ()):
                for n in at_vertex.get(v, ()):
                    if n.key not in seen:
                        seen.add(n.key)
                        stack.append(n)
        keys = {e.key for e in comp}
        ends, corners = [], []
        for v, es in at_vertex.items():
            mine = [e for e in es if e.key in keys]
            if not mine:
                continue
            uses = sum((e.vertices[0] == v) + (e.vertices[1] == v) for e in mine)
            if uses == 1:
                ends.append((v, mine[0]))
            elif len(mine) == 2 and not smooth_joint(mine[0], mine[1], v, angle):
                corners.append(v)
            elif len(mine) > 2:
                corners.append(v)
        chains.append(Chain(comp, closed=not ends, ends=ends, corners=corners))
    return chains


def continuations(edge: Edge, vertex, pool: Iterable[Edge], angle: float = TANGENT_ANGLE) -> list[Edge]:
    """Рёбра `pool`, продолжающие `edge` в вершине `vertex` по касательной, той же выпуклости, не гладкие."""
    out = []
    for n in pool:
        if n.key == edge.key or vertex not in (n.vertices or ()):
            continue
        if n.convexity == "smooth" or (edge.convexity and n.convexity and n.convexity != edge.convexity):
            continue
        if smooth_joint(edge, n, vertex, angle):
            out.append(n)
    return out


def complete_chains(selected: Sequence[Edge], pool: Sequence[Edge],
                    angle: float = TANGENT_ANGLE) -> tuple[list[Edge], list[Edge]]:
    """Достроить выбранные рёбра до полных касательных цепочек по рёбрам `pool` (обычно все рёбра детали).

    Возвращает (все рёбра цепочек, добавленные). Продолжение ищется на открытых концах: ребро `pool` в той же
    вершине, с той же выпуклостью и совпадающей касательной; неоднозначное продолжение (два кандидата) не
    берётся — о нём скажет `chain_issues`."""
    result = {e.key: e for e in _unique(selected)}
    added: list[Edge] = []
    at_vertex = _by_vertex(pool)
    frontier = [(v, e) for c in edge_chains(list(result.values()), angle) for v, e in c.ends]
    while frontier:
        v, e = frontier.pop()
        cand = [n for n in continuations(e, v, at_vertex.get(v, ()), angle) if n.key not in result]
        if len(cand) != 1:
            continue
        n = cand[0]
        result[n.key] = n
        added.append(n)
        for w in set(n.vertices or ()):
            if w != v and w is not None:
                frontier.append((w, n))
    return list(result.values()), added


def chain_issues(selected: Sequence[Edge], pool: Sequence[Edge] | None = None,
                 angle: float = TANGENT_ANGLE) -> list[str]:
    """Проблемы набора рёбер для скругления/фаски — до операции.

    * ребро без топологии (не из `read_edges`) или не из текущей детали (`pool`) — отбор устарел;
    * гладкое ребро (грани по касательной) — скруглять/снимать нечего;
    * повтор ребра;
    * открытый конец, который продолжается по касательной невыбранным ребром — операция оборвётся ступенью;
    * неоднозначное продолжение (развилка касательных рёбер);
    Смешение выпуклых и вогнутых рёбер в одной цепочке — не ошибка (сообщает `PartBuilder` в предупреждениях).
    """
    issues = []
    keys = [e.key for e in selected]
    if any(k is None for k in keys):
        issues.append("рёбра без топологии (не из PartBuilder.edges()/read_edges) — цепочку проверить нельзя")
        return issues
    dup = len(keys) - len(set(keys))
    if dup:
        issues.append(f"повтор рёбер: {dup}")
    pool_keys = {e.key for e in pool} if pool is not None else None
    stale = [e for e in selected if pool_keys is not None and e.key not in pool_keys]
    if stale:
        issues.append(f"{len(stale)} рёб. нет в текущей детали — отбор устарел после следующей операции, "
                      "отберите заново (b.edges()/edges_between)")
    smooth = [e for e in selected if e.convexity == "smooth"]
    if smooth:
        issues.append(f"{len(smooth)} гладк. рёб. (грани стыкуются по касательной) — скруглять нечего: "
                      + _edges_where(smooth))
    at_vertex = _by_vertex(pool or [])
    for c in edge_chains(_unique(selected), angle):
        for v, e in c.ends:
            cand = continuations(e, v, at_vertex.get(v, ()), angle)
            cand = [n for n in cand if n.key not in set(keys)]
            if len(cand) == 1:
                issues.append(f"{c}: обрыв касательной цепочки у {_chain_point(e, v)} — продолжение ({cand[0].kind}) не "
                              "выбрано, будет ступень")
            elif len(cand) > 1:
                issues.append(f"{c}: развилка у {_chain_point(e, v)} — {len(cand)} касательных продолжения")
    return issues


def _unique(edges: Iterable[Edge]) -> list[Edge]:
    out, seen = [], set()
    for e in edges:
        k = e.key if e.key is not None else id(e)
        if k not in seen:
            seen.add(k)
            out.append(e)
    return out


def _chain_point(e: Edge, v) -> str:
    p = e.start if e.vertices and e.vertices[0] == v else e.end
    return "(" + ", ".join(f"{c:.4g}" for c in p) + ")" if p else "?"


def _edges_where(es: Sequence[Edge]) -> str:
    return "; ".join(f"{e.kind} {_chain_point(e, e.vertices[0] if e.vertices else None)}" for e in es[:4]) + \
        (" …" if len(es) > 4 else "")


