# === Сборка пакета: модули kompas_lib.* как пространства имён этого файла
# ==================================================================================================================
def _install(packages: tuple[str, ...], names: dict[str, str]) -> None:
    """Зарегистрировать модули kompas_lib.* в sys.modules, сделать корень пакетом и подключить hook для pkgutil."""
    _NAMES.update({rel: frozenset(value.split()) for rel, value in names.items()})
    root = globals()
    root["__path__"] = [f"{__file__}!/{_ROOT}"]
    root["__package__"] = _ROOT
    if root.get("__spec__") is not None:
        root["__spec__"].submodule_search_locations = root["__path__"]
    for rel in names:
        module = _submodule(rel)
        if rel in packages:
            module.__path__ = [f"{__file__}!/{_ROOT}/{rel.replace('.', '/')}"]
            module.__package__ = module.__name__
        if "." not in rel:
            root.setdefault(rel, module)
    for hook in tuple(_sys.path_hooks):
        if getattr(hook, "_kompas_monolith_root", None) == _ROOT:
            _sys.path_hooks.remove(hook)
    _sys.path_hooks.insert(0, _PathHook())
    prefix = f"{__file__}!/{_ROOT}"
    for path in tuple(_sys.path_importer_cache):
        if isinstance(path, str) and path.startswith(prefix):
            _sys.path_importer_cache.pop(path, None)


class _PathFinder:
    """Список модулей пакета для pkgutil.iter_modules/walk_packages; сами модули уже в sys.modules."""

    def __init__(self, entry: str):
        prefix = f"{__file__}!/{_ROOT}"
        if entry == prefix:
            self.package = ""
        elif isinstance(entry, str) and entry.startswith(prefix + "/"):
            self.package = entry[len(prefix) + 1:].replace("/", ".")
        else:
            raise ImportError(entry)

    def find_spec(self, fullname, target=None):
        return None

    def invalidate_caches(self):
        return None

    def iter_modules(self, prefix=""):
        parent = f"{self.package}." if self.package else ""
        for relative in sorted(_NAMES):
            child = relative[len(parent):] if relative.startswith(parent) else ""
            if child and "." not in child:
                yield prefix + child, hasattr(_sys.modules.get(f"{_ROOT}.{relative}"), "__path__")


class _PathHook:
    _kompas_monolith_root = _ROOT

    def __call__(self, entry):
        return _PathFinder(entry)


